INSERT INTO `tb_item` (`item_id`, `item_title`, `community_id`, `collection_id`, `item_alternative`, `item_issued_day`, `item_issued_month`, `item_issued_year`, `item_description`, `item_abstract`, `item_sponsorship`, `item_citation`, `item_uri`, `item_publisher`) VALUES
('ITM00000000002', 'การประยุกต์ใช้แบบจำลองทางสถิติสำหรับการแจกแจงผลจับสัตว์น้ำโดยน้ำหนัก และการจัดกลุ่มโครงสร้างประชาคมสัตว์น้ำในทะเลสาบสงขลา', 'COM00000000005', 'COM00000000002', 'Statistical Models for the Distribution of Fish Catch Weights and Clustering by Species with Application to Songkhla Lake', 0, 0, '2551', '', '<p>วิทยานิพนธ์ฉบับนี้ ได้ประยุกต์ใช้แบบจำลองทางสถิติที่เหมาะสมสำหรับการประเมินผล จับสัตว์น้ำ และการจัดกลุ่มโครงสร้างประชากรสัตว์น้ำที่สำรวจพบในทะเลสาบสงขลา โดยแยก การศึกษาออกเป็น 2 ส่วน คือ ส่วนที่หนึ่ง มีวัตถุประสงค์ เพื่อประเมินภาวะการเปลี่ยนแปลงของ ทรัพยากรสัตว์น้ำ พร้อมพัฒนาแบบจำลองทางสถิติสำหรับการพยากรณ์ผลจับสัตว์น้ำในลุ่มน้ำ ทะเลสาบสงขลา การศึกษาในส่วนที่สอง มีวัตถุประสงค์ เพื่อประเมินรูปแบบการกระจายของผล จับสัตว์น้ำในรอบปี ที่จับได้จากเครื่องมือประมงหลักที่ใช้กันมากในทะเลสาบสงขลา พร้อมพัฒนา แบบจำลองทางสถิติสำหรับการจัดกลุ่มโครงสร้างประชากรสัตว์น้ำโดยจำแนกตามชนิดสัตว์น้ำ ซึ่ง ผลการศึกษา ทั้ง 2 ส่วนนี้ สามารถนำไปประยุกต์ใช้ในการบริหารจัดการทรัพยากรสัตว์น้ำ และ ควบคุมการทำประมงในทะเลสาบสงขลาให้มีความสมเหตุสมผล สอดคล้องกับพลวัตรประชากร สัตว์น้ำได้มากยิ่งขึ้น</p>', 'สาขาวิชาวิธีวิทยาการวิจัย มหาวิทยาลัยสงขลานครินทร์', '', 'https://www.oas.psu.ac.th/book/041/', 'มหาวิทยาลัยสงขลานครินทร์'),
('ITM00000000003', 'แผนพัฒนากำลังคนอาชีวศึกษาเพื่อสนับสนุนนโยบายเมืองต้นแบบ “สามเหลี่ยมมั่นคง มั่งคั่ง ยั่งยืน” ในพื้นที่จังหวัดภาคใต้ชายแดน', 'COM00000000006', 'COM00000000002', 'The Workforce Development Plan of Vocational Education to Support the Policy of Prototype City on the', 0, 0, '2565', '', '<p>วิจัยเรื่องนี้มีวัตถุประสงค์ ได้แก่ 1) เพื่อศึกษาความต้องการแรงงาน คุณลักษณะแรงงาน และแผนการจัดการศึกษา เพื่อสนับสนุนนโยบายเมืองต้นแบบ &ldquo;สามเหลี่ยมมั่นคง มั่งคั่ง ยั่งยืน&rdquo; 2) เพื่อศึกษาแบบความร่วมมือในการจัดการศึกษาอาชีวศึกษาร่วมกับภาครัฐและเอกชน เพื่อสนับสนุนนโยบายเมืองต้นแบบ &ldquo;สามเหลี่ยมมั่นคง มั่งคั่ง ยั่งยืน&rdquo; 3) เพื่อสร้างแผนพัฒนากำลังคนอาชีวศึกษาเพื่อสนับสนุนนโยบายเมืองต้นแบบ &ldquo;สามเหลี่ยมมั่นคง มั่งคั่ง ยั่งยืน&rdquo; โดยใช้การวิจัยเชิงคุณภาพ โดยแบ่งขั้นตอนเป็น 2 ระยะ ระยะที่ 1 การศึกษาความต้องการคุณลักษณะแรงงาน แนวโน้มอาชีพภาคอุตสาหกรรมและธุรกิจบริการ และแบบความร่วมมือ เพื่อสนับสนุนนโยบายเมืองต้นแบบ &ldquo;สามเหลี่ยมมั่นคง มั่งคั่ง ยั่งยืน&rdquo; ระยะที่ 2 จัดทำแผนพัฒนากำลังคนอาชีวศึกษา เพื่อสนับสนุนนโยบายเมืองดันแบบ &ldquo;สามเหลี่ยมมั่นคง มั่งคั่ง ยั่งยืน&rdquo; ในพื้นที่จังหวัดภาคให้ชายแดน ขั้นตอนการวิจัย ได้แก่ การสังเคราะห์เอกสาร สัมภาษณ์กลุ่มเป้าหมาย 10 คน วิเคราะห์เนื้อหา สรุปแล้วส่งให้กลุ่มเป้าหมายเต็มยืนยันเนื้อหา จากนั้นนำมาสังเคราะห์ วิเคราะห์ และประเมินผล ข้อมูลที่ได้โดยผู้ทรงคุณวุฒิ ที่มีบทบาท ออกนโยบายและติดตามงาน จำนวน 3 คน จากกระทรวงศึกษาธิการ สภาพัฒนาการเศรษฐกิจและสังคมแห่งชาติ และผู้แทนพิเศษของรัฐบาล ในการแก้ปัญหาภาคใต้ชายแดน อย่างละ 1 คน</p>', 'สาขาวิชาการบริหารการศึกษา มหาวิทยาลัยสงขลานครินทร์', '', 'https://www.oas.psu.ac.th/book/160/', 'มหาวิทยาลัยสงขลานครินทร์'),
('ITM00000000004', 'ศึกษาเปรียบเทียบกฎหมายอิสลามว่าด้วยอาหารฮาลาล', 'COM00000000011', 'COM00000000002', 'Comparative Study of Islamic Law on Halal Food', 8, 4, '2566', '', '<p>การวิจัยเรื่องศึกษาเปรียบเทียบกฎหมายอิสลามว่าด้วยอาหารฮาลาล มีวัตถุประสงค์เพื่อศึกษาบทบัญญัติอิสลามเกี่ยวกับอาหารฮาลาลด้านวัตถุดิบ ศึกษาเปรียบเทียบทัศนะของสี่มัษฺฮับในกฎหมายอิสลามเกี่ยวกับอาหารด้านวัตถุดิบ วิเคราะห์การใช้หลักการผ่อนปรนเกี่ยวกับการบริโภคอาหารฮารอมในภาวะคับขัน และศึกษาทัศนะของมัษฺฮับที่สามารถนำไปใช้เชิงพาณิชย์ในกลุ่มประเทศมุสลิม ใช้วิธีการวิจัยเชิงคุณภาพ เก็บรวบรวมข้อมูลจากเอกสาร ใช้วิธีวิเคราะห์ข้อมูลเชิงพรรณนา ผลการวิจัยพบว่าศาสนาอิสลามให้ความสำคัญเกี่ยวกับเรื่องของอาหารเป็นอย่างยิ่ง มีอายะฮ์อัลกุรอาน ฮะดีษ และตำราวิทยาการอิสลามมากมายสาธยายเกี่ยวกับอาหารทั้งทางตรงและทางอ้อม ทั้งนี้เนื่องจากอาหารมีบทบาทและอิทธิพลต่อมนุษย์ทั้งในมิติทางโลกและทางธรรม โลกนี้และโลกหน้า อาหารในอิสลามจะต้องมีคุณสมบัติหลัก 2 ประการคือ หนึ่ง ฮาลาล หมายถึงเป็นที่อนุมัติ สอง ฏอยยิบ หมายถึงดีมีประโยชน์สะอาด ปลอดภัย มีคุณค่าทางโภชนาการรวมทั้งอาหารเสริมเพื่อสุขภาพและอาหารสำหรับผู้ป่วย แหล่งที่มาของอาหารคือพืชและสัตว์ ตัวบทบัญญัติอิสลามว่าด้วยวัตถุดิบดั้งเดิมของอาหารมี 3 ลักษณะคือ 1. ตัวบทบัญญัติที่ระบุว่าฮาลาล 2. ตัวบทบัญญัติที่ระบุว่าฮารอมหรือไม่อนุมัติ 3. ไม่มีตัวบทบัญญัติระบุเป็นอย่างหนึ่งอย่างใด โดยหลักการเดิมอาหารทุกชนิดเป็นที่อนุมัติให้บริโภค ยกเว้นอาหารที่มีตัวบทห้ามบริโภค ในอัลกุรอานมีอาหารประเภทสัตว์ 10 ชนิดที่ห้ามบริโภคคือ สัตว์ตายเอง เลือด หมู สัตว์ที่ถูกพลีให้แก่ผู้อื่นนอกจากอัลลอฮฺ สัตว์ที่ถูกรัดคอตาย สัตว์ที่ถูกตีจนตาย สัตว์ที่ตกมาตาย สัตว์ที่ถูกขวิดตาย สัตว์ที่ถูกสัตว์ร้ายกัดกินจนตาย สัตว์ที่ถูกบูชายัญ ฮะดีษได้ห้ามบริโภคสัตว์บางชนิดเพิ่มเติม เช่น ลาบ้าน สัตว์ปีกที่มีกรงเล็บแหลมคม สัตว์ดุร้ายมีเขี้ยว และสัตว์ที่กินสิ่งสกปรกเป็นอาหารหลัก ส่วน ม้า กระต่าย กระรอก สัตว์น้ำที่ตาย เต่า ตะพาบน้ำ และแมงดา เป็นที่ ฮาลาลบริโภคตามทัศนะที่มีน้ำหนักมากกว่า พืชทุกชนิดโดยรวมเป็นที่อนุมัติให้บริโภคได้ ยกเว้นพืชที่สกปรก พืชที่มีโทษหรือพิษภัย และพืชที่ทำให้มึนเมา บกพร่องหรือเสียสติ ส่วนภาวะคับขันในบริบทของอาหารคือ สภาพความคับขันที่หากไม่บริโภคอาหาร ฮารอมแล้วจะเกิดความเสียหายต่อสุขภาพ ร่างกายหรือถึงแก่ชีวิตได้ บทบัญญัติอิสลามครอบคลุมภาวะคับขันทุกบริบท การบริโภคอาหารฮารอมในภาวะคับขันเป็นสิ่งวาญิบ อนุญาตให้ผู้ที่ประสบภาวะคับขันเนื่องจากขาดอาหารที่ครอบคลุมกว้างขวางอย่างต่อเนื่องบริโภคอาหารจนอิ่มได้ ส่วนภาวะคับขันเนื่องจากขาดอาหารที่ไม่ครอบคลุมกว้างขวางอย่างต่อเนื่อง อนุญาตให้บริโภคอาหาร ฮารอมปริมาณที่พอประทังชีวิต โดยไม่อนุญาตให้บริโภคอาหารฮารอมเกินความอิ่มทั้งสองกรณี อาหารทุกชนิดที่สามารถประทังชีวิตในภาวะคับขันเป็นที่อนุญาตให้บริโภค ยกเว้นเนื้อมนุษย์ ทั้งนี้เหตุผลโดยรวมของการอนุญาตให้บริโภคอาหารฮารอมในภาวะคับขันคือเพื่อขจัดอันตรายที่จะเกิดขึ้น</p>\r\n<p>This study, a comparative study of Islamic Law on Halal food, aims at examining the Islamic Law related to Halal food ingredients and comparing the views on Halal food ingredients within the framework of the four Sunni Islamic schools of thought. The study also explores the flexibility of food consumption in critical conditions and the views of the four schools of thought that can be used commercially in Muslim countries. Data were collected from various sources of document. Descriptive analysis was used in data analysis. The findings in this study show that Islam emphasizes on various aspects of food. Quranic verses, Ahadith and other Islamic texts have directly and indirectly provided explanations on this subject. This is because food is important to human lives: on worldly and religious dimensions; and in this world and the hereafter. According to Islamic principles, food must have two main features i. e. Halal and Tayyib. Halal means lawful or permitted. Tayyib means healthy, benefits, clean, safe and nutritious, including supplements and patient foods. Sources of food include plants and animals. Islamic principles state that original raw materials can be classified into 3 features: 1) the halal/lawful, 2) the haram or forbidden, and 3) no specific provision/neither halal nor haram. The Islamic principles provide that all types of food are lawful, unless proven otherwise. Quran has specified 10 animals that are forbidden for consumption i. e. any animal that dies a natural death and is not slaughtered, blood, swine (pork), any animal on whom the name of anyone other than Allah is invoked, any animal killed by jerk, any animal being beaten to death, any animals fell death, any animals killed gore, any animals eaten by beast to death, and any animals being sacrificed. The Hadith prohibited some other animals, including donkey, any birds with sharp claws, any feral animals with fangs, and any animals that eat dirt as staple food. In addition, horse, rabbit, squirrel, dead aquatic animals, turtle, soft shell turtle, and water bug are Halal in the views of majority of the Muslim scholars. All types of plants are legal, except dirty plants, plants that harm, intoxicated plants, and any plants impaired consciousness and mental breakdown. This study showed that critical time in the context of the diet, are the time in which abstaining from consuming forbidden food will harm one&rsquo;s health or body or cause death. The provisions of Islamic law on this issue cover all critical time and the law provides that consuming haram food in a critical time is compulsory. Islamic Law allows those who suffer from a long-term and wide spread critical time due to lack of food to continue consuming haram food until full enjoyment. In the event of a critical time due to lack of food which is not wide spread and continuous, one is allowed to consume a sufficient amount of haram food to sustain life. In both cases, all kinds of food, except human flesh are allowed. The rationale behind allowing the consumption of haram food in Islamic Law is to eliminate any possible harmfulness</p>', '', 'วิทยานิพนธ์ (ปร.ด.(อิสลามศึกษา))--มหาวิทยาลัยสงขลานครินทร์, 2561', '', 'มหาวิทยาลัยสงขลานครินทร์ วิทยาเขตปัตตานี'),
('ITM00000000005', 'การวิเคราะห์องค์ประกอบและสภาพการดำเนินงานตามหลักจริยธรรมอิสลาม ของโรงเรียนอิกเราะสามัญศึกษา กรุงเทพมหานคร', 'COM00000000004', 'COM00000000002', 'Factor Analysis and State of the Implementation of Islamic Ethics in Iqra Muslim School, Bangkok', NULL, 10, '2566', '', '<div class=\"row text-left\">\r\n<div class=\"col-sm-10\">การทำวิจัยเรื่อง การวิเคราะห์องค์ประกอบและสภาพการดำเนินงานตามหลัก จริยธรรมอิสลามของโรงเรียนอิกเราะสามัญศึกษา กรุงเทพมหานคร มีวัตถุประสงค์เพื่อ 1) วิเคราะห์องค์ประกอบการดำเนินงานตามหลักจริยธรรมอิสลามของโรงเรียนเครือข่ายโรงเรียนอิกเราะสามัญ ศึกษา กรุงเทพมหานคร 2) ศึกษาสภาพการดำเนินงานตามหลักจริยธรรมอิสลามของโรงเรียน อิกเราะสามัญศึกษา กรุงเทพมหานคร กลุ่มตัวอย่างที่ใช้ในการวิจัยครั้งนี้ มีจำนวนทั้งสิ้น 173 คน ซึ่ง แบ่งออกเป็น 2 กลุ่ม คือ กลุ่มที่ 1 จำนวน 148 คน เป็นผู้บริหาร ครูและพนักงานของโรงเรียนเครือข่าย ที่ใช้หลักสูตรอิสลามศึกษาแบบมักตับ เป็นกลุ่มตัวอย่างที่ใช้วิเคราะห์องค์ประกอบ กลุ่มที่ 2 จำนวน 25 คน เป็นผู้บริหาร หัวหน้ากลุ่มสาระ หัวหน้าช่วงชั้น หัวหน้าฝ่ายตัรบิยะฮ์ และหัวหน้าแผนกต่างๆ จำนวน 25 คนของโรงเรียนอิกเราะสามัญศึกษา เป็นกลุ่มตัวอย่างที่ใช้ศึกษาสภาพดำเนินงานตามหลัก จริยธรรมอิสลามของโรงเรียนอิกเราะสามัญศึกษา กรุงเทพมหานคร ผู้วิจัยได้เก็บรวบรวมข้อมูลด้วย เทคนิคการวิจัยเชิงผสานวิธี (Mixed methods research) ระหว่างวิธีวิจัยเชิงปริมาณและเชิงคุณภาพ โดยใช้โรงเรียนอิกเราะสามัญศึกษาเป้นหน่วยวิเคราะห์ (unit of analysis) เครื่องมือที่ใช้ในการศึกษา เพื่อตอบวัตถุประสงค์ข้อที่ 1 เป็นแบบสอบถาม วิเคราะห์ข้อมูลด้วยโปรแกรมคอมพิวเตอร์สำเร็จรูป ผู้วิจัยใช้เทคนิคการวิเคราะห์องค์ประกอบหลัก (Principle Component Analysis &ndash; PCA) โดยใช้โปรแกรมสำเร็จรูปทางสถิติเพื่อสกัดองค์ประกอบ (Factor Extraction) และเครื่องมือที่ใช้ในการศึกษา เพื่อตอบวัตถุประสงค์ข้อที่ 2 เป็นประเด็นคำถามที่ใช้สำหรับการสนทนากลุ่ม (Focus Group) ผลการวิจัยเชิงปริมาณพบว่า องค์ประกอบการดำเนินงานตามหลักจริยธรรมอิสลาม ของโรงเรียนเครือข่ายโรงเรียนอิกเราะสามัญศึกษา กรุงเทพมหานคร ประกอบด้วย 6 องค์ประกอบ 30 ตัวแปรสังเกต ได้แก่ 1) หลักอะดาละฮฺ (Adalah ; หลักความเที่ยงธรรม ความเหมาะสม) มี 6 ตัว แปรสังเกต 2) หลักชูรอ (Syura ; การปรึกษาหารือและการมีส่วนร่วม) มี 6 ตัวแปรสังเกต 3) หลักอิตกอน (Itqan ; การมุ่งพัฒนาสู่ความเป็นเลิศ) มี 5 ตัวแปรสังเกต 4) หลักอะมานะฮฺ (Amanah ; ความรับผิดชอบ) มี 5 ตัวแปรสังเกต 5) หลักมุรอกอบะฮฺ (Muraqabah ; หลักความ โปร่งใส ตรวจสอบได้) มี 4 ตัวแปรสังเกต และ 6) หลักอิคลาศ (Ikhlas ; ความบริสุทธิ์ใจ) มี 4 ตัวแปร สังเกต โดยองค์ประกอบที่ได้ถือว่าเป็นองค์ประกอบที่เชื่อถือได้ มีความสอดคล้องภายในอยู่ในระดับดี มาก ผลการวิจัยเชิงคุณภาพพบว่า โรงเรียนอิกเราะสามัญศึกษา กรุงเทพมหานคร มีสภาพ การดำเนินงานในบรรยากาศอิสลามที่มุ่งเน้นวิถีอิสลามเป็นฐานในการจัดการ (Islamic Based Management) หลอหลอมผู้บริหาร ครู พนักงานและบุคลากรของโรงเรียนด้วยการกระตุ้น (ตัรฆีบ) ให้เห็นคุณค่าของงานด้วยการมุ่งหวังความพึงพอพระทัยจากอัลลอฮฺ หวังในผลบุญและความสำเร็จทั้ง ในโลกนี้และโลกหน้า มีการเสริมกำลังใจเชิงบวกด้วยการมอบฮะดิยะฮฺ (รางวัล) มีการจัดวางโครงสร้าง การบริหาร กำหนดนโยบายทางด้านศาสนาและนโยบายทั่วไปอย่างชัดเจน กำหนดเป้าหมายร่วมกันคือ การสร้างประชาชาติ (อุมมะฮฺ) ที่เลอเลิศ นอกจากนี้ยังมีการพัฒนาบุคลากร การสอนงาน การกระจาย งาน และการติดตามงานอย่างต่อเนื่อง มีระบบเบิกจ่ายวัสดุอุปกรณ์และงบประมาณต่างๆ ระบบ ตรวจสอบ สรุปงานและประเมินผลงานที่ชัดเจน ผ่านกิจกรรมและวิธีปฏิบัติอันเด่นชัดที่ผลักดันให้ทุกคน เห็นคุณค่าในอัตลักษณ์แห่งการเป็นโรงเรียนวิถีอิสลาม</div>\r\n</div>\r\n<div class=\"row text-left\">\r\n<div class=\"col-sm-2\">&nbsp;</div>\r\n<div class=\"col-sm-10\"><em>Abstract:</em>&nbsp;This research entitled Factor Analysis and state of the Implementation of Islamic Ethics in Iqra Muslim School, Bangkok is aimed to 1) analyze components of Islamic Ethics of affiliated schools of Iqra Muslim School Bangkok, 2) study the state of the implementation of Islamic Ethics in Iqra Muslim School, Bangkok. The Samples consisting of 173 people were divided into 2 groups. The first group selected for exploratory analysis consisted of 148 administrators, teachers, and officials of affiliated schools of Iqra Muslim School that used the Maktab Islamic Studies Curriculum. The second group, comprising 25 samples, was used for a study on the state of the Implementation of Islamic Ethics in Iqra Muslim School, Bangkok. Mixed-methods research, which combines quantitative research methods and qualitative research methods was used in this study. Questionnaires were employed to address the first research objective. Data obtained from questionnaires were analyzed using Principal Component Analysis &ndash; PCA and Factor Extraction. The questions for focus group discussion served as the research instrument used to address the second research objective. The data obtained from group discussions were analyzed using content analysis. The results of the research indicate that components of Islamic Ethics of affiliated schools of Iqra Muslim School Bangkok consist of 6 components with 30 indicators. Of these Adalah with 6 indicators, Syura with 6 indicators, Itqan with 5 indicators, Amanah with 5 indicators, Muraqabah with 4 indicators, and Ikhlas with 4 indicators. The components are found to be reliable and the internal consistency is very high. The results of the qualitative research found that Iqra Muslim School Bangkok operates in an Islamic environment that focuses on Islam as the base of management (Islamic Based Management). Under this environment, the school enables to forge a bond between its administrators, teachers, staff, and personnel by encouraging them (targheeb) to see the value of their work by expecting to gain the satisfaction of Allah Ta\'ala, hoping for merit and success both in this world and the next world. Positive encouragement was provided through hadiyah (reward). Clear religious and general policies were set in the school. Members of the school set their goals together which were to create an excellent nation (Ummah al-wustaa). In addition, the school\'s focus on personnel development, work instruction, work distribution, and continuous follow-up work was also apparent. There is a system for the disbursement of materials, equipment, and various budgets, a system for checking, summarizing the work, and evaluating the work clearly. All these systems were run through predominant activities and practices that encourage everyone to appreciate the value of the identity of being an Islamic school.</div>\r\n</div>\r\n<div class=\"row text-left\">\r\n<div class=\"col-sm-2\"><label><strong>Publisher</strong></label></div>\r\n<div class=\"col-sm-10\">มหาวิทยาลัยสงขลานครินทร์ วิทยาเขตปัตตานี. สำนักวิทยบริการ</div>\r\n</div>', 'สาขาการบริหารและการจัดการการศึกษาอิสลาม', '', 'https://kb.psu.ac.th/server/api/core/bitstreams/47e0a908-e2e5-466a-8a64-d1cdbc4a5948/content', 'มหาวิทยาลัยสงขลานครินทร์ วิทยาเขตปัตตานี'),
('ITM00000000006', 'การพัฒนาชุดฝึกอบรมครูแบบมีส่วนร่วม เรื่อง ทักษะการสร้างชุดการเรียนรู้แบบบูรณาการอิสลามศึกษากับวิชาวิทยาศาสตร์ในโรงเรียนสันติศึกษา จังหวัดเชียงใหม่', 'COM00000000004', 'COM00000000002', 'Participatory Development of Teachers’ Training Package on Skills for Creating an Integrated Learning Package for Islamic Studies with Science Subjects in Santi Suksa School Chiang Mai Province', NULL, 10, '2566', '', '<div class=\"row text-left\">\r\n<div class=\"col-sm-10\">การวิจัยในครั้งนี้เป็นการวิจัยเชิงปฏิบัติการ มีวัตถุประสงค์เพื่อ 1) พัฒนาและหาประสิทธิภาพของชุดฝึกอบรมครู ที่พัฒนา แบบมีส่วนร่วม เรื่อง ทักษะการสร้างชุดการเรียนรู้แบบ บูรณาการอิสลามศึกษากับวิชาวิทยาศาสตร์ 2) ศึกษาผลการใช้ชุดฝึกอบรมครู ที่พัฒนา แบบมีส่วนร่วมเรื่อง ทักษะการสร้างชุดการเรียนรู้แบบบูรณาการอิสลามศึกษากับวิชาวิทยาศาสตร์ และ 3) ศึกษา ความพึงพอใจของครูที่มีต่อการอบรม เชิงปฏิบัติการด้วย ชุดฝึกอบรมครู ที่พัฒนา แบบมีส่วนร่วม เรื่องทักษะการสร้างชุดการเรียนรู้แบบบูรณาการอิสลามศึกษากับวิชาวิทยาศาสตร์ในโรงเรียนสันติศึกษา จังหวัดเชียงใหม่ กลุ่มเป้าหมาย คือ ครูผู้สอนในโรงเรียนสันติศึกษา จังหวัดเชียงใหม่ จำนวน 20 คน คัดเลือกกลุ่มเป้าหมายแบบเจาะจง เครื่องมือที่ใช้ในการวิจัยประกอบด้วย 1) ชุดฝึกอบรมครูที่พัฒนาแบบมีส่วนร่วม เรื่อง ทักษะการสร้างชุดการเรียนรู้แบบบูรณาการอิสลามศึกษากับวิชาวิทยาศาสตร์ในโรงเรียนสันติศึกษา จังหวัดเชียงใหม่ 2) แบบทดสอบก่อน -หลังการฝึกอบรม 3) แบบประเมิน แผนการจัดการเรียนรู้แบบบูรณาการ และ 4.) แบบสอบถามความพึงพอใจของครู วิเคราะห์ข้อมูลด้วยสถิติเชิงพรรณนา โดยหาค่าร้อยละ ค่าเฉลี่ย ค่าเบี่ยงเบน มาตรฐาและการทดสอบค่าทีแบบสองกลุ่มตัวอย่างที่สัมพันธ์กัน ( t-test for Dependent Samples)ผลการวิจัยพบว่า ในการพัฒนา ชุดฝึกอบรมครูแบบมีส่วนร่วม เรื่อง ทักษะการสร้างชุดการเรียนรู้แบบบูรณาการอิสลามศึกษากับวิชาวิทยาศาสตร์ นั้น มีขั้นตอนการพัฒนาแบบมีส่วนร่วม 7 ขั้นตอนดังนี้ คือ 1) ศึกษาแนวคิดทฤษฎีที่เกี่ยวข้องกับการพัฒนาชุดฝึกอบรมและวิธีการอบรมจากเอกสารงานที่เกี่ยวข้อง 2) พัฒนาเนื้อหาตามแนวคิดด้านโครสร้างเนื้อหาของชุดฝึกอบรม 3) พัฒนาชุดฝึกอบรม แบบมีส่วนร่วมกับครู (ฉบับร่าง) 4) ตรวจสอบคุณภาพของชุดฝึกอบรมโดยผู้เชี่ยวชาญและปรับปรุงแก้ไข 5) นำชุดฝึกอบรมไปทดลองใช้ 6) จัดทำชุดฝึกอบรมฉบับสมบูรณ์ และ 7) นำชุดฝึกอบรมฉบับสมบูรณ์ไปใช้กับครูกลุ่มเป้าหมายและหาค่าประสิทธิภาพ โดยผลการหา ประสิทธิภาพจากการนำการนำชุดฝึกอบรมครูที่พัฒนาแบบมีส่วนร่วม เรื่อง ทักษะการสร้างชุดการเรียนรู้แบบบูรณาการอิสลามศึกษากับวิชาวิทยาศาสตร์ ไปอบรมเชิงปฏิบัติการกับครูกลุ่มเป้าหมาย พบว่ามีค่า ประสิทธิภาพโดยรวมเท่ากับ 90.33/93.17 สูงกว่าเกณฑ์ (80/80) ผลการใช้ชุดฝึกอบรมครู แบบมีส่วนร่วม เรื่อง ทักษะการสร้างชุดการเรียนรู้แบบบูรณาการอิสลามศึกษากับวิชาวิทยาศาสตร์ พบว่า ครูมีความรู้ความเข้าใจเกี่ยวกับการจัดการเรียนรู้แบบบูรณาการหลังการฝึกอบรมสูงกว่า (ค่าเฉลี่ย 93.17) ก่อนการฝึกอบรม (ค่าเฉลี่ย 74.33) อย่างมีนัยสำคัญทางสถิติที่ระดับ 0.05 ครูมี ทักษะการเขียนแผนการเรียนรู้แบบบูรณาการอิสลามศึกษากับวิชาวิทยาศาสตร์ ในระดับคุ ณภาพ ที่ ดี มาก ( ได้ คะแนนรวม 28/30 คะแนน ) และ ครูมีความพึงพอใจต่อการอบรม เชิงปฏิบัติการ ด้วยชุดฝึกอบรมครูแบบมีส่วนร่วม เรื่อง ทักษะการสร้างชุดการเรียนรู้แบบบูรณาการอิสลามศึกษากับวิชาวิทยาศาสตร์ในโรงเรียนสันติศึกษา จังหวัดเชียงใหม่ โดยรวม ในระดับดีมาก (ค่าเฉลี่ย 4.95)</div>\r\n</div>\r\n<div class=\"row text-left\">\r\n<div class=\"col-sm-2\">&nbsp;</div>\r\n<div class=\"col-sm-10\"><em>Abstract:</em> This study is action research. The objectives of the study are to: 1) develop and determine the efficiency value of teachers&rsquo; training package on skills for creating an integrated learning package for Islamic studies with science subjects, which was developed through participatory means; 2) study the results of using teachers&rsquo; training package on skills for creating an integrated learning package for Islamic studies with science subjects; and 3) examine teachers\' satisfaction towards training by workshops using teachers&rsquo; training package on skills for creating an integrated learning package for Islamic studies with science subjects in Santi Sukas schools, Chiang Mai Province. The target group is 20 teachers who were purposefully selected from Santi Sukas schools. Chiang Mai Province. The research tools consist of 1) teachers&rsquo; training package on skills for creating an integrated learning package for Islamic studies with science subjects, and 2) pre- and post-training tests 3) Integrated learning plan evaluation form 4.) teachers&rsquo; satisfaction questionnaire. Data were analyzed using descriptive statistics, including percentage, mean, and standard deviation, and t-tests for dependent samples. The study findings showed that there are seven steps involved in developing teachers&rsquo; training packages on skills for creating an integrated learning package for Islamic studies with science subjects through participatory means. These are: 1) reviewing relevant theoretical concepts for developing a training package and related training technique documents, 2) creating material based on the ideas for the training package\'s structure and content, 3) creating a draft version of the teachers&rsquo; training package in collaboration with the teachers, 4) evaluating and enhancing the teachers\' training package draft by specialists in the field 5) experimenting the training package, 6)develop a final training package, and 7) implementing the training package with theteachers through workshops and evaluating its efficiency values. The level of efficiencyof teachers&rsquo; training packages on skills for creating an integrated learning package forIslamic studies with science subjects was found to be 90.33/93.17, which is higher thanthe predetermined criteria of 80/80. The results of using teachers&rsquo; training package onskills for creating an integrated learning package for Islamic studies with sciencesubjects showed that teachers have knowledge and understanding about an integratedlearning package for Islamic studies with science subjects after training was higher(mean 93.17) than before training (mean 74.33 ) with statistical significance at the 0.05and teachers have skills in writing integrated learning plan for Islamic studies withscience subjects, as reflected in the quality of the learning plan, which obtained veryhigh score (total score of 28/30 points) and the overall level of teachers\' satisfactiontowards training by workshops using teachers&rsquo; training package on skills for creating anintegrated learning package for Islamic studies with science subjects in Santi Sukasschools, Chiang Mai Province was very high (mean 4.95).</div>\r\n</div>', 'สาขาการบริหารและการจัดการการศึกษาอิสลาม', '', 'https://kb.psu.ac.th/items/90db67f3-7980-46a2-afb4-c460ed4666bf', 'มหาวิทยาลัยสงขลานครินทร์ วิทยาเขตปัตตานี'),
('ITM00000000007', 'การประเมินการใช้หลักสูตรอิสลามศึกษาตามหลักสูตรแกนกลางการศึกษาขั้นพื้นฐาน พุทธศักราช 2551 ในสถานศึกษา สังกัดสำนักงานเขตพื้นที่การศึกษาประถมศึกษาปัตตานี เขต 2', 'COM00000000004', 'COM00000000002', 'Assessment of the Implementation of Islamic Studies Curriculum based on the Basic Education Core Curriculum B.E. 2551 in Educational Institutions Affiliated with Pattani Primary Educational Service Area Office 2', NULL, 11, '2566', '', '<div class=\"row text-left\">\r\n<div class=\"col-sm-10\">การวิจัยครั้งนี้ใช้วิธีการวิจัยเชิงสำรวจมีวัตถุประสงค์เพื่อ 1) เพื่อศึกษาสภาพปัญหา การใช้หลักสูตรอิสลามศึกษาตามหลักสูตรแกนกลางการศึกษาขั้นพื้นฐาน พุทธศักราช 2551 2) เพื่อ ประเมินการใช้หลักสูตรอิสลามศึกษาตามหลักสูตรแกนกลางการศึกษาขั้นพื้นฐาน พุทธศักราช 2551 3) เพื่อศึกษาแนวทางการใช้หลักสูตรอิสลามศึกษาตามหลักสูตรแกนกลางการศึกษาขั้นพื้นฐาน พุทธศักราช 2551 ในสถานศึกษา สังกัดสำนักงานเขตพื้นที่การศึกษาประถมศึกษาปัตตานี เขต 2 ให้ มีประสิทธิภาพ โดยใช้แบบจำลองซิปป์ (CIPP) ของสตัฟเฟิลบีม (Stufflebram) ประเมินองค์ประกอบ ด้านบริบท ด้านปัจจัยเบื้องต้น ด้านกระบวนการ และด้านผลผลิตที่เกี่ยวกับหลักสูตร กลุ่มตัวอย่างที่ ใช้ในการวิจัยครั้งนี้ ได้แก่ ผู้ทรงคุณวุฒิ จำนวน 6 คน คัดเลือกกลุ่มตัวอย่างด้วยวิธีการสุ่มแบบเจาะจง โดยพิจารณาคุณสมบัติด้านคุณวุฒิ ความรู้ความเชี่ยวชาญด้านหลักสูตรอิสลามศึกษาตามหลักสูตร แกนกลางการศึกษาขั้นพื้นฐาน พุทธศักราช 2551 และครูผู้สอนที่ใช้หลักสูตรอิสลามศึกษาตาม หลักสูตรแกนกลางการศึกษาขั้นพื้นฐาน พุทธศักราช 2551 ในสถานศึกษา สังกัดสำนักงานเขตพื้นที่ การศึกษาประถมศึกษาปัตตานี เขต 2 จำนวน 100 คน โดยใช้วิธีการสุ่มอย่างง่าย เครื่องมือวิจัย ประกอบด้วยแบบสอบถามออนไลน์ (Google forms) และสัมภาษณ์แบบกึ่งโครงสร้าง ผลการศึกษา พบว่า 1. ผลการวิเคราะห์สภาพปัญหาการใช้หลักสูตรอิสลามศึกษาตามหลักสูตร แกนกลางการศึกษาขั้นพื้นฐาน พุทธศักราช 2551 ในสถานศึกษา สังกัดสำนักงานเขตพื้นที่การศึกษา ประถมศึกษาปัตตานี เขต 2 พบว่า 1) ด้านการจัดการเรียนการสอน พบว่า หลักสูตรที่มีการสอน รายวิชาสามัญควบคู่ศาสนา มีรายวิชาที่มากเกินไป ทำให้เวลาเรียนไม่เพียงพอ 2) ด้านครูผู้สอน พบว่า ครูผู้สอนไม่ได้จบตรงสาขา ทำให้มีอุปสรรคในการใช้หลักสูตร ไม่สามารถถ่ายทอดองค์ความรู้ ได้อย่างถ่องแท้ ขาดความรู้ความเข้าใจในการจัดทำแผนการเรียนรู้ที่ถูกต้องได้ และ 3) ด้านการ จัดสรรงบประมาณ พบว่า โรงเรียนไม่ได้รับการจัดสรรงบประมาณในการจัดการเรียนการสอนอิสลามศึกษา ทำให้ส่งผลกระทบต่อการจัดการเรียนการสอน เช่น ขาดแคลนหนังสือเรียน สื่อการ สอนต่าง ๆ 2. ความคิดเห็นของครูต่อการประเมินการใช้หลักสูตรอิสลามศึกษาตามหลักสูตร แกนกลางการศึกษาขั้นพื้นฐาน พุทธศักราช 2551 ใน 4 ด้าน ด้านบริบท ด้านปัจจัยเบื้องต้น ด้าน กระบวนการ และด้านผลผลิต โดยภาพรวมและรายข้ออยู่ในระดับมาก 3. ผลการวิเคราะห์แนวทางการใช้หลักสูตรอิสลามศึกษาตามหลักสูตรแกนกลาง การศึกษาขั้นพื้นฐาน พุทธศักราช 2551 ในสถานศึกษา สังกัดสำนักงานเขตพื้นที่การศึกษา ประถมศึกษาปัตตานี เขต 2 ให้มีประสิทธิภาพ ควรมีแนวทาง ดังนี้ 1) การจัดการเรียนการสอนแบบ บูรณาการรายวิชา 2) การเลือกเครื่องมือการเรียนรู้ สื่อทำมือ และสื่อเทคโนโลยีต่าง ๆ ที่เหมาะสม สำหรับการเรียนรู้อิสลามศึกษา 3) การสนับสนุนจากหน่วยงานที่เกี่ยวข้องโดยเฉพาะด้านงบประมาณ ในการจัดสรรทรัพยากรต่าง ๆ เช่น หนังสือเรียน บุคลากรหรือวิทยากรอิสลามศึกษา การอบรมและ สัมมนา 4) การสร้างกิจกรรมการเรียนรู้อิสลามศึกษาโดยการออกแบบกิจกรรมที่สนับสนุนการเรียนรู้ และทักษะต่าง ๆ เพื่อให้ผู้เรียนได้รับประสบการณ์จริงและสามารถปฏิบัติได้ (5) การวัดและ ประเมินผลด้วยวิธีที่หลายหลาย เช่น การใช้แบบทดสอบเพื่อวัดความความรู้ความเข้าใจในเนื้อหาที่ เรียนและแบบสังเกตเพื่อประเมินการปฏิบัติตามหลักศาสนาอิสลาม 6) การติดตามการใช้หลักสูตร อิสลามศึกษาโดยการนิเทศติดตามและประเมินความคืบหน้าตามเป้าหมายที่กำหนดไว้ และ 7) การ ปรับปรุงและพัฒนาหลักสูตรอิสลามศึกษาผ่านการทบทวนหลักสูตรและจัดกิจกรรมปรับปรุงการ เรียนรู้ตามผลการประเมิน</div>\r\n</div>\r\n<div class=\"row text-left\">\r\n<div class=\"col-sm-2\">&nbsp;</div>\r\n<div class=\"col-sm-10\"><em>Abstract:</em> This study is survey research and aims to 1) examine the problems relating to the implementation of Islamic education curriculum based on the basic education core curriculum of B.E. 2551, 2) assess the utilization of Islamic education curriculum based on the basic education core curriculum of B.E. 2551, and 3) study the guidelines for effective implementation of Islamic education curriculum based on the basic education core curriculum of B.E. 2551 in schools under Pattani Primary Educational Service Area Office 2, using Stufflebeam&rsquo;s model CIPP (Context, Input, Process, and Product). The sample includes six qualified individuals who were purposively selected based on their qualifications and expertise related to the curriculum. 100 teachers who teach Islamic education curriculum based on the basic education core curriculum of the B.E. 2551 in schools under Pattani Primary Educational Service Area Office 2 were randomly selected. The research tools consist of an online questionnaire (Google Forms) and semi-structured interviews. The study findings revealed the following: 1. Results of analysis of the problems relating to the implementation of Islamic education curriculum based on the basic education core curriculum of B.E. 2551 in Pattani Primary Educational Service Area Office 2 as follows: (1) the curriculum has an overwhelming amount of subjects, including general and religious subjects, which results in inadequate teaching time, (2) some teachers lack specialized qualifications, causing them to ineffectively transmit knowledge and develop appropriate learning plans, (3) budget allocation for Islamic education is insufficient, resulting in a lack of textbooks and teaching materials. 2. The overall and each item score levels of teachers&rsquo; opinion on the assessment of the use of Islamic education curriculum based on the basic education core curriculum of the B.E. 2551 in four aspects: context, input, processes, and outcomes were high. 3. The results of the analysis of guidelines for effective implementing Islamic education curriculum based on the basic education core curriculum of the B.E. 2551 in schools under Pattani Primary Educational Service Area Office 2 as follows: 1) the method of instruction and learning used was subject-integrated; 2) choosing appropriate learning tools, such as hands-on or interactive materials and digital media, for Islamic instruction; 3) securing funding for textbooks, staff, Islamic education instructors, training sessions, and seminars, among other things, from pertinent organizations; 4) creating educational activities that help students learn and grow in a variety of areas so they can acquire real-world experience and useful skills; 5) utilizing a variety of asseesment and measurement techniques, such as tests to measure students&rsquo; knowledge and comprehension of the contents learned and observation assessment form to assess their application of Islamic principles; 6) following up Islamic education curriculum implementation and monitoring teaching and learning and evaluate their progress according to the established goals; and 7) Islamic education curriculum was revised and activities were arranged in accordance with assessement findings.</div>\r\n</div>', 'สาขาการบริหารและการจัดการการศึกษาอิสลาม', '', 'https://kb.psu.ac.th/items/fbd0b55d-0ce7-420c-bc66-bf9d5d7a22ef', 'มหาวิทยาลัยสงขลานครินทร์ วิทยาเขตปัตตานี'),
('ITM00000000008', 'การพัฒนารูปแบบการบูรณาการการแพร่กระจายนวัตกรรมและการประชาสัมพันธ์สำหรับบัณฑิตอาสา เพื่อสร้างความตระหนักรู้และความเข้าใจในการแก้ไขปัญหาและพัฒนาจังหวัดชายแดนภาคใต้ของศูนย์อำนวยการบริหารจังหวัดชายแดนภาคใต้', 'COM00000000006', 'COM00000000002', 'Development of Innovation Diffusion and Public Relations Integration Model for Bundit Arsa to Create Awareness and Understanding in Solving Problems and Developing the Southern Most Provinces of the Southern Border Provinces Administrative Center', NULL, 10, '2566', '', '<div class=\"row text-left\">\r\n<div class=\"col-sm-10\">การวิจัยนี้เป็นการวิจัยและพัฒนา มีเป้าหมายเพื่อพัฒนานวัตกรรมการบูรณาการการ แพร่กระจายนวัตกรรมและการประชาสัมพันธ์สำหรับบัณฑิตอาสาเพื่อสร้างความตระหนักรู้และความ เข้าใจในการแก้ไขปัญหาและพัฒนาจังหวัดชายแดนภาคใต้ของศูนย์อำนวยการบริหารจังหวัดชายแดน ภาคใต้ (ศอ.บต.) ดำเนินการวิจัยโดยอาศัยการมีส่วนร่วมกับผู้มีส่วนได้ส่วนเสียและผู้ที่เกี่ยวข้องได้แก่ บุคลากรภาครัฐ บัณฑิตอาสา ประชาชนและผู้เชี่ยวชาญด้านการประชาสัมพันธ์และเทคโนโลยี เก็บ รวบรวมข้อมูลโดยแบบสำรวจ การสัมภาษณ์ การสนทนากลุ่ม การฝึกอบรมและการทดลองปฏิบัติ วิเคราะห์ข้อมูลโดยการวิเคราะห์สถิติเชิงพรรณนา การวิเคราะห์ค่า PNI และการวิเคราะห์เนื้อหา ผลการวิจัยนำไปสู่รูปแบบการบูรณาการการแพร่กระจายนวัตกรรมการประชาสัมพันธ์ที่เหมาะสม ได้แก่ STCRIE ประกอบด้วย Setting คือ การเตรียมความพร้อมในเรื่ององค์ประกอบที่สำคัญในการดำเนินการการบูรณา การการแพร่กระจายนวัตกรรมและการประชาสัมพันธ์สำหรับบัณฑิตอาสา ได้แก่ การมีทีม (T-Team) การมีช่องทางสื่อสาร (C-Channel) การสนับสนุนสิ่งอำนวยความสะดวกและการบริหารจัดการ (S-Support) และตัวแทนในการเป็นผู้นำการเปลี่ยนแปลง (R-Representative) ได้แก่ บัณฑิตอาสา Training คือ การฝึกอบรมและพัฒนาตัวบุคคลที่ทำหน้าที่ในการดำเนินการในทักษะที่ จำเป็น เช่น ทักษะในการสื่อสาร การพูดในที่ชุมชน การผลิตสื่อ การผลิตคอนเทนต์ต่างๆ เป็นต้น Creating คือ การสร้างสรรค์สื่อคอนเทนต์ หรือ การเปลี่ยนข้อมูลข่าวสารที่มีในรูปแบบ เอกสารเป็นสื่ออิเล็กทรอนิกส์รูปแบบที่หลากหลาย ที่น่าสนใจ ซึ่งต้องเป็นเรื่องที่เกี่ยวข้องกับการใช้ ชีวิตประจำวัน สุขภาพ การศึกษา การทำงาน รวมถึงโอกาสพิเศษต่าง ๆ Relationship คือ การสร้างความสัมพันธ์ในชุมชน ที่เป็นฐานสำคัญในการพัฒนาและสร้าง ความก้าวหน้าให้แก่ชุมชน Integration of innovation diffusion and public relations คือ ขั้นการดำเนินกล ยุทธ์และปฏิบัติการในการการแพร่กระจายนวัตกรรมและการประชาสัมพันธ์ Evaluation คือ การประเมินระหว่างดำเนินการแต่ละขั้น เพื่อที่จะแก้ไขข้อบกพร่องในการ ดำเนินการ และการประเมินหลังเสร็จสิ้นการดำเนินการ เพื่อสรุปผลการแพร่กระจายนวัตกรรม</div>\r\n</div>\r\n<div class=\"row text-left\">\r\n<div class=\"col-sm-2\">&nbsp;</div>\r\n<div class=\"col-sm-10\"><em>Abstract:</em> This research and development aimed to develop the innovation of integration of Innovation diffusion and public relations for Bandit Arsa to develop awareness and understanding in problem solving and developing the southern most provinces under the Southern Border Provinces Administrative Center (SBPAC). It was conducted through participation among stakeholders and contributors namely government personnel, Bandit Arsa, citizens and professionals of public relations and technology. Data were collected using surveys, interviews, discussions, training and practicality. The descriptive analysis, PNI values analysis and content analysis were used for the data analysis. The findings indicated the STCRIE model of integration of innovation diffusion and public relation - which consisted of: Setting referred to the preparation of necessary key elements in diffusion of innovation and public relation process for Bandit Arsa. The key elements included Team (T-Team), Communication channels (C-Channel), Support of facility and management (S-Support) and volunteers in leading changes of Bandit Arsa (R-Representative). Training was the training and developing important skills for particular person who took responsibility in each task i.e., communication skill, public speaking skill, media and content productions skill and etc. Creating was media and content production or the ability to change the available information in form of documents into any kind of interesting electronic media related to daily life, health, education, job and any special occasion. Relationship was to build up with the community during the process of integration. Integration of innovation diffusion and public relations was the strategic management and action in the community. Evaluation was to perform every single step to solve any defects in each process and the evaluation after completing all the processes to summarize the result of innovation diffusion. Abstract(Thai): การวิจัยนี้เป็นการวิจัยและพัฒนา มี</div>\r\n</div>', 'สาขาวิชาภาวะผู้นำและนวัตกรรมทางการศึกษาภาวะผู้นำและนวัตกรรมทางการศึกษา', '', 'https://kb.psu.ac.th/items/3b248a82-628b-482e-bacc-efd1b9322494', 'มหาวิทยาลัยสงขลานครินทร์ วิทยาเขตปัตตานี'),
('ITM00000000009', 'การพัฒนารูปแบบสิ่งแวดล้อมการเรียนรู้แบบเสมือนด้วยกระบวนการออกแบบวิศวกรรมที่ส่งเสริมทักษะความคิดสร้างสรรค์ สำหรับนักเรียนชั้นมัธยมศึกษาปีที่ 3', 'COM00000000012', 'COM00000000002', 'Development of Virtual Learning Environment Model with Engineering Design Process to Enhance Creative Thinking Skills for Ninth Grade Students', NULL, 10, '2566', '', '<div class=\"row text-left\">\r\n<div class=\"col-sm-10\">การวิจัยในครั้งนี้มีวัตถุประสงค์ 1) เพื่อพัฒนารูปแบบสิ่งแวดล้อมการเรียนรู้แบบเสมือนด้วยกระบวนการออกแบบวิศวกรรมที่ส่งเสริมทักษะความคิดสร้างสรรค์ สำหรับนักเรียนชั้นมัธยมศึกษาปีที่ 3 2) เพื่อศึกษาผลการใช้สิ่งแวดล้อมการเรียนรู้แบบเสมือนด้วยกระบวนการออกแบบวิศวกรรมที่ส่งเสริมทักษะความคิดสร้างสรรค์ สำหรับนักเรียนชั้นมัธยมศึกษาปีที่ 3 กลุ่มตัวอย่างที่ใช้ในการวิจัย คือ นักเรียนชั้นมัธยมศึกษาปีที่ 3 โรงเรียนเบญจมราชูทิศ จังหวัดปัตตานี จำนวน 1 ห้องเรียน มีนักเรียน 39 คน ใช้วิธีการสุ่มแบบกลุ่ม (Cluster Random Sampling) โดยใช้ห้องเรียนเป็นหน่วยของการสุ่ม (Sampling Unit) จากห้องเรียน จำนวน 10 ห้องเรียน เครื่องมือที่ใช้ ในการวิจัย ได้แก่ รูปแบบสิ่งแวดล้อมการเรียนรู้แบบเสมือนด้วยกระบวนการออกแบบวิศวกรรม สิ่งแวดล้อม การเรียนรู้แบบเสมือนด้วยกระบวนการออกแบบวิศวกรรม แผนการจัดกิจกรรมการเรียนรู้ เครื่องมือที่ใช้ในการเก็บรวบรวมข้อมูล ได้แก่ แบบประเมินความเหมาะสมของรูปแบบสิ่งแวดล้อมการเรียนรู้แบบเสมือนด้วยกระบวนการออกแบบวิศวกรรม แบบประเมินคุณภาพของสิ่งแวดล้อมการเรียนรู้แบบเสมือนด้วยกระบวนการออกแบบวิศวกรรม แบบประเมินคุณภาพของแผนการจัดกิจกรรมการเรียนรู้ แบบประเมินทักษะความคิดสร้างสรรค์ วิเคราะห์ข้อมูล โดยใช้สถิติเชิงพรรณนา ได้แก่ ค่าเฉลี่ย ส่วนเบี่ยงเบนมาตรฐาน ร้อยละ การวิเคราะห์ความแปรปรวนทางเดียว แบบวัดซ้ำ (One-way repeated measure ANOVA) และการเปรียบเทียบรายคู่ด้วยวิธีทดสอบแบบ Bonferroni ผลการวิจัยพบว่า (1) รูปแบบสิ่งแวดล้อมการเรียนรู้แบบเสมือนด้วยกระบวนการออกแบบวิศวกรรม มี 2 องค์ประกอบหลัก ได้แก่ สิ่งแวดล้อมการเรียนรู้แบบเสมือน และกระบวนการออกแบบวิศวกรรม ซึ่งแต่ละส่วนมีองค์ประกอบย่อย ดังนี้ สิ่งแวดล้อมการเรียนรู้แบบเสมือนมี 5 องค์ประกอบ ได้แก่ 1) การติดต่อ สื่อสาร 2) การทำงานร่วมกัน 3) การแบ่งปันทรัพยากร 4) การสะท้อนคิดสร้างสรรค์ 5) การสนับสนุนผู้เรียน และกระบวนการออกแบบวิศวกรรมมี 5 ขั้นตอน ได้แก่ 1) ขั้นการกำหนดปัญหา 2) ขั้นการออกแบบ 3) ขั้น การพัฒนา 4) ขั้นการประเมินผล 5) ขั้นการนำเสนอ และมีผลการประเมินความเหมาะสมของรูปแบบสิ่งแวดล้อมการเรียนรู้แบบเสมือนด้วยกระบวนการออกแบบวิศวกรรมอยู่ในระดับมาก (2) ผลการใช้สิ่งแวดล้อมการเรียนรู้ แบบเสมือนด้วยกระบวนการออกแบบวิศวกรรม พบว่า ทักษะความคิดสร้างสรรค์ของนักเรียนครั้งที่ 1 มีค่าเท่ากับ 64.76 ครั้งที่ 2 มีค่าเท่ากับ 75.14 และครั้งที่ 3 มีค่าเท่ากับ 91.19 สูงขึ้น อย่างมีนัยสำคัญทางสถิติที่ระดับ .01</div>\r\n</div>\r\n<div class=\"row text-left\">\r\n<div class=\"col-sm-2\">&nbsp;</div>\r\n<div class=\"col-sm-10\"><em>Abstract:</em> The objectives of this research were 1) to develop a virtual learning environment model with engineering design process to enhance creative thinking skills for ninth grade students and 2) to examine the outcomes of utilizing the virtual learning environment model with engineering design process to enhance creative thinking skills for ninth grade students. The sample group for this research consisted of one classroom comprising 39 students from the ninth grade at Benjamarachutit Pattani School. The selection of the classroom was done using cluster random sampling, with a total of 10 classrooms considered and the classroom serving as the sampling unit. The research instruments included a virtual learning environment model with engineering design process, a virtual learning environment with engineering design process, and a lesson plan. Data were gathered through a suitability assessment of the virtual learning environment model with engineering design process, a quality assessment of the virtual learning environment with engineering design process, a quality assessment of the lesson plan, and an assessment of creative thinking skills. Subsequently, the collected data were analyzed using descriptive statistics, including mean, standard deviation, and percentage, as well as one-way repeated measure ANOVA and pairwise comparison using the Bonferroni method. The findings revealed that a virtual learning environment with engineering design process consisted of two core components: a virtual learning environment and an engineering design process. Each component contained specific sub-elements. The virtual learning environment encompassed five sub-elements: 1) communication, 2) collaboration, 3) resource sharing, 4) creative reflection, and 5) learner support. The engineering design process involved five steps: 1) problem definition, 2) design, 3) development, 4) evaluation, and 5) presentation. An evaluation indicated that the suitability of the virtual learning environment model with engineering design process to enhance creative thinking skills was at a high level. Furthermore, the results showed that the utilization of the virtual learning environment with engineering design process significantly improved students\' creative thinking skills. The average score increased from 64.76 in the first assessment to 75.14 in the second assessment and further rose to 91.19 in the third assessment. This improvement was statistically significant at the significance level of .01.</div>\r\n</div>', '', '', '', ''),
('ITM00000000011', 'การพัฒนาการศึกษาออนไลน์ระบบเปิดสำหรับมหาชน เรื่อง การอยู่ร่วมกันในบริบทสังคมพหุวัฒนธรรม เพื่อส่งเสริมพฤติกรรมการสร้างความรู้และความตระหนักในคุณค่าทางวัฒนธรรม สำหรับผู้เรียนระดับอุดมศึกษา', 'COM00000000008', 'COM00000000002', 'Development of Massive Open Online Course on Coexistence in Multicultural Society to Promote Knowledge Construction and Awareness of Cultural Values for Undergraduate Students', NULL, 11, '2566', '', '<div class=\"row text-left\">\r\n<div class=\"col-sm-10\">การวิจัยครั้งนี้มีวัตถุประสงค์เพื่อ 1) พัฒนาการศึกษาออนไลน์ระบบเปิดสำหรับ มหาชน เรื่องการอยู่ร่วมกันในบริบทสังคมพหุวัฒนธรรม เพื่อส่งเสริมพฤติกรรมการสร้างความรู้และ ความตระหนักในคุณค่าทางวัฒนธรรม สำหรับผู้เรียนระดับอุดมศึกษา 2) ศึกษาพฤติกรรมการสร้าง ความรู้ของผู้เรียนระดับอุดมศึกษาก่อนเรียนและหลังเรียนด้วยการศึกษาออนไลน์ระบบเปิดสำหรับ มหาชน เรื่องการอยู่ร่วมกันในบริบทสังคมพหุวัฒนธรรม 3) ศึกษาความตระหนักในคุณค่าทาง วัฒนธรรมของผู้เรียนระดับอุดมศึกษาก่อนเรียนและหลังเรียนด้วยการศึกษาออนไลน์ระบบเปิด สำหรับมหาชน เรื่องการอยู่ร่วมกันในบริบทสังคมพหุวัฒนธรรม และ 4) ศึกษาความพึงพอใจของ ผู้เรียนในระดับอุดมศึกษาที่เรียนด้วยการศึกษาออนไลน์ระบบเปิดสำหรับมหาชน เรื่องการอยู่ร่วมกัน ในบริบทสังคมพหุวัฒนธรรม กลุ่มเป้าหมายที่ใช้ในการวิจัยประกอบด้วย นักศึกษาปริญญาตรีจำนวน 60 คน เครื่องมือที่ใช้ในการวิจัยประกอบไปด้วย 1) การศึกษาออนไลน์ระบบเปิดสำหรับมหาชน เรื่อง การอยู่ร่วมกันในบริบทสังคมพหุวัฒนธรรม 2) แบบวัดพฤติกรรมการสร้างความรู้3) แบบวัดความตระหนัก ในคุณค่าทางวัฒนธรรม และ 4) แบบประเมินความพึงพอใจ ผลการวิจัยพบว่า 1) การศึกษาออนไลน์ระบบเปิดสำหรับมหาชน เรื่องการ อยู่ร่วมกันในบริบทสังคมพหุวัฒนธรรม มีระดับความเหมาะสมอยู่ในระดับมากที่สุด (</div>\r\n</div>', '', '', '', ''),
('ITM00000000012', 'การพัฒนาการศึกษาออนไลน์ระบบเปิดสำหรับมหาชน เรื่อง การบริโภคของชาวมุสลิม เพื่อส่งเสริมพฤติกรรมการสร้างความรู้สำหรับบุคคลทั่วไป', 'COM00000000012', 'COM00000000002', 'Development of Massive Open Online Course on Muslim Way of Life in Food Consumption to Promote Knowledge Construction for General Public', NULL, 11, '2566', '', '<div class=\"row text-left\">\r\n<div class=\"col-sm-10\">การวิจัยครั้งนี้มีวัตถุประสงค์เพื่อ 1) พัฒนาการศึกษาออนไลน์ระบบเปิดสำหรับ มหาชน เรื่องการอยู่ร่วมกันในบริบทสังคมพหุวัฒนธรรม เพื่อส่งเสริมพฤติกรรมการสร้างความรู้และ ความตระหนักในคุณค่าทางวัฒนธรรม สำหรับผู้เรียนระดับอุดมศึกษา 2) ศึกษาพฤติกรรมการสร้าง ความรู้ของผู้เรียนระดับอุดมศึกษาก่อนเรียนและหลังเรียนด้วยการศึกษาออนไลน์ระบบเปิดสำหรับ มหาชน เรื่องการอยู่ร่วมกันในบริบทสังคมพหุวัฒนธรรม 3) ศึกษาความตระหนักในคุณค่าทาง วัฒนธรรมของผู้เรียนระดับอุดมศึกษาก่อนเรียนและหลังเรียนด้วยการศึกษาออนไลน์ระบบเปิด สำหรับมหาชน เรื่องการอยู่ร่วมกันในบริบทสังคมพหุวัฒนธรรม และ 4) ศึกษาความพึงพอใจของ ผู้เรียนในระดับอุดมศึกษาที่เรียนด้วยการศึกษาออนไลน์ระบบเปิดสำหรับมหาชน เรื่องการอยู่ร่วมกัน ในบริบทสังคมพหุวัฒนธรรม กลุ่มเป้าหมายที่ใช้ในการวิจัยประกอบด้วย นักศึกษาปริญญาตรีจำนวน 60 คน เครื่องมือที่ใช้ในการวิจัยประกอบไปด้วย 1) การศึกษาออนไลน์ระบบเปิดสำหรับมหาชน เรื่อง การอยู่ร่วมกันในบริบทสังคมพหุวัฒนธรรม 2) แบบวัดพฤติกรรมการสร้างความรู้3) แบบวัดความตระหนัก ในคุณค่าทางวัฒนธรรม และ 4) แบบประเมินความพึงพอใจ ผลการวิจัยพบว่า 1) การศึกษาออนไลน์ระบบเปิดสำหรับมหาชน เรื่องการ อยู่ร่วมกันในบริบทสังคมพหุวัฒนธรรม มีระดับความเหมาะสมอยู่ในระดับมากที่สุด (</div>\r\n</div>', 'สาขาวิชาเทคโนโลยีและสื่อสารการศึกษา', '', 'https://kb.psu.ac.th/items/859630c9-c851-4c59-926e-0cbd235f347b', 'มหาวิทยาลัยสงขลานครินทร์ วิทยาเขตปัตตานี'),
('ITM00000000013', 'การพัฒนาการศึกษาออนไลน์ระบบเปิดสำหรับมหาชนที่บูรณาการพอแคสต์เรื่องการพยาบาลผู้ป่วยภาวะหัวใจเต้นผิดจังหวะและการอ่านผลคลื่นไฟฟ้าหัวใจเพื่อส่งเสริมพฤติกรรมการสร้างความรู้ของนักศึกษาพยาบาลศาสตรบัณฑิต', 'COM00000000002', 'COM00000000002', 'Development of Massive Open Online Course integrating with Podcasts on Nursing care Patients with Arrhythmia and Electrocardiogram Intervention to Promote Knowledge Construction of Nursing Students', NULL, 11, '2566', '', '<div class=\"row text-left\">\r\n<div class=\"col-sm-10\">การวิจัยครั้งนี้มีวัตถุประสงค์เพื่อ 1 ) พัฒนาการพัฒนาการศึกษาออนไลน์ระบบเปิด สำหรับมหาชนที่บูรณาการพอดแคสต์เรื่อง การพยาบาลผู้ป่วยภาวะหัวใจเต้นผิดจังหวะและการอ่าน ผลคลื่นไฟฟ้าหัวใจเพื่อส่งเสริมพฤติกรรมการสร้างความรู้ของนักศึกษาพยาบาลศาสตรบัณฑิต 2 ) ศึกษาพฤติกรรมการสร้างความรู้ของนักศึกษาพยาบาลศาสตรบัณฑิต 3 ) ศึกษาผลสัมฤทธิ์ทางการ เรียนรู้ก่อนและหลังเรียน 4 ) ศึกษาความพึงพอใจของนักศึกษาพยาบาลศาสตรบัณฑิตต่อการศึกษา ออนไลน์ระบบเปิดสำหรับมหาชนที่บูรณาการพอดแคสต์โดยมีกลุ่มตัวอย่างคือนักศึกษาพยาบาล หลักสูตรพยาบาลศาสตรบัณฑิต ชั้นปีที่ 3 คณะพยาบาลศาสตร์มหาวิทยาลัยสงขลานครินทร์ที่มีความ ยินดีให้ความร่วมมือในการวิจัย โดยเครื่องมือที่ใช้ในการวิจัยประกอบไปด้วย 1) แบบทดสอบ เรื่อง การพยาบาลผู้ป่วยภาวะหัวใจเต้นผิดจังหวะและการอ่านผลคลื่นไฟฟ้าหัวใจ 2 ) แบบวัดพฤติกรรมการ สร้างความรู้ และ 3 ) แบบประเมินความพึงพอใจ ผลการวิจัยพบว่า 1 ) ตัวการศึกษาออนไลน์ระบบเปิดสำหรับมหาชนที่บูรณาการ พอดแคสต์เรื่อง การพยาบาลผู้ป่วยภาวะหัวใจเต้นผิดจังหวะและการอ่านผลคลื่นไฟฟ้า มีระดับความ เหมาะสมอยู่ในระดับมากที่สุด (</div>\r\n</div>', '', '', 'https://kb.psu.ac.th/items/5e7b9dae-1b3d-491d-bf45-9dd5e8cf2fbe', '');
INSERT INTO `tb_item` (`item_id`, `item_title`, `community_id`, `collection_id`, `item_alternative`, `item_issued_day`, `item_issued_month`, `item_issued_year`, `item_description`, `item_abstract`, `item_sponsorship`, `item_citation`, `item_uri`, `item_publisher`) VALUES
('ITM00000000014', 'การพัฒนาโปรแกรมการฝึกออกกำลังกายโดยใช้น้ำหนักตัวเพื่อสร้างเสริมสุขสมรรถนะสำหรับนักเรียนชั้นประถมศึกษาตอนปลายในจังหวัดปัตตานี', 'COM00000000012', 'COM00000000002', 'Development of Body Weight Exercise Program for Health Related Physical Fitness for Upper Elementary Students in Pattani Province', NULL, 11, '2566', '', '<div class=\"row text-left\">\r\n<div class=\"col-sm-10\">การศึกษาวิจัยในครั้งนี้ มีวัตถุประสงค์เพื่อ 1) พัฒนาโปรแกรมการฝึกออกกำลังกายโดยใช้น้ำหนักตัวสำหรับนักเรียนชั้นประถมศึกษาตอนปลายในจังหวัดภาคใต้ชายแดน 2) เปรียบเทียบสุขสมรรถนะก่อนและหลังการใช้โปรแกรมการฝึกออกกำลังกายโดยใช้น้ำหนักตัวภายในกลุ่มทดลองและกลุ่มควบคุม 3) เปรียบเทียบสุขสมรรถนะสำหรับนักเรียนชั้นประถมศึกษาตอนปลายระหว่างนักเรียนที่ใช้โปรแกรมการฝึกออกกำลังกายโดยใช้น้ำหนักตัวกับกลุ่มควบคุม กลุ่มตัวอย่างเป็นนักเรียนชั้นประถมศึกษาปีที่ 5 โรงเรียนเมืองปัตตานี ปีการศึกษา 2564 มีอายุ 10-12 ปี ซึ่งการเลือกกลุ่มตัวอย่างในครั้งนี้ได้มาโดยใช้วิธีการสุ่มตัวอย่างแบบหลายขั้นตอน (Multi-stage Random Sampling) จำนวน 46 คน แบ่งเป็น 2 กลุ่ม กลุ่มที่ 1 ควบคุมจำนวน 23 คน มีอายุเฉลี่ย 11.0 ปี ส่วนสูงเฉลี่ย 144.39 ซม. และมีน้ำหนักตัวเฉลี่ย 38.23 กก. กลุ่มที่ 2 กลุ่มทดลองจำนวน 23 คน มีอายุเฉลี่ย 11.13 ปี ส่วนสูงเฉลี่ย 144.87 ซม. และมีน้ำหนักตัวเฉลี่ย 38.35 กก. ทำการฝึกออกกำลังกายโดยใช้น้ำหนักตัว เป็นเวลา 8 สัปดาห์ ๆ ละ 2 วัน เครื่องมือที่ใช้ในการทดลองได้แก่ 1) โปรแกรม การฝึกออกกำลังกายโดยใช้น้ำหนักตัว จำนวน 24 ท่า โดยแบ่งตามกลุ่มของกล้ามเนื้อจำนวน 6 กลุ่ม ในแต่ละกลุ่มของกล้ามเนื้อจะมีท่าในการออกกำลังกายจำนวน 4 ท่า ยกตัวอย่าง เช่น กลุ่มกล้ามเนื้อหน้าอก : มัดกล้ามเนื้อหน้าอก (Pectoralis) ประกอบด้วยท่าการฝึกออกกำลังกายโดยใช้น้ำหนักตัว ได้แก่ 1) Push-Ups 2) Plank Rotations 3) Chest Squeezes 4) Shoulder Taps 2) แบบทดสอบสุขสมรรถนะมาตรฐานนานาชาติ (International Committee for the Standardization of Physical Fitness Test หรือ ICSPFT) และ 3) แบบทดสอบและเกณฑ์มาตรฐานสุขสมรรถนะของนักเรียน ระดับประถมศึกษา (อายุ 7 - 12 ปี) ของสำนักวิทยาศาสตร์การกีฬา กรมพลศึกษา กระทรวงการท่องเที่ยวและกีฬา ผลการวิจัยพบว่า 1. ผลการพัฒนาโปรแกรมการฝึกออกกำลังกายโดยใช้น้ำหนักตัว เพื่อสร้างเสริมสุขสมรรถนะ สำหรับนักเรียนชั้นประถมศึกษาตอนปลายในจังหวัดปัตตานี โดยมีค่าดัชนีความสอดคล้อง (IOC) เท่ากับ 0.80 ประกอบด้วย 1) รูปแบบการฝึกวิธีการฝึกแบบแรงต้าน (Resistance training) โดยใช้น้ำหนักตัว (Body weight exercise) 2) หลักการออกกำลังกาย (Principle of Exercise) ของ American College of Medicine (ACSM, 2018) 3) หลักการฝึก (Principle of Training) โดยใช้ หลักการฝึกแบบก้าวหน้า (Progressive of Training) โดยการเพิ่มจำนวน set ของการฝึกจาก 2 set ในสัปดาห์ที่ 1-4 เป็น 3 set ในสัปดาห์ที่ 5- 8 และใช้การฝึกแบบหลากหลาย (Verities of Training) ในการกำหนดชุดการฝึกให้มีท่าทางที่หลากหลายสำหรับการฝึกในเด็ก และ 4) โปรแกรมการฝึกเป็นรูปแบบการฝึกทั้งตัว (Full body workout) โดยพัฒนาส่วนต่าง ๆ ประกอบด้วย กลุ่มของกล้ามเนื้ออก, กลุ่มของกล้ามเนื้อขา, กลุ่มของกล้ามเนื้อท้อง, กลุ่มของกล้ามเนื้อหลัง, กลุ่มของกล้ามเนื้อแขน, กลุ่มของกล้ามเนื้อสะโพก โดยแต่ละกลุ่มของกล้ามเนื้อ 2. ผลการเปรียบเทียบค่าเฉลี่ยสุขสมรรถนะก่อนและหลังการใช้โปรแกรมการฝึกออกกำลังกายโดยใช้น้ำหนักตัวสำหรับนักเรียนชั้นประถมศึกษาตอนปลายในจังหวัดปัตตานี พบว่าภายหลังการฝึกนักเรียนชายและนักเรียนหญิงที่ใช้โปรแกรมการฝึกออกกำลังกายโดยใช้น้ำหนักตัว มีมวลของกล้ามเนื้อ, ความแข็งแรงของกล้ามเนื้อ, ความอดทนของกล้ามเนื้อ และความอดทนของระบบไหลเวียนและหายใจ เพิ่มขึ้นอย่างมีนัยสำคัญทางสถิติที่ระดับ.01 ส่วนเปอร์เซ็นต์ไขมันร่างกาย ลดลงอย่างมีนัยสำคัญทางสถิติที่ระดับ .01 สำหรับดัชนีมวลกาย และอัตราเส้นรอบเอวต่อรอบไม่พบความแตกต่างทางสถิติที่ระดับนัยสำคัญ .01 ทั้งนักเรียนหญิงและนักเรียนชาย ส่วนความอ่อนตัวของนักเรียนหญิง ภายหลังการใช้โปรแกรมการฝึกออกกำลังกายโดยใช้น้ำหนักตัวไม่พบความแตกต่างกัน 3. ผลการเปรียบเทียบสุขสมรรถนะสำหรับนักเรียนชั้นประถมศึกษาตอนปลายระหว่างนักเรียนที่ใช้โปรแกรมการฝึกออกกำลังกายโดยใช้น้ำหนักตัวกับนักเรียนที่ออกกำลังกายปกติ พบว่า ค่าเฉลี่ยของสุขสมรรถนะระหว่างนักเรียนชายที่ออกกำลังกายตามปกติ และนักเรียนชายที่ใช้โปรแกรมการฝึกออกกำลังกายโดยใช้น้ำหนักตัว มีความแข็งแรงของกล้ามเนื้อและความอดทนของกล้ามเนื้อ ในรายการลุก-นั่ง 30 วินาที และวิ่งเร็ว 50 เมตร แตกต่างอย่างมีนัยสำคัญทางสถิติที่ระดับ .05 ส่วนองค์ประกอบของร่างกาย, ความอ่อนตัว และความแข็งแรงของกล้ามเนื้อ ในรายการแรงบีบมือ ไม่พบความแตกต่างอย่างมีนัยสำคัญทางสถิติที่ระดับ .05 สำหรับนักเรียนหญิงที่ใช้โปรแกรมการฝึกออกกำลังกายโดยใช้น้ำหนักตัว (กลุ่มทดลอง) ภายหลังการฝึกไม่พบความแตกต่างกันในทุกรายการ คำสำคัญ : การฝึกด้วยน้ำหนักโดยใช้น้ำหนักตัว, สุขสมรรถนะ, นักเรียนชั้นประถมศึกษาตอนปลาย</div>\r\n</div>\r\n<div class=\"row text-left\">\r\n<div class=\"col-sm-2\">&nbsp;</div>\r\n<div class=\"col-sm-10\"><em>Abstract:</em> The purpose of this research was to 1) To development the body weight exercise programs for Health Related physical fitness in Pattani Province upper elementary students. 2) To compare Health Related physical fitness between before and after training program in experimental and control groups. 3) To compare Health Related physical fitness between experimental and control groups after training program. 46 upper elementary students&rsquo; boy and girl aged 10-12 years and randomly assigned into two groups. Group I: 23 upper elementary students are Control Group (CG) mean (age 11 years, height 144.39 cm, Weight 39.23 kg). Group II: 23 upper elementary students are Experimental Group (EG) (Body weight training programs workout 8 weeks, 2 days/ week) mean (age 11.13 years, height 144.87 cm, Weight 38.35 kg). The data for the studies was found that 1. The results of the development of a bodyweight exercise program to enhance well-being for students in upper primary school in Pattani Province The consistency index (IOC) was 0.80 consisting of 1) Resistance training exercises using body weight exercises. 2) The principle of exercise (Principle of Exercise) of the American College of Medicine (ACSM, 2018) 3) The principle of training using progressive training by increasing the number of sets of training from 2 sets at weeks 1-4 to 3 sets, at weeks 5-8 and use variations of training to define a set of different postures for pediatric training; and 4) The training program is a full body workout by developing different parts, consisting of pectoral muscle group, leg muscle group, abdominal muscle group, back muscle group, muscle group. forearm, hip muscle group by each muscle group 2. There was a statistically significant increase in muscle mass, strength and endurance in and statistically significant decrease in body fat percentage at the .01 level in male students&rsquo; experimental group, while there was no difference in female students&rsquo; experimental group. 3. After training there was found that, the male students&rsquo; experimental group had the muscle mass, flexibility, muscle strength and muscle endurance significantly higher than the control group at the .05 level and the female student experiment group, and the female students&rsquo; experiment group had the muscle mass, flexibility, strength, and endurance significantly higher than the control group at the .05 level. It was concluded that the body weight exercise programs can improved students&rsquo; Health Related physical fitness. Therefore, it should be used the exercise program for promoted student&rsquo;s health their fitness. In addition, the exercise program can also be used in physical education teaching and learning for students to have good physical health. Keywords : body weight training, physical fitness test, upper elementary students</div>\r\n</div>', '', '', '', ''),
('ITM00000000015', 'ทุนทางจิตวิทยาเชิงบวก ความเครียดและปัจจัยที่ส่งผลต่อภาวะหมดไฟในการทำงาน ของบุคลากรสายสนับสนุนวิทยาลัยการสาธารณสุขสิรินธร ในสังกัดสถาบันพระบรมราชชนก', 'COM00000000002', 'COM00000000002', 'Positive Psychological Capital, Stress and Factors Affecting Burnout among Support Staff at Sirindhorn College of Public Health, the Affiliation Praboromarajchanok Institute.', NULL, 11, '2566', '', '<div class=\"row text-left\">\r\n<div class=\"col-sm-10\">การศึกษาวิจัยครั้งนี้ มีวัตถุประสงค์เพื่อศึกษา 1) ระดับทุนทางจิตวิทยาเชิงบวก ความเครียด และภาวะหมดไฟในการทำงานของบุคลากรสายสนับสนุน 2) ความสัมพันธ์ระหว่างปัจจัยส่วนบุคคล ทุนทางจิตวิทยาเชิงบวก ความเครียด และภาวะหมดไฟในการทำงานของบุคลากร สายสนับสนุน 3) ปัจจัยที่ส่งผลต่อภาวะหมดไฟ ของบุคลากรสายสนับสนุน กลุ่มตัวอย่างที่ใช้ในการวิจัย คือ บุคลากรสายสนับสนุน วิทยาลัยการสาธารณสุขสิรินธร ในสังกัดสถาบันพระบรมราชชนก จำนวน 131 คน ประจำปี 2564 วิเคราะห์ข้อมูล ด้วยค่าร้อยละ ค่าเฉลี่ย ค่าส่วนเบี่ยงเบนมาตรฐาน ค่าสัมประสิทธิ์สหสัมพันธ์แบบเพียร์สัน และวิเคราะห์การถดถอยเชิงพหุคูณ ผลการศึกษา พบว่า 1) บุคลากรสายสนับสนุน มีทุนทางจิตวิทยาเชิงบวกโดยรวมอยู่ในระดับมาก (x ̅ = 4.02, SD. = 0.99) มีความเครียดส่วนใหญ่อยู่ในระดับสูง ร้อยละ 36.60 ภาวะหมดไฟในการทำงานส่วนใหญ่อยู่ในระดับต่ำ 2) ภาวะหมดไฟในการทำงานมีความสัมพันธ์เชิงลบระดับปานกลางกับทุนทางจิตวิทยาเชิงบวก (r = -.422) อย่างมีนัยสำคัญทางสถิติที่ระดับ .01 และภาวะหมดไฟในการทำงานมีความสัมพันธ์เชิงบวกระดับปานกลางกับความเครียด (r = .551) อย่างมีนัยสำคัญทางสถิติที่ระดับ .01 และ 3) ตัวแปรอิสระ ที่สามารถร่วมกันพยากรณ์ภาวะหมดไฟในการทำงานของบุคลากรสายสนับสนุน คือ ความเครียด (&beta; = .354) ทุนทางจิตวิทยาเชิงบวก (&beta; = -.334) และระดับการปฏิบัติงาน (&beta; = .222) ได้อย่างมีนัยสำคัญทางสถิติที่ .05</div>\r\n</div>\r\n<div class=\"row text-left\">\r\n<div class=\"col-sm-2\">&nbsp;</div>\r\n<div class=\"col-sm-10\"><em>Abstract:</em> The objective of this research study is to research 1) Positive psychological capital and burnout in the workplace of support staff 2) The relationship between personal factors, positive psychological capital and burnout in the workplace of support staff 3) Burnout factors among support staff. The research sample consists of 131 support personnel from the Sirindhorn College of Public Health, the Institute of Physical Education under the Royal Thai Government on 2022. The data will be analyzed by percentage, average, Standard Deviation, Pearson\'s Correlation Coefficient, and Multiple Regression Analysis. According to the result 1) The support staff have a high overall level of positive psychological capital (x ̅ = 4.02, SD. = 0.99) A majority of the support staff experience high levels of stress, with 36.60%. and low levels of burnout 2) The level of burnout in the workplace has a moderate negative correlation with positive psychological capital (r = -.422) at a significant level of .01 The level of burnout in the workplace has a moderate positive correlation with the level of stress (r = .551) at a significant level of .01 and 3) The independent variable that can be used to predict burnout among support staff is stress. (&beta; = .354) positive psychological capital (&beta; = -.334) and officer lever (&beta; = .222) at a significant level of .05</div>\r\n</div>', '', '', 'https://kb.psu.ac.th/bitstreams/57fefc35-f35d-474e-868d-3f5c716c723d/download', ''),
('ITM00000000016', 'ปัจจัยเชิงสาเหตุที่มีอิทธิพลต่อคุณลักษณะการเป็นผู้ประกอบการของนักศึกษาปริญญาตรี ในสามจังหวัดชายแดนใต้', 'COM00000000009', 'COM00000000002', 'Causal Factors Influencing Entrepreneurship Characteristics of Undergraduate Students in Three Southern Border Provinces', NULL, 0, '2565', '', '<p>การวิจัยครั้งนี้ มีวัตถุประสงค์เพื่อ 1) พัฒนาแบบวัดคุณลักษณะการเป็นผู้ประกอบการของนักศึกษาปริญญาตรีในสามจังหวัดชายแดนใต้2) ตรวจสอบความสอดคล้อง<br>ของโมเดลความสัมพันธ์เชิงสาเหตุตามสมมติฐานกับข้อมูลเชิงประจักษ์3) ศึกษาปัจจัยเชิงสาเหตุที่มีอิทธิพลทั้งทางตรง และอิทธิพลทางอ้อมต่อคุณลักษณะการเป็นผู้ประกอบการของนักศึกษาปริญญาตรีในสามจังหวัดชายแดนใต้กลุ่มตัวอย่างที่ใช้ในการวิจัย คือ นักศึกษาปริญญาตรีในสามจังหวัดชายแดนใต้จำนวน 600 คน เครื่องมือที่ใช้ในการวิจัยเป็นแบบสอบถามมาตรประมาณค่า 5 ระดับสถิติที่ใช้ในการวิเคราะห์ข้อมูล คือ ความถี่ ร้อยละ ค่าเฉลี่ย ส่วนเบี่ยงเบนมาตรฐาน ความเบ้ความโด่ง ค่าสัมประสิทธิ์สหสัมพันธ์แบบเพียร์สัน การวิเคราะห์เส้นทางโดยใช้โปรแกรม LISREL&nbsp;Version 8.72<br>ผลการวิจัยพบว่า<br>1. แบบวัดคุณลักษณะการเป็นผู้ประกอบการของนักศึกษาปริญญาตรีในสามจังหวัดชายแดนใต้มีลักษณะแบบมาตรประมาณค่า 5 ระดับของ Likert มีข้อคำถาม จำนวน 18 ข้อ<br>จำแนกเป็น 5 องค์ประกอบ คือ ความมีนวัตกรรม ความกล้าเสี่ยง การทำงานเชิงรุก ความกล้าที่จะแข่งขัน การมีอิสระในการบริหารงาน ตรวจสอบความตรงเชิงพินิจมีค่าระหว่าง 0.60 ถึง 1.00&nbsp;ค่าความเชื่อมั่นทั้งฉบับเท่ากับ 0.878 และค่าอำนาจจำแนกมีค่าระหว่าง 0.306 ถึง 0.850&nbsp;ผลการวิเคราะห์องค์ประกอบเชิงยืนยัน (CFA) พบว่า โมเดลการวัดคุณลักษณะการเป็นผู้ประกอบการของนักศึกษามีความตรงเชิงโครงสร้าง โมเดลมีความสอดคล้องกลมกลืนกับข้อมูลเชิงประจักษ์<br>2. โมเดลความสัมพันธ์เชิงสาเหตุตามสมมติฐานมีความสอดคล้องกลมกลืนกับข้อมูลเชิงประจักษ์ และค่าสัมประสิทธิ์การพยากรณ์ (R2) ของคุณลักษณะการเป็นผู้ประกอบการ พบว่า<br>มีค่าเท่ากับ 0.93 นั่นแสดงว่า ตัวแปรที่นำมาศึกษาในโมเดลสามารถร่วมกันอธิบายความแปรปรวนของคุณลักษณะการเป็นผู้ประกอบการของนักศึกษาปริญญาตรีในสามจังหวัดชายแดนใต้ ได้ร้อยละ&nbsp;93 อย่างมีนัยสำคัญทางสถิติที่ระดับ .01</p>\r\n<p>3. ปัจจัยเชิงสาเหตุที่มีอิทธิพลต่อคุณลักษณะการเป็นผู้ประกอบการได้รับอิทธิพลโดยรวมสูงสุดจากปัจจัยทางครอบครัว รองลงมาคือ ปัจจัยลักษณะส่วนบุคคล ปัจจัยการจัดการเรียนรู้<br>และปัจจัยการตั้งใจในการเป็นผู้ประกอบการตามลำดับ ส่วนปัจจัยที่มีอิทธิพลทางอ้อมสูงสุดต่อคุณลักษณะการเป็นผู้ประกอบการของนักศึกษา คือ ปัจจัยทางครอบครัวมีอิทธิพลทางอ้อมผ่านการจัดการเรียนรู้ และลักษณะส่วนบุคคลไปยังคุณลักษณะการเป็นผู้ประกอบการของนักศึกษา รองลงมาปัจจัยการจัดการเรียนรู้มีอิทธิพลทางอ้อมผ่านลักษณะส่วนบุคคลไปยังคุณลักษณะการเป็นผู้ประกอบการของนักศึกษา</p>', 'สาขาวิชาการวิจัยและประเมินผลการศึกษา', '', 'https://kb.psu.ac.th/server/api/core/bitstreams/8e5d3e6b-2608-4418-9aea-e5b4fafd7b03/content', 'มหาวิทยาลัยสงขลานครินทร์'),
('ITM00000000017', 'ผลของการปรึกษาเชิงจิตวิทยาแบบกลุ่มด้วยแนวคิดจิตวิทยาเชิงบวก เพื่อเสริมสร้างสุขภาวะแก่นักศึกษาครอบครัวหย่าร้าง', 'COM00000000012', 'COM00000000002', 'The Effects of Group Psychological Counseling Based on Positive Psychology for Well-being Promotion Divorced Family Students', NULL, 0, '2565', '', '<p>การวิจัยกึ่งทดลองครั้งนี้มีวัตถุประสงค์เพื่อศึกษาผลของการปรึกษาเชิงจิตวิทยาแบบกลุ่มด้วยแนวคิดจิตวิทยาเชิงบวกเพื่อเสริมสร้างสุขภาวะแก่นักศึกษาครอบครัวหย่าร้าง โดยมีกลุ่มตัวอย่าง คือ&nbsp;นักศึกษาระดับประกาศนียบัตรวิชาชีพชั้นสูง (ปวส.) วิทยาลัยอาชีวศึกษาปัตตานี จังหวัดปัตตานีที่มาจากครอบครัวหย่าร้าง จำนวน 8 คน สมัครใจเข้าร่วมโปรแกรมให้การปรึกษาเชิงจิตวิทยาแบบกลุ่มด้วยแนวคิดจิตวิทยาเชิงบวก จำนวน 12 ครั้ง ครั้งละ 90 นาที เครื่องมือที่ใช้ในการวิจัย ได้แก่ (1) โปรแกรมการให้การปรึกษาแบบกลุ่มด้วยแนวคิดจิตวิทยาเชิงบวก ประกอบด้วย ความหวัง ความหยุ่นตัว การมองโลกในแง่ดีและการรับรู้ความสามารถของตนเอง (2) แบบวัดสุขภาวะมีค่าความเชื่อมั่นที่ 0.78 ประกอบด้วย<br>4 ด้าน คือ ด้านร่างกาย ด้านจิตใจ ด้านสังคม และด้านปัญญา กลุ่มตัวอย่างได้รับการประเมินแบบวัดสุขภาวะก่อนทดลองและหลังทดลอง สถิติที่ใช้ในการวิเคราะห์ได้แก่ ค่าร้อยละ ค่าเฉลี่ย ส่วนเบี่ยงเบนมาตรฐาน คะแนนพัฒนาการสัมพัทธ์ และสถิติทดสอบสมมติฐาน The Wilcoxon Matched PairsSigned Ranks Test<br>ผลการวิจัย<br>1. หลังการเข้าร่วมโปรแกรมการปรึกษาเชิงจิตวิทยาแบบกลุ่มด้วยแนวคิดจิตวิทยาเชิงบวกนักศึกษาครอบครัวหย่าร้างมีระดับสุขภาวะสูงกว่าก่อนเข้าร่วมโปรแกรมการปรึกษาอย่างมีนัยสําคัญทางสถิติที่ระดับ .05<br>2. ระดับพัฒนาการสัมพัทธ์สุขภาวะของนักศึกษาที่มาจากครอบครัวหย่าร้างหลังการเข้าร่วมโปรแกรมให้การปรึกษาแบบกลุ่มด้วยแนวคิดจิตวิทยาเชิงบวก มีพัฒนาการสัมพัทธ์สุขภาวะเพิ่มขึ้นเฉลี่ยร้อยละ 80.69 อยู่ในระดับสูงมาก<br>3. โปรแกรมให้การปรึกษาแบบกลุ่มด้วยแนวคิดจิตวิทยาเชิงบวกส่งผลให้นักศึกษาครอบครัวหย่าร้างมีสุขภาวะที่สูงขึ้นทุกด้าน โดยด้านจิตใจมีระดับสุขภาวะสูงที่สุด</p>', 'สาขาวิชาจิตวิทยา', '', '', 'มหาวิทยาลัยสงขลานครินทร์'),
('ITM00000000018', 'การพัฒนาหลักสูตรบูรณาการเรื่อง “กึมม๊วก: สาน-ศาสตร์-ศิลป์ ร่องรอย วัฒนธรรมและภูมิปัญญา” โดยใช้โครงงานเป็นฐานเพื่อส่งเสริมทักษะอาชีพและความสามารถในการแก้ปัญหาอย่างสร้างสรรค์ สำหรับนักเรียนระดับมัธยมศึกษาตอนต้น โรงเรียนพื้นที่เกาะ จังหวัดสตูล', 'COM00000000008', 'COM00000000002', 'The Development of Integration Curriculum “Keum-Muk: Sarn-Sard-Sin  Traces of Culture and Wisdom” through Project-Based-Learning to  Promote Professional Skills and Creative Problem Solving Competency  of Junior High School Students on Island Area, Satun', NULL, 0, '2566', '', '<p class=\"isSelectedEnd\">การวิจัยครั้งนี้มีวัตถุประสงค์เพื่อ 1) ศึกษาข้อมูลพื้นฐานและความต้องการจำเป็นในการพัฒนาหลักสูตรบูรณาการ 2) พัฒนาหลักสูตรบูรณาการ &ldquo;กึมม๊วก: สาน-ศาสตร์-ศิลป์ ร่องรอยวัฒนธรรมและภูมิปัญญา&rdquo; โรงเรียนบ้านเกาะหลีเป๊ะ จังหวัดสตูล 3) หาประสิทธิภาพและประสิทธิผลของหลักสูตรบูรณาการฯ และ 4) ปรับปรุงหลักสูตรบูรณาการฯ ดำเนินการวิจัยในลักษณะการวิจัยและพัฒนา (R&amp;D) วิธีการวิจัยแบบผสมผสานวิธี (Mixed Method Research) กลุ่มเป้าหมายที่ใช้ในการเก็บรวบรวมข้อมูล ได้แก่ ชาวบ้านเกาะหลีเป๊ะ ปราชญ์ชาวบ้าน อาจารย์มหาวิทยาลัยด้านหลักสูตร ผู้บริหาร ครูผู้สอน คณะกรรมการสถานศึกษา และกลุ่มเป้าหมายที่ใช้ในการทดลอง ได้แก่ นักเรียนระดับชั้นมัธยมศึกษาปีที่ 2 โรงเรียนบ้านเกาะหลีเป๊ะ จังหวัดสตูล ภาคเรียนที่ 2 ปีการศึกษา 2565 จำนวน 1 ห้องเรียน 23 คน ใช้เวลา 20 ชั่วโมง เครื่องมือที่ใช้ ได้แก่ แบบสัมภาษณ์ ประเด็นสนทนากลุ่ม หลักสูตรบูรณาการฯ แบบประเมินทักษะอาชีพ แบบประเมินความสามารถในการแก้ปัญหาอย่างสร้างสรรค์ และแบบสอบถามความพึงพอใจของนักเรียนที่มีต่อหลักสูตรบูรณาการฯ วิเคราะห์ข้อมูลโดยใช้การวิเคราะห์เชิงประเด็น ค่าเฉลี่ย ส่วนเบี่ยงเบนมาตรฐาน และการวิเคราะห์เนื้อหา</p>\r\n<p>ผลการวิจัยพบว่า 1) ผลการวิเคราะห์ข้อมูลพื้นฐานและความต้องการจำเป็นในการพัฒนาหลักสูตรบูรณาการ พบว่า ควรมีการพัฒนาหลักสูตรโดยใช้องค์ความรู้ภูมิปัญญาท้องถิ่นที่มุ่งเน้นทักษะอาชีพและความสามารถในการแก้ปัญหาอย่างสร้างสรรค์ เพื่อการประกอบอาชีพในอนาคต 2) ผลการพัฒนาหลักสูตรบูรณาการฯ มี 3 ส่วนคือ 1. หลักสูตรบูรณาการฯ 9 องค์ประกอบ คือ ความเป็นมา, หลักการ, จุดมุ่งหมาย, คำอธิบายรายวิชาเพิ่มเติม, โครงสร้างเนื้อหาสาระ, เวลาเรียน การจัดกิจกรรมการเรียนรู้, สื่อ/แหล่งเรียนรู้ และการวัดและประเมินผล 2. คู่มือการใช้หลักสูตร และ 3. หน่วยการเรียนรู้และแผนการจัดการเรียนรู้ มี 3 หน่วยการเรียนรู้ และมี 10 แผนการจัดการเรียนรู้ 3) ผลการหาประสิทธิภาพของหลักสูตรบูรณาการฯ พบว่า มีค่าประสิทธิภาพ E1/E2 เท่ากับ 77.85/81.89 สูงกว่าเกณฑ์ที่กำหนด และประสิทธิผล พบว่า ทักษะอาชีพ (', 'สาขาวิชาหลักสูตรและการสอน', '', 'https://kb.psu.ac.th/items/1109ab21-d2a1-4376-9d3c-976f9d65cefd', 'มหาวิทยาลัยสงขลานครินทร์ วิทยาเขตปัตตานี'),
('ITM00000000019', 'ปัจจัยด้านจิตวิทยาเชิงบวกการสนับสนุนทางสังคมที่ส่งผลต่อแรงจูงใจในการทำงาน ของเจ้าหน้าที่สาธารณสุขในพื้นที่สามจังหวัดชายแดนภาคใต้', 'COM00000000012', 'COM00000000002', 'Positive Psychological Factors and Social Support Affecting Public Health Officers Working Motivation in Three Southern Border Provinces', NULL, 8, '2565', '', '<p>การวิจัยครั้งนี้เป็นการศึกษาวิจัยเชิงพรรณนา วัตถุประสงค์ เพื่อ (1) ศึกษาระดับจิตวิทยาเชิงบวก การสนับสนุนทางสังคมและแรงจูงใจในการทำงานของเจ้าหน้าที่สาธารณสุขในพื้นที่สามจังหวัดชายแดนภาคใต้ (2) ศึกษาเปรียบเทียบความแตกต่างของปัจจัยส่วนบุคคลกับแรงจูงใจในการทำงานของเจ้าหน้าที่สาธารณสุขในพื้นที่สามจังหวัดชายแดนภาคใต้ (3) ศึกษาความสัมพันธ์ของจิตวิทยาเชิงบวก การสนับสนุนทางสังคม กับแรงจูงใจในการทำงานของเจ้าหน้าที่สาธารณสุขในพื้นที่สามจังหวัดชายแดนภาคใต้ และ (4) ศึกษาปัจจัยที่ส่งผลต่อแรงจูงใจในการทำงานของเจ้าหน้าที่สาธารณสุขในพื้นที่สามจังหวัดชายแดนภาคใต้ กลุ่มตัวอย่างที่ใช้ในการวิจัย คือเจ้าหน้าที่สาธารณสุขที่ปฏิบัติงานในพื้นที่สามจังหวัดชายแดนภาคใต้ จำนวน 480 คน เครื่องมือที่ใช้ในการวิจัยเป็นแบบสอบถาม 4 ส่วน ประกอบด้วย (1) ข้อมูลส่วนบุคคล (2) จิตวิทยาเชิงบวก (3) การสนับสนุนทางสังคม (4) แรงจูงใจในการทำงาน การวิเคราะห์ข้อมูล ใช้โปรแกรมสำเร็จรูปในการวิเคราะห์ข้อมูลทางสถิติ<br>ผลการศึกษาพบว่า (1) ระดับปัจจัยด้านจิตวิทยาเชิงบวก การสนับสนุทางสังคม และแรงจูงใจในการทำงานของเจ้าหน้าที่สาธารณสุขในพื้นที่สามจังหวัดชายแดนภาคใต้อยู่ในระดับสูงทุกด้าน(x</p>', 'สาขาวิชาจิตวิทยา', '', 'file:///D:/%E0%B8%A1%E0%B8%B8%E0%B8%81/D/Inhouse%20Database/%E0%B8%90%E0%B8%B2%E0%B8%99%E0%B8%82%E0%B9%89%E0%B8%AD%E0%B8%A1%E0%B8%B9%E0%B8%A5%20TDC,%20PSUKB,%20SOREDA/Thesis/ThesisC20/TC2044/TC2044.pdf', 'มหาวิทยาลัยสงขลานครินทร์ วิทยาเขตปัตตานี'),
('ITM00000000020', 'การพัฒนาเครือข่ายความร่วมมือเพื่อพัฒนาแหล่งเรียนรู้นอกโรงเรียนสำหรับโรงเรียนเอกชน สอนศาสนาอิสลามในอำเภอสายบุรี จังหวัดปัตตานี', 'COM00000000004', 'COM00000000002', 'The Development of a Collaborative Network for Developing Out of School  Learning Resources among Islamic Private Schools  in Saiburi District, Pattani Province', NULL, 7, '2566', '', '<p>การศึกษาในครั้งนี้มีวัตถุประสงค์เพื่อ 1) พัฒนาเครือข่ายความร่วมมือในการพัฒนาแหล่ง เรียนรู้นอกโรงเรียนสําหรับโรงเรียนเอกชนสอนศาสนาอิสลามในอําเภอสายบุรี จังหวัดปัตตานี และ 2) เพื่อศึกษาผลจากกระบวนการดังกล่าว กลุ่มตัวอย่างเป็นครูผู้สอนระดับมัธยมศึกษาในโรงเรียนเอกชนสอนศาสนาอิสลามกลุ่มสลินดงบายู อําเภอสายบุรี จังหวัดปัตตานี &nbsp;จํานวน 4 โรงเรียน โรงเรียนละ 2 คน รวม 8 คน &nbsp;ใช้วิธีการเลือกกลุ่มตัวอย่างแบบเจาะจง เครื่องมือที่ใช้ในการวิจัยคือ กิจกรรมพัฒนาเครือข่ายความร่วมมือ แบบสัมภาษณ์กลุ่ม และแบบประเมินความพึงพอใจ &nbsp;วิเคราะห์ ผลด้วยการวิเคราะห์เนื้อหา และใช้สถิติเชิงพรรนณา &nbsp;ผลการวิจัยพบว่า 1) กิจกรรมการเรียนรู้ที่ พัฒนาขึ้นด้วยแนวคิด &ldquo;การพัฒนาเครือข่าย&rdquo; มีกระบวนการ 6 ขั้นตอนคือ ขั้นตระหนักถึงความ จําเป็นในการสร้างเครือข่าย ขั้นประสานหน่วยงาน/องค์กรเครือข่าย ขั้นสร้างพันธสัญญาร่วมกัน ขั้น บริหารจัดการเครือข่าย ขั้นพัฒนาความสัมพันธ์ และขั้นรักษาความสัมพันธ์ และ 2) ครูผู้สอนสามารถ ใช้เครือข่ายการเรียนรู้ในการพัฒนาแหล่งเรียนรู้นอกโรงเรียนใน โดยออกแบบและทดลองใช้แผนการ จัดการเรียนรู้แบบบูรณาการแหล่งเรียนรู้เมืองสายบุรีด้วยแนวคิด &ldquo;ชมวัง-ชิมอาหาร-สานสัมพันธ์ฉันท์ มิตร-สร้างสังคมพหุวัฒนธรรม&rdquo; &nbsp;มีการทดลองสอน วิพากษ์ และนิเทศการสอน และมีความพึงพอใจ ในการเข้าร่วมกิจกรรมในระดับมาก</p>', 'สาขาการบริหารและการจัดการการศึกษาอิสลาม', '', 'https://soreda.oas.psu.ac.th/show_detail.php?research_id=1185', 'มหาวิทยาลัยสงขลานครินทร์ วิทยาเขตปัตตานี'),
('ITM00000000021', 'การศึกษาแนวทางการให้บริการสังคมมุสลิมเชิงจิตอาสาแบบอิสลามของผู้บริหารโรงเรียนเอกชนสอนศาสนาอิสลามในจังหวัดสงขลา', 'COM00000000004', 'COM00000000002', 'Study of Islamic Ways of Voluntarily Serving the Muslim Community by the Private Schools’ Administrators in Songkhla Province', NULL, 0, '2565', '', '<p>การวิจัยนี้มีวัตถุประสงค์เพื่อ 1) ศึกษาความหมายและโครงสร้างสังคมไทยมุสลิม<br>2) &nbsp; &nbsp;ศึกษาการให้บริการสังคมเชิงจิตอาสาในทัศนะทั่วไปและอิสลาม และ3) ศึกษาแนวทางการ ให้บริการสังคมมุสลิมเชิงจิตอาสาแบบอิสลามของผู้บริหารโรงเรียนเอกชนสอนศาสนาอิสลาม ในจังหวัดสงขลา โดยใช้แบบสอบถามและแบบสัมภาษณ์เป็นเครื่องมือเพื่อการวิจัย เก็บข้อมูลจาก เอกสารปฐมภูมิ ทุติยภูมิ ตติยภูมิ และผู้บริหารโรงเรียนเอกชนสอนศาสนาอิสลามในจังหวัดสงขลา จำนวน 48 โรงเรียน ผลการวิจัยพบว่า<br>1. &nbsp; &nbsp;สังคมไทยมุสลิมคือกลุ่มคนที่รวมตัวกันในประเทศไทย มีการปฏิสัมพันธ์ การ<br>ติดต่อสื่อสารทางสังคมระหว่างกันผ่านวิถีชีวิต วัฒนธรรม ขนบธรรมเนียมและประเพณีปฏิบัติ เป็น สังคมที่มีเอกลักษณ์เฉพาะตัวที่ต่างจากสังคมอื่นๆ ซึ่งเห็นได้จากกฎระเบียบปฏิบัติที่ยึดถืออัลกุรอาน และอัสสุนนะฮฺเป็นแนวทางในการปฏิบัติ โดยมีโครงสร้างสังคมประกอบด้วย 5 ประการ คือ&nbsp; &nbsp;1) หลักการยึดมั่นหรือความเชื่อ 2) ผู้นำทางสังคม 3) สถาบันทางสังคม 4) วาระทางสังคม และ<br>5) &nbsp; &nbsp;วัฒนธรรมค่านิยม<br>2. &nbsp; &nbsp;การให้บริการสังคมเชิงจิตอาสาในทัศนะทั่วไปและอิสลามมีความเหมือนกันคือ<br>การเสียสละ การให้ความช่วยเหลือทั้งในส่วนของทรัพย์ แรงกาย แรงสมอง แม้กระทั่งเวลาที่ตนมี ให้กับบุคคลหรือกลุ่มคนเพื่อให้ได้รับประโยชน์ ได้รับการแก้ปัญหา หรือเพื่อการพัฒนาโดยไม่หวัง ผลตอบแทน สำหรับความต่างของการให้บริการเชิงจิตอาสาอิสลามจากทัศนะทั่วไปคือ ทุกมิติในวิถี ปฏิบัติของอิสลามจะใช้หลักความเชื่อและบทบัญญัติแห่งพระผู้เป็นเจ้า และจากการศึกษาหลักคำ สอนอิสลามในคัมภัร์อัลกุรอาน อัสสุนนะฮฺ และทัศนะนักปราชญ์และวิชาการมุสลิมในยุคต่างๆ พบว่า แนวทางการให้บริการสังคมเชิงจิตอาสาตามแบบอิสลามมี 16 ประการ ได้แก่ 1) การเป็นอิหม่าม ละหมาด 2) การอะซาน 3) การบริการมัสยิด 4) การสอนคัมภีร์อัลกุรอานและศาสตร์ต่าง ๆ &nbsp;5) การ<br>สอนคนที่ไม่รู้ผลิตสิ่งของ 6) การบริจาคทาน 7) การเลี้ยงดู (اﻧﻔﺎق) 8) การสร้างความปรองดองระหว่างมนุษย์ 9) การใช้ให้ทำความดีและห้ามปรามการทำความชั่ว 10) การช่วยเหลือคนขัดสน ยากจน 11) การช่วยเหลือคนทุกข์ 12) การขจัดสิ่งกีดขวางออกจากถนน 13) การช่วยรักษาคน &nbsp; &nbsp; หูหนวกให้เป็นปกติ 14) การอธิบายให้คนปัญญาอ่อนเข้าใจ 15) การนำทางคนตาบอด และ 16) การ ทำความดีต่อปศุสัตว์และบรรดาสัตว์ทั่วไป &nbsp; &nbsp;&nbsp;<br>3. ผลการวิเคราะห์พฤติกรรม แรงจูงใจ และการให้บริการสังคมมุสลิมเชิงจิตอาสา<br>แบบอิสลามของผู้บริหารโรงเรียนเอกชนสอนศาสนาอิสลามในจังหวัดสงขลา พบว่า พฤติกรรมและแรงจูงใจจิตอาสาของผู้บริหารโรงเรียนเอกชนสอนศาสนาอิสลามในจังหวัดสงขลา โดยภาพรวมอยู่ใน ระดับสูง สำหรับการให้บริการสังคมมุสลิมเชิงจิตอาสาแบบอิสลามของผู้บริหารโรงเรียนเอกชนสอน ศาสนาอิสลามในจังหวัดสงขลา โดยภาพรวมอยู่ในระดับปานกลาง โดยรายการที่มีค่าเฉลี่ยสูงสุดคือ การให้บริการสังคมเชิงจิตอาสาโดยการใช้ให้ทำความดีและห้ามปรามการทำความชั่ว &nbsp;<br>4. แนวทางการให้บริการสังคมมุสลิมเชิงจิตอาสาแบบอิสลามของผู้บริหารโรงเรียน เอกชนสอนศาสนาอิสลามในจังหวัดสงขลา พบว่า แนวทางการให้บริการสังคมมุสลิมเชิงจิตอาสาแบบ อิสลามของผู้บริหารโรงเรียนเอกชนสอนศาสนาอิสลามในจังหวัดสงขลามี 3 รูปแบบ คือ 1) แนว ทางการให้บริการสังคมมุสลิมเชิงจิตอาสาแบบอิสลามในรูปแบบการกระทำหรือการปฏิบัติ 2) แนวทางการให้บริการสังคมเชิงจิตอาสาแบบอิสลามในรูปแบบการบริหารจัดการ และ 3) แนว ทางการให้บริการสังคมเชิงจิตอาสาแบบอิสลามในรูปแบบการให้ความรู้</p>', 'สาขาวิชาอิสลามศึกษา', '', '', 'มหาวิทยาลัยสงขลานครินทร์ วิทยาเขตปัตตานี'),
('ITM00000000022', 'มุสลิมเกาะยาวน้อย : การผสมผสานทางวัฒนธรรม การปรับตัวและการธำรงอัตลักษณ์', 'COM00000000008', 'COM00000000002', 'Muslims in Koh Yao Noi: Cultural Coexistence, Adaptation and Identity Maintenance', NULL, 8, '2565', '', '<p class=\"isSelectedEnd\">วิทยานิพนธ์นี้ มีวัตถุประสงค์ 1) เพื่อศึกษาถึงความเป็นมาและภูมิหลังของมุสลิมเกาะยาวน้อย 2) เพื่อศึกษาการฟื้นฟูอิสลามในตำบลเกาะยาวน้อย อำเภอเกาะยาว จังหวัดพังงา และ 3) เพื่อวิเคราะห์การผสมผสานทางวัฒนธรรม การปรับตัวและการธำรงอัตลักษณ์ของมุสลิมเกาะยาวน้อย ท่ามกลางบริบททางสังคมที่เปลี่ยนแปลง การวิจัยครั้งนี้เป็นการวิจัยเชิงคุณภาพ ค้นคว้าจากเอกสารและภาคสนามโดยใช้เทคนิควิธีการวิจัยทางมานุษยวิทยาวัฒนธรรมชาติพันธุ์วรรณาเป็นระยะเวลา 6 เดือน ใช้กระบวนการการเก็บข้อมูล 5 รูปแบบ ได้แก่ การศึกษาเอกสาร การสัมภาษณ์แบบไม่เป็นทางการ การสัมภาษณ์เชิงลึก การสังเกตแบบมีส่วนร่วม และการสนทนากลุ่ม ต่อมาใช้การวิเคราะห์แบบอุปนัย (Analytic Induction) และวิเคราะห์โดยการจำแนกชนิดข้อมูล (Typological Analysis)&nbsp;ผลการวิจัย พบว่า 1) เกาะยาวน้อยเป็นชุมชนเก่าแก่ที่มีมานานกว่า 200-300 ปี มีความเกี่ยวข้องทางประวัติศาสตร์กับเมืองถลาง (จังหวัดภูเก็ต) และมีความหลากหลายทางชาติพันธุ์ อีกทั้งวัฒนธรรมส่วนใหญ่ยังคงยึดอยู่กับตามวัตรปฏิบัติและการวินิจฉัยของปะหลางแอ 2) การฟื้นฟูอิสลามในตำบลเกาะยาวน้อย อำเภอเกาะยาว จังหวัดพังงา แบ่งออกเป็นสามกลุ่มแนวคิด คือ กลุ่มอนุชนซุนนีอนุรักษ์นิยม (แนวคิดศูฟีย์) กลุ่มญะมาอะฮฺ ตับลีฆ และกลุ่มสะละฟียฺ 3) การผสมผสานทางวัฒนธรรมของมุสลิมเกาะยาวน้อยประกอบด้วย ภราดรภาพ, พื้นฐานทางความคิดและการวิวัฒนาการของกลุ่มศูฟียฺและกลุ่มสะละฟียฺในเกาะยาวน้อย, ประเด็นความขัดแย้งระหว่างกลุ่มศูฟีย์และกลุ่มสะละฟียฺในเกาะยาวน้อย, และมุมมองเกี่ยวกับวาทกรรมคณะเก่า-คณะใหม่ ในส่วนของการเปลี่ยนแปลงทางสังคมในเกาะยาวน้อยมีสี่ช่วงเวลา ซึ่งก่อให้เกิดกลุ่มแนวคิดทั้งสามกลุ่ม รวมถึงกลุ่มชาวบ้านบางส่วน ในแต่ละกลุ่มมีการปรับตัวและการธำรงอัตลักษณ์ที่แตกต่างกัน</p>', 'สาขาวิชาอิสลามศึกษา', '', '', 'มหาวิทยาลัยสงขลานครินทร์ วิทยาเขตปัตตานี'),
('ITM00000000023', 'การจัดการแหล่งเรียนรู้วิถีมุสลิมโดยใช้กระบวนการแบบมีส่วนร่วมสำหรับครู สังกัดศูนย์ส่งเสริมการเรียนรู้อำเภอสายบุรี จังหวัดปัตตานี', 'COM00000000008', 'COM00000000002', 'Managing Muslim Learning Resources Using a Participatory Process for Teachers at the Sai Buri District Learning Promotion Center, Pattani Province', NULL, 7, '2566', '', '<p>การวิจัยเชิงปฏิบัติการนี้มีวัตถุประสงค์เพื่อ 1) ศึกษาปัญหาและแนวทางการจัดการแหล่งเรียนรู้สำหรับครู 2) พัฒนากระบวนการแบบมีส่วนร่วมเพื่อการจัดการแหล่งเรียนรู้วิถีมุสลิมสำหรับครู 3) ศึกษาผลการใช้กระบวนการแบบมีส่วนร่วมเพื่อการจัดการแหล่งเรียนรู้วิถีมุสลิมสำหรับครู และ 4) ศึกษากลไกการนำกระบวนการแบบมีส่วนร่วมเพื่อการจัดการแหล่งเรียนรู้วิถีมุสลิมไปขยายผลสู่สถานศึกษา กลุ่มเป้าหมายที่ใช้ในการวิจัยครั้งนี้ ประกอบด้วยกลุ่มจากศูนย์ส่งเสริมการเรียนรู้อำเภอสายบุรี จำนวน 36 คน และกลุ่มเป้าหมายจากชุมชนในเขตเทศบาลอำเภอสายบุรี จำนวน 5 คน ใช้วิธีการเลือกกลุ่มตัวอย่างแบบเจาะจง เครื่องมือที่ใช้ในการวิจัยคือ กระบวนการแบบมีส่วนร่วม แบบสัมภาษณ์กลุ่ม แบบประเมินทักษะกระบวนการแบบมีส่วนร่วมสำหรับครู แบบประเมินแผนการจัดการแหล่งเรียนรู้สำหรับครู และแบบประเมินความพึงพอใจของครูต่อการใช้กระบวนการแบบมีส่วนร่วม วิเคราะห์ข้อมูลเชิงคุณภาพด้วยการวิเคราะห์เนื้อหา ส่วนข้อมูลเชิงปริมาณวิเคราะห์ด้วยค่าร้อยละ ค่าเฉลี่ย ค่าเบี่ยงเบนมาตรฐาน ผลการวิจัยพบว่า 1) ปัญหาการจัดการแหล่งเรียนรู้สำหรับครู ประกอบด้วย ด้านผู้เรียน กระบวนการสอน เนื้อหาการสอน และการมีส่วนร่วมของเครือข่ายชุมชน ส่วนแนวทางการจัดการ แหล่งเรียนรู้สำหรับครู ประกอบด้วย การใช้แหล่งเรียนรู้บูรณาการกับรายวิชาที่เกี่ยวข้อง การสร้างบรรยากาศของการเรียนรู้ การจัดประสบการณ์ให้ผู้เรียนโดยยึดหลักการมีส่วนร่วม การออกแบบเทคนิคและกระบวนการเรียนรู้ ในการบริหารจัดการแหล่งเรียนรู้แบบมีส่วนร่วมกับภาคีเครือข่าย 2) การพัฒนากระบวนการแบบมีส่วนร่วมเพื่อการจัดการแหล่งเรียนรู้วิถีมุสลิมสำหรับครู ประกอบด้วย 6 ขั้นตอน คือ ร่วมวิเคราะห์ ร่วมออกแบบ ร่วมพัฒนา ร่วมนำไปใช้ ร่วมประเมินผล และร่วมขยายผล โดยได้รับการประเมินคุณภาพในระดับดีมาก 3) ผลการใช้กระบวนการแบบมีส่วนร่วมเพื่อการจัดการแหล่งเรียนรู้ วิถีมุสลิมสำหรับครู พบว่า ครูมีการออกแบบแผนการจัดการแหล่งเรียนรู้วิถีมุสลิม ได้รับการประเมินคุณภาพระดับดี (x̅ = 4.18, S.D. = 0.80) ครูมีทักษะกระบวนการแบบมีส่วนร่วมในการจัดการแหล่งเรียนรู้ โดยได้รับการประเมินคุณภาพระดับดี (x̅ = 3.96, S.D.= 0.68) และมีความพึงพอใจของครูต่อกระบวนการแบบมีส่วนร่วมโดยภาพรวมอยู่ในระดับมาก (x̅ = 4.20, S.D. = 0.58) และ 4) ผลการศึกษากลไกการนำกระบวนการแบบมีส่วนร่วมเพื่อการจัดการแหล่งเรียนรู้วิถีมุสลิมสำหรับครูไปขยายผลสู่สถานศึกษาจากการจัดเวทีนำเสนอ พบว่ากลไกการพัฒนาแบบ MAMP ประกอบด้วยกลไกด้านการบริหารจัดการ (Management) กลไกด้านวิชาการ (Academic) กลไกด้านแรงจูงใจ (Motivation) และภาคีเครือข่าย (Partnership)</p>', '', '', '', 'มหาวิทยาลัยสงขลานครินทร์ วิทยาเขตปัตตานี'),
('ITM00000000024', 'สภาพการปรับตัวของครอบครัวมุอัลลัฟในชุมชนมุสลิมเขตบางกะปิ กรุงเทพมหานคร: กรณีศึกษามัสยิดยามิอุ้ลมุตตะกีน (ลำสาลี)', 'COM00000000006', 'COM00000000002', 'Participatory Development of Teachers’ Training Package on Skills for Creating an Integrated Learning Package for Islamic Studies with Science Subjects  in Santi Suksa School Chiang Mai Province', NULL, 7, '2566', '', '<p>การวิจัยในครั้งนี้เป็นการวิจัยเชิงปฏิบัติการ มีวัตถุประสงค์เพื่อ 1) พัฒนาและหา ประสิทธิภาพของชุดฝึกอบรมครูที่พัฒนาแบบมีส่วนร่วม เรื่อง ทักษะการสร้างชุดการเรียนรู้แบบ บูรณาการอิสลามศึกษากับวิชาวิทยาศาสตร์ 2) ศึกษาผลการใช้ชุดฝึกอบรมครูที่พัฒนาแบบมีส่วนร่วม เรื่อง ทักษะการสร้างชุดการเรียนรู้แบบบูรณาการอิสลามศึกษากับวิชาวิทยาศาสตร์ และ3) ศึกษา ความพึงพอใจของครูที่มีต่อการอบรมเชิงปฏิบัติการด้วยชุดฝึกอบรมครูที่พัฒนาแบบมีส่วนร่วม เรื่อง ทักษะการสร้างชุดการเรียนรู้แบบบูรณาการอิสลามศึกษากับวิชาวิทยาศาสตร์ในโรงเรียนสันติศึกษา จังหวัดเชียงใหม่ กลุ่มเป้าหมาย คือ ครูผู้สอนในโรงเรียนสันติศึกษา จังหวัดเชียงใหม่ จำนวน 20 คน คัดเลือกกลุ่มเป้าหมายแบบเจาะจง เครื่องมือที่ใช้ในการวิจัยประกอบด้วย 1) ชุดฝึกอบรมครูที่พัฒนา แบบมีส่วนร่วม เรื่อง ทักษะการสร้างชุดการเรียนรู้แบบบูรณาการอิสลามศึกษากับวิชาวิทยาศาสตร์ ในโรงเรียนสันติศึกษา &nbsp;จังหวัดเชียงใหม่ 2) แบบทดสอบก่อน-หลังการฝึกอบรม 3) แบบประเมิน แผนการจัดการเรียนรู้แบบบูรณาการ และ4.) แบบสอบถามความพึงพอใจของครู วิเคราะห์ข้อมูลด้วย สถิติเชิงพรรณนา โดยหาค่าร้อยละ ค่าเฉลี่ย ค่าเบี่ยงเบนมาตรฐาน และการทดสอบค่าทีแบบสองกลุ่ม ตัวอย่างที่สัมพันธ์กัน ( t-test for Dependent Samples) &nbsp; &nbsp; &nbsp;<br>ผลการวิจัยพบว่า ในการพัฒนาชุดฝึกอบรมครูแบบมีส่วนร่วม เรื่อง ทักษะการสร้าง ชุดการเรียนรู้แบบบูรณาการอิสลามศึกษากับวิชาวิทยาศาสตร์นั้น &nbsp;มีขั้นตอนการพัฒนาแบบมีส่วน ร่วม 7 ขั้นตอนดังนี้ คือ 1) ศึกษาแนวคิดทฤษฎีที่เกี่ยวข้องกับการพัฒนาชุดฝึกอบรมและวิธีการอบรม จากเอกสารงานที่เกี่ยวข้อง 2) พัฒนาเนื้อหาตามแนวคิดด้านโครสร้างเนื้อหาของชุดฝึกอบรม 3) พัฒนาชุดฝึกอบรมแบบมีส่วนร่วมกับครู (ฉบับร่าง) 4) ตรวจสอบคุณภาพของชุดฝึกอบรมโดย ผู้เชี่ยวชาญและปรับปรุงแก้ไข 5) นำชุดฝึกอบรมไปทดลองใช้ 6) จัดทำชุดฝึกอบรมฉบับสมบูรณ์ และ 7) นำชุดฝึกอบรมฉบับสมบูรณ์ไปใช้กับครูกลุ่มเป้าหมายและหาค่าประสิทธิภาพ โดยผลการหา ประสิทธิภาพจากการนำการนำชุดฝึกอบรมครูที่พัฒนาแบบมีส่วนร่วม เรื่อง ทักษะการสร้างชุดการ เรียนรู้แบบบูรณาการอิสลามศึกษากับวิชาวิทยาศาสตร์ ไปอบรมเชิงปฏิบัติการกับครูกลุ่มเป้าหมาย พบว่ามีค่าประสิทธิภาพโดยรวมเท่ากับ 90.33/93.17 สูงกว่าเกณฑ์ (80/80) ผลการใช้ชุดฝึกอบรมครแบบมีส่วนร่วม เรื่อง ทักษะการสร้างชุดการเรียนรู้แบบบูรณาการอิสลามศึกษากับวิชาวิทยาศาสตร์ พบว่า ครูมีความรู้ความเข้าใจเกี่ยวกับการจัดการเรียนรู้แบบบูรณาการหลังการฝึกอบรมสูงกว่า (ค่าเฉลี่ย 93.17) ก่อนการฝึกอบรม (ค่าเฉลี่ย 74.33) อย่างมีนัยสำคัญทางสถิติที่ระดับ 0.05 ครูมี ทักษะการเขียนแผนการเรียนรู้แบบบูรณาการอิสลามศึกษากับวิชาวิทยาศาสตร์ในระดับคุณภาพที่ดี มาก (ได้คะแนนรวม 28/30 คะแนน ) และ ครูมีความพึงพอใจต่อการอบรมเชิงปฏิบัติการด้วยชุด ฝึกอบรมครูแบบมีส่วนร่วม เรื่อง ทักษะการสร้างชุดการเรียนรู้แบบบูรณาการอิสลามศึกษากับวิชา วิทยาศาสตร์ในโรงเรียนสันติศึกษา จังหวัดเชียงใหม่ &nbsp;โดยรวมในระดับดีมาก (ค่าเฉลี่ย 4.95) &nbsp;&nbsp;</p>', 'การบริหารและการจัดการการศึกษาอิสลาม', '', '', 'มหาวิทยาลัยสงขลานครินทร์ วิทยาเขตปัตตานี'),
('ITM00000000025', 'แนวทางของชัยคุ้ลอิสลามอิบนุตัยมียะฮฺต่อความเห็นต่างในหนังสือร็อฟอุ้ลมะลามอะนิ้ลอะอิมมะติ้ลอะลาม', 'COM00000000006', 'COM00000000002', 'The method of sheikhul Islam Ibnu Taimiyah about the different opinions in the Rofulmalam Anil Aimmatilaalam', NULL, 9, '2566', '', '<p>การวิจัยเรื่องแนวทางของชัยคุ้ลอิสลามอิบนุตัยมียะฮฺต่อความเห็นต่างในหนังสือร็อฟอุ้ลมะลามอะนิ้ลอะอิมมะติ้ลอะอฺลาม มีวัตถุประสงค์เพื่อศึกษาประวัติ ผลงานทางวิชาการ การเผยแผ่และแนวทางของอิบนุตัยมียะฮฺต่อความเห็นต่างในหนังสือสือร็อฟอุ้ลมะลามอะนิ้ลอะอิมมะติ้ลอะอฺลามรวมทั้งทัศนคติของท่านที่มีต่อปวงปราชญ์โดยศึกษาเปรียบเทียบแนวทางของท่านกับแนวทางของกัลยาณชนยุค 300 ปีแรก อีกทั้งผลกระทบที่เกิดขึ้นกับประชาชาติอิสลามจากอดีตถึงปัจจุบัน ผู้วิจัยใช้วิธีการวิจัยเชิงคุณภาพ เก็บรวบรวมข้อมูลจากเอกสาร ใช้วิธีวิเคราะห์ข้อมูลเชิงพรรณนา<br>ผลการวิจัยพบว่า 1) อิบนุตัยมียะฮฺคือปราชญ์ที่มีชื่อเสียงและเป็นที่ยอมรับ ท่านมีบทบาทสำคัญต่อวิชาการอิสลาม ประพันธ์หนังสือในศาสตร์อิสลามทุกแขนงมีสานุศิษย์มากมาย หนังสือเล่มหนึ่งที่โดดเด่นเรื่องความเห็นต่างคือ ร็อฟอุ้ลมะลามอะนิ้ลอะอิมมะติ้ลอะอฺลาม เป็นหนังสือที่ได้รับการยอมรับอย่างสูงจากอดีตถึงปัจจุบันในเรื่องการนำเสนอข้อเท็จจริงเกี่ยวกับปัจจัยและสาเหตุของความเห็นต่างซึ่งเป็นหนังสือที่สะท้อนจุดยืนและแนวคิดของอิบนุตัยมียะฮฺในเรื่องความเห็นต่างที่มีนัยสำคัญคือมีความสอดคล้องกับแนวทางของกัลยาณชนยุค 300 ปีแรกและการให้เกียรติต่อปวงปราชญ์ในประเด็นการเห็นต่างที่อยู่ในกรอบของหลักการ 2) ความเห็นต่างเป็นหนึ่งในพระประสงค์ของอัลลอฮฺ เป็นเรื่องปกติที่เกิดขึ้นได้และมิใช่พึ่งเกิดในยุคปัจจุบันหากแต่มีมาตั้งแต่อดีตและเกิดกับคนทุกระดับตั้งแต่ระดับนบีเศาะฮาบะฮฺ จนถึงปวงปราชญ์ ปัจจัยที่ทำให้เกิดความเห็นต่างมาจากปัจจัย 3 ประการ และสาเหตุ 10 ประการดังที่อิบนุตัยมียะฮฺกล่าวไว้ในหนังสือร็อฟอุ้ลมะลามอะนิ้ลอะอิมมะติ้ลอะอฺลาม โดยข้อเท็จจริงความเห็นต่างจะไม่ส่งผลกระทบเชิงลบต่อประชาชาติอิสลามเลยหากมีความเข้าใจที่ถูกต้อง เพราะอิสลามมิได้เปิดกว้างในเรื่องความเห็นต่างจนไร้ขอบเขตหากแต่อิสลามได้วางกรอบและกฎเกณฑ์ไว้อย่างรัดกุม ดังนั้นการศึกษาอย่างถ่องแท้และเข้าใจ มีทัศนคติที่ดีและเปิดใจรับจะส่งผลดีด้านการค้นคว้า วิจัย วิเคราะห์และสังเคราะห์เป็นเหตุที่ทำให้เกิดองค์ความรู้และนวัตกรรมที่เป็นประโยชน์ต่อวิชาการและการอยู่ร่วมกันของประชาชาติอิสลาม</p>', 'สาขาวิชาอิสลามศึกษา', '', '', 'มหาวิทยาลัยสงขลานครินทร์ วิทยาเขตปัตตานี'),
('ITM00000000026', 'สภาพ ผลกระทบ และแนวทางการบริหารงานวิชาการของโรงเรียนเอกชนสอนศาสนาอิสลามในจังหวัดชายแดนภาคใต้ที่ใช้นวัตกรรมการศึกษาชั้นเรียนแบบญี่ปุ่น', 'COM00000000009', 'COM00000000002', 'Conditions, Impacts, and Guidelines of Using Lesson Study Innovation for Academic Affair Management in the Deep South Private Islamic Schools', NULL, 9, '2566', '', '<p>การวิจัยครั ้งนี้เป็นการวิจัยเชิงคุณภาพ 1) เพื ่อศึกษาสภาพทั ่วไปของการดำเนินงาน นวัตกรรมการศึกษาชั ้นเรียนของโรงเรียน 2) เพื ่อศึกษาผลกระทบของการใช้นวัตกรรมการศึกษาชั้น เรียนที ่มีผลต่อการบริหารงานวิชาการของโรงเรียน และ 3) เพื ่อนำเสนอข้อเสนอแนะแนวทางการ บริหารงานวิชาการของโรงเรียนเอกชนสอนศาสนาอิสลามในจังหวัดชายแดนภาคใต้ที ่ใช้นวัตกรรม การศึกษาชั ้นเรียนแบบญี ่ปุ ่น แบ่งการวิจัยเป็น 2 ตอน โดยตอนที ่ 1 ทำการสนทนากลุ ่มกับผู ้บริหาร หัวหน้าวิชาการ และครูผู ้สอน จากโรงเรียนแกนนำ 7 โรงเรียน จำนวน 12 ท่าน และทำการสนทนา กลุ่มกับผู้เชี่ยวชาญด้านนวัตกรรมการศึกษาชั้นเรียนอีก 3 ท่าน พร้อมกันนั้นได้มีการเก็บข้อมูลแบบไม่ มีส่วนร่วมกับโรงเรียนแกนนำทั้ง 7 โรงเรียน และตอนที่ 2 ทำการสนทนากลุ่มกับผู้ทรงคุณวุฒิ 5 ท่าน จากผู ้ทรงคุณวุฒิด้านนวัตกรรมการศึกษาชั ้นเรียน 2 ท่าน ผู ้ทรงคุณวุฒิด้านการบริหารโรงเรียน เอกชนสอนศาสนาอิสลาม 2 ท่าน และผู ้ทรงคุณวุฒิด้านการพัฒนาวิชาชีพครู 1 ท่าน ผลการวิจัย พบว่า 1. การบริหารวิชาการของโรงเรียนเอกชนสอนศาสนาอิสลามจังหวัดชายแดนภาคใต้ ก่อนใช้นวัตกรรมการศึกษาชั ้นเรียน มีการจัดกิจกรรม โครงการที ่ไม่ได้มุ ่งเน้นไปที ่ชั ้นเรียน ไม่ตอบ โจทย์มาตรฐานประกันคุณภาพด้านผู ้เรียนและด้านครู ไม่ใส่ใจในการศึกษาหลักสูตรในการออกแบบ การสอน รูปแบบการจัดการเรียนการสอนในชั้นเรียนไม่ได้มุ่งเน้นที่ผู้เรียนเป็นสำคัญ มีข้อจำกัดในการ สนับสนุนงบประมาณและทรัพยากรการเรียนรู้ รูปแบบการวัดและประเมินผลเน้นการสอบเป็นหลัก และการพัฒนาครูผู ้สอนจะเน้นไปที ่การจัดการอบรมหรือส่งเข้าอบรมภายนอกซึ ่งไม่สามารถนำมา พัฒนาหรือปรับใช้ได้จริง นอกจากนี ้ยังมีข้อค้นพบเพิ ่มเติมว่า โรงเรียนเอกชนสอนศาสนาอิสลาม จังหวัดชายแดนภาคใต้เริ ่มต้นรู ้จักนวัตกรรมการศึกษาชั ้นเรียนผ่านประสบการณ์และการทำงานของ มหาวิทยาลัยทักษิณ มหาวิทยาลัยสงขลานครินทร์ และโรงเรียนเอกชนสอนศาสนาอิสลามที ่เข้าร่วมมา ก่อน ด้วยความเข้าใจว่านวัตกรรมการศึกษาชั ้นเรียนนั ้นส่งเสริมการพัฒนาวิชาชีพผ่านชุมชนการ เรียนรู ้วิชาชีพ(PLC) ส่งเสริมการพัฒนานวัตกรรมการสอน ส่งเสริมการสอนที ่เน้นการคิดและส่งเสริม ความมั ่นใจในการนำเสนอของนักเรียน มีภูมิหลังและความเป็นมาของการขยายแนวคิดนวัตกรรม การศึกษาชั ้นเรียนในจังหวัดชายแดนภาคใต้ตั ้งแต่ปีพ.ศ. 2547 ซึ ่งมีการพูดคุยเป็นทางการของ มหาวิทยาลัยในพื ้นที ่จังหวัดชายแดนภาคใต้ และยังพบว่าแนวคิด หลักการอิสลามมีความเอื ้อให้เกิด การดำเนินนวัตกรรมการศึกษาชั้นเรียนให้ประสบความสำเร็จและราบรื่น 2. การใช้นวัตกรรมการศึกษาชั ้นเรียน มีผลต่อการบริหารงานวิชาการของโรงเรียน เอกชนสอนศาสนาอิสลามจังหวัดชายแดนภาคใต้ ด้านแผนงานวิชาการและการประกัน สามารถตอบ โจทย์มาตรฐานการประกันคุณภาพภายในและภายนอก ด้านการบริหารหลักสูตร ทำให้ผู้เกี่ยวข้องทุกฝ่าย ทั ้งผู ้บริหาร หัวหน้าวิชาการและครูผู ้สอนให้ความใส่ใจศึกษาหลักสูตร พร้อมกับมีการปรับปรุง หลักสูตร ด้านการจัดการเรียนรู ้ ทำให้ผู ้บริหารมีบทบาทในการจัดการชั ้นเรียน เน้นการจัดการเรียน การสอนที ่เน้นผู ้เรียนเป็นสำคัญ ด้านการบริหารทรัพยากรการเรียนรู ้ ผู ้บริหารสนับสนุนสื ่อ อุปกรณ์ การเรียนรู้ เพื่อเอื้อให้ครูผู้สอนสามารถออกแบบสื่อการสอนได้ ด้านการวัดและประเมินผล ทำให้การ ประเมินเน้นไปที ่พัฒนาการรายบุคคลและให้ความสำคัญกับกระบวนการ แนวคิดการแก้ปัญหาของ นักเรียนเป็นสำคัญ และด้านการพัฒนาวิชาชีพครู ทำให้รูปแบบการพัฒนาครูเปลี ่ยนการจากการเน้น ส่งครูเข้าอบรมมาเป็นการพัฒนาผ่านกระบวนการทำงานปกติในชั ้นเรียน ทำงานร่วมกันเป็นทีม ซึ ่งมี ผู้บริหารเป็นผู้ที่มีบทบาทสำคัญในการพัฒนาวิชาชีพครู 3. ข้อเสนอแนะแนวทางการบริหารวิชาการสำหรับโรงเรียนเอกชนสอนศาสนา อิสลามจังหวัดชายแดนภาคใต้ที่ใช้นวัตกรรมการศึกษาชั้นเรียน โรงเรียนที่ใช้นวัตกรรมฯ ต้องวางแผน กำหนดปฏิทินการดำเนินงานนวัตกรรมการศึกษาชั ้นเรียนในปฏิทินการดำเนินงานหลักของโรงเรียน ผู ้บริหาร ต้องมีบทบาทในด้านหลักสูตร การจัดการเรียนรู ้ การสนับสนุนและบริหารทรัพยากรการ เรียนรู้ มีส่วนร่วมในการติดตามการวัดและประเมินผลการเรียนรู้ มีบทบาทสำคัญในการพัฒนาวิชาชีพ ครูผู ้สอนด้วยการส่งเสริมและสนับสนุนให้ครูได้เรียนรู้และพัฒนาตนเองด้วยการเรียนรู ้ทั ้งภายในและ ภายนอก ส่วนหัวหน้าวิชาการ จะต้องร่วมกับผู ้บริหารในการออกแบบ ดำเนินการและติดตามการ ดำเนินงานนวัตกรรมการศึกษาชั ้นเรียนให้ดำเนินการอย่างต่อเนื ่อง และครูผู ้สอนต้องทำความเข้าใจ หลักสูตร ตระหนักและออกแบบการจัดการเรียนรู ้ที ่เน้นผู ้เรียนเป็นสำคัญ ผลิตสื ่อสำหรับการสอนที่ สอดคล้องกับวิธีการจัดการเรียนรู ้ ตระหนักถึงการทำงานเป็นทีม เรียนรู ้และรับฟังข้อเสนอแนะ เปิด ชั้นเรียนอย่างต่อเนื่อง และเข้าร่วมกิจกรรมต่าง ๆ ของเครือข่าย&nbsp;</p>', 'สาขาวิชาการบริหารและการจัดการการศึกษาอิสลาม', '', '', 'มหาวิทยาลัยสงขลานครินทร์ วิทยาเขตปัตตานี'),
('ITM00000000027', 'การพัฒนาชุดฝึกอบรมด้วยเทคนิคการคิดเชิงออกแบบเพื่อพัฒนาความรู้และทักษะด้านการจัดการเรียนการสอนออนไลน์สำหรับครูผู้สอนอิสลาม โรงเรียนบ้านเทพา จังหวัดสงขลา', 'COM00000000009', 'COM00000000002', 'Development of a Training Packages by Design Thinking to develop  knowledge and skills in online teaching management for Islamic  teachers at Ban Thepha School, Songkhla Province', NULL, 9, '2565', '', '<p>Developing teachers through online teaching training is very necessary in the epidemic of COVID-19. The objectives of this research were 1) to create and find quality of online instructional training package for Islamic teachers. Ban Thepha School, Songkhla Province 2) to develop knowledge in online teaching management 3) to assess skills in online teaching and learning management4) to assess the satisfaction of the participants.the target groups used in the research were 4 Islamic studies teachers selected by a specific method. the tools used in the research were A training package with design thinking techniques to develop knowledge and skills in online teaching management, consisting of training courses training plan training materials and tools for measuring and assessing training, such as a training test on knowledge of online teaching management and skills assessment form the results of the study showed that 1) The training package using Design Thinking Techniques to develop knowledge and skills in online teaching and learning management developed passed the specified average criteria and was appropriate and consistent with all issues. 2) The knowledge test result of online teaching management after training was higher than 80 percent, and 3) the skill of online teaching management after training was at a very good level 4) Islamic teachers had a very good level of satisfaction with the online teaching training package.</p>', 'สาขาการบริหารและการจัดการการศึกษาอิสลาม', '', '', 'มหาวิทยาลัยสงขลานครินทร์ วิทยาเขตปัตตานี'),
('ITM00000000028', 'วิถีปฏิบัติแบบมุสลิมต่อชนต่างศาสนิกในสังคมหลากวัฒนธรรม กรณีศึกษา การเคลื่อนไหวองค์กรวะสะฏียะฮ์ในประเทศไทย', 'COM00000000006', 'COM00000000002', 'The Muslim Conduct in Relation to Non–Muslims in Multi-Cultural Society A Case Study Movement  of Wasatiyyah Organization in Thailand', NULL, 10, '2565', '', '<p>งานวิจัยฉบับนี้ เป็นงานวิจัยเชิงคุณภาพ โดยมีวัตถุประสงค์เพื่อศึกษา (1) บทบัญญัติเกี่ยวกับความสัมพันธ์ระหว่างมนุษยชาติ ประวัติศาสตร์ยุคท่านนบีมุฮัมหมัด สิทธิและกฎเกณฑ์ต่างๆว่าด้วยวิถีปฏิบัติระหว่างมุสลิมกับชนต่างศาสนิก (2) หลักการของอัลวะสะฏียะฮ์ ประวัติความเป็นมา องค์กรอัลวะสะฏียะฮ์ และการเคลื่อนไหววะสะฏียะฮ์ในประเทศไทย (3) วิถีปฏิบัติแบบมุสลิมในการอยู่ร่วมกันอย่างสันติด้วยแนวทางอัลวะสะฏียะฮ์ในประเทศไทยในการศึกษานี้ องค์ความรู้เกิดจากการวิเคราะห์เนื้อหาจากข้อมูล 2 ส่วน (1) บทบัญญัติแห่งคัมภีร์อัลกุรอาน อัลหะดีษ ทัศนะของบรรดาปราชญ์อิสลามโดยเฉพาะในยุค 300 ปีแรกตามปฏิทินอิสลาม ทัศนะของนักวิชาการอิสลามในประเด็นดังกล่าว และกฎเกณฑ์ทางด้านนิติศาสตร์อิสลาม เช่น มะกอศิดชะรีอะฮ์ อุศูลุลฟิกฮ์ เกาะวาอิดอัลฟิกฮียะฮ์ ฟิกฮ์ฮุ้ลวากิอียะฮ์ ฟิกฮ์ฮุ้ลเอาละวียะฮ์และฟิกฮ์ฮุ้ลอะก้อลลียะฮ์ (2) การสัมภาษณ์เชิงลึกของผู้ก่อตั้งและผู้กาหนดนโยบายขององค์กรวะสะฏียะฮ์&nbsp;ผลการวิจัยพบว่า<br>1. การเปลี่ยนแปลงทางสังคมของท่านนบีมุฮัมหมัด จะใช้หลักการอิสลามมาปลูกฝังคุณธรรมจริยธรรม พัฒนาความสัมพันธ์ระหว่างมนุษย์และให้มีการช่วยเหลือซึ่งกันและกันของสมาชิกในสังคม<br>2. ท่านนบีมุฮัมหมัด ได้กาหนดสิทธิและหน้าที่ที่พึงปฏิบัติต่อรัฐและประเทศชาติร่วมกันคือ การร่วมกันพัฒนาและสร้างความเจริญรุ่งเรืองให้แก่ประเทศชาติ การรักษาความสงบสุขของชาติบ้านเมือง<br>3. แนวทาง&ldquo;อัลวะสะฏียะฮ์&rdquo;มีองค์ประกอบที่สาคัญอยู่ 6 ประการคือ (1) ความดีเลิศ (2) ความยุติธรรม (3) ความสมดุล (4) ความซื่อสัตย์ต่อหลักธรรม (5) ความเรียบง่าย (6) ความฉลาดในการคิดไตร่ตรอง<br>4. กรอบของอัลวะสะฏียะฮ์ในการประยุกต์ใช้ในบริบทของสังคมไทย ต้องวางอยู่บนหลักการของ ฟิกฮ์ อัล-อะก้อลลิยาต คือ (1) การป้องกันอันตราย (2) การปกป้องผลดีที่จะเกิดขึ้น (3) ความยืดหยุ่น (4) การจัดลาดับความสาคัญของบัญญัติอิสลาม (5) ความถูกกาละเทศะ) (6)การประเมินถึงผลเสีย<br>5. หลักการของอัลวะสะฏียะฮ์ในการสร้างสันติภาพกับชนต่างศาสนิกในประเทศไทย ได้แก่ (1)ยอมรับความแตกต่าง (2) เคารพและให้เกียรติต่อความต่าง (3) ปฏิสัมพันธ์ที่ดีกับความต่าง (4) อดทนต่อความต่าง (5) แสวงจุดร่วม สงวนจุดต่าง</p>', 'สาขาวิชาอิสลามศึกษา', '', 'https://kb.psu.ac.th/server/api/core/bitstreams/d490f873-6b98-4e10-9d75-1e3624d964a4/content', 'มหาวิทยาลัยสงขลานครินทร์ วิทยาเขตปัตตานี'),
('ITM00000000029', 'ศึกษาดัชนีการเก็บเกี่ยวและการยืดอายุลองกองโดยเทคนิคทางฟิสิกส์', 'COM00000000001', 'COM00000000002', 'Study on Postharvest Index and Storage Period of Longkong Fruit using Physics Techniques', NULL, 9, '2566', '', '<p>งานวิจัยฉบับนี้มีวัตถุประสงค์เพื่อศึกษาดัชนีการเก็บเกี่ยวลองกองที่เหมาะสม โดยใช้ เทคนิควัดคลื่นไมโครเวฟ วัดสเปกตรัมสีผิวผลลองกอง และวัดค่าความจุไฟฟ้า และศึกษาผลของการ ฉายรังสีแกมมาต่อการยืดอายุหลังการเก็บเกี่ยวลองกอง พบว่า ค่าความเข้มข้นของคลื่นไมโครเวฟที่ ส่งผ่านผลลองกองแบบไม่ปอกเปลือก แบบปอกเปลือก และแบบน้ำ มีค่าอยู่ในช่วง 0.75-0.58 mA, 0.78-0.62 mA และ 0.89-0.79 mA ตามลำดับ โดยช่อลองกองผลติดแน่น รสชาดหวานอมเปรี้ยว เหมาะสำหรับขายตลาดไกลสวน สำหรับค่าที่อยู่ในช่วง 0.58-0.41 0.70 mA ตามลำดับ ผลลองกองสุกเหลืองทั้งช่อ เหมาะสำหรับขายตลาดใกล้สวน เหมาะสำหรับส่งขายตลาด ยาขาดหา A, 0.62-0.45 mA และ 0.79- ไกลสวนเนื่องจากขอติดผลสวยงาม รสชาติหวานอมเปรี้ยว ค่าสเปกตรัมในช่วง 195-256 เหมาะ สำหรับขายตลาดใกล้สวน มีรสชาติหวามเข้มและมีสีที่เหลือ ส่วนการศึกษาวัดค่าประจุไฟฟ้า ไม่สามารถหา ความสัมพันธ์ได้ สำหรับการฉายรังสีแกมมาเพื่อยืดอายุผลลองกองหลังการเก็บเกี่ยว พบว่า ความเข้ม รังสีที่ 500 Gy ทำให้ผลลองกองที่บรรจุอยู่ในถุงพลาสติกสามารถอยู่ได้นานที่สุด 13 วัน ในสภาวะ อุณหภูมิ 18 องศาเซลเซียส</p>', 'สาขาวิชาฟิสิกส์ประยุกต์', '', '', 'มหาวิทยาลัยสงขลานครินทร์ วิทยาเขตปัตตานี'),
('ITM00000000030', 'การประเมินปริมาณสารกัมมันตรังสีธรรมชาติและแก๊สเรดอนในวัสดุก่อสร้างและในอาคารเรียนบริเวณตอนล่างของจังหวัดยะลา', 'COM00000000012', 'COM00000000002', 'Assessment of Natural Radionuclides and Radon Gas in Building Materials and Indoor Schools Building In the Southern Part of Yala Province', NULL, 10, '2566', '', '<p>งานวิจัยนี้ได้ศึกษาปริมาณสารกัมมันตรังสีธรรมชาติได้แก่ 226Ra, 232Th และ 40K ในวัสดุก่อสร้าง จำนวน 41 ตัวอย่าง โดยใช้ระบบการวิเคราะห์แกมมาสเปกโตรเมตรี ด้วยหัววัดเจอมาเนียมบริสุทธิ์สูง (HPGe) เพื่อประเมินดัชนีอันตรายจากกัมมันตภาพรังสีที่เกี่ยวข้อง และศึกษาปริมาณแก๊สเรดอนในอาคารเรียนบริเวณตอนล่างของจังหวัดยะลา เนื่องจากบริเวณตอนล่างของจังหวัดยะลา มีสภาพทางธรณีวิทยาที่ประกอบด้วยหินตะกอน หินแปร และมีหินอัคนีชนิดหินแกรนิต กระจายตัวอยู่ในบริเวณต่าง ๆ นอกจากนั้นมีการทำอุตสาหกรรมก่อสร้าง ซึ่งวัสดุก่อสร้างเหล่านี้ส่วนใหญ่เป็นหินแกรนิต หินปูน และมักจะมีส่วนประกอบของนิวไคลด์กัมมันตรังสีจากธรรมชาติ ได้แก่ 226Ra, 232Th และ 40K ที่เป็นต้นกำเนิดของการปลอดปล่อยแก๊สเรดอน ซึ่งส่งผลต่อสุขภาพและเพิ่มโอกาสการเป็นมะเร็งปอดของผู้อยู่อาศัยในบริเวณดังกล่าวในระยะยาวได้ พบว่าค่าเฉลี่ยปริมาณสารกัมมันตรังสีของ 226Ra, 232Th และ 40K ในตัวอย่างหิน ดิน ทราย บริเวณตอนล่างของจังหวัดยะลามีค่าสูงกว่าค่าเฉลี่ยของโลกสำหรับดิน (UNSCEAR, 2000) ค่าเฉลี่ยของโลกสำหรับวัสดุก่อสร้าง (UNSCEAR, 1993) โดยตัวอย่างหินจะพบว่าปริมาณสารกัมมันตรังสีของ 226Ra และ 40K สูงสุดที่โรงเรียนบ้านปะเด็ง อำเภอธารโต ส่วน 232Th มีค่าสูงสุดในโรงเรียนเบตง (วีระราษฎร์ประสาน) อำเภอเบตง ตัวอย่างดินนั้นพบว่าปริมาณสารกัมมันตรังสีของ 226Ra, 232Th มีค่าสูงสุดโรงเรียนบ้านวังใหม่ อำเภอเบตง ส่วน 40K มีค่าสูงสุดในโรงเรียนบ้านไทยพัฒนา อำเภอธารโต และสำหรับตัวอย่างทรายพบว่าปริมาณสารกัมมันตรังสีของ 226Ra, 232Th มีค่าสูงสุดในโรงเรียนบ้านศรีนคร อำเภอธารโต ส่วน 40K มีค่าสูงสุดในโรงเรียนเขื่อนบางลาง อำเภอบันนังสตา สำหรับค่าดัชนีความเป็นอันตรายทางรังสีทั้ง 5 ค่านั้นได้แก่ ค่ากัมมันตภาพรังสีสมมูลเรเดียม (Raeq) ค่าดัชนีความเสี่ยงการได้รับรังสีจากภายนอก (Hex) ค่าดัชนีความเสี่ยงการได้รับรังสีจากภายใน (Hin) และอัตราปริมาณรังสีแกมมาดูดกลืน (D) และปริมาณรังสีที่ได้รับจากภายนอกร่างกายประจำปี (E) พบว่าตัวอย่างหินค่าดัชนีความเป็นอันตรายทางรังสีทั้ง 5 ค่านั้นมีค่าต่ำกว่าเมื่อเทียบค่ามาตรฐานที่กำหนดไว้ ส่วนตัวอย่างดิน และทราย ค่ากัมมันตภาพรังสีสมมูลเรเดียม ค่าดัชนีความเสี่ยงการได้รับรังสีจากภายนอก ค่าดัชนีความเสี่ยงการได้รับรังสีจากภายใน และอัตราปริมาณรังสีแกมมาดูดกลืน มีค่าสูงกว่าเมื่อเทียบค่ามาตรฐานที่กำหนดไว้ มีเพียงปริมาณรังสีที่ได้รับจากภายนอกร่างกายประจำปีเท่านั้นที่ต่ำกว่าค่ามาตรฐานที่กำหนดไว้&nbsp;ส่วนปริมาณความเข้มข้นของแก๊สเรดอนภายในอาคารเรียน บริเวณตอนล่างของจังหวัดยะลา มีค่าเฉลี่ยเท่ากับ 9.12&plusmn;3.42 Bq/m3 โดยมีค่าสูงสุดที่โรงเรียนบ้านทรายแก้ว อำเภอบันนังสตา และต่ำสุดที่โรงเรียนบ้านตาเนาะปูเต๊ะ อำเภอบันนังสตาโดยทุกโรงเรียนมีค่าต่ำกว่าเกณฑ์ที่องค์การพิทักษ์สิ่งแวดล้อมแห่งสหรัฐอเมริกาได้กำหนดระดับเรดอนภายในอาคารไว้ที่ 148 Bq/m3 โดยในพื้นที่ที่ศึกษามีสภาพธรณีวิทยาเป็นหินแกรนิตแต่มีปริมาณความเข้มข้นของก๊าซเรดอนไม่สูงมากนัก เนื่องจากอาคารเรียนส่วนใหญ่จะมีการเปิดประตูหน้าต่างอยู่เสมอ ซึ่งเป็นการลดระดับความเข้มข้นของก๊าซเรดอนภายในอาคาร</p>', 'สาขาวิชาฟิสิกส์ประยุกต์', '', '', 'มหาวิทยาลัยสงขลานครินทร์ วิทยาเขตปัตตานี');
INSERT INTO `tb_item` (`item_id`, `item_title`, `community_id`, `collection_id`, `item_alternative`, `item_issued_day`, `item_issued_month`, `item_issued_year`, `item_description`, `item_abstract`, `item_sponsorship`, `item_citation`, `item_uri`, `item_publisher`) VALUES
('ITM00000000031', 'การบำบัดและการรีไซเคิลคอนเดนเสทจากกระบวนการผลิตผลพลอยได้ของ โรงงานทูน่ากระป๋อง', 'COM00000000010', 'COM00000000002', 'Treatment and Recycling of Condensate from By-Products Production Process of Canned Tuna Factory', NULL, 10, '2566', '', '<p>งานวิจัยนี้มีวัตถุประสงค์เพื่อศึกษาการบำบัดน้ำคอนเดนเสทจาก กระบวนการผลิตผลพลอยได้ของโรงงานผลิตปลาทูน่ากระป๋องเพื่อนำกลับไปใช้ในกระบวนการผลิตน้ำมันปลา โดยการปรับลด pH และการดูดซับกลิ่นด้วยถ่านกัมมันต์ทางการค้า Eunicarb ID900 งานวิจัยเริ่มต้นด้วยการศึกษาผลของ pH (7.0-9.0) ต่อการกำจัดซีโอดี (พารามิเตอร์ที่เป็นตัวแทนของ กลิ่น) ด้วยถ่านกัมมันต์ในระดับห้องปฏิบัติการ ตามด้วยการศึกษาการดูดซับแบบต่อเนื่องในระดับกึ่ง อุตสาหกรรมเพื่อบำบัดน้ำคอนเดนเสทในกระบวนการจริง จากการทดลองพบว่า ที่ pH ต่ำมีอัตรา การดูดซับที่เร็วกว่า ในขณะที่ที่ pH สูงสามารถกำจัดซีโอดีได้สูงสุดมากกว่า 90% การดูดซับ สอดคล้องกับสมการอัตราการดูดซับอันดับสองเทียม และไอโซเทอมการดูดซับตามสมการฟรุนดลิช จากการศึกษาการบำบัดน้ำคอนเดนเสทในระดับกึ่งอุตสาหกรรมโดยใช้คอลัมน์ดูดซับที่มีขนาด เส้นผ่านศูนย์กลาง 15 เซนติเมตร สูง 150 เซนติเมตร พบว่าที่ทุกอัตราการไหลของน้ำคอนเดนเสท (ปรับ pH เป็น 7.3-7.5) ที่ใช้ในการทดลองคือ 0.5 - 2.5 ลบ.ม./ชม. สามารถกำจัดกลิ่นฉุนและน้ำ คอนเดนเสทหลังบำบัดมีคุณภาพดีขึ้นและผ่านมาตรฐานน้ำใช้ในกระบวนการผลิตน้ำมันปลาที่บริษัท กําหนด นอกจากนี้ได้ศึกษาอายุการใช้งานของถ่านกัมมันต์ต่อการบำบัดน้ำคอนเดนเสทแบบต่อเนื่อง ทีอัตราการไหล 2.5 ลบ.ม./ชม. ซึ่งเป็นอัตราการไหลที่สอดคล้องกับอัตราการผลิตคอนเดนเสทจริง ของบริษัทพบว่ามีวัฏจักรการเดินระบบอย่างมีประสิทธิภาพเท่ากับ 6 เดือน และหลังนำกลับไปใช้ ในกระบวนการผลิตน้ำมันปลา พบว่าไม่มีผลกระทบต่อสินค้าน้ำมันปลาทั้งในเชิงคุณภาพและปริมาณ เมื่อประเมินความเป็นไปได้ทางเศรษฐศาสตร์ในการติดตั้งระบบบำบัดน้ำคอนเดนเสทด้วยการดูดซับ โดยถ่านกัมมันต์สำหรับโรงงานจริงพบว่ามีต้นทุนในการบำบัดเท่ากับ 8.14 บาท/ลบ.ม. สามารถ ประหยัดต้นทุนของน้ำป้อนเข้ากระบวนการผลิตและการบำบัดน้ำคอนเดนเสทได้ 202,500 บาท/ปี ให้ระยะเวลาคืนทุนเท่ากับ 2.86 ปี</p>', 'สาขาวิชาเคมีประยุกต์', '', '', 'มหาวิทยาลัยสงขลานครินทร์ วิทยาเขตปัตตานี'),
('ITM00000000032', 'การตรวจสอบความเข้มข้นของก๊าซเรดอนเพื่อคาดคะเนการเกิดแผ่นดินไหวบริเวณรอยเลื่อนเขาเด่น จังหวัดสุราษฎร์ธานี', 'COM00000000007', 'COM00000000002', 'Monitoring of Radon Concentration to Predict Earthquakes  at Khaoden Fault, Surat Thani Province', NULL, 10, '2565', '', '<p>งานวิจัยนี ้มีวัตถุประสงค์เพื ่อตรวจวัดระดับก๊าซเรดอนด้วยวิธีหัววัดรอยนิวเคลียร์ แบบของแข็ง ตามแนวรอยเลื ่อนเขาเด่น จังหวัดสุราษฎร์ธานี เป็นระยะทาง 23.2 กิโลเมตร โดยมี สถานีตรวจวัด 12 สถานี ทำการเก็บตัวอย่าง 12 ครั ้งระหว่างเดือนสิงหาคม พ.ศ.2562 ถึง เดือน สิงหาคม พ.ศ. 2563 เพื่อคาดคะเนโอกาสที่จะเกิดแผ่นดินไหวบริเวณรอยเลื่อนดังกล่าว พบว่า สถานี ตรวจวัด KDF2, KDF3, KDF4 &nbsp;และ KDF12 มีค่าความเข้มข้นของก๊าซเรดอนสูงกว่าตำแหน่งอ้างอิง 2-10 เท่า จำนวนหลายครั้ง ซึ่งมีโอกาสเสี่ยงที่จะเกิดแผ่นดินไหวได้ ดังนั้นสถานีตรวจวัดดังกล่าวควร ใช้เป็นสถานีเฝ้าระวังการเกิดแผ่นดินไหวโดยควรมีการตรวจวัดก๊าซเรดอนอย่างต่อเนื่อง&nbsp;</p>', 'สาขาวิชาฟิสิกส์ประยุกต์', '', '', 'มหาวิทยาลัยสงขลานครินทร์ วิทยาเขตปัตตานี'),
('ITM00000000033', 'การทำนายการเกิดแผ่นดินไหวบริเวณรอยเลื่อนระนอง จังหวัดระนอง โดยวิเคราะห์ปริมาณก๊าซเรดอนที่เปลี่ยนแปลง', 'COM00000000007', 'COM00000000002', 'Prediction of Earthquakes at the Ranong Fault, Ranong Province by Analyzing the Amount of Radon Gas Changed', NULL, 10, '2566', '', '<p>แผ่นดินไหวเป็นปรากฏการณ์ธรรมชาติที่บ่งบอกว่าโลกยังไม่อยู่ในสภาวะสมดุล เนื่องจากความกดดันมหาศาลที่สะสมภายใต้แผ่นเปลือกโลก ทำให้เกิดการปล่อยพลังงานออกมาใน รูปคลื่นแผ่นดินไหว ส่งผลให้โครงสร้างอาคารต่าง ๆ ได้รับความเสียหายหรือพังทลาย รวมถึงชีวิตของ ผู้คน ส่วนใหญ่เกิดในบริเวณรอยเลื่อนมีพลังพาดผ่านในพื้นที่ และในบริเวณนี้จะมีการแพร่ของก๊าซ เรตอนขึ้นมาอันเนื่องมาจากการเคลื่อนตัวของแผ่นเปลือกโลก การเพิ่มขึ้นหรือลดลงของก๊าซเรดอน อย่างฉับพลัน เป็นปรากฏการณ์ที่เกิดขึ้นก่อนเกิดแผ่นดินไหว การเปลี่ยนแปลงของก๊าซเรดอนบริเวณรอยเลื่อนระนอง จังหวัดระนอง 10 ตำแหน่งและบริเวณ ตำแหน่งอ้างอิง 2 ตำแหน่ง (ความยาวรอยเลื่อนเส้นนี้ 20.65 km) เนื่องจากบริเวณนี้รอยเลื่อนระนอง พาดผ่านในพื้นที่ชุมชนจึงมีความน่าสนใจในการทำวิจัย โดยตรวจวัดปริมาณความเข้มข้นของก๊าซ เรตอนด้วยเทคนิคหัววัดรอยนิวเคลียร์ชนิดของแข็ง ชนิดแผ่นฟิล์ม CR-39 เพื่อวิเคราะห์การ เปลี่ยนแปลงของก๊าซเรดอนและข้อมูลการเกิดแผ่นดินไหวบริเวณรอยเลื่อนระนอง จังหวัดระนองและ บริเวณใกล้เคียง ในช่วง 5 ปี ปี ผลการคึกษาพบว่า บริเวณที่มีรอยเลื่อนพาดผ่านในพื้นที่หรือ อยู่ใกล้แนวรอยเลื่อนจะตรวจวัดความเข้มข้นของก๊าซเรดอนได้สูงกว่าสถานีอื่น ต่อเนื่องไปในอนาคตอีกอย่าง &ldquo;ส่งานข้อมูลของกรมอุตุนิยมวิทยา (Seismograph) และ ในช่วงทำการวิจัยใน ครั้งที่ 1 พบข้อมูลแผ่นดินไหวในกลุ่มรอยเลื่อนระนองทั้งหมด 3 ครั้ง ในพื้นที่อำเภอตะกั่วป่า จังหวัด พังงา จำนวน 2 ครั้ง ขนาด 2.1 และ 2.2 ตามลำดับ และในวันที่ 6 กุมภาพันธ์ 2563 และในพื้นที่ อำเภอบางสะพาน จังหวัดประจวบคีรีขันธ์ จำนวน 1 ครั้ง ขนาด 2.8 โดยความเข้มข้นของก๊าซเรดอน ที่ตรวจวัดได้ทุกสถานี ในครั้งที่ 1 พบว่า มีความเข้มข้นของก๊าซเรดอนสูงในทุกสถานี และลดลงในครั้ง ถัดไปที่ทำการตรวจวัด สรุปได้ว่าการเปลี่ยนแปลงความเข้มข้นของก๊าซเรดอนมีความสัมพันธ์กับ แผ่นดินไหนที่ตรวจวัดได้ และระบุได้ว่าสถานี RNF2 และสถานี RNF8 เป็นสถานีที่มีศักยภาพที่จะใช้ เตือนภัยการเกิดแผ่นดินไหวที่จะเกิดจากแนวรอยเลื่อนระนองในอนาคตได้ เนื่องจาก 2 สถานีนี้ ตรวจวัดปริมาณความเข้มข้นของก๊าซเรดอนได้สูงกว่าสถานีอื่นและ สถานี Background 2 ถึง 5 เท่า และอยู่ใกล้ในแนวรอยเลื่อนระนอง</p>', 'สาขาวิชาฟิสิกส์ประยุกต์', '', '', 'มหาวิทยาลัยสงขลานครินทร์ วิทยาเขตปัตตานี'),
('ITM00000000034', 'การกำหนดอายุด้วยเทคนิคอิเล็กตรอนสปินเรโซแนนซ์ของซากหอยน้ำจืดจากแหล่งโบราณคดีเพิงผาปาโต๊ะโระ ถ้ำเขาหาน จังหวัดสตูล ภาคใต้ของประเทศไทย', 'COM00000000008', 'COM00000000002', 'Electron Spin Resonance Dating of Freshwater Shells in Pa Toh Roh Shelter Archaeological site, Khao Han Cave,   Satun Province, Southern Thailand', NULL, 10, '2566', '', '<p>สำนักศิลปากรที่ 13 สงขลา ได้สำรวจและขุดค้นแหล่งโบราณคดีทางภาคใต้ตอนล่างของประเทศไทย ซึ่งพบทั้งหลักฐานทางโบราณวัตถุและนิเวศวัตถุจำนวนมาก เช่น โครงกระดูกมนุษย์ ภาชนะดินเผา เปลือกหอย กระดูกสัตว์ หนึ่งในแหล่งโบราณคดีนั้นคือ แหล่งโบราณคดีเพิงผาปาโต๊ะโระ ถ้ำเขาหาน จังหวัดสตูล ภาคใต้ของประเทศไทย งานวิจัยนี้ได้ประยุกต์ใช้เทคนิคอิเล็กตรอนสปินเรโซแนนซ์ (ESR) เพื่อกำหนดอายุซากหอยน้ำจืดซึ่งเก็บจากแหล่งโบราณคดีเพิงผาปาโต๊ะโระ จำนวน 6 ตัวอย่าง ที่ระดับความลึกต่างกัน 3 ระดับ ประกอบด้วย ตัวอย่างซากหอยน้ำจืดรหัส SH1-010, SH2-123, SH3-248 (ระดับ 2, 70-80 cm), SH3-028, SH5-253 (ระดับ 3, 80-90 cm) และ SH6-140 (ระดับ 4, 90-100 cm) จากการตรวจสอบตัวอย่างซากหอยน้ำจืดด้วยเทคนิคการเลี้ยวเบนรังสีเอกซ์ (XRD) พบว่าโครงสร้างผลึกแบบอราโกไนต์และแคลไซต์ ต่อมาศึกษาลักษณะเฉพาะของสัญญาณ ESR จากผลึกตัวอย่างซากหอยน้ำจืด ขนาด 90-150 &micro;m พบว่าสัญญาณ ESR ที่ไม่ผ่านการฉายรังสี (0 Gy) ปรากฏสัญญาณแบบหกพีคและสัญญาณแบบพีคคู่ โดยสัญญาณแบบหกพีคระบุว่าเป็นสัญญาณที่เกิดจากแมงกานีสไอออน (Mn2+) และสัญญาณแบบพีคคู่ระบุว่าเกิดจากปฏิกิริยาระหว่างหินปูนของแคลเซียมคาร์บอเนตในซากหอยน้ำจืดกับความชื้น และเมื่อผ่านการฉายรังสีที่ขนาด 120 Gy พบว่าสัญญาณที่เกิดจากแมงกานีสไอออน (Mn2+) ไม่มีการเพิ่มขึ้นตามปริมาณรังสี แต่เพิ่มขึ้นบริเวณภายใต้สนามแม่เหล็กในช่วง 349-352 mT ซึ่งสามารถระบุชนิดของสัญญาณที่เกิดขึ้นได้ ซึ่งประกอบด้วยสัญญาณที่เกิดจากโมเลกุลไอออน SO2- และ SO3- ที่มีค่า g = 2.0057 และ g = 2.0031 ตามลำดับ และโมเลกุลไอออน CO2- ที่มี g = 2.0016 และ g = 1.9973 จากผลดังกล่าว เมื่อนำมาวิเคราะห์พบว่า สัญญาณที่ g = 2.0016 ที่เกิดจากโมเลกุลไอออน CO2- มีความเหมาะสมต่อการวิเคราะห์ค่าปริมาณรังสีสะสมที่ใช้ในการกำหนดอายุด้วยเทคนิค ESR โดยศึกษาจากกราฟความสัมพันธ์ของความเข้มสัญญาณ ESR ที่เพิ่มขึ้นจากการฉายรังสีแกมมาตั้งแต่ 0-120 Gy ด้วยวิธี Additive dose พบว่ามีความสัมพันธ์เป็นเชิงเส้น และมีค่าปริมาณรังสีสะสม 11.32&plusmn;0.39 Gy ถึง 22.84&plusmn;0.76 Gy ต่อมาวิเคราะห์เพื่อหาค่าปริมาณรังสีต่อปี โดยศึกษาจากปริมาณความเข้มข้นธาตุกัมมันตรังสีในธรรมชาติ (U-238, Th-232 และ K-40) ทั้งในตัวอย่างซากหอยน้ำจืดและดินรอบซากหอยน้ำจืด ด้วยเทคนิค NAA รวมทั้งปริมาณรังสีคอสมิก พบว่ามีค่า 2.88&plusmn;0.07 ถึง 6.90&plusmn;0.06 mGy/y (6) จากผลของปริมาณรังสีสะสมและปริมาณรังสีต่อปี เมื่อนำมาวิเคราะห์ค่าอายุของตัวอย่างซากหอยน้ำจืด พบว่ามีค่า 3,310&plusmn;115 ถึง 4,655&plusmn;210 y ค่าอายุของซากหอยน้ำที่ได้นี้สามารถยืนยันได้ว่าจัดอยู่ในสมัยยุคก่อนประวัติศาสตร์ โดยมีอายุย้อนไปถึงยุคหินใหม่ (Neolithic period) ซึ่งคล้ายกันกับการค้นพบของแหล่งโบราณคดีใกล้เคียง นอกจากนี้อายุที่ได้ยังสอดคล้องกับผลลัพธ์จากการรายงานการกำหนดอายุแบบสัมพัทธ์ของสำนักกรมศิลปากรที่ 13 สงขลา รวมทั้งการตรวจสอบของซากหอยน้ำจืดด้วยเทคนิคเทอร์โมลูมิเนสเซนซ์ที่ทำการศึกษามาก่อนหน้านี้แล้ว</p>', 'สาขาวิชาฟิสิกส์ประยุกต์', '', 'https://kb.psu.ac.th/bitstreams/53ea335c-a2fc-417d-b708-00a9817e05db/download', 'มหาวิทยาลัยสงขลานครินทร์ วิทยาเขตปัตตานี'),
('ITM00000000035', 'การกำหนดอายุของเครื่องปั้นดินเผาและเปลือกหอยน้ำจืดด้วยเทคนิคลูมิเนสเซนซ์ จากแหล่งโบราณคดีเพิงผาทวดตา ทวดยาย จังหวัดสงขลา', 'COM00000000008', 'COM00000000002', 'Dating of Pottery and Freshwater Shells in Thoud-Ta Thoud-Yai Archaeological Site at Cave Songkhla Province using Luminescence Technique', NULL, 10, '2566', NULL, '<p>แหล่งโบราณคดีเพิงผาทวดตา ทวดยาย จังหวัดสงขลา สันนิษฐานเบื้องต้นว่าเป็นแหล่งโบราณคดีในยุคก่อนประวัติศาสตร์ทางภาคใต้ของประเทศไทย เนื่องจากค้นพบหลักฐานทางโบราณคดีมากมาย ได้แก่ ซากเปลือกหอย ลูกปัด โครงกระดูกมนุษย์ กระดูกสัตว์ และเศษภาชนะเครื่องปั้นดินเผา งานวิจัยนี้สนใจวิเคราะห์ค่าอายุด้วยเทคนิคลูมิเนสเซนซ์ในตัวอย่างเศษเครื่องปั้นดินเผาและซากเปลือกหอยน้ำจืด ซึ่งตัวอย่างทั้งสองอยู่ในระดับชั้นดินเดียวกันคือ 50-60 cm เมื่อตรวจสอบโครงสร้างผลึกด้วยเทคนิคการเลี้ยวเบนของรังสีเอกซ์ (X-ray diffraction, XRD) พบว่าตัวอย่างเครื่องปั้นดินเผาที่สกัดแล้วมีโครงสร้างเป็นผลึกควอตซ์ และตัวอย่างเปลือกหอยน้ำจืดมีโครงสร้างเป็นอะราโกไนต์และแคลไซต์ กระบวนการกำหนดอายุด้วยเทคนิคลูมิเนสเซนซ์ แบ่งเป็นสองส่วนคือ ปริมาณรังสีสะสม และปริมาณรังสีต่อปี ในส่วนแรกพบว่าผลการศึกษาตัวอย่างเครื่องปั้นดินเผาด้วยเทคนิค TL อุณหภูมิที่ 180 ํ C เหมาะสมที่สุดในการกำหนดอายุ โดยค่าปริมาณรังสีสะสมเฉลี่ยของตัวอย่างมีค่าเท่ากับ 12.49&plusmn;0.12 Gy และปริมาณรังสีสะสมเฉลี่ยของตัวอย่างเครื่องปั้นดินเผาด้วยเทคนิค OSL มีค่าเท่ากับ 12.56 &plusmn; 0.10 Gy ในขณะที่ปริมาณรังสีสะสมของตัวอย่างเปลือกหอยน้ำจืดด้วยเทคนิค TL พบว่าอุณหภูมิที่ 350 ํ C เหมาะสมที่สุดในการกำหนดอายุ ค่าปริมาณรังสีสะสมของตัวอย่างเปลือกหอยน้ำจืดมีค่าเท่ากับ 30.49&plusmn;0.05 Gy ในส่วนที่สองคือ ปริมาณรังสีต่อปีของตัวอย่างเครื่องปั้นดินเผา และเปลือกหอยน้ำจืด ซึ่งวิเคราะห์จากปริมาณความเข้มข้นของธาตุยูเรเนียม (U-238) ทอเรียม (Th-232) และโพแทสเซียม (K-40) ของตัวอย่างและสิ่งแวดล้อมรอบตัวอย่าง รวมถึงรังสีคอสมิก โดยวัดปริมาณกัมมันตภาพรังสีด้วยระบบวัดรังสีแกมมาด้วยหัววัดเจอร์มาเนียมบริสุทธิ์สูง (HPGe) และการวิเคราะห์โดยการอาบนิวตรอน (NAA) พบว่า ปริมาณรังสีต่อปีของตัวอย่างเครื่องปั้นดินเผามีค่าเท่ากับ 1.139 &plusmn; 0.11 mGy/year และของตัวอย่างเปลือกหอยน้ำจืดมีค่าเท่ากับ 3.360 &plusmn; 0.20 mGy/year ซึ่งจากผลการวิเคราะห์ปริมาณทั้งสองข้างต้นสามารถนำมากำหนดค่าอายุของตัวอย่างได้ดังนี้ เครื่องปั้นดินเผาที่วิเคราะห์ด้วยเทคนิค TL และ OSL มีค่าอายุเท่ากับ 10,930 &plusmn; 1,090 และ 11,031 &plusmn; 1,165 years ตามลำดับ และค่าอายุของเปลือกหอยน้ำจืดที่วิเคราะห์ด้วยเทคนิค TL มีค่าเท่ากับ 9,067 &plusmn; 531 years พบว่าค่าอายุของเครื่องปั้นดินเผาและเปลือกหอยน้ำจืดมีอายุที่ใกล้เคียงกันมาก ซึ่งเป็นไปตามข้อสันนิษฐานที่ว่า ตัวอย่างที่อยู่ในชั้นดินระดับเดียวกันควรมีอายุที่ใกล้เคียงกัน และค่าอายุที่ใกล้เคียงกันนี้ก็สามารถยืนยันอายุของแหล่งโบราณคดีเพิงผาทวดตา ทวดยายได้อีกว่าเป็นแหล่งโบราณคดีในยุคก่อนประวัติศาสตร์จริง ผลการศึกษาเหล่านี้สามารถเชื่อมโยงกับประวัติศาสตร์ภาคใต้ของประเทศไทยซึ่งเป็นเป้าหมายหลักของการศึกษาวิจัย</p>', 'สาขาวิชาฟิสิกส์ประยุกต์', '', '', 'มหาวิทยาลัยสงขลานครินทร์ วิทยาเขตปัตตานี'),
('ITM00000000036', 'กระบวนการกลายเป็นคำสันธานของคำกริยาในภาษาไทย', 'COM00000000004', 'COM00000000002', 'Grammaticalization of Verbs into Conjunctions in the Thai Language', NULL, 10, '2566', NULL, '<p>งานวิจัยนี้มีวัตถุประสงค์เพื่อศึกษากระบวนการกลายเป็นคำสันธานของคำกริยา ในภาษาไทยจำนวน 25 คำ ได้แก่ คำว่า กลับ กว่า เกิด ขืน คล้าย คือ จน ซ้ำ ตรง ต่อ ตาม ถึง แถม เท่า เผื่อ พอ ลง ลอง เลย แล แล้ว ยัง ไว้ เหมือน และ ให้ ตั้งแต่สมัยสุโขทัยถึงปัจจุบันปีพุทธศักราช 2560 โดยมีวัตถุประสงค์เพื่อศึกษาหน้าที่และความหมายของคำสันธาน ที่มีรูปเดียวกับคำกริยาจำนวน 25 คำ และเพื่ออธิบายกระบวนการกลายเป็นคำสันธานของคำกริยาทางด้านวากยสัมพันธ์และความหมาย ทั้งนี้ผู้วิจัยมีสมมติฐานว่าคำสันธานที่มีรูปเดียวกับคำกริยา ในสมัยปัจจุบันทำหน้าที่และมีความหมายแตกต่างกันในภาษาไทยแต่ละสมัย และการเปลี่ยนแปลงทางวากยสัมพันธ์และความหมายของคำสันธานที่มีรูปเดียวกับคำกริยาสอดคล้องกับแนวคิด การกลายเป็นคำไวยากรณ์<br>ผลการศึกษาพบว่า ในแต่ละสมัยคำจำนวน 25 คำ ปรากฏหน้าที่ได้ 5 หน้าที่ ได้แก่ คำกริยา คำหน้ากริยา คำหลังกริยา คำบุพบท และคำสันธาน การเปลี่ยนแปลงทางความหมาย พบคำที่มีการกลายเป็นคำไวยากรณ์สมบูรณ์แล้ว ได้แก่ คำว่า กว่า โดยปรากฏเป็นคำกริยารอบนอกตั้งแต่สมัยสุโขทัย ในขณะที่ปรากฏเป็นคำสันธานรอบนอกและคำหลังกริยารอบนอกในทุกสมัย คำที่มีการกลายเป็นคำไวยากรณ์ยังไม่สมบูรณ์โดยปรากฏเป็นคำกริยาลดลงในขณะที่เป็นคำสันธานเพิ่มขึ้นอย่างต่อเนื่อง ได้แก่ กลับ เกิด ขืน คล้าย คือ จน ซ้ำ ตรง ต่อ ตาม ถึง แถม เท่า เผื่อ พอ ยัง ลง ลอง เลย แล แล้ว ไว้ เหมือน ให้ โดยมีพัฒนาการอย่างต่อเนื่อง เนื่องจากความถี่ ในปรากฏเป็นคำสันธานสูงขึ้นและลดลงบางสมัย<br>ลักษณะทางความหมายของคำกริยาพบว่าคำกริยาจำนวนหนึ่งมีความหมายเปลี่ยนแปลงไปในลักษณะมีความหมายกว้างขึ้น แบ่งเป็น 2 กลุ่ม กลุ่มแรกเป็นคำกริยา แสดงการกระทำ มีอรรถลักษณ์ขั้นที่ 2 คือ [+เคลื่อนที่] ต่อมา มีอรรถลักษณ์ขั้นที่ 2 เป็น [+เคลื่อนที่] และ [-เคลื่อนที่] ได้แก่ คำว่า กลับ ตาม ถึง ลง กลุ่มที่ 2 เป็นคำกริยาแสดงสภาพที่มีอรรถลักษณ์ขั้นที่ 2 เป็น [+ลักษณะ] ต่อมา มีอรรถลักษณ์ขั้นที่ 2 เป็น [+ลักษณะ] และ [+สถานที่] แล้วยังเป็นคำกริยาแสดงการกระทำ มีอรรถลักษณ์ขั้นที่ 2 เป็น [+เคลื่อนที่] อีกด้วย ได้แก่ คำว่า ตรง<br>นอกจากนี้ลักษณะทางความหมายของคำสันธานยังมีการเปลี่ยนแปลงความหมาย ในลักษณะกว้างออก จำนวน 5 คำ ได้แก่ คำว่า กว่า เป็นสันธานบอกเวลาก่อนต่อมาขยายไป บอกการเปรียบเทียบ และบอกความขัดแย้งเชิงเปรียบเทียบ คำว่า ต่อ เป็นสันธานบอกเงื่อนไข ต่อมาขยายไปบอกสาเหตุที่แสดงผลขัดแย้ง คำว่า เท่า เป็นคำสันธานบอกเวลาสิ้นสุด ต่อมาขยายไป บอกการเปรียบเทียบ คำว่า พอ เป็นคำสันธานบอกเวลาก่อน ต่อมาขยายความหมายไป บอกวัตถุประสงค์ คำว่า แล้ว เป็นสันธานบอกเวลาภายหลัง และบอกเวลาภายหลังเพื่อเพิ่มความ ต่อมาขยายไปบอกเวลาภายหลังอันเป็นผล บอกเวลาภายหลังซึ่งขัดแย้งกับที่ควรเป็น และบอกเวลาภายหลังเพื่อเพิ่มความซึ่งขัดแย้งกับที่ควรเป็น และยังพบว่ามีการเปลี่ยนแปลงความหมาย ในลักษณะแคบเข้า จำนวน 1 คำ ได้แก่ คำว่า ยัง ปรากฏเป็นคำสันธานบอกความขัดแย้งเชิงตรงข้ามกับที่ควรจะเป็น บอกความขัดแย้งเชิงเปรียบเทียบ และบอกการเสริมความ ต่อมามีความหมาย แคบเข้า โดยไม่ปรากฏการบอกความขัดแย้งเชิงเปรียบเทียบ<br>กระบวนการกลายเป็นคำไวยากรณ์ของคำที่ศึกษาพบว่า ผ่านกลไกทางวากยสัมพันธ์ คือ การวิเคราะห์ใหม่และการเทียบแบบ ผ่านการเปลี่ยนแปลงทางความหมาย คือ การอุปลักษณ์และการนามนัย ทำให้เกิดการเปลี่ยนแปลงทางภาษา ดังนี้ (1) การทำให้มีความหมายทั่วไป (2) การสูญคุณสมบัติของหมวดคำ (3) การเจาะจงเลือก (4) กระบวนการแยก และ (5) การนำมาใช้ใหม่ ส่วนทิศทางการกลายเป็นคำไวยากรณ์เป็นการเปลี่ยนแปลงแบบทิศทางเดียวและค่อยเป็นค่อยไป</p>', 'สาขาวิชาภาษาไทย', '', '', 'มหาวิทยาลัยสงขลานครินทร์ วิทยาเขตปัตตานี'),
('ITM00000000037', 'การพัฒนาวัสดุเชิงประกอบจีโอพอลิเมอร์จากกากตะกอนเหล็กเป็นวัสดุกำบังรังสีแกมมา', 'COM00000000009', 'COM00000000002', 'Development of Geopolymer Composite from Iron Sludge as a Gamma Radiation Shielding Material', NULL, 10, '2564', NULL, '<p data-path-to-node=\"0\">ในการศึกษาครั้งนี้ได้ทำการพัฒนาวัสดุเชิงประกอบจีโอโพลิเมอร์จากกากตะกอนเหล็กเป็นวัสดุกำบังรังสีแกมมาเพื่อพัฒนาเป็นวัสดุกำบังรังสีแทนการใช้ปูนซีเมนต์ที่ก่อให้เกิดก๊าซคาร์บอนไดออกไซด์ จากกระบวนการเผาที่อุณหภูมิสูง และทำการศึกษาอิทธิพลของปริมาณกากตะกอนเหล็กจากโรงงานอุตสาหกรรม ที่มีต่อคุณสมบัติทางกายภาพและการลดทอนรังสีของวัสดุเชิงประกอบจีโอโพลิเมอร์ที่ได้ โดยในการทดลองใช้วัตถุดิบหลัก คือ ดินเหนียวจังหวัดนครศรีธรรมราช สารละลายด่างเข้มข้นที่มีส่วนผสมของสารละลายโซเดียมซิลิเกต (<span class=\"math-inline\" data-math=\"\\text{Na}_2\\text{SiO}_3\" data-index-in-node=\"474\">$\\text{Na}_2\\text{SiO}_3$</span>) ต่อสารละลายโซเดียมไฮดรอกไซด์ (<span class=\"math-inline\" data-math=\"\\text{NaOH}\" data-index-in-node=\"529\">$\\text{NaOH}$</span>) คือ <span class=\"math-inline\" data-math=\"2:1\" data-index-in-node=\"546\">$2:1$</span> โดยความเข้มข้นของสารละลายโซเดียมไฮดรอกไซด์ คือ <span class=\"math-inline\" data-math=\"10\\text{ M}\" data-index-in-node=\"597\">$10\\text{ M}$</span> และใช้กากตะกอนเหล็กที่ปริมาณ <span class=\"math-inline\" data-math=\"0, 10, 20, 30, 40\" data-index-in-node=\"638\">$0, 10, 20, 30, 40$</span> และ <span class=\"math-inline\" data-math=\"50\\%\" data-index-in-node=\"660\">$50\\%$</span> โดยมวลของดินเหนียว ทำการผสมและขึ้นรูปด้วยวิธีการอัดจากนั้นบ่มที่อุณหภูมิห้องเป็นเวลา <span class=\"math-inline\" data-math=\"28\" data-index-in-node=\"750\">$28$</span> วัน แล้วนำไปทดสอบสมบัติต่าง ๆ จากผลการทดลอง พบว่า คุณสมบัติทางกายภาพ จีโอพอลิเมอร์มีความหนาแน่นเพิ่มขึ้นเมื่อเพิ่มปริมาณกากตะกอนเหล็กมากขึ้น โดยความหนาแน่นอยู่ที่ช่วง <span class=\"math-inline\" data-math=\"2.026 - 2.207\\text{ g/cm}^3\" data-index-in-node=\"920\">$2.026 - 2.207\\text{ g/cm}^3$</span> ส่วนร้อยละการดูดซึมน้ำมีค่าต่ำสุดเท่ากับ <span class=\"math-inline\" data-math=\"11.7\\%\" data-index-in-node=\"989\">$11.7\\%$</span> ที่ปริมาณกากตะกอนเหล็ก <span class=\"math-inline\" data-math=\"20\\%\" data-index-in-node=\"1019\">$20\\%$</span> ในขณะที่ความทนต่อแรงอัดของจีโอพอลิเมอร์ มีค่าสูงที่สุดเท่ากับ <span class=\"math-inline\" data-math=\"80\\text{ MPa}\" data-index-in-node=\"1086\">$80\\text{ MPa}$</span> ที่ปริมาณกากตะกอนเหล็กเท่ากับ <span class=\"math-inline\" data-math=\"20\\%\" data-index-in-node=\"1130\">$20\\%$</span> เช่นกัน ซึ่งสอดคล้องกับผลของค่าร้อยละการดูดซึมน้ำกับผล SEM ที่แสดงการกระจาย และแทรกตัวของกากตะกอนเหล็กในจีโอพอลิเมอร์ ส่วนการศึกษาโครงสร้างทางจุลภาคของจีโอพอลิเมอร์ด้วยเทคนิค XRD แสดงให้เห็นว่า ภายหลังการเกิดปฏิกิริยาจีโอพอลิเมอร์มีโครงสร้างแบบกึ่งผลึก และผลึกของแร่ควอตซ์ในดินเหนียวไม่เกิดการเปลี่ยนโครงสร้าง ในทางตรงกันข้ามแร่เกอลินไนต์ (Kaolinite) ได้เปลี่ยนโครงสร้าง นอกจากนี้ คุณสมบัติทางการลดทอนรังสี จีโอพอลิเมอร์ดินเหนียวผสมกากตะกอนเหล็ก ที่ระดับพลังงาน <span class=\"math-inline\" data-math=\"1.172\" data-index-in-node=\"1597\">$1.172$</span> และ <span class=\"math-inline\" data-math=\"1.330\\text{ MeV}\" data-index-in-node=\"1607\">$1.330\\text{ MeV}$</span> จากแหล่งกำเนิดรังสีแกมมา <span class=\"math-inline\" data-math=\"^{60}\\text{Co}\" data-index-in-node=\"1649\">$^{60}\\text{Co}$</span> พบว่า สัมประสิทธิ์การลดทอนรังสีแกมมาเชิงเส้นมีค่าแปรผันตรงกับปริมาณกากตะกอนเหล็ก แต่อย่างไรก็ตาม ความสามารถในการลดทอนรังสีไม่ได้ขึ้นกับความหนาแน่นของวัสดุเพียงอย่างเดียว แต่ขึ้นกับการกระจายตัวของสารตัวเติมในวัสดุที่เป็นเนื้อหลักด้วยเช่นกัน โดยสัมประสิทธิ์การลดทอนรังสีแกมมาเชิงเส้นมีค่าสูงสุดที่ปริมาณตะกอนเหล็ก <span class=\"math-inline\" data-math=\"50\\%\" data-index-in-node=\"1976\">$50\\%$</span> มีค่าสูงสุดเท่ากับ <span class=\"math-inline\" data-math=\"0.8428 \\pm 8.5 \\times 10^{-2}\\text{ cm}^{-1}\" data-index-in-node=\"2000\">$0.8428 \\pm 8.5 \\times 10^{-2}\\text{ cm}^{-1}$</span> ที่ระดับพลังงาน <span class=\"math-inline\" data-math=\"1.330\\text{ MeV}\" data-index-in-node=\"2061\">$1.330\\text{ MeV}$</span> และ <span class=\"math-inline\" data-math=\"0.8285 \\pm 2.8 \\times 10^{-2}\\text{ cm}^{-1}\" data-index-in-node=\"2082\">$0.8285 \\pm 2.8 \\times 10^{-2}\\text{ cm}^{-1}$</span> สำหรับพลังงาน <span class=\"math-inline\" data-math=\"1.172\\text{ MeV}\" data-index-in-node=\"2141\">$1.172\\text{ MeV}$</span> ส่วนความหนา (HVL) คือความหนาที่ทำให้ความเข้มรังสีลดลงครึ่งหนึ่ง ซึ่งมีค่าลดลงเมื่อปริมาณกากตะกอนเหล็กเพิ่มขึ้น ในรูปร้อยละของรังสีที่ผ่านแผ่นกำบังรังสี พบว่าแผ่นจีโอพอลิเมอร์สามารถป้องกันรังสีได้ <span class=\"math-inline\" data-math=\"35.5 &ndash; 64.5\\%\" data-index-in-node=\"2354\">$35.5 &ndash; 64.5\\%$</span></p>\r\n<p data-path-to-node=\"1\">จากงานวิจัยนี้ สามารถสรุปได้ว่า กากตะกอนเหล็กมีความสามารถป้องกันรังสีแกมมา และยังช่วยเสริมความแข็งแรงให้จีโอพอลิเมอร์ได้</p>', 'สาขาวิชาฟิสิกส์ประยุกต์', '', '', 'มหาวิทยาลัยสงขลานครินทร์ วิทยาเขตปัตตานี'),
('ITM00000000038', 'วาทกรรมการท่องเที่ยวในนิตยสารเพื่อการท่องเที่ยวของไทย', 'COM00000000008', 'COM00000000002', 'Discourse on Tourism in Thai Travel Magazines', NULL, 10, '2565', NULL, '<p>งานวิจัยนี้มุ่งศึกษาวาทกรรมการท่องเที่ยวในนิตยสารเพื่อการท่องเที่ยวของไทย ที่ปรากฏในนิตยสารอนุสาร อ.ส.ท. และนิตยสารเพื่อนเดินทาง ระหว่าง พ.ศ. 2530&ndash;2559 จานวน 720 ฉบับ ผู้วิจัยเลือกศึกษาเฉพาะบทความแนะนาสถานที่ท่องเที่ยว บทบรรณาธิการ และคอลัมน์ถาม-ตอบจดหมายของผู้อ่าน โดยใช้แนวทางทฤษฎีวาทกรรมวิเคราะห์เชิงวิพากษ์ (Critical Discourse Analysis) และแนวคิดชาติพันธุ์วรรณนาแห่งการสื่อสาร (Ethnography of Communication) เป็นกรอบในการวิเคราะห์ ผลการศึกษาปรากฏดังนี้ นิตยสารเพื่อการท่องเที่ยวของไทยถ่ายทอดอุดมการณ์สาคัญ 5 อุดมการณ์ ได้แก่ 1. อุดมการณ์ทุนนิยม 2. อุดมการณ์ความเป็นเมืองความเป็นชนบท 3. อุดมการณ์การพัฒนา 4. อุดมการณ์ความเป็นไทย และ 5. อุดมการณ์ชนชั้นทางสังคม โดยผู้ผลิตได้ประกอบสร้างและถ่ายทอดอุดมการณ์ทั้งหมดผ่านกลวิธีทางภาษา 10 กลวิธี ได้แก่ กลวิธีการใช้คาเรียกขาน กลวิธีคาแสดงอาการ กลวิธีการใช้อุปลักษณ์ กลวิธีแสดงทัศนภาวะ (ทัศนภาวะความมั่นใจ ทัศนภาวะความพึงพอใจ ทัศนภาวะความต้องการ) กลวิธีการอ้างถึง (การอ้างถึงเชิงสถิติ การอ้างถึงรางวัล การอ้างถึงแบบเหมารวม และการอ้างถึงคาสัมภาษณ์ของบุคคลต่าง ๆ) กลวิธีการขยายความ กลวิธีการใช้สหบท กลวิธีการใช้มูลบท กลวิธีการตั้งคาถาม เชิงวาทศิลป์ และกลวิธีการใช้จุดจับใจเชิงข่าว ซึ่งตลอดระยะเวลา 30 ปี (พ.ศ. 2530-2559) นิตยสารเพื่อการท่องเที่ยวของไทยได้ถ่ายทอดและผลิตซ้าอุดมการณ์ตามการปฏิสัมพันธ์ที่มีต่อเหตุการณ์ ในสังคม นโยบายส่งเสริมการท่องเที่ยว และระบบเศรษฐกิจของประเทศในช่วงเวลาต่าง ๆ</p>', 'สาขาวิชาภาษาไทย', '', '', 'มหาวิทยาลัยสงขลานครินทร์ วิทยาเขตปัตตานี'),
('ITM00000000039', 'วาทกรรม“เด็กดี”: การศึกษาเปรียบเทียบแบบเรียนชั้นประถมศึกษาไทยกับมาเลเซีย', 'COM00000000004', 'COM00000000002', '“Good Child” Discourses: Comparative Study of Thai and Malaysian', NULL, 10, '2565', NULL, '<p>วิทยานิพนธ์นี้มีวัตถุประสงค์เพื่อวิเคราะห์และเปรียบเทียบวาทกรรมและปฏิบัติการทาง วาทกรรม&ldquo;เด็กดี&rdquo; ในบริบทสังคมและวัฒนธรรมของไทยกับมาเลเซีย ตามกรอบแนวคิดวาทกรรมวิเคราะห์เชิงวิพากษ์ของแฟร์คลาฟ (Fairclough, 1995) สมมุติฐานการวิจัยมี 2 ประการ คือ ประการแรก วาทกรรม&ldquo;เด็กดี&rdquo; ในแบบเรียนของไทยประกอบสร้างขึ้นจากชุดวาทกรรมต่างๆ ได้แก่ วาท-กรรมชาติ วาทกรรมศาสนาพุทธ วาทกรรมพระมหากษัตริย์ วาทกรรมระบบอาวุโสและระบบอุปถัมภ์ รวมถึงวาทกรรมหน้าที่ของปัจเจกบุคคล ส่วนวาทกรรมในแบบเรียนมาเลเซียประกอบสร้างขึ้นจากวาทกรรมความรักศักดิ์ศรีของปัจเจกบุคคล วาทกรรมสถาบันครอบครัวและวาทกรรมว่าด้วย พหุวัฒนธรรมรวมทั้งชุดวาทกรรมศาสนาอิสลาม ประการที่ 2 วาทกรรมและปฏิบัติการทางวาทกรรม&ldquo;เด็กดี&rdquo; ในบริบทสังคมและวัฒนธรรมของไทยกับมาเลเซียมีทั้งที่เหมือนและแตกต่างกัน กลุ่มข้อมูลที่ใช้ศึกษา คือ แบบเรียนไทยและมาเลเซียในรอบ 1 ทศวรรษ (ระหว่าง พ.ศ. 2550 &ndash; 2559) จำนวน 39 เล่ม ได้แก่ แบบเรียนของไทย จำนวน 24 เล่ม และแบบเรียนของมาเลเซีย จำนวน 15 เล่ม<br>ผลการวิจัยสรุปได้ว่า แบบเรียนไทยและมาเลเซีย มีวาทกรรม&ldquo;เด็กดี&rdquo; ร่วมกัน ได้แก่ วาทกรรมชาติ วาทกรรมศาสนา วาทกรรมพระมหากษัตริย์ วาทกรรมระบบอาวุโส และวาทกรรมหน้าที่ของปัจเจกบุคคล<br>ส่วนวาทกรรม&ldquo;เด็กดี&rdquo; ที่แตกต่างกัน ได้แก่ ประการแรก วาทกรรม&ldquo;เด็กดี&rdquo; ของไทยจะให้ความสำคัญกับพระมหากษัตริย์ ส่วนแบบเรียนมาเลเซียให้ความสำคัญกับศาสนาในฐานะเป็นศูนย์รวมของจิตใจเป็นหลัก ประการที่สองในแบบเรียนไทยเน้นระบบอาวุโส ทั้งความสัมพันธ์ของคนในครอบครัว ระบบเครือญาติกับสังคมมากกว่าในแบบเรียนของมาเลเซีย ประการที่สาม วาทกรรม&ldquo;เด็กดี&rdquo; ในแบบเรียนไทยสัมพันธ์กับวาทกรรม&ldquo;เด็กดี&rdquo; ที่ภาครัฐเป็นผู้กำหนดค่านิยม 12 ประการ ส่วนในแบบเรียนของมาเลเซีย วาทกรรม&ldquo;เด็กดี&rdquo; สัมพันธ์กับหลักคำสอนของศาสนาอิสลาม</p>', 'สาขาวิชาภาษาไทย', '', '', 'มหาวิทยาลัยสงขลานครินทร์ วิทยาเขตปัตตานี'),
('ITM00000000040', 'สตรีมุสลิม: ชีวิต และบทบาทการเป็นนักเคลื่อนไหวทางสังคมในพื้นที่จังหวัดชายแดนภาคใต้', 'COM00000000006', 'COM00000000002', 'Muslim Women: Life and Role as Social Activists in the Southern Border Provinces', NULL, 10, '2565', NULL, '<p>จังหวัดชายแดนภาคใต้ นอกจากปัญหาสถานการณ์ความไม่สงบที่สร้างความเสียหายต่อชีวิตและทรัพย์สินของคนในพื้นที่แล้ว ยังมีอีกหลายประเด็นที่มีความสาคัญ เช่น ประเด็นสิทธิสตรีความไม่เท่าเทียมระหว่างเพศชายและเพศหญิง การวิจัยนี้มีวัตถุประสงค์เพื่อศึกษา 1) ศึกษารูปแบบการดาเนินชีวิต และสถานภาพทางสังคมของสตรีมุสลิมที่เป็นนักเคลื่อนไหวทางสังคมในพื้นที่สามจังหวัดชายแดนภาคใต้ 2) ศึกษาบทบาทของสตรีมุสลิมในการเป็นนักเคลื่อนไหวทางสังคม และ 3) เสนอแนวทางการพัฒนาสตรีมุสลิมให้มีบทบาทในการเป็นนักเคลื่อนไหวทางสังคม เก็บข้อมูลจากผู้ให้ข้อมูลหลักในพื้นที่สามจังหวัดชายแดนภาคใต้ ได้แก่ จังหวัดปัตตานี จังหวัดยะลา และจังหวัดนราธิวาส จังหวัดละ 5 คน รวมทั้งสิ้น 15 คน โดยใช้เครื่องมือการสัมภาษณ์เชิงลึก และการสนทนากลุ่ม<br>ผลการศึกษาพบว่า<br>1) การศึกษารูปแบบการดาเนินชีวิต และสถานภาพทางสังคมของสตรีมุสลิมที่เป็นนักเคลื่อนไหวในพื้นที่สามจังหวัดชายแดนใต้ เห็นว่าสตรีมุสลิมในพื้นที่สามจังหวัดมีรูปแบบการดาเนินชีวิตที่เรียบง่ายตามครรลองของศาสนาอิสลาม หากสตรีใดที่มีครอบครัวหน้าที่หลักคือการดูแลครอบครัว ไม่ออกไปทางานนอกบ้าน แต่เนื่องด้วยสถานการณ์ความไม่สงบในพื้นที่ที่เกิดขึ้น ทาให้การดาเนินชีวิตของสตรีกลุ่มนี้เปลี่ยนไป เขาสูญเสียผู้นาครอบครัว สูญเสียลูก จากเหตุการณ์ความไม่สงบ หรือแม้แต่ปัญหาการหย่าร้างที่เกิดขึ้นในพื้นที่ ส่งผลให้สตรีกลุ่มนี้ต้องเปลี่ยนแปลงการดาเนินชีวิตของตนเองเพื่อความอยู่รอด และผันตัวมาเป็นนักเคลื่อนไหวทางสังคมเพื่อช่วยเหลือเยียวยาสตรีที่ได้รับผลกระทบคนอื่น ๆ จึงทาให้รูปแบบการดาเนินชีวิตของสตรีมุสลิมในพื้นที่เปลี่ยนไปจากอดีต แต่ในขณะเดียวกันสตรีเหล่านี้ยังคงยึดถือข้อปฏิบัติตนในฐานะภรรยาที่ดี และเป็นแม่ที่ดี ตามที่ศาสนาได้บัญญัติไว้ ในด้านของการได้รับการยอมรับสถานภาพทางสังคม สตรีมุสลิมบางส่วนยังไม่ได้รับการยอมรับจากสังคมอย่างแพร่หลายมากนัก โดยเฉพาะกับคนรุ่นเก่าที่เป็นผู้สูงอายุ ที่มักจะมีความเชื่อและยังคงยึดถือแนวทางปฏิบัติตามหลักศาสนาอิสลามอย่างเคร่งครัด และมองว่าสิ่งที่สตรีกลุ่มนี้กาลังปฏิบัติคือสิ่งที่ผิด ทาให้กลุ่มคนบางกลุ่มในสังคมมีมุมมองที่ไม่ดีนักต่อสตรีมุสลิมที่เป็นนักเคลื่อนไหว<br>2) บทบาทของสตรีมุสลิมในการเป็นนักเคลื่อนไหว ส่วนใหญ่จะมีบทบาทในการช่วยเหลือเยียวยาสตรีที่ได้รับผลกระทบจากความรุนแรงในพื้นที่ ไม่ว่าจะเป็นความรุนแรงจากสถานการณ์หรือแม้กระทั่งความรุนแรงในครอบครัว ลักษณะการทางานคือการเข้าไปให้คาแนะนา ให้คาปรึกษา โดยบทบาทและกระบวนการทางานจะเริ่มตั้งแต่การรับข้อร้องเรียน การลงพื้นที่เข้าไปให้คาปรึกษาแบบตัวต่อตัว และการช่วยเหลือโดยการประสานงานไปยังหน่วยงานรับผิดชอบต่าง ๆ ที่เกี่ยวข้องในพื้นที่ และอีกหนึ่งบทบาทที่สาคัญ คือ การเรียกร้องถึงความเท่าเทียมทางเพศ ส่วนในการดาเนินงานมักพบปัญหา และอุปสรรค คือ การจัดสรรเวลาในการทางานกับเวลาในการดูแลครอบครัวไม่สมดุล และการไม่ถูกยอมรับจากกลุ่มคนบางกลุ่มในสังคม ทาให้การเข้าถึงสตรีมุสลิมที่อยู่ในชุมชนเกิดความยากลาบาก<br>3) แนวทางการพัฒนาสตรีมุสลิมให้มีบทบาทในการเป็นนักเคลื่อนไหวทางสังคมในพื้นที่สามจังหวัดชายแดนภาคใต้ สิ่งสาคัญคือการองค์ความรู้ที่จะต้องได้รับการสนับสนุนจากองค์กรเอกชน ภาครัฐ หรือหน่วยงานที่เกี่ยวข้องอื่น ๆ เข้ามามีส่วนร่วมในการให้ความรู้ ความเข้าใจในด้านงานขับเคลื่อนสังคมให้แก่สตรีมุสลิมที่เป็นนักเคลื่อนไหวในพื้นที่ การส่งเสริมการพัฒนาสตรีมุสลิมให้สามารถเป็นกระบอกเสียงแก่ตนเองต่อการเรียกร้องสิทธิที่เกิดจากการไม่ได้รับความยุติธรรมในสังคมอย่างเข้มแข็ง และสร้างพลังใจให้สตรีมุสลิมได้เล็งเห็นถึงคุณค่าในตัวเอง มีการจัดสรรกระบวนการทางานของเครือข่ายที่ดี เพื่อไม่ให้เกิดปัญหากับรูปแบบการดาเนินชีวิตของสตรีมุสลิมในอนาคต</p>', 'สาขาวิชาการบริหารการพัฒนาสังคม', '', '', 'มหาวิทยาลัยสงขลานครินทร์ วิทยาเขตปัตตานี'),
('ITM00000000041', 'ความสุขของผู้สูงอายุในอำเภอเทพา จังหวัดสงขลา', 'COM00000000003', 'COM00000000002', 'Happiness among the older persons in Thepha District, Songkhla Province', NULL, 10, '2565', NULL, '<p>การวิจัยครั้งนี้มีวัตถุประสงค์ 1) เพื่อประเมินความสุขของผู้สูงอายุในอำเภอเทพา จังหวัดสงขลา 2) เพื่อวิเคราะห์ปัจจัยที่มีผลต่อความสุขของผู้สูงอายุในอำเภอเทพา จังหวัดสงขลา 3) เพื่อเสนอแนวทางการส่งเสริมความสุขของผู้สูงอายุในอำเภอเทพา จังหวัดสงขลา การวิจัยนี้เป็นการวิจัยแบบผสมผสาน (Mixed Method) จากการสุ่มตัวอย่างจากผู้สูงอายุในอำเภอเทพา จังหวัดสงขลา ทั้งเพศชายและหญิง ที่มีอายุตั้งแต่ 60 ปีขึ้นไป จำนวน 385 คน เครื่องมือที่ใช้ในการเก็บข้อมูลประกอบด้วยแบบประเมินและแบบสัมภาษณ์เกี่ยวกับความสุขของผู้สูงอายุในอำเภอเทพา จังหวัดสงขลา และทำการวิเคราะห์ข้อมูลด้วยค่าสถิติ ร้อยละ ค่าเฉลี่ย ส่วนเบี่ยงแบนมาตรฐาน ค่าสัมประสิทธิ์สหสัมพันธ์ และค่าสถิติการถดถอยพหุคูณ<br>ผลการวิจัยเชิงปริมาณพบว่า ความสุขของผู้สูงอายุในอำเภอเทพา จังหวัดสงขลา โดยรวมอยู่ในระดับมาก เมื่อพิจารณาเป็นรายด้าน พบว่า อันดับแรกเป็นด้านความสุขอันเกิดจากการตระหนักถึงคุณค่าในตนเอง รองลงมาเป็นด้านความสุขอันเกิดจากการได้รับสวัสดิการของรัฐ และ ด้านความสุขอันเกิดจากความสามารถในการดูแลตนเองได้ ตามลำดับ และพบว่า ปัจจัยดังกล่าวมีความสัมพันธ์ทางบวกกับระดับความสุขของผู้สูงอายุ อย่างมีนัยสำคัญทางสถิติที่ระดับ 0.01 ( r = 0.86, 0.77, 0.87 ตามลำดับ) โดยสามารถร่วมพยากรณ์ความความสุขของผู้สูงอายุในอำเภอเทพา จังหวัดสงขลาได้ร้อยละ 88 อย่างมีนัยสำคัญทางสถิติที่ระดับ 0.01 (R2=0.88, p&lt;0.01)<br>ผลการวิจัยเชิงคุณภาพ โดยการสัมภาษณ์ผู้สูงอายุที่มีผลคะแนนสูงสุดทุกตำบลในอำเภอเทพา จำนวน 7 ตำบลๆ ละ 5 คน รวมทั้งสิ้น 35 คน พบว่าผู้สูงอายุส่วนใหญ่ให้นิยามความสุขเป็นการได้อยู่พร้อมหน้าพร้อมตาของคนในครอบครัวและได้เห็นลูกหลานเป็นคนดีประสบความสำเร็จในชีวิต พบแนวทางการส่งเสริมความสุขของผู้สูงอายุในอำเภอเทพา จังหวัดสงขลา ได้แก่ 1) ผู้สูงอายุควรนิยามความสุขให้สอดคล้องกับการตระหนักถึงคุณค่าในตนเอง 2) ผู้สูงอายุควรปรับตัวทางอารมณ์และความคิดให้สอดคล้องกับสภาวะการณ์ปัจจุบัน 3) ผู้สูงอายุควรเลือกงานที่พอเหมาะกับสภาพร่างกาย 4) ผู้สูงอายุควรทำกิจกรรมเวลาว่างให้เกิดประโยชน์ 5) บุคคลคนใกล้ชิดควรให้ความสำคัญต่อผู้สูงอายุ 6) ชุมชนหรือรัฐควรที่จัดสภาพสิ่งแวดล้อมที่ดีให้ผู้สูงอายุ 7) รัฐควรดูแลผู้สูงอายุให้ทั่วถึงและเท่าเทียม 8) รัฐควรจัดสวัสดิการทางสังคมอย่างต่อเนื่อง 9) รัฐควรมีบทบาทในส่งเสริมกิจกรรมทางศาสนาที่ใช้ยึดเหนี่ยวจิตใจให้มากขึ้น 10) รัฐควรเข้ามามีบทบาทในการดูแลความปลอดภัยของชุมชนโดยเฉพาะเรื่องอัตราการเกิดอาชญากรรมต่อผู้สูงอายุ</p>', 'สาขาวิชาการบริหารการพัฒนาสังคม', '', '', 'มหาวิทยาลัยสงขลานครินทร์ วิทยาเขตปัตตานี'),
('ITM00000000042', 'รูปแบบการปฏิบัติงานเชิงสร้างสรรค์ของบุคลากรในองค์การบริหารส่วนตำบล อำเภอเมือง จังหวัดปัตตานี', 'COM00000000009', 'COM00000000002', 'The Creative Performance Model of Personnel in Subdistrict Administrative Organization, Mueang District, Pattani Province', NULL, 10, '2565', '', '<p>การวิจัยครั้งนี้มีวัตถุประสงค์เพื่อ 1) ศึกษาระดับการปฏิบัติงานเชิงสร้างสรรค์ของบุคลากรในองค์การบริหารส่วนตำบล อำเภอเมือง จังหวัดปัตตานี 2) ศึกษาพฤติกรรมการปฏิบัติงานเชิงสร้างสรรค์ของบุคลากรในองค์การบริหารส่วนตำบล อำเภอเมือง จังหวัดปัตตานี 3) เสนอรูปแบบการปฏิบัติงานเชิงสร้างสรรค์ของบุคลากรในองค์การบริหารส่วนตำบล อำเภอเมือง จังหวัดปัตตานี ผู้วิจัยแบ่งการวิจัยเป็น 2 ส่วน คือ 1) วิจัยเชิงปริมาณ กลุ่มตัวอย่างเป็นพนักงานส่วนตำบลในองค์การบริหารส่วนตำบล อำเภอเมือง จังหวัดปัตตานี จำนวน 195 ท่าน เครื่องมือที่ใช้ในการเก็บข้อมูลเป็นแบบสอบถามมาตราส่วนประมาณค่า 5 ระดับ วิเคราะห์ข้อมูลโดยใช้สถิติเชิงพรรณนา ค่าความถี่ ค่าร้อยละ ค่าเฉลี่ย และค่าเบี่ยงเบนมาตรฐาน 2) วิจัยเชิงคุณภาพ กลุ่มตัวอย่าง คือ บุคลากรองค์การบริหารส่วนตำบล อำเภอเมือง จังหวัดปัตตานี 9 ท่าน เป็นบุคลากรระดับปฏิบัติงาน 3 ท่าน บุคลากรระดับหัวหน้างาน 3 ท่าน และผู้บริหาร 3 ท่าน วิเคราะห์ข้อมูลเชิงคุณภาพโดยวิธีวิเคราะห์เนื้อหา&nbsp;ผลการวิจัยพบว่า 1) ระดับการปฏิบัติงานเชิงสร้างสรรค์โดยภาพรวมอยู่ในระดับมาก (</p>', 'สาขาวิชาการบริหารการพัฒนาสังคม', '', '', 'มหาวิทยาลัยสงขลานครินทร์ วิทยาเขตปัตตานี'),
('ITM00000000043', 'แนวทางการเสริมสร้างความมั่นคงทางสุขภาพของแรงงานประมงพื้นบ้าน บ้านปาตา ตำบลตะโละกาโปร์ อำเภอยะหริ่ง จังหวัดปัตตานี', 'COM00000000012', 'COM00000000002', 'Guidelines for Strengthening the Health Security of Traditional Fishing Labor at Pata Village, Talokapo Subdistrict, Yaring District, Pattani Province', NULL, 10, '2565', NULL, '<p>การวิจัยครั้งนี้มีวัตถุประสงค์เพื่อศึกษาสภาพความมั่นคงทางสุขภาพของแรงงานประมงพื้นบ้านและเพื่อหาแนวทางการเสริมสร้างความมั่นคงทางสุขภาพของแรงงานประมงพื้นบ้าน<br>บ้านปาตา ตำบลตะโละกาโปร์ ทำการศึกษาเชิงปริมาณและเชิงคุณภาพ โดยใช้แบบสอบถามเป็นแบบมาตราส่วนประมาณค่า ชนิด 3 ระดับ และสถิติที่ใช้ในการวิเคราะห์ข้อมูล ได้แก่ ค่าเฉลี่ย ส่วนเบี่ยงเบนมาตรฐาน และแบบสัมภาษณ์และสนทนากลุ่ม วิเคราะห์ข้อมูลโดยการวิเคราะห์เนื้อหาผลการศึกษาสภาพความมั่นคงทางสุขภาพของแรงงานประมงพื้นบ้าน พบว่า<br>1) การเข้าถึงบริการทางสุขภาพโดยรวมอยู่ในระดับมาก อย่างไรก็ตามเมื่อพิจารณาเป็นรายด้านพบว่า&nbsp;เข้ารับบริการตรวจสุขภาพเป็นประจำทุกปียังอยู่ในระดับปานกลาง 2) ทักษะการดูแลสุขภาพเบื้องต้นโดยรวมอยู่ในระดับมาก 3) พฤติกรรมสุขภาพ โดยรวมอยู่ในระดับมากทั้ง 4 ด้าน และประเด็นที่อยู่ในระดับน้อย ได้แก่ การออกกำลังกาย 4) ภาวะสุขภาพ โดยรวมอยู่ในระดับมากทั้ง 4 ด้าน สำหรับแนวทางการเสริมสร้างความมั่นคงทางสุขภาพพบว่า หน่วยงานที่เกี่ยวข้องได้มีการดำเนินการตามกฎบัตรออตตาวา ซึ่งมี 3 กลยุทธ์ และ 5 ปฏิบัติ อย่างไรก็ตามหากมีการปรับปรุง และพัฒนาจะส่งผลให้สามารถสร้างเสริมความมั่นคงทางสุขภาพของแรงงานประมงพื้นบ้านได้อย่างมีประสิทธิภาพมากขึ้น</p>', 'สาขาวิชาการบริหารการพัฒนาสังคม', '', '', 'มหาวิทยาลัยสงขลานครินทร์ วิทยาเขตปัตตานี'),
('ITM00000000044', 'การพัฒนาคุณลักษณะผู้ประกอบการเพื่อสังคมของกลุ่มผู้ผลิตปุ๋ย บ้านสามร้อยไร่ ตำบลอัยเยอร์เวง อำเภอเบตง จังหวัดยะลา', 'COM00000000001', 'COM00000000002', 'The Development of Social Enterpreneur Characteristics: A Case of Fertilizer  Producer Group of Sam Roi Rai Village, Ayer Weng Subdistrict,  Betong District, Yala Province', NULL, 10, '2564', NULL, '<p>การวิจัยครั้งนี้มีวัตถุประสงค์เพื่อ ศึกษาคุณลักษณะความเป็นผู้ประกอบการเพื่อสังคม และ เพื่อศึกษาแนวทางการพัฒนาคุณลักษณะผู้ประกอบการเพื่อสังคมของกลุ่มผู้ผลิตปุ๋ย บ้านสามร้อยไร่ ตาบลอัยเยอร์เวง อาเภอเบตง จังหวัดยะลา เป็นการวิจัยเชิงคุณภาพ ศึกษาเกี่ยวกับคุณลักษณะผู้ประกอบการเพื่อสังคมจานวน 16 คุณลักษณะ, องค์ประกอบการประกอบการเพื่อสังคมที่จาเป็นต้องพัฒนาให้ครอบคลุม 4 องค์ประกอบ และนาเสนอวิธีการพัฒนาคุณลักษณะผู้ประกอบการเพื่อสังคม 3 ด้าน เชื่อมโยงกับหลักการบริหารงานของกลุ่ม (PDCA) เพื่อให้เกิดนวัตกรรมของกลุ่มและเพิ่มประสิทธิภาพการทางานของกลุ่มผู้ประกอบการเพื่อสังคม<br>ผลการศึกษาพบว่า คุณลักษณะการประกอบการเพื่อสังคมบ้านสามร้อยไร่ ตาบลอัยเยอร์เวง อาเภอเบตง จังหวัดยะลา มีจานวน 14 คุณลักษณะ ทาให้เกิดแนวทางการพัฒนา ต่อยอดองค์ความรู้ให้กับกลุ่มผู้ผลิตปุ๋ยเกี่ยวกับคุณลักษณะการประกอบการเพื่อสังคม ครอบคลุมครบทั้ง 16 คุณลักษณะ โดยการเสนอวิธีการพัฒนากลุ่มตามหลักการบริหารงานการประกอบการเพื่อสังคมเพื่อเป็นแนวทางการพัฒนาชุมชนอื่นต่อไป</p>', 'สาขาวิชาการบริหารการพัฒนาสังคม', '', '', 'มหาวิทยาลัยสงขลานครินทร์ วิทยาเขตปัตตานี'),
('ITM00000000045', 'แนวทางการพัฒนาแหล่งท่องเที่ยวเชิงอาหาร ย่านเมืองเก่าสงขลา', 'COM00000000008', 'COM00000000002', 'Guidelines for the Development  of  Food Tourism', NULL, 10, '2565', NULL, '<p>การศึกษาแนวทางการพัฒนาแหล่งท่องเที่ยวเชิงอาหาร ย่านเมืองเก่าสงขลา มีวัตถุประสงค์ เพื่อศึกษาสถานการณ์การท่องเที่ยวเชิงอาหาร ย่านเมืองเก่าสงขลาผ่านความต้องการของ นักท่องเที่ยว และมุมมองของผู้ประกอบการ หน่วยงานภาครัฐและเอกชนที่เกี่ยวข้องกับการท่องเที่ยว ศึกษาพฤติกรรมและเปรียบเทียบพฤติกรรมการท่องเที่ยวเชิงอาหารของนักท่องเที่ยวจำแนกตามเพศ อายุ อาชีพ และรายได้ และเสนอแนวทางในการพัฒนาแหล่งท่องเที่ยวเชิงอาหารในย่านเมืองเก่าสงขลา เป็นการวิจัยแบบผสมผสาน (Mixed Method) ประกอบด้วยศึกษาวิจัยเชิงปริมาณ (Quantitative Research) เครื่องมือที่ใช้ คือ แบบสอบถาม จากนักท่องเที่ยวที่เดินทางมา ท่องเที่ยวในย่านเมืองเก่าสงขลา และเชิงคุณภาพ (Qualitative Research) เครื่องมือที่ใช้ คือ แบบสัมภาษณ์จากผู้ประกอบการ หน่วยงานภาครัฐและเอกชนที่เกี่ยวข้องกับการท่องเที่ยวย่านเมืองเก่าสงขลา โดยนำเสนอข้อมูลเป็นตาราง และพรรณนาวิเคราะห์ ผลการศึกษาสรุปได้ดังนี้&nbsp;(1) สถานการณ์การท่องเที่ยวเชิงอาหาร ย่านเมืองเก่าสงขลาผ่านความต้องการของนักท่องเที่ยว และมุมมองของผู้ประกอบการ หน่วยงานภาครัฐและเอกชนที่เกี่ยวข้องกับการท่องเที่ยว พบว่า นักท่องเที่ยวเดินทางมาเพื่อผ่อนคลายความเครียด โดยการรับประทานอาหารและชมบรรยากาศในย่านเมืองเก่าสงขลา เพราะมีอาหารที่หลากหลายและมีพื้นที่ที่สวยงาม ส่วนมุมมองของผู้ประกอบการ หน่วยงานภาครัฐและเอกชนที่เกี่ยวข้องกับการท่องเที่ยว พบว่า ย่านเมืองเก่ามีร้านอาหาร อาคารบ้านเรือน รวมถึงสตรีทอาร์ตที่ดึงดูดนักท่องเที่ยว และสะดวกในการเดินทาง&nbsp;(2) ผลการเปรียบเทียบพฤติกรรมการท่องเที่ยวเชิงอาหารของนักท่องเที่ยวจำแนกตามอายุ อาชีพ และรายได้ พบว่า แตกต่างกัน อย่างมีนัยสำคัญทางสถิติที่ระดับ 0.05 ส่วนนักท่องเที่ยวที่มีเพศแตกต่างกัน มีพฤติกรรมของนักท่องเที่ยว ไม่แตกต่างกัน&nbsp;(3) แนวทางในการพัฒนาแหล่งท่องเที่ยวเชิงอาหารย่านเมืองเก่าสงขลา พบว่า ควรมีการเพิ่มสตรีทอาร์ตที่เกี่ยวกับอาหาร และปรับทัศนวิสัยในร้านอาหารให้มีมุมหรือวิวถ่ายภาพมากขึ้น เพิ่มห้องน้ำ ที่จอดรถ ป้ายบอกทาง รถรางนำเที่ยว มัคคุเทศก์ให้กับนักท่องเที่ยวขาจร จุดปฐมพยาบาล และสิ่งอำนวยความสะดวกให้กับผู้สูงอายุหรือผู้พิการ และเสนอแนะให้มีกิจกรรมมหกรรมอาหารท้องถิ่น แข่งขันรับประทานอาหาร ประกวดการทำอาหาร รวมทั้งให้หน่วยงานที่เกี่ยวข้องและคนในท้องถิ่นร่วมกันวางแผนยุทธศาสตร์เกี่ยวกับการตลาด ตรวจสอบมาตรฐานความปลอดภัยของอาหาร ส่งเสริมให้ชุมชนเป็นเจ้าของกิจการและมีส่วนร่วมพัฒนาการท่องเที่ยวเชิงอาหาร</p>', 'สาขาวิชาการบริหารการพัฒนาสังคม', '', '', 'มหาวิทยาลัยสงขลานครินทร์ วิทยาเขตปัตตานี'),
('ITM00000000046', 'การเตรียมความพร้อมก่อนเข้าสู่วัยผู้สูงอายุของมุสลิมะห์ที่เป็นโสดในเทศบาลเมืองปัตตานี', 'COM00000000003', 'COM00000000002', 'Preparing Female Muslims in Pattani Municipality for Transitioning to Senior Citizens', NULL, 10, '2564', NULL, '<p>การวิจัยนี้เป็นการศึกษาเชิงคุณภาพ (Qualitative Research) มีวัตถุประสงค์&nbsp;(1) เพื่อศึกษาเงื่อนไขการอยู่เป็นโสดของมุสลิมะห์ในเทศบาลเมืองปัตตานี และ (2) เพื่อศึกษา<br>การเตรียมความพร้อมก่อนเข้าสู่วัยผู้สูงอายุของมุสลิมะห์ที่เป็นโสดในเทศบาลเมืองปัตตานีเก็บรวบรวมข้อมูลด้วยแบบสัมภาษณ์กึ่งโครงสร้าง สัมภาษณ์แบบเจาะลึกและการสังเกตแบบไม่มี&nbsp;ส่วนร่วมจากกลุ่มผู้ให้ข้อมูลที่เป็นมุสลิมะห์ ซึ่งมีภูมิลำเนาในเทศบาลเมืองปัตตานี จำนวน 9 คน&nbsp;ใช้วิธีการวิเคราะห์ข้อมูลแบบสามเส้าและนำเสนอข้อมูลด้วยการอธิบายเชิงพรรณนา&nbsp;ผลการวิจัย พบว่า (1) เงื่อนไขการอยู่เป็นโสดของมุสลิมะห์ในเทศบาลเมืองปัตตานี&nbsp;มีเงื่อนไข 4 ด้าน ประกอบด้วย 1) เงื่อนไขด้านครอบครัว ได้แก่ สถานภาพในครอบครัว<br>สภาพแวดล้อมภายในและภายนอกครอบครัว ลักษณะการเลี้ยงดูในครอบครัว ภาระหน้าที่ในครอบครัว 2) เงื่อนไขด้านจิตใจ ได้แก่ ทัศนคติต่อการแต่งงาน มาตรฐานในการเลือกคู่ครอง<br>ประสบการณ์ความรัก 3) เงื่อนไขด้านสังคม ประกอบด้วย การศึกษาและการทำงาน 4) เงื่อนไขด้านวัฒนธรรม ประกอบด้วย การปรับตัวภายใต้คำสอนของศาสนาและการสนับสนุน 5) เงื่อนไขด้านสุขภาพ ประกอบด้วย โรคประจำตัว (2) การเตรียมความพร้อมก่อนเข้าสู่วัยผู้สูงอายุของมุสลิมะห์&nbsp;พบว่ามีมุสลิมะห์ 2 กลุ่มคือ กลุ่มที่มีการเตรียมความพร้อมก่อนเข้าสู่วัย ประกอบด้วยการเตรียมความพร้อมใน 5 ด้าน ได้แก่ 1) ด้านสุขภาพร่างกาย 2) ด้านจิตใจและจิตวิญญาณ&nbsp;3) ด้านการเงิน 4) ด้านที่อยู่อาศัยและผู้ดูแล 5) ด้านสังคม และกลุ่มมุสลิมะห์ที่ไม่ได้มีการเตรียมความ&nbsp;พร้อมก่อนเข้าสู่วัยผู้สูงอายุ</p>', 'สาขาวิชาการบริหารการพัฒนาสังคม', '', '', 'มหาวิทยาลัยสงขลานครินทร์ วิทยาเขตปัตตานี'),
('ITM00000000047', 'ความรู้ทางการเงินและปัจจัยในการเข้าถึงแหล่งเงินทุนของชาวมุสลิมใน จังหวัดปัตตานี', 'COM00000000009', 'COM00000000002', 'Financial Literacy and Factors in Accessing Financial Resources of Muslim in Pattani Province', NULL, 10, '2564', NULL, '<p>The purpose of this research was to Study of Islamic financial literacy and Islamic financial products of Muslims in Pattani Province, study the factors that influence Muslims\' access to financial sources in Pattani Province and Suggest ways to access funding sources for Muslims in Pattani Province. The research was done on a sample of 420 residents of Pattani who practice Islam and are of legal age, all of them are over 20 years old. The binary logistic regression method was then used to analyze the data. The majority of the participants were female, with a bachelor\'s degree and religious education at the Mutawa Setah (5-7) level. They were mostly self-employed. The average monthly income is between 9,000 and 15,000 baht, with monthly costs of less than 9,000 baht. There were 312 samples in all who had access to finance (loanable) and 312 samples who did not (unloanable). According to McFadden R2 met goodness of fit, the model was able to predict with 80.24 percent accuracy in 108 examples of analysis of factors affecting Muslim people\'s access to financing sources in Pattani Province. At the.01 level, the likelihood-ratio chi-squared was statistically significant. The guidelines for accessing funding found that Relevant agencies must provide training on Islamic finance and finance, Public relations on financial or banking matters in which the Shariah principle is applied to provide services, Financial institutions should provide knowledge about writing a business plan and learn about Islamic finance and finance.</p>', 'สาขาวิชาการบริหารการพัฒนาสังคม', '', '', 'มหาวิทยาลัยสงขลานครินทร์ วิทยาเขตปัตตานี'),
('ITM00000000048', 'การประยุกต์ใช้ Tetraselmis sp. เพื่อการเลี้ยงกุ้งในระบบน้ำเขียว และการใช้โปรไบโอติกในอาหารกุ้งสำหรับต่อต้านเชื้อ Vibrio parahaemolyticus', 'COM00000000005', 'COM00000000002', 'Application of Tetraselmis sp. to Green Water Technique for Shrimp  Cultivation and Utilization of Probiotics in Feed on Resistance to Vibrio parahaemolyticus', NULL, 10, '2566', NULL, '<p>การประยุกต์ใช้สาหร่ายขนาดเล็ก Tetraselmis sp. ในระบบน้ําเขียว และการใช้ โปรไบโอติกผสมอาหารกุ้งในการเพาะเลี้ยงกุ้งได้ดําเนินการโดยคาดหวังว่าจะสามารถต่อต้านเชื้อ Vibrio parahaemolyticus ที่ก่อโรคกุ้งได้ &nbsp;ซึ่งอาจเป็นแนวทางหนึ่งในการป้องกันการสูญเสียผลผลิต กุ้งจากเชื้อดังกล่าวในอุตสาหกรรมการเพาะเลี้ยงกุ้ง โดยการทดลองแบ่งเป็น 3 ส่วน คือส่วนแรกเป็น ศึกษาการเจริญเติบโตของ Tetraselmis sp. และ แบคทีเรียสังเคราะห์แสง (Photosynthesis Bacteria, PSB) ที่ระดับความเข้มข้นของนมอินทรีย์แตกต่างกัน ส่วนที่สอง เป็นการศึกษาผลของการ ให้อาหารผสม โยเกิร์ต และแบคทีเรียสังเคราะห์แสง (PSB) ต่อการเจริญเติบโต และอัตราการรอด ตายของกุ้งขาวแวนนาไม (Litopenaeus &nbsp;vannamei) ในระบบที่มี Tetraselmis sp. และในระบบ ที่ไม่มี Tetraselmis sp. และส่วนสุดท้ายเป็นการศึกษาประสิทธิภาพของการใช้ โยเกิร์ต และ PSB ผสมในอาหารกุ้งให้กุ้งกินเพื่อทดสอบการต้านทานเชื้อ V. parahaemolyticus ในกุ้งขาวแวนนา ไมที่เลี้ยงในระบบที่มี Tetraselmis sp. และกุ้งขาวแวนนาไมที่เลี้ยงในระบบที่ไม่มี Tetraselmis sp. &nbsp;<br>ผลส่วนแรกในการศึกษาการเจริญเติบโตของ Tetraselmis sp. และ PSB โดยการ เพาะเลี้ยง Tetraselmis sp. และ PSB ในขวดโหลขนาด 10 ลิตร บริเวณกลางแจ้งเป็นระยะเวลา 1 สัปดาห์ โดยใช้นมอินทรีย์ที่เป็นเศษเหลือจากโรงงานผลิตนม บริษัทแดรี่โฮม จํากัด เป็นอาหารใน ปริมาณที่แตกต่างกัน 4 ระดับ คือ 0.25, 0.50, 1.00 และ 2.00 เปอร์เซ็นต์ สําหรับการทดลองเลี้ยง Tetraselmis sp. ส่วนการทดลองเลี้ยง PSB &nbsp;มี 4 ระดับ คือ 10, 20, 30 และ 40 เปอร์เซ็นต์ ศึกษา การ เจ ริ ญ เติบโต โดยการ วัดค่ าการ ดูดกลื นแ ส ง ( optical density, OD) ด้วยเค รื่ อง Spectrophotometer ที่ความยาวคลื่น 680 นาโนเมตร (OD680) สําหรับ Tetraselmis sp. และ ความยาวคลื่น 970 นาโนเมตร (OD970) สําหรับ PSB ผลการศึกษาพบว่า ในการทดลองเลี้ยง Tetraselmis sp. ในวันที่ 3 ของการทดลองที่ระดับอาหาร 2 เปอร์เซ็นต์ มีค่า OD680 สูงสุด คือ 0.094 นาโนเมตร รองลงมาคือที่ระดับอาหาร 1.00, 0.50 และ 0.25 เปอร์เซ็นต์ ตามลําดับ คือมีค่า OD680 เป็น 0.092, 0.078 และ 0.046 นาโนเมตร ตามลําดับ นอกจากนี้ ไม่มีความแตกต่างกันอย่างมี นัยสําคัญทางสถิติ (p&gt;0.05) ในค่า OD ของสาหร่ายชนิดนี้ที่เลี้ยงในนมอินทรีย์ที่ระดับ 1 และ 2 เปอร์เซ็นต์ ในส่วนของการเลี้ยง PSB พบว่าในวันที่ 3 ของการทดลอง ที่ระดับอาหาร 40 เปอร์เซ็นต์ PSB มีค่า OD970 สูงสุด มีค่าเท่ากับ 0.328 นาโนเมตร รองลงมา คือ 30, 20 และ 10 เปอร์เซ็นต์ ตามลําดับ ซึ่งมีค่าเท่ากับ 0.315, 0.268 และ 0.265 ตามลําดับ เมื่อนํามาวิเคราะห์ทางสถิติที่ความ เชื่อมั่น 95 เปอร์เซ็นต์ การเจริญเติบโตของ PSB ที่เลี้ยงในอาหารระดับ 40 เปอร์เซ็นต์ ที่วัดจากค่า OD970 มีความแตกต่างกับ PSB ที่อาหารระดับ 10, 20 และ 30 เปอร์เซ็นต์ อย่างมีนัยสําคัญทางสถิติ (p&lt;0.05) แต่การเจริญเติบโตของ PSB ที่ระดับอาหาร 10 และ 20 เปอร์เซ็นต์ ไม่มีความแตกต่างกัน อย่างมีนัยสําคัญทางสถิติ &nbsp;<br>การวิจัยส่วนที่ 2 เป็นการศึกษาผลของการให้อาหารกุ้งผสมโปรไบโอติกคือ โยเกิร์ต &nbsp;(yogurt) และ PSB ต่อการเจริญเติบโต และอัตราการรอดตายของกุ้งขาวที่เลี้ยงในระบบที่มี Tetraselmis sp. เป็นระยะเวลา 5 สัปดาห์ พบว่า กุ้งที่มีการนํา Tetraselmis sp. มาประยุกต์ใช้ใน ระบบร่วมกับการใช้โปรไบโอติก 2 ชนิดที่แตกต่างกันคือ โยเกิร์ต และ PSB ผสมในอาหารสําหรับเลี้ยง กุ้งมีน้ําหนักที่เพิ่มขึ้น และพบว่าการเจริญเติบโตจําเพาะ อัตราการเจริญเติบโตต่อวัน และอัตราการ เปลี่ยนอาหารเป็นเนื้อของกุ้งในทุกชุดการทดลอง ไม่มีความแตกต่างกันอย่างมีนัยสําคัญทางสถิติ (p&gt;0.05) แต่อัตราการรอดตายของกุ้งที่ได้รับอาหารผสมโปรไบโอติกทั้งโยเกิร์ตและ PSB มีค่าสูงกว่า ชุดควบคุม โดยชุดที่ได้รับอาหารที่ผสม PSB มีค่าสูงสุด คือ ร้อยละ 95.00 มีความแตกต่างอย่างมี นัยสําคัญทางสถิติ (p&lt;0.05) เมื่อเทียบกับชุดควบคุม และได้ทดลองเลี้ยงกุ้งในระบบที่ไม่มี Tetraselmis sp. อีกหนึ่งชุดการทดลองเป็นระยะเวลา 5 สัปดาห์ พบว่าน้ําหนักที่เพิ่มขึ้น อัตราการ เจริญเติบโตต่อวัน การเจริญเติบโตจําเพาะ อัตราการเปลี่ยนอาหารเป็นเนื้อ และอัตราการรอดตาย ของกุ้งในทุกชุดการทดลองไม่มีความแตกต่างกันอย่างมีนัยสําคัญทางสถิติ (p&gt;0.05) &nbsp;<br>การวิจัยส่วนที่ 3 เป็นการทดลองเลี้ยงกุ้งขาวแวนนาไมในระบบที่มี Tetraselmis &nbsp;sp. และกุ้งขาวที่เลี้ยงในระบบที่ไม่มี Tetraselmis sp. เพื่อเป็นการศึกษาประสิทธิภาพของการใช้ โปรไบโอติกโยเกิร์ต และ PSB ในการต้านทานเชื้อ V. parahaemolyticus โดยการทดสอบการต้าน เชื้อ V. parahaemolyticus ของกุ้งที่เลี้ยงโดยแช่กุ้งในเชื้อ V. parahaemolyticus ที่ระดับความ เข้มข้น 1&times;107 CFU ต่อมิลลิลิตร นาน 2 ชั่วโมง ทดลองเลี้ยงเป็นเวลา 1 สัปดาห์ พบว่ากุ้งที่เลี้ยงใน ระบบที่มี Tetraselmis sp. ในชุดที่ได้รับอาหารผสมโปรไบโอติกทั้งสองชนิดมีอัตราการรอดตาย สูงสุดแตกต่างกันอย่างมีนัยสําคัญทางสถิติ (p&lt;0.05) เมื่อเทียบกับชุดที่ได้รับอาหารสําเร็จรูปเพียงอย่างเดียว (ควบคุม) ส่วนกุ้งที่เลี้ยงในระบบที่ไม่มี Tetraselmis sp. ในชุดควบคุมปรากฏว่าเมื่อครบ 36 ชั่วโมงพบอัตราการรอดตายต่ําที่สุดเพียงร้อยละ 13 ซึ่งแตกต่างอย่างมีนัยสําคัญทางสถิติ (p&lt;0.05) เมื่อเทียบกับกลุ่มที่ได้รับอาหารผสมโปรไบโอติก และได้แบ่งกุ้งส่วนหนึ่งจาการเลี้ยงมาวัด ค่าสีของกุ้งหลังจากผ่านการต้ม โดยใช้เครื่องวัดสีระบบ CIE L* a* b* (L* ค่าความสว่าง, a* ค่าสีแดง และ b* ค่าสีเหลือง) พบว่ากุ้งที่เลี้ยงในระบบที่มี Tetraselmis sp. ด้วยอาหารผสมโปรไบโอติกมีค่า a* และ b* แตกต่างกันอย่างมีนัยสําคัญทางสถิติเมื่อเทียบกับชุดควบคุม (p&lt;0.05) ในส่วนของกุ้งที่ เลี้ยงในระบบที่ไม่มี Tetraselmis sp. พบว่า ค่า a* ของกุ้งขาวที่ได้รับอาหารผสมโปรไบโอติกทั้งสอง ชนิดไม่มีความแตกต่างกันอย่างมีนัยสําคัญทางสถิติ &nbsp;(p&gt;0.05) แต่มีความแตกต่างอย่างมีนัยสําคัญ ทางสถิติ (p&lt;0.05) ในกุ้งที่ได้รับอาหารผสมโยเกิร์ต และ PSB เมื่อเทียบกับชุดควบคุม จากผลการศึกษาในครั้งนี้ สรุปได้ว่า Tetraselmis sp. มีผลในการต่อต้านเชื้อ V. &nbsp;parahaemolyticus ของกุ้งขาวเมื่อเลี้ยงกุ้งขาวในระบบที่มีสาหร่ายชนิดนี้ นอกจากนี้โปรไบโอติกทั้ง โยเกิร์ต และแบคทีเรียสังเคราะห์แสง ยังให้ผลในการต่อต้านเชื้อ V. parahaemolyticus ของกุ้งขาว เมื่อผสมในอาหารกุ้ง ดังนั้นสรุปได้ว่า ทั้งสาหร่ายขนาดเล็ก Tetraselmis sp. และ โปรไบโอติกทั้ง yogurt และแบคทีเรียสังเคราะห์แสง เมื่อนํามาประยุกต์ใช้ร่วมกันในการเลี้ยงกุ้งขาวสามารถส่งเสริม ให้กุ้งมีภูมิต้านทานต่อเชื้อ Vibrio parahaemolyticus เพิ่มโอกาสในการรอดตาย เพิ่มผลผลิตจาก การเพาะเลี้ยงกุ้ง และเพิ่มสีกุ้งให้เข้มขึ้น&nbsp;</p>', 'สาขาวิชาวิทยาศาสตร์และเทคโนโลยีประมง', '', '', 'มหาวิทยาลัยสงขลานครินทร์ วิทยาเขตปัตตานี'),
('ITM00000000049', 'ลักษณะทางนิเวศวิทยาและชีววิทยาบางประการของเม่นทะเลชนิด Temnopleurus toreumaticus ในอ่าวปัตตานี', 'COM00000000005', 'COM00000000002', 'Some Ecological and Biological Aspects of Sea Urchin  Temnopleurus toreumaticus in Pattani Bay', NULL, 10, '2565', NULL, '<p>การศึกษาในครั้งนี้มีวัตถุประสงค์เพื่อประเมินการแพร่กระจายของเม่นแต่งตัว<br>น้าตาล (Temnopleurus toreumaticus) ความสัมพันธ์กับปัจจัยทางสิ่งแวดล้อมและสัตว์หน้าดิน ชนิดอื่น ชีววิทยาการสืบพันธุ์ ผลของขนาดของเม่นแต่งตัวน้าตาลและเดือนต่อการกินอาหาร ทาการศึกษาโดยเก็บตัวอย่างเม่นแต่งตัวน้าตาลและสัตว์หน้าดินชนิดอื่นบริเวณสถานีต่าง ๆ จานวน 8 สถานีครอบคลุมอ่าวปัตตานี จังหวัดปัตตานี ระหว่างเดือนพฤศจิกายน 2561 ถึง เดือนกรกฎาคม 2563 โดยใช้วิธีลากคราด นาตัวอย่างที่ได้แช่ในน้าเย็นจัดทันทีแล้วนากลับไปยังห้องปฏิบัติการเพื่อทาการวิเคราะห์ในขั้นตอนต่อไป วัดค่าคุณสมบัติบางประการของน้าและ เก็บตัวอย่างตะกอนดินจากสถานีต่าง ๆ จากการศึกษาพบว่าเม่นแต่งตัวน้าตาลมีค่าความชุกชุมเฉลี่ย 22 ตัว/1,000 ตารางเมตร จากการศึกษาความสัมพันธ์ระหว่างเม่นแต่งตัวน้าตาลกับปัจจัยสิ่งแวดล้อม พบว่าความชุกชุมของเม่นแต่งตัวน้าตาล มีความสัมพันธ์ทางบวกกับค่าความเค็ม ความลึก ความโปร่งใส ความเป็นกรด-ด่างของดินและอนุภาคทราย ความชุกชุมของเม่นแต่งตัวน้าตาลสัมพันธ์กับกลุ่ม polychaete สกุล Nephtys 2 Glycera 2 และ Perinereis กลุ่ม mollusc สกุล Clithon, Barbatia และ crustaceans กลุ่ม amphipod และสกุล Lepidophthalmus ผลจากการศึกษาการกินอาหารพบว่าเม่นแต่งตัวน้าตาลกินอาหาร 7 กลุ่ม คือ polychaete (29.15%) mollusc (24.69%) crustaceans (22.25%) sand (10.62%) sponge (4.88%) fish (4.83%) และ plant (3.58%) ตามลาดับ ในขณะที่จานวนชนิดของอาหารเฉลี่ย ค่าดัชนีการเต็มกระเพาะอาหารเฉลี่ย ค่าดัชนีกระเพาะอาหารว่าง และค่าความกว้างของอาหาร เท่ากับ 2.88&plusmn;1.38, 4.56&plusmn;2.40, 16.13 และ 0.43 ตามลาดับ สัดส่วนเพศของเม่นแต่งตัวน้าตาลเพศผู้ต่อเพศเมีย มีค่าเท่ากับ 0.9:1.0 (P&gt;0.05) ขนาดแรกเริ่มสืบพันธุ์ของเม่นแต่งตัวน้าตาลเพศผู้ 33.17 มิลลิเมตร และเพศเมีย 37.08 มิลลิเมตร จากการทดสอบทางสถิติพบว่าขนาดของเม่นแต่งตัวน้าตาลและเดือนที่เก็บตัวอย่างมีผลต่อจานวนชนิดอาหารในกระเพาะอาหารอย่างมีนัยสาคัญยิ่ง (P&lt;0.001) ในขณะที่ขนาดของเม่นแต่งตัวน้าตาลไม่มีผลต่อค่าการเต็มกระเพาะของอาหาร (P&gt;0.05) การศึกษาวิจัยในครั้งนี้นับว่าเป็นการรายงานครั้งแรกที่ศึกษาเกี่ยวกับเม่นทะเลชนิดนี้และจะเป็นข้อมูลพื้นฐานที่สาคัญสาหรับประยุกต์ใช้เพื่อการเพาะเลี้ยงและอนุรักษ์เม่นแต่งตัวน้าตาลในอนาคต</p>', 'สาขาวิชาวิทยาศาสตร์และเทคโนโลยีประมง', '', '', 'มหาวิทยาลัยสงขลานครินทร์ วิทยาเขตปัตตานี');
INSERT INTO `tb_item` (`item_id`, `item_title`, `community_id`, `collection_id`, `item_alternative`, `item_issued_day`, `item_issued_month`, `item_issued_year`, `item_description`, `item_abstract`, `item_sponsorship`, `item_citation`, `item_uri`, `item_publisher`) VALUES
('ITM00000000050', 'Effects of Pom-nang Seaweed, Gracilaria fisheri on Growth, Survival, Feed Efficiency and Catalase Production of Juvenile Mud Crab, Scylla paramamosain', 'COM00000000005', 'COM00000000002', 'ผลของสาหร่ายผมนาง Gracilaria fisheri ต่ออัตราการเจริญเติบโต อัตรา การรอดตาย ประสิทธิภาพการใช้อาหาร และการสร้างคะตาเลสของปูขาว Scylla paramamosain ระยะวัยรุ่น', NULL, 10, '2022', NULL, '<p>The study on the effects of Pom-nang seaweed, Gracilaria fisheri on growth, survival, feed efficiency and catalase production of juvenile mud crab, Scylla paramamosain was conducted. The main objectives of this study are to investigate (1) effect of dietary diets with different Pom-nang seaweed supplementation&rsquo;s levels on growth rate, survival rate, feed efficiency and catalase activity of juvenile mud crab and (2) influence of Pom-nang seaweed density as a shelter and stocking density on growth, feed efficiency, and survival rates of juvenile mud crab. Two experiments were conducted. The first experiment, juvenile mud crabs were individually stocked in plastic containers with an initial body weight of 0.02 g. Two factors including five dietary treatments (Pom-nang seaweed powder supplemented at the level of 0%, 2%, 4% and 6% and control; mysid shrimp) and two shelter treatments (with Pom-nang seaweed as shelter and without shelter) were designed. Juvenile mud crabs were fed at 8% body weight for 28 days. It was found that different diets had significant effects on weight gain (WG), specific growth rate on body weight (SGRw), protein efficiency ratio (PER) but not for feed conversion ratio (FCR), catalase activity (CAT) and survival rate of the crabs. The crabs reared with seaweeds as shelter had significantly different PER, FCR, CAT and survival rate values compared to those without seaweeds as shelter (P &lt; 0.05). There were significant differences on the interactions of the combined factor on WG, SGR and PER (P &lt;0.05). It was found that mysid shrimp was the most appropriate food for nursing juvenile mud crab. However, formulated diets supplemented with seaweeds had a potential to replace mysid shrimp. The combination of seaweed as shelter and the formulated diets with 4% seaweed (PSP4) had the highest values of all growth performances and survival rate compared to the others. The second experiment, effect of stocking density and density of Pom-nang seaweed as shelter on growth and survival rates of juvenile mud crab were conducted using juvenile mud crab with an initial body weight of 0.02 g. Two factors including four stocking density treatments (100, 200, 300 and 400 crab/m2) and four densities of Pom-nang seaweed as shelter (100 g/m2, 500 g/m2, 1,000 g/m2 and without shelter) were tested. Juvenile mud crabs were fed with PSP4 at 8% body weight for 28 days. It was found that different stocking density had significant effects on PER and FCR (P &lt;0.05), and different density of Pom-nang seaweed as a shelter had significant effects on PER, FCR and survival rate (P &lt;0.05). The stocking density at 400 crab/m2 and high density of Pom-nang seaweed as a shelter at 1,000 g/m2 was the optimal rate for nursing juvenile mud crab as indicated by growth performances and survival rate. There was no impact of interaction effect of the combined factor. This study can support a new technique and method for the development of nursing mud crab in the future.</p>', 'Fishery Science and Technology', '', '', 'Prince of Songkla University'),
('ITM00000000051', 'วะสะฏียะฮฺ ความจำเป็น และแนวทางการจัดการความขัดแย้งที่เป็นผลมาจากความเห็นต่างในสังคมไทยมุสลิมในสามจังหวัดชายแดนภาคใต้', 'COM00000000006', 'COM00000000002', 'Wasatiyyah: Its Necessity and Approach to Managing Conflicts Resulting from Disagreement in Thai Muslim Society in Three Southern Border Provinces', NULL, 10, '2565', NULL, '<p class=\"isSelectedEnd\">การวิจัยนี้มีวัตถุประสงค์เพื่อ 1) ศึกษาแนวคิดและความจำเป็นในการปรับใช้วะสะฏียะฮฺในความเห็นต่างในอิสลาม 2) ศึกษาสาเหตุและสภาพความขัดแย้งที่เป็นผลมาจากความเห็นต่างในสังคมไทยมุสลิมในสามจังหวัดชายแดนภาคใต้ และ 3) ศึกษาแนวทางการเสริมสร้างการปรับใช้วะสะฏียะฮฺในการจัดการความขัดแย้งที่เป็นผลมาจากความเห็นต่างในสังคมไทยมุสลิมในสามจังหวัดชายแดนภาคใต้ โดยใช้วิธีการศึกษาเชิงคุณภาพจากการศึกษาข้อมูลเอกสารที่เกี่ยวข้องและการสัมภาษณ์แบบเจาะลึกจากกลุ่มผู้ให้ข้อมูลหลัก จำนวน 27 คน จาก 9 กลุ่ม ๆ ละ 3 คน ประกอบด้วย ผู้ทรงคุณวุฒิจุฬาราชมนตรี คณะกรรมการกลางอิสลามแห่งประเทศไทย คณะกรรมการอิสลามประจำจังหวัด คณะกรรมการอิสลามประจำมัสยิด คณะกรรมการสถาบันหรือศูนย์วะสะฏียะฮฺ นักวิชาการมุสลิมในสถาบันอุดมศึกษา โต๊ะครูหรือเจ้าของสถาบันการศึกษาปอเนาะ ผู้บริหารโรงเรียนเอกชนสอนศาสนาอิสลาม และวิทยากรอิสลามศึกษาแบบเข้ม และจัดประชุมอิงผู้ทรงคุณวุฒิโดยใช้วิธีการแบบเจาะจงและเป็นตัวแทนจากกลุ่มตัวอย่างผู้ให้ข้อมูลการสัมภาษณ์ จำนวน 9 คน เครื่องมือที่ใช้ในการศึกษาเป็นแบบสัมภาษณ์แบบกึ่งมาตรฐาน วิเคราะห์ข้อมูลเชิงคุณภาพ ได้แก่ วิธีการนับจำนวน วิเคราะห์เชิงพรรณนา วิเคราะห์แบบอุปนัย การเชื่อมโยงเชิงตรรกะ การให้ความหมาย และการเปรียบเทียบข้อมูล โดยนำข้อมูลที่ได้มาสร้างเป็นข้อสรุปและนำเสนอในรูปตารางประกอบความเรียงและการจัดกลุ่มข้อมูลที่ได้สรุปตามประเด็น ซึ่งผลการวิจัยพบว่า</p>\r\n<ol start=\"1\" data-spread=\"false\">\r\n<li>แนวคิดและความจำเป็นในการปรับใช้วะสะฏียะฮฺในความเห็นต่างในอิสลาม คือ แนวคิดในการขับเคลื่อนความเชื่อและความคิดของผู้นำเสนอคำสอนอิสลามให้อยู่บนแนวทางอิสลามสายกลาง ซึ่งปลอดภัยจากความสุดโต่งและความหย่อนยาน เป็นแนวคิดที่ตระหนักรู้และเข้าใจวิธีการนำเสนออิสลาม โดยให้ความสำคัญต่อหลักฐานและยอมรับการใช้สติปัญญา ยึดมั่นในอุดมการณ์ ความถูกต้อง และคำนึงถึงสภาพความเป็นจริง โดยสามารถจัดลำดับความสำคัญก่อนหลัง มีความยืดหยุ่นในการสร้างแรงจูงใจและการสำทับอย่างเหมาะสม ให้ความสำคัญต่อเนื้อหาและสาระที่ครอบคลุมมิติต่าง ๆ ของชีวิต รวมถึงให้ความใส่ใจต่อเรื่องบุคลิกภาพ และมีมารยาทในการเคารพความเห็นต่างในหลักคำสอนของอิสลาม</li>\r\n<li>สาเหตุความเห็นต่างเกี่ยวกับหลักการศาสนาในสังคมไทยมุสลิมในสามจังหวัดชายแดนภาคใต้ เกิดขึ้นจาก 3 สาเหตุ คือ 1) ความแตกต่างด้านตัวบุคคล 2) ความแตกต่างด้านหลักฐาน และ 3) ความแตกต่างด้านการแสดงความเห็น ขณะที่สภาพความขัดแย้งที่เป็นผลมาจากความเห็นต่างได้ส่งผลกระทบต่อสังคมไทยมุสลิมในสามจังหวัดชายแดนภาคใต้ 2 ด้านสำคัญ คือ ด้านการปฏิบัติตามหลักการศาสนา และด้านความเป็นเอกภาพของสังคม</li>\r\n<li>แนวทางการเสริมสร้างการใช้วะสะฏียะฮฺในการจัดการความขัดแย้งที่เป็นผลมาจากความเห็นต่างในสังคมไทยมุสลิมในสามจังหวัดชายแดนภาคใต้ จำแนกเป็น 6 ด้าน คือ 1) ด้านการมีความบริสุทธิ์ใจและการมุ่งหวังสัจธรรมจากความเห็นต่าง 2) ด้านการมีทัศนคติเชิงบวกต่อผู้เห็นต่าง 3) ด้านการแสดงความเห็นต่างด้วยมารยาทที่ดีงาม 4) ด้านการศึกษาและทบทวนประเด็นที่มีความเห็นต่าง 5) ด้านการให้ความเป็นธรรมต่อตนเองและไม่ยึดติดทรรศนะ และ 6) ด้านการคำนึงถึงความถูกต้องและผลประโยชน์ส่วนรวม</li>\r\n</ol>', 'สาขาวิชาอิสลามศึกษา', '', 'https://kb.psu.ac.th/items/5913e2e6-1b6b-4ce1-a35b-c76b4edd6219', 'มหาวิทยาลัยสงขลานครินทร์ วิทยาเขตปัตตานี'),
('ITM00000000052', 'บทเรียนการมีส่วนร่วมเพื่อจัดการ “ความขัดแย้ง” ระหว่างชุมชนกับโรงเรียน ในสามจังหวัดชายแดนภาคใต้ (ตอนที่1)', 'COM00000000006', 'COM00000000004', '', NULL, 10, 'ปีที่ 34 ฉบับที่ 4 ตุลาคม - ธันวาคม 2556', '', '', '', '', 'https://so05.tci-thaijo.org/index.php/rusamelae/article/view/62799/51638', 'มหาวิทยาลัยสงขลานครินทร์ วิทยาเขตปัตตานี'),
('ITM00000000053', 'บทเรียนการมีส่วนร่วมเพื่อจัดการความขัดแย้ง ระหว่างชุมชนกับโรงเรียน ในสามจังหวัดชายแดนภาคใต้ (ตอนจบ)', 'COM00000000006', 'COM00000000004', '', NULL, 10, 'ปีที่ 35 ฉบับที่ 1   มกราคม-มีนาคม 2557', '', '', '', 'วารสารรูสมิแล', 'https://so05.tci-thaijo.org/index.php/rusamelae/article/view/57432/47597', 'มหาวิทยาลัยสงขลานครินทร์ วิทยาเขตปัตตานี'),
('ITM00000000054', 'การยืดอายุผลิตภัณฑ์พริกแกง และออกแบบบรรจุภัณฑ์', 'COM00000000010', 'COM00000000001', '', NULL, 10, '2561', NULL, '<p class=\"isSelectedEnd\">ห้างหุ้นส่วนจำกัดแม่พรผลิตและจำหน่ายผลิตภัณฑ์พริกแกงมา 40 กว่าปี มีผลิตภัณฑ์มากกว่า 20 ชนิดที่จัดจำหน่ายในปัจจุบัน ประสบปัญหาอายุการไม่คงที่ และไม่สามารถเก็บได้นาน ซึ่งมีสาเหตุจากปริมาณเชื้อจุลินทรีย์เริ่มต้น และยีสต์ราในวัตถุดิบ และระหว่างการผลิต การควบคุมปริมาณเชื้อจุลินทรีย์และยีสต์รา สามารถทำได้โดยลดปริมาณเชื้อเริ่มต้นจากวัตถุดิบ ความเป็นกรด-ด่าง (pH) ปริมาณน้ำอิสระ (aw) การใช้ความร้อนระหว่างการผลิต และชนิดของบรรจุภัณฑ์ เป็นต้น&nbsp;การล้างพริกสดด้วยสารละลาย KMnO₄ โซเดียมไบคาร์บอเนต และกรดอะซิติก พบว่าพริกสดที่ล้างด้วยกรดอะซิติกความเข้มข้น 1.5% สามารถลดเชื้อจุลินทรีย์ทั้งหมดจาก 5.10&plusmn;0.02 log cfu/g เหลือ 3.59&plusmn;0.19 log cfu/g และไม่พบยีสต์รา (ND) การใช้น้ำร้อนเติมลงไปในขั้นตอนบดผสมสามารถลดปริมาณเชื้อจุลินทรีย์ทั้งหมดได้ในพริกแกงเขียวหวาน 4.90&plusmn;0.21 log cfu/ml เหลือ 3.84&plusmn;0.21 log cfu/g&nbsp;การลด aw โดยการเติมเกลือโพแทสเซียมคลอไรด์ ซอร์บิทอล และกลีเซอรอล ที่ระดับความเข้มข้นที่เหมาะสมสามารถลดค่า aw ได้จาก 0.92&plusmn;0.02 เหลือ 0.88&ndash;0.91 รวมถึงการเติมวัตถุเจือปนอาหาร (Food preservative) ประเภทโซเดียมเบนโซเอต ไนซิน นาตาไมซิน ร่วมกับการปรับสภาวะดังกล่าว สามารถยืดอายุการจัดจำหน่ายได้ ชนิดของบรรจุภัณฑ์และรายละเอียดบรรจุภัณฑ์มีผลต่ออายุการจัดจำหน่าย และการตัดสินใจซื้อผลิตภัณฑ์พริกแกงของผู้บริโภค</p>', 'สถาบันวิจัยและนวัตกรรมอาหาร สํานักวิจัยและพัฒนา มหาวิทยาลัยสงขลานครินทร์', '', 'https://kb.psu.ac.th/items/feb7dbf9-b406-4e6d-b305-a7d288daf449', 'มหาวิทยาลัยสงขลานครินทร์ วิทยาเขตปัตตานี'),
('ITM00000000055', 'Climate Change Impacts and Adaptation of Households in U-Tapao River Sub-Basin, Thailand', 'COM00000000007', 'COM00000000004', '', NULL, 10, '2021', NULL, '<p>Flood, storm, and drought have frequently impacted households in the U-Tapao River Sub-basin, Songkhla Province, Thailand, as a result of climate change. Studying how to assist them in better adapting to the effects of climate change is a critical mission that researchers should strive to achieve. The goals of this study are to (1) investigate the effects of climate change on households in the U-Tapao River Sub-basin, (2) examine the adaptation strategies they used, (3) the challenges they faced when attempting to adapt, and (4) provide recommendations for future adaptation. The study was carried out in the jurisdictions of three local government authorities. A survey questionnaire was used to collect quantitative data from 300 households, which was then analyzed using frequency, percentage, mean, and standard deviation. To supplement survey data, qualitative data were collected from 50 key informants via in-depth interviews and focus-group discussions. Climate change impacted households in four ways, according to the findings: health, housing, agriculture, and livelihood activities. Although households can take general measures to mitigate the effects of climate change on their health and livelihood, they do not appear to be able to take preventive measures to minimize flooding impacts on their house and property, nor do they appear to be able to adopt on-farm adaptation strategies to prevent income loss. The main impediment to taking more effective measures is a lack of funds, knowledge, and technical assistance. As a result, practical recommendations are provided at the end of this paper to help overcome such challenges and encourage households to adopt more adaptation strategies.</p>', 'Faculty of Environmental Management และ Faculty of Management Sciences, Prince of Songkla University', 'International Journal of Sustainable Development and Planning (IJSDP)', 'https://iieta.org/journals/ijsdp/paper/10.18280/ijsdp.160610?utm_source=chatgpt.com', ''),
('ITM00000000056', 'การประเมินและเปรียบเทียบดัชนีชี้วัดความเปราะบางต่ออุทกภัยของเมือง: กรณีศึกษา หาดใหญ่ เชียงใหม่ และอุบลราชธานี', 'COM00000000007', 'COM00000000004', 'Assessment and comparison of urban flood vulnerability index: a case study of Hat Yai, Chiang Mai and Ubon Ratchathan', NULL, 10, 'Vol. 41 No. 3 (2022): Journal of Science and Technology Mahasarakham University', NULL, '<p>บทความนี้เสนอความเปราะบางของเมืองต่ออุทกภัยโดยใช้ดัชนีชี้วัดความเปราะบาง ประกอบด้วยความเปราะบาง 4 บริบท ได้แก่ บริบทด้านสังคม บริบทด้านเศรษฐกิจ บริบทด้านสิ่งแวดล้อม และบริบทด้านกายภาพ ขั้นตอนการดำาเนินการ ประกอบ ด้วย การคัดเลือกตัวแปร การเก็บรวบรวมข้อมูลและวิเคราะห์ตัวแปร การสร้างสมการและการคำานวณค่าดัชนีชี้วัดความเปราะ บาง เมื่อเปรียบเทียบความเปราะบางของเมืองต่อการเกิดอุทกภัยของ 3 เมือง ประกอบด้วย เมืองหาดใหญ่ เมืองเชียงใหม่ และ เมืองอุบลราชธานี ผลการศึกษาพบว่า เมืองที่มีความเปราะบางต่อการเกิดอุทกภัยสูงสุดถึงตำ่าสุดได้แก่ เมืองเชียงใหม่ เมือง หาดใหญ่ และเมืองอุบลราชธานี ตามลำาดับ เมื่อพิจารณาแยกตามบริบท เมืองเชียงใหม่ มีความเปราะบางสูงสุดในบริบทด้าน สังคมและสิ่งแวดล้อม เมืองหาดใหญ่ มีความเปราะบางสูงสุดในบริบทด้านเศรษฐกิจ และเมืองอุบลราชธานีมีความเปราะบาง สูงสุดในบริบทด้านกายภาพ</p>', 'ศูนย์วิจัยภัยพิบัติทางธรรมชาติภาคใต้ มหาวิทยาลัยสงขลานครินทร์', '', 'https://li01.tci-thaijo.org/index.php/scimsujournal/article/view/253217?utm_source=chatgpt.com', ''),
('ITM00000000057', 'Investigation of 37 years weather record and its relation to human health: A case study in Songkhla Province, Southern Thailand', 'COM00000000007', 'COM00000000004', '', NULL, 10, 'Vol. 17 No. 4 (2021): July', NULL, '<p>The weather data from the ThaiMeteorologicalDepartment during1982-2018 wereanalysedand identified theclimate change situation in Songkhla Province,Thailand. Result indicated that temperature, humidity, rainfall, sunlight and heat index was statisticsignificantlyincreased at p&lt;0.05,while the monthly maximum wind speed decreasedin temperature change which 33% less than global temperature change. The increase intemperature consequently affected the other parameters such as humidity,rainfallandheat index. Moreover, the storm frequencies in Songkhla werenot increased. Their frequencies of occurrence were slightly fluctuated. Another finding was thestorm arrival date slightly shifted to the end of year. The characterizationof relationshipbetween climate change and health conditionswere related to the diseases e.g. gastroenteritis,dengue fever, malaria,bloodinfectiondisease and upper respiratoryinfectionfrom the year 2002to 2018. Thesecondary data of crucial meteorological factors were recorded. The resultsrevealed that the morbidity rates per 1,000 population for gastroenteritis,blood infection diseases,upper respiratory infectionthat had positive statical relationship with the average annual relative humidity with r2= 0.460, 0.461 and 0.486 ( p&lt;0.05) respectively, whereas dengue fever and malaria are not related to statistical relationshipwith allthe investigated climatic variables including the average annual rainfall. Probablyclimatic change would increase the outbreaks of the gastroenteritis, blood infection, upper respiratory diseases,while it had notaffected on the spread of dengue fever and malaria according to topographic factor in the study area.</p>', 'Coastal Oceanography and Climate Change Research Center, Faculty of Environmental Management', '', 'https://li04.tci-thaijo.org/index.php/IJAT/article/view/6236/781', ''),
('ITM00000000058', 'ผลของอาหารเสริมสาหร่ายไส้ไก่ (Ulva intestinalis Linnaeus) ต่อการเจริญเติบโตและสีเปลือกของกุ้งขาว (Litopenaeus vannamei Boone, 1931)', 'COM00000000006', 'COM00000000002', 'Effect of Ulva intestinalis Linnaeus Supplemented Diet on Growth Performance and Shell Color of Litopenaeus vannamei Boone, 1931', NULL, 10, '2565', NULL, '<p>สาหร่ายทะเลได้รับความสนใจในการเสริมในอาหารเพื่อการเลี้ยงกุ้งทะเลด้วย คาดหวังว่าจะเป็นประโยชน์ต่อการเจริญเติบโตของกุ้งและช่วยเพิ่มสีของกุ้งที่ปรุงสุก จึงได้ทำการศึกษาผลของการเสริมสาหร่ายไส้ไก่ (Ulva intestinalis) ซึ่งเป็นสาหร่ายทะเลชนิดหนึ่งในอาหารเพื่อเลี้ยงกุ้งขาว (Litopenaeus vannamei) โดยใช้อาหารที่มีโปรตีนร้อยละ 40 และไขมันร้อยละ 10 เตรียมอาหารทดลองให้มีความแตกต่างกัน 6 ระดับ (ร้อยละ 0, 6, 12, 18, 24 และ 30) ของผงสาหร่ายไส้ไก่ โดยใช้กุ้งขาวในระยะโพสลาวา 30 (น้ำหนักเริ่มต้นเฉลี่ยที่ 0.12&plusmn;0.01 กรัม) โดยให้อาหาร 6 มื้อต่อวัน เป็นการให้อาหารจนอิ่ม มีการเปลี่ยนถ่ายน้ำทุกสัปดาห์และชั่งน้ำหนักทุก 2 สัปดาห์ หลังจากทำการทดลองเสร็จสิ้นในสัปดาห์ที่ 12 กุ้งที่เลี้ยงด้วยอาหารเสริมสาหร่ายไส้ไก่ที่ร้อยละ 0 มีน้ำหนักสุดท้ายสูงที่สุด (12.27&plusmn;0.84 กรัม) และความยาวสูงสุด (10.97&plusmn;0.27 เซนติเมตร) และมีน้ำหนักที่เพิ่มขึ้นมากกว่ากุ้งที่เลี้ยงด้วยอาหารเสริมสาหร่ายไส้ไก่กลุ่มอื่นในช่วงสัปดาห์ที่ 0-8</p>\r\n<p>อัตราการเจริญเติบโตจำเพาะมีค่าสูงในช่วงสัปดาห์ที่ 0-2 กุ้งที่เลี้ยงด้วยอาหารเสริมสาหร่ายไส้ไก่ที่ร้อยละ 0 มีค่าสูงที่สุดอยู่ที่ 11.75&plusmn;0.12 % day-1 และมีค่าลดลงตามระยะเวลาในการเลี้ยงกุ้งที่เพิ่มขึ้น อัตราการกินอาหารของกุ้งที่เลี้ยงด้วยอาหารเสริมสาหร่ายไส้ไก่ที่ร้อยละ 30 มีค่ามากที่สุดตลอดการทดลอง เช่นเดียวกับค่าอัตราการเปลี่ยนอาหารเป็นเนื้อของกุ้งกลุ่มนี้มีค่าสูงที่สุดด้วย ในส่วนของประสิทธิภาพการใช้โปรตีนของกุ้งที่เลี้ยงด้วยอาหารเสริมสาหร่ายไส้ไก่ที่ร้อยละ 0 มีค่าสูงกว่ากุ้งที่เลี้ยงด้วยอาหารเสริมสาหร่ายไส้ไก่กลุ่มอื่นในช่วงสัปดาห์ที่ 0-12 ในส่วนของอัตราการรอดตายไม่มีความแตกต่างกันทางสถิติ ยกเว้นในสัปดาห์ที่ 2-4 และ 8-10 ของกุ้งที่เลี้ยงด้วยอาหารเสริมสาหร่ายไส้ไก่ที่ร้อยละ 6 มีอัตราการรอดตายอยู่ที่ร้อยละ 80.79&plusmn;10.33 และ 92.31&plusmn;7.69 ตามลำดับ ซึ่งสูงกว่ากุ้งที่เลี้ยงด้วยอาหารเสริมสาหร่ายไส้ไก่ในสัดส่วนอื่น</p>\r\n<p>การวิเคราะห์คุณภาพซากของกุ้งหลังเลี้ยงมีปริมาณโปรตีนอยู่ในช่วงร้อยละ 65.68-69.70, ไขมันร้อยละ 2.81-3.20, เยื่อใยร้อยละ 6.53-6.80, ความชื้นร้อยละ 10.36-7.29 และเถ้าร้อยละ 12.87-10.89 แร่ธาตุบางชนิดในตัวกุ้งหลังเลี้ยงพบว่ามีธาตุแคลเซียมของกุ้งที่เลี้ยงด้วยอาหารเสริมสาหร่ายไส้ไก่ที่ร้อยละ 12-24 ซึ่งสูงกว่ากุ้งที่เลี้ยงด้วยอาหารเสริมสาหร่ายไส้ไก่กลุ่มอื่น ขณะที่แร่ธาตุเหล็กลดลงเมื่อกุ้งได้รับอาหารเสริมสาหร่ายไส้ไก่มากกว่าร้อยละ 18</p>\r\n<p>ในส่วนของความเข้มสีของกุ้งหลังจากเลี้ยงพบว่าค่าความแดง (a*) (p&lt;0.05) ลดลงหลังต้ม ขณะที่ค่าความสว่าง (L*) และความเหลือง (b*) ไม่มีความแตกต่างกันทางสถิติ ยกเว้นกุ้งที่เลี้ยงด้วยอาหารเสริมสาหร่ายไส้ไก่ที่ร้อยละ 30 ค่าความเหลือง (b*) ของกุ้งลดลงอย่างมีนัยสำคัญ</p>\r\n<p>ผลการศึกษาในครั้งนี้สรุปได้ว่าการเสริมสาหร่ายไส้ไก่ (Ulva intestinalis) ในอาหารเลี้ยงกุ้งขาว (Litopenaeus vannamei) ในระยะโพสลาวา 30 ส่งผลให้กุ้งที่เลี้ยงมีการเจริญเติบโตที่ลดลงและค่าของสีในช่วงความแดงของกุ้งลดลงหลังจากปรุงสุก</p>', 'สาขาวิชาวิทยาศาสตร`และเทคโนโลยีประมง', '', 'https://kb.psu.ac.th/items/5417e509-1d2c-47b0-8993-c30827098b95', 'มหาวิทยาลัยสงขลานครินทร์ วิทยาเขตปัตตานี'),
('ITM00000000059', 'ความสมบูรณ์เพศของแม่ปลาสลิด Trichogaster pectoralis (Regan, 1910) ระยะแรกรุ่นและเทคนิคการเพาะพันธุ์ในเรือนเพาะฟัก', 'COM00000000005', 'COM00000000002', 'Sexual Maturation of Early Stage Female Snakeskin Gourami, Trichogaster pectoralis (Regan, 1910) and Breeding Techniques in Farming Hatchery', NULL, 10, '2565', NULL, '<p>Study on characteristics of early mature snakeskin gourami (Trichogaster pectoralis) female was performed by researching on fecundity, Gonadosomatic index , GSI) and the width of snakeskin gourami female abdomen which was increased during maturity. The result was that the average total length and the average weight of early mature female was 17.31&plusmn; 0.55 centimeter (n=20) and 73.78&plusmn; 7.18 g. Gonadosomatic index was 4.50&plusmn;0.95%. The egg of the snakeskin gourami was pelagic, round and yellow. The breeding could be performed by injection of synthetic hormone to induce spawning at 30 microgram/ 1 Kg fish and the ratio of male to female was 1:1. The average egg diameter was 822 &plusmn; 4.58 millimeter (n=10,000), which was divided into 5 groups: group 1 (500-600 micrometer), group 2 (601-700 micrometer), group 3 (701-800 micrometer), group 4 (801-900 micrometer) and group 5 (901-1,000 micrometer) which were 0.10&plusmn;0.28, 1.63&plusmn;1.82 , 47.56&plusmn;7.70, 40.28&plusmn;5.91, 10.43&plusmn;4.81 %, respectively. The average fecundity was 17,140&plusmn;1,017 eggs. The extension of abdominal width was increased 85.31&plusmn;25.04 % (n=20). Average spawning ratio was 60.09&plusmn;45.97% at 27.0-30.5&deg;C water temperature. This result can be applied for development of commercial snakeskin breeding.</p>', 'สาขาวิชาวิทยาศาสตร์และเทคโนโลยีประมง', '', 'https://kb.psu.ac.th/items/b621a76a-92f4-4129-9d94-778764e02900', ''),
('ITM00000000060', 'นวัตกรรมสิ่งทอเส้นใยเฮมป์ สู่การออกแบบผลิตภัณฑ์แฟชั่นไลฟ์สไตล์กลุ่มผู้สูงวัยญี่ปุ่น ด้วยแนวคิดบีซีจี (BCG)', 'COM00000000003', 'COM00000000002', 'Hemp textile innovation with BCG concept to fashion lifestyle product design for Japan aging society', NULL, 10, '2566', NULL, '<p>การวิจัยครั้งนี้มีวัตถุประสงค์ 1. เพื่อหาแนวทางการสร้างสรรค์ผลิตภัณฑ์แฟชั่นไลฟ์สไตล์(Lifestyle) จากนวัตกรรมสิ่งทอเส้นใยเฮมป์ (ประโยชน์ต่อสังคมและเศรษฐกิจ) 2. เพื่อหาแนวทางการสร้างนวัตกรรมสิ่งทอเส้นใยเฮมป์ ด้วยแนวคิด BCG (ประโยชน์ตามยุทธศาสตร์ชาติ 20 ปี) จากแนวทางการศึกษาสิ่งทอจากเส้นใยเฮมป์ ซึ่งกำลังเป็นพืชเศรษฐกิจที่น่าจับตามองของไทยและกำลังพัฒนาในการเพาะปลูกและการเปิดการค้าเสรีที่เติบโตมากขึ้นในตลาดระดับโลก ผลการศึกษาพบว่าเฮมป์ เป็นเส้นใยชนิดหนึ่งที่สามารถนำมาพัฒนาได้หลากหลาย ผู้วิจัยได้แนวทางการสร้างสรรค์นวัตกรรมสิ่งทอเส้นใยเฮมป์ ผสมผสานความรู้ทางภูมิปัญญา เพื่อการออกแบบผลิตภัณฑ์แฟชั่นไลฟ์สไตล์ เช่น การนำเส้นใยสิ่งทอที่มีความหลากหลายมาพัฒนาร่วมกันเพื่อให้เกิดการสร้างสรรค์ โครงสร้างสิ่งทอภูมิปัญญาที่มีความสวยงามและมีคุณสมบัติที่ดีต่อการใช้งานอย่างมีประสิทธิภาพ เป็นต้น สามารถตอบโจทย์แนวทางยุทธศาสตร์ของประเทศด้านการวิจัยและนวัตกรรมก้าวหน้าอย่างยั่งยืนในทุกมิติ และมีความสอดคล้องต่อแนวคิด BCG อีกทั้งแนวทางดังกล่าว ยังเป็นการช่วยเพิ่มเสน่ห์ คุณคุณค่าสมบัติของเส้นใยเฮมป์ ของไทย ให้เป็นที่รู้จักในตลาดโลก ทั้งด้านประสิทธิภาพที่ดี ความสวยงามน่าใช้งาน ความคงทนของเส้นใย การสวมใส่ที่นุ่มสบาย ตลอดจนสามารถนำไปพัฒนาเป็นผลิตภัณฑ์สินค้าเชิงพาณิชย์ในตลาดสินค้าแฟชั่นไลฟ์สไตล์เพื่อการแข่งขันและการส่งออกในตลาดระดับโลก ทำให้ชื่อเสียงของเฮมป์ ไทยเป็นที่รู้จักอย่างแพร่หลายและสามารถพัฒนาทั้งในด้านสิ่งทออุตสาหกรรมและภูมิปัญญาควบคู่กันไปอย่างยั่งยืน</p>', '', 'ศิลปกรรมศาสตรดุษฎีบัณฑิต', 'https://tdc.thailis.or.th/tdc/browse.php?option=show&browse_type=title&titleid=735812&query=%BC%D9%E9%CA%D9%A7%C7%D1%C2&s_mode=any&d_field=&d_start=0000-00-00&d_end=2569-10-07&limit_lang=&limited_lang_code=&order=&order_by=&order_type=&result_id=166&maxid', 'จุฬาลงกรณ์มหาวิทยาลัย. สำนักงานวิทยทรัพยากร'),
('ITM00000000061', 'การพัฒนาเพื่อเพิ่มมูลค่าของผลิตภัณฑ์เหลือทิ้งทางการเกษตรด้วยนวัตกรรมสารสกัดไฮโดรโซลจากสมุนไพรไทยสำหรับผลิตภัณฑ์ชำระล้างร่างกายสำหรับผู้สูงวัย', 'COM00000000003', 'COM00000000001', 'Developing for creating value added of by-product from an agricultural by innovative Thai herb hydrosols for anti-aging body cleansing product', NULL, 10, '2567', NULL, '<p>การวิจัยครั้งนี้มีวัตถุประสงค์เพื่อพัฒนาผลิตภัณฑ์สบู่เหลวที่มีคุณสมบัติในการกำจัดกลิ่นคนแก่ ซึ่งเกิดจากสารประกอบ 2-nonenal ที่เป็นสาเหตุสำคัญของกลิ่นไม่พึงประสงค์ โดยได้ทำการสกัดสารออกฤทธิ์จากสมุนไพรต่าง ๆ หลายชนิดและนำมาประเมินประสิทธิภาพในการกำจัดกลิ่นของสารสกัดสมุนไพรโดยทดสอบความสามารถในการลดสารประกอบ 2-nonenal ทั้งในหลอดทดลองและบนผิวหนังเทียมด้วยเทคนิคแก๊สโครมาโทรกราฟีควบคู่กับเทคนิคจมูกอิเล็กทรอนิกส์ โดยเลือกใช้สารสกัดไฮโดรโซลซึ่งเป็นของเหลือที่เกิดจากกระบวนการสกัดน้ำมันหอมระเหย เนื่องจากเป็นสารสกัดที่อ่อนโยน อีกทั้งยังเป็นการเพิ่มมูลค่าแก่ของที่เหลือทิ้งจากกระบวนผลิตทางการเกษตรให้มีมูลค่าสูงขึ้น จากผลการทดสอบพบว่าสารสกัดจากหมากสามารถยับยั้งและลดความเข้มข้นของ 2-nonenal ได้อย่างมีประสิทธิภาพมากที่สุด ผสมผสานกับสารสกัดไฮโดรโซลจากมะขามป้อมที่มีฤทธิ์ในการต้านอนุมูลอิสระ และความสามารถในต้านเชื้อก่อโรคในผิวหนังได้เป็นอย่างดี แล้วนำมาเป็นส่วนผสมในสบู่เหลวกำจัดกลิ่นคนแก่ ซึ่งเป็นสูตรที่อ่อนโยนปราศจากสารที่ก่อให้เกิดการระคายเคือง มีความสามารถในการต้านอนุมูลอิสระ ต้านการอักเสบ พร้อมทั้งออกแบบกลิ่นใน 3 รูปแบบ ได้แก่ 1) วู้ดดี้ ให้ความรู้สึกสงบ สุขุม 2) ไวท์ฟอรัล ให้ความรู้สึกผ่อนคลายและอ่อนหวาน และ 3) กรีนเฟช ให้ความรู้สึกสะอาด สดชื่นจากสมุนไพรสีเขียว เพื่อสร้างประสบการณ์การใช้งานที่ตอบสนองต่อผู้บริโภคที่หลากหลาย นอกจากนี้ผลงานวิจัยยังได้ดำเนินการยื่นจดอนุสิทธิบัตร จำนวน 2 เรื่อง ได้แก่ 1) กรรมวิธีการสกัดสารออกฤทธิ์จากหมากเพื่อใช้ในผลิตภัณฑ์กำจัดกลิ่นกายผู้สูงอายุ เลขที่คำขอ 253001880 และ 2) สบู่เหลวกำจัดกลิ่นกายผู้สูงอายุ เลขที่คำขอ 253001882 ผลงานวิจัยนี้จึงสามารถสะท้อนถึงความเป็นไปได้ทั้งในเชิงวิชาการและเชิงพาณิชย์ พร้อมถ่ายทอดเทคโนโลยีสู่การผลิตในระดับอุตสาหกรรมและสร้างมูลค่าเพิ่มให้กับสมุนไพรไทยได้อย่างยั่งยืน</p>', 'มหาวิทยาลัยเทคโนโลยีราชมงคลพระนคร. คณะวิทยาศาสตร์และเทคโนโลยี', '', 'https://tdc.thailis.or.th/tdc/browse.php?option=show&browse_type=title&titleid=735400&query=%BC%D9%E9%CA%D9%A7%C7%D1%C2&s_mode=any&d_field=&d_start=0000-00-00&d_end=2569-10-07&limit_lang=&limited_lang_code=&order=&order_by=&order_type=&result_id=165&maxid', 'มหาวิทยาลัยเทคโนโลยีราชมงคลพระนคร'),
('ITM00000000062', 'การบูรณาการเทคโนโลยีผลิตภัณฑ์อาหารสุขภาพจากใบชะพลูสำหรับผู้สูงวัยของวิสาหกิจชุมชนบางปลานวัตวิถี จังหวัดสมุทรปราการ', 'COM00000000003', 'COM00000000001', 'Hemp textile innovation with BCG concept to fashion lifestyle product design for Japan aging society', NULL, 10, '2567', NULL, '<p>การบูรณาการเทคโนโลยีผลิตภัณฑ์อาหารสุขภาพจากใบชะพลูสำหรับผู้สูงวัยของวิสาหกิจชุมชนบางปลานวัตวิถี จังหวัดสมุทรปราการ มีวัตถุประสงค์เพื่อศึกษาสำรวจผลิตภัณฑ์อาหารที่เหมาะสมในการผลิตอาหารสุขภาพจากใบชะพลูสำหรับผู้สูงวัย ศึกษาพัฒนาสูตรและกรรมวิธีการผลิตผลิตภัณฑ์อาหารสุขภาพจากใบชะพลูสำหรับผู้สูงวัย และศึกษาการเปลี่ยนแปลงระหว่างการเก็บรักษาของผลิตภัณฑ์อาหารสุขภาพจากใบชะพลูสำหรับผู้สูงวัย โดยเริ่มจากการศึกษาค้นคว้าข้อมูลผลิตภัณฑ์ที่เหมาะสม พบว่า แกงหอยขมใบชะพลูเหมาะสมในการผลิตผลิตภัณฑ์อาหารสุขภาพจากใบชะพลูสำหรับผู้สูงวัย จากนั้นทำการศึกษาพัฒนาสูตรพื้นฐานที่เหมาะสมในผลิตแกงหอยขมใบชะพลู พบว่า สูตรที่ 3 เป็นสูตรที่เหมาะสมในการผลิตแกงหอยขมใบชะพลูมากที่สุด โดยมีค่าสีที่ได้คือสีเหลืองอมแดงโทนเข้ม ค่า pH เป็นด่างอยู่ที่ \"7.85&plusmn;0.28\" และค่าTSS อยู่ที่ \"14.17&plusmn;0.05\" oBrix ส่วนค่าเกลือ ไม่สามารถวัดค่าเกลือได้ ศึกษาปริมาณนมทดแทนกะทิที่เหมาะสม ซึ่งทำการศึกษาปริมาณนมทดแทนกะทิ จำนวน 5 ระดับ คือ (นม:กะทิ) 0:100, 25:75, 50:50, 75:25 และ100:0 % พบว่า ระดับที่ 50:50 เป็นปริมาณนมทดแทนกะทิที่เหมาะสมในการผลิตแกงหอยขมใบชะพลู โดยมีค่าสีที่ได้คือสีเหลืองอมแดงโทนเข้ม ค่า pH เป็นด่างอยู่ที่ \"7.70&plusmn;0.12\" และค่าTSS อยู่ที่\" 12.50&plusmn;0.05\" oBrix ส่วนค่าเกลือ อยู่ที่ \"10.33&plusmn;0.00\" ศึกษาชนิดของสารให้ความหวานที่เหมาะสมในผลิตแกงหอยขมใบชะพลูจำนวน 3 ชนิด คือ ซูคราโลส, หญ้าหวาน, อิริทริทอล และไม่ใส่สารให้ความหวาน และนำมาเปรียบเทียบกับสูตรควบคุม พบว่า สารให้ความหวานซูคราโลส เป็นสารให้ความที่เหมาะสมในการผลิตแกงหอยขมใบชะพลู จากนั้นศึกษาปริมาณใบชะพลูจำนวน 3 ระดับ คือ 6, 8 และ10%ของปริมาณส่วนผสม ต่อ 1 สูตร และนำมาเปรียบเทียบกับสูตรควบคุม พบว่า ระดับที่ 8% เป็นปริมาณใบชะพลูที่เหมาะสมในการผลิตแกงหอยขมใบชะพลู โดยมีค่าสีที่ได้คือสีเหลืองอมเขียวโทนเข้ม ค่า pH เป็นด่างใกล้ความเป็นกลางอยู่ที่ \"7.01&plusmn;0.24\" และมีค่าTSS อยู่ที่\" 11.00&plusmn;0.00\" oBrix ส่วนค่าเกลือ ไม่สามารถวัดค่าเกลือได้ และศึกษาการเปลี่ยนแปลงระหว่างการเก็บรักษาของแกงหอยขมใบชะพลูที่อุณหภูมิ -20 องศาเซลเซียส สุ่มตรวจในวันที่ 1, 7, 14, 21 และ28 วัน พบว่า ด้านค่าสี ค่า pH และTSS (oBrix) มีค่าลดลงเรื่อยๆทีละน้อยเมื่อระยะเวลาการเก็บรักษานานขึ้น ส่วนผลการสุ่มตรวจวิเคราะห์คุณภาพทางจุลินทรีย์ทั้งหมด (TPC) ปริมาณยีสต์ และราของผลิตภัณฑ์แกงหอยขมใบชะพลู พบว่า มีปริมาณจุลินทรีย์ทั้งหมดจำนวนน้อย และมีปริมาณยีสต์ รา ไม่พบ</p>', 'มหาวิทยาลัยเทคโนโลยีราชมงคลพระนคร. คณะเทคโนโลยีคหกรรมศาสตร์', '', 'https://tdc.thailis.or.th/tdc/browse.php?option=show&browse_type=title&titleid=731604&query=%BC%D9%E9%CA%D9%A7%C7%D1%C2&s_mode=any&d_field=&d_start=0000-00-00&d_end=2569-10-07&limit_lang=&limited_lang_code=&order=&order_by=&order_type=&result_id=164&maxid', 'มหาวิทยาลัยเทคโนโลยีราชมงคลพระนคร'),
('ITM00000000063', 'นวัตกรรมการแปรรูปผักตบชวาสู่การพัฒนาผลิตภัณฑ์และบรรจุภัณฑ์อัตลักษณ์ ชุมชนสนับสนุนการท่องเที่ยวเชิงวัฒนธรรมและตลาดสีเขียว เพื่อการพัฒนาชุมชนผู้สูงวัยกลุ่มวิสากิจชุมชนท่องเที่ยวตลาดคลองสวน ๑๐๐ ปีและวิสากิจชุมชนเกษตรสุขสรรค์ คลองกระแชงเตย จังหวัดสมุทรปราการ', 'COM00000000003', 'COM00000000001', 'Processing innovation water hyacinth to product development and community identity packaging, support cultural tourism and green marketfor the development of the elderly community.100 Years Khlong Suan Market tourism community and Khlong Krachang Toei suk', NULL, 10, '2567', NULL, '<p>โครงการ นวัตกรรมการแปรรูปผักตบชวาสู่การพัฒนาผลิตภัณฑ์และบรรจุภัณฑ์อัตลักษณ์ชุมชนสนับสนุนการท่องเที่ยวเชิงวัฒนธรรมและตลาดสีเขียว เพื่อการพัฒนาชุมชนผู้สูงวัย กลุ่มวิสากิจชุมชนท่องเที่ยวตลาดคลองสวน ๑๐๐ ปีและวิสากิจชุมชนเกษตรสุขสรรค์คลองกระแชงเตย จังหวัดสมุทรปราการ เป็นโครงการวิจัยเชิงคุณภาพ โดยมีวัตถุประสงค์ 1.) เพื่อศึกษา วิเคราะห์ต้นทุนทางธรรมชาติ เชิงวัฒนธรรมชุมชน สู่การสร้างอัตลักษณ์รูปแบบผลิตภัณฑ์ บรรจุภัณฑ์จากวัสดุทางธรรมชาติ เพื่อรักษาสิ่งแวดล้อม 2.) เพื่อออกแบบและพัฒนาผลิตภัณฑ์ บรรจุภัณฑ์ สร้างอัตลักษณ์วัฒนธรรมส่งเสริมตลาดสีเขียวและการท่องเที่ยวเชิงวัฒนธรรม 3.) เพื่อบูรณาการองค์ความรู้เทคโนโลยีถ่ายทอดสู่หน่วยงานและชุมชนผู้สูงวัย ส่งเสริมอาชีพ สังคมและเศรษฐกิจ กลุ่มวิสากิจชุมชนท่องเที่ยวตลาดคลองสวน ๑๐๐ ปีและวิสากิจชุมชนเกษตรสุขสรรค์คลองกระแชงเตย จังหวัดสมุทรปราการ พื้นที่วิจัย ได้แก่ ชุมชนตลาดคลองสวน ๑๐๐ ปี และ ชุมชนเกษตรสุขสรรค์คลองกระแชงเตย จังหวัดสมุทรปราการ โดยใช้วิธีการคัดเลือกแบบเจาะจง กลุ่มเป้าหมาย คือ วิสาหกิจชุมชนตลาดคลองสวน ๑๐๐ ปี และวิสาหกิจชุมชนเกษตรสุขสรรค์คลองกระแชงเตย จังหวัดสมุทรปราการ รวม 50 คน โดยคัดเลือกตามเกณฑ์ที่กำหนดไว้ วิธีดำเนินการวิจัยในหลากหลายมิติ คือการออกแบบและพัฒนาต้นแบบผลิตภัณฑ์จักสานจากเส้นใยผักตบชวา เพื่อส่งเสริมอาชีพและส่งเสริมอัตลักษณ์พื้นถิ่น ต้นแบบผลิตภัณฑ์ของที่ระลึกจากการแปรรูปผักตบชวา เพื่อส่งเสริมอาชีพและส่งเสริมอัตลักษณ์พื้นถิ่น ต้นแบบบรรจุภัณฑ์อัตลักษณ์พื้นถิ่นจากผักตบชวา ส่งเสริมการขายและการท่องเที่ยว การสร้างต้นแบบ การทดสอบและการประเมินความพึงพอใจ ตลอดจนการเผยแพร่องค์ความรู้ขยายผลสู่ชุมชน ผลการวิจัยพบว่า ผลงานวิจัย ได้แก่ ต้นแบบ ผลิตภัณฑ์จักสานจากเส้นใยผักตบชวา ต้นแบบผลิตภัณฑ์ของที่ระลึกจากการแปรรูปผักตบชวา ต้นแบบบรรจุภัณฑ์ผักตบชวา รวมทั้งการอบรมให้สู่ชุมชน มีผลการประเมินความพึงพอใจของผู้เข้าร่วม อยู่ในเกณฑ์ดีมากที่สุด เนื่องจากการนำทรัพยากรทางธรรมชาติ ได้แก่ ผักตบชวา ที่มีจำนวนมากในพื้นที่ สร้างปัญหากับคุณภาพน้ำในแหล่งน้ำ สามารถนำมาแปรรูปแล้วสร้างสรรค์ผลิตภัณฑ์ บรรจุภัณฑ์ใหม่ๆ เป็นรูปแบบของเอกลักษณ์ชุมชนตัวเอง และสนับสนุนการท่องเที่ยวตลาดสีเขียวและการท่องเที่ยวเชิงวัฒนธรรม ส่งเสริมรายได้ สร้างอาชีพให้คนในพื้นที่ ทั้งพัฒนากำลังคนกลุ่มผู้สูงวัยและกลุ่มวิสากิจชุมชนท่องเที่ยวตลาดคลองสวน ๑๐๐ปี และวิสากิจชุมชนเกษตรสุขสรรค์คลองกระแชงเตยได้ และผู้วิจัยเสนอแนะแนวทางให้หน่วยงานที่เกี่ยวข้อง เพื่อการพัฒนาเชิงนโยบายด้านเศรษฐกิจและสังคม สร้างกระบวนการมีส่วนร่วมของชุมชน นำเอานวัตกรรมนี้ ไปใช้ประโยชน์จริงกับชุมชนต่อไป</p>', 'กองทุนส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม', 'มหาวิทยาลัยเทคโนโลยีราชมงคลพระนคร. คณะสถาปัตยกรรมศาสตร์และการออกแบบ', 'https://tdc.thailis.or.th/tdc/browse.php?option=show&browse_type=title&titleid=731182&query=%BC%D9%E9%CA%D9%A7%C7%D1%C2&s_mode=any&d_field=&d_start=0000-00-00&d_end=2569-10-07&limit_lang=&limited_lang_code=&order=&order_by=&order_type=&result_id=163&maxid', 'มหาวิทยาลัยเทคโนโลยีราชมงคลพระนคร'),
('ITM00000000064', 'ศึกษาวัสดุท้องถิ่นและวัสดุเหลือใช้ทางการเกษตรเพื่อออกแบบและพัฒนาผลิตภัณฑ์ ของที่ระลึก ด้วยการบูรณาการเทคโนโลยีกับวัฒนธรรม สำหรับรองรับสังคมผู้สูงวัย อำเภอควนกาหลง จังหวัดสตูล', 'COM00000000003', 'COM00000000001', 'Study local materials and agricultural waste to design and develop souvenir products by integrating technology with culture to support the aging society Khuan Kalong District, Satun Province', NULL, 10, '2567', NULL, '<p>การวิจัยนี้ มุ่งเน้น [1] เพื่อศึกษาวัสดุท้องถิ่นและวัสดุเหลือใช้ทางการเกษตรสร้างสรรค์เป็นผลิตภัณฑ์ของที่ระลึกเชิงวัฒนธรรม ตามแนวคิดเศรษฐกิจหมุนเวียน 2] เพื่อออกแบบและพัฒนาผลิตภัณฑ์ของที่ระลึกเชิงวัฒนธรรม จากวัสดุท้องถิ่นที่สะท้อนเรื่องราววัฒนธรรมเพื่อรองรับนวัตกรรมด้านสังคมสูงวัย อำเภอควนกาหลง จังหวัดสตูล โดยการวิจัยนี้เป็นการวิจัยเชิงปฏิบัติแบบมีส่วนร่วมใช้การวิจัยเชิงปฏิบัติการแบบมีส่วนร่วม โดยสะท้อนความจริงสอดคล้องกับการปฏิบัติในบริบทของกรอบแนวคิด ร่วมเสนอแนวความคิดในการสร้างกระบวนองค์ความรู้ใหม่ เพื่อปรับปรุงชีวิตความเป็นอยู่และการทำงาน ของชุมชน แบ่งกลุ่มตัวอย่างในการศึกษาวิจัยออกเป็น 3 กลุ่ม คือ 1] แบบสอบถามเชิงลึก จากตัวแทนของชุมชนและนักวิชาการท้องถิ่น จำนวน 5 คน เพื่อสมบัติของวัสดุและหาปัจจัยในการออกแบบ 2] แบบสอบถามสำหรับการออกแบบ เก็บข้อมูลสำหรับการ ออกแบบร่างผลิตภัณฑ์ของที่ระลึกแบบเจาะจง จำนวน 30 คน สำหรับกลุ่มตัวอย่างที่เป็นนักออกแบบ นักวิชาการและผู้เชี่ยวชาญด้านการออกแบบและนักการตลาดสำหรับพัฒนาแผนการตลาดระดับชุมชน และ 3] แบบประเมินความพึงพอใจ หลังจากการออกแบบผลิตภัณฑ์ของที่ระลึกด้วยกลุ่มตัวอย่าง 385 คน เป็นประชากรกลุ่มตัวอย่างที่มีอายุตั้งแต่ 20 - 60 ปี (กลุ่มวัยใกล้เกษียณ) นักท่องเที่ยวภายในพื้นที่และนอกพื้นที่ ผู้เชี่ยวชาญและนักออกแบบ โดยมีการสรุปผลดังนี้ 1. วัสดุท้องถิ่นและวัสดุเหลือใช้ทางการเกษตรสร้างสรรค์เป็นผลิตภัณฑ์ของที่ระลึกเชิงวัฒนธรรม เพื่อรองรับนวัตกรรมด้านสังคมสูงวัย ตามแนวคิดเศรษฐกิจหมุนเวียน 1] ทรัพยากรทางธรรมชาติอะไรที่โดดเด่นมากที่สุดในจังหวัดสตูลเป็นลำดับที่ 1 คือ ปาล์มน้ำมัน 2] วัสดุเหลือใช้ทางการเกษตรที่สามารถใช้ประโยชน์หลังจากการเก็บเกี่ยวแปรรูป และสามารถพัฒนาเป็นผลิตภัณฑ์ของที่ระลึกได้เป็นลำดับ 1 ปาล์มน้ำมัน ลำดับ 2 ยางพารา และ 3 กล้วยน้ำว้า โดยเกิดวัสดุใหม่เป็นกระดาษเส้นใยพืชที่สามารถขึ้นรูปเป็นผลิตภัณฑ์ของที่ระลึกได้ 2. อัตลักษณ์ทางวัฒนธรรมในท้องถิ่นเป็นฐานสำหรับออกแบบของที่ระลึก พบว่าพืชเศรษฐกิจที่แปรรูปใช้เศษวัสดุเหลือใช้ทางการเกษตรจากปาล์มน้ำมัน ทางใบปาล์มน้ำมัน ใบยางทะลายปาล์ม และกาบกล้วยได้ ผ้าบาติก หนัง ด้วยวิธีการเย็บอย่างง่ายคิดเป็นร้อยละ 64.66 มีการออกแบบร่างและพัฒนาเป็นต้นแบบจำลอง 8 ต้นแบบ และต้นแบบจริง 4 ต้นแบบ โดยผลการประเมินผลการออกแบบผลิตภัณฑ์ของที่ระลึก และการวิเคราะห์ผลกระทบต่อสิ่งแวดล้อมในขั้นตอนของการออกแบบ และการประเมินรูปแบบความพึงพอใจของงานผลิตภัณฑ์ของที่ระลึก มีระดับความพึงพอใจระดับมากที่ค่าเฉลี่ย X\" 4.43 (SD = 0.01) [3] การประเมินวัฏจักรของต้นแบบจำลองผลิตภัณฑ์ของที่ระลึก 1] การเลือกวัสดุที่มีผลกระทบต่อสิ่งแวดล้อมน้อย 2] การใช้วัสดุ 3] ใช้ กระบวนการผลิตที่เหมาะสม 4] อายุการใช้งานที่เหมาะสม 5] ลักษณะการออกแบบผลิตต้นแบบงานผลิตภัณฑ์ของที่ระลึก 6] ระบบการจัดการหลังหมดอายุการใช้งานที่เหมาะสม 7] ความเหมาะสมของผลิตภัณฑ์ที่สามารถผลิตใช้และจำหน่ายได้จริง ผลสรุปรวมมีระดับความพึงพอใจระดับมากที่ค่าเฉลี่ย X\" 4.40 (SD = 0.81) มีการพัฒนาผลิตภัณฑFของที่ระลึกสำหรับส่งเสริมการท่องเที่ยวในชุมชนใช้เทคนิคภูมิปัญญาที่ชุมชนสามารถฝึกทักษะได้ เมื่อมีระบบการผลิต การจำหน่าย และบริการ เพื่อสร้างรายได้สู่ครัวเรือนและชุมชนแล้ว ผลิตภัณฑ์ที่เกิดขึ้นจะนำไปสู่ &ldquo;อุตสาหกรรมสร้างสรรค์&rdquo; ที่ใช้การสร้างสรรค์ทุนทางปัญญาที่เป็นปัจจัยพื้นฐานสู่การพัฒนาที่ยั่งยืน</p>', 'กองทุนส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม', 'มหาวิทยาลัยเทคโนโลยีราชมงคลพระนคร. คณะสถาปัตยกรรมศาสตร์และการออกแบบ', 'https://tdc.thailis.or.th/tdc/browse.php?option=show&browse_type=title&titleid=731179&query=%BC%D9%E9%CA%D9%A7%C7%D1%C2&s_mode=any&d_field=&d_start=0000-00-00&d_end=2569-10-07&limit_lang=&limited_lang_code=&order=&order_by=&order_type=&result_id=162&maxid', 'มหาวิทยาลัยเทคโนโลยีราชมงคลพระนคร'),
('ITM00000000065', 'สภาพปัญหาคุณภาพชีวิตของผู้สูงวัยในเขตดุสิต กรุงเทพมหานคร', 'COM00000000003', 'COM00000000002', 'Quality of life problems of the elderly in Dusit District, Bangkok', NULL, 10, '2568', NULL, '<p>สภาพปัญหาคุณภาพชีวิตของผู้สูงวัยเป็นสิ่งสำคัญและมีความจำเป็นที่ส่งผลต่อผู้สูงวัยในเขตดุสิต กรุงเทพมหานคร เป็นอย่างมาก ดังนั้นผู้วิจัยจึงมีความสนใจในปัญหาและแนวทางในการแก้ไขปัญหาของคุณภาพชีวิตของผู้สูงวัย โดยมีวัตถุประสงค์ในการวิจัย ดังนี้ 1) เพื่อศึกษาสภาพปัญหาคุณภาพชีวิตของผู้สูงวัยในเขตดุสิต กรุงเทพมหานคร 2) เพื่อนำเสนอแนวทางการพัฒนาคุณภาพชีวิตของผู้สูงวัยในเขตดุสิต กรุงเทพมหานคร การวิจัยนี้เป็นการวิจัยเชิงคุณภาพ ผู้ให้ข้อมูลสำคัญจำนวน 17 คน โดยเป็นการสัมภาษณ์เชิงลึก เครื่องมือที่ใช้วิจัย ได้แก่ แบบสัมภาษณ์ ผลการวิจัยพบว่า 1. สภาพปัญหาคุณภาพชีวิตของผู้สูงวัยในเขตดุสิต กรุงเทพมหานคร พบปัญหา ดังนี้ 1.1 สภาพร่างกายมีปัญหา คือ ผู้สูงอายุบางคนขาดความรู้และความตระหนักในการดูแลสุขภาพตนเอง เช่น การรับประทานอาหารที่ไม่สมดุล การสูบบุหรี่ และการดื่มสุรา ซึ่งส่งผลกระทบต่อสุขภาพในระยะยาว 1.2 สภาพจิตใจมีปัญหา คือ ผู้สูงอายุที่ไม่ได้มีบทบาทในสังคมเหมือนเดิม จึงอาจรู้สึกว่าตนเองไม่มีคุณค่า โดยผู้สูงอายุที่ต้องอยู่บ้านตามลำพัง โดยเฉพาะในเวลากลางวันที่ไม่มีใครอยู่บ้าน อาจรู้สึกโดดเดี่ยวและถูกทอดทิ้ง 1.3 สภาพความสัมพันธ์ทางด้านสังคมมีปัญหา คือ เด็กสมัยใหม่ให้ความสำคัญกับผู้สูงอายุลดลง เนื่องจากมีการเปลี่ยนแปลงค่านิยมทางสังคม ทำให้ความเอื้อเฟื้อและความกตัญญูต่อผู้สูงอายุลดลง 1.4 สภาพสิ่งแวดล้อมมีปัญหา คือ การจราจรที่หนาแน่นและการใช้ยานพาหนะที่ใช้น้ำมันเป็นเชื้อเพลิง ทำให้เกิดการเผาไหม้และปล่อยสารพิษ เช่น ฝุ่นละออง PM2.5 และควันเสีย ซึ่งทำให้อากาศมีมลพิษสูง 2. แนวทางการพัฒนาคุณภาพชีวิตของผู้สูงวัยในเขตดุสิต กรุงเทพมหานคร คือ 2.1 ด้านร่างกาย ควรมีการปรับปรุงสิ่งแวดล้อมและบริการที่ให้บริการกับผู้สูงอายุเป็นสิ่งที่สำคัญอย่างหนึ่ง และควรที่จะส่งเสริมการรับรู้ข้อมูลที่สำคัญเกี่ยวกับสุขภาพ เช่น การป้องกันโรค การออกกำลังกาย และการเข้าถึงบริการด้านการแพทย์อย่างง่ายดาย เป็นต้น 2.2 ด้านจิตใจ การปรับปรุงสิ่งแวดล้อมและบริการที่ให้บริการกับผู้สูงอายุเป็นสิ่งที่สำคัญ การรับรู้ข้อมูลที่สำคัญเกี่ยวกับสุขภาพและพฤติกรรมที่ดีต่อสุขภาพของผู้สูงอายุ เช่น การป้องกันโรค การออกกำลังกาย และการเข้าถึงบริการด้านการแพทย์อย่างง่ายดาย เป็นต้น 2.3 ความสัมพันธ์ทางด้านสังคม ควรมีการส่งเสริมความร่วมมือระหว่างคนในครอบครัวหรือเพื่อนบ้านในชุมชนและผู้สูงอายุ เป็นการเชื่อมโยงให้ชุมชนเกิดความแข็งแกร่ง 2.4 ด้านสิ่งแวดล้อม ควรการสร้างสถานที่พักผ่อนและการออกกำลังกายที่เหมาะสม พร้อมกับการปรับปรุงสิ่งแวดล้อมให้เอื้อต่อการดำเนินชีวิตของผู้สูงอายุได้ดียิ่งขึ้น และการสร้างกลุ่มจิตอาสาในชุมชนเพื่อซ่อมแซมบ้าน ทั้งนี้เป็นการเส้นทางที่ชัดเจนในการเพิ่มคุณภาพชีวิตและส่งเสริมสุขภาพของผู้สูงอายุในชุมชนพื้นที่เขตดุสิต</p>', 'มหาวิทยาลัยราชภัฏสวนสุนันทา', 'รัฐศาสตรมหาบัณฑิต. ปริญญาโท. การเมืองการปกครอง', 'https://tdc.thailis.or.th/tdc/browse.php?option=show&browse_type=title&titleid=727804&query=%BC%D9%E9%CA%D9%A7%C7%D1%C2&s_mode=any&d_field=&d_start=0000-00-00&d_end=2569-10-07&limit_lang=&limited_lang_code=&order=&order_by=&order_type=&result_id=161&maxid', 'มหาวิทยาลัยราชภัฏสวนสุนันทา. ศูนย์วิทยบริการ'),
('ITM00000000066', 'แบบจำลองโลจิตพหุสำหรับการเลือกใช้รถโดยสารกึ่งสาธารณะของผู้สูงวัยเพื่อไปรักษาพยาบาล', 'COM00000000003', 'COM00000000002', 'Paratransit modal choice of medication access for the elderly using multinomial logit model', NULL, 10, '2565', NULL, '<p>การพัฒนาระบบขนส่งสาธารณะสำหรับผู้สูงวัยเป็นสิ่งจำเป็นสำหรับประเทศไทยที่เข้าสู่สังคมสูงวัย การออกแบบรถโดยสารกึ่งสาธารณะ (Paratransit) ที่เหมาะสำหรับผู้ที่ไม่สะดวกในการเดินทางที่สามารถเรียกใช้ได้ตามต้องการควรมีความเข้าใจในพฤติกรรมการเลือกใช้ซึ่งจะช่วยสร้างความคุ้มค่าของระบบ งานวิจัยนี้ทำการสร้างแบบจำลองพฤติกรรมการเลือกใช้รถโดยสารกึ่งสาธารณะสำหรับการเดินทางของผู้สูงวัยเพื่อไปโรงพยาบาล โดยวิเคราะห์ข้อมูลที่สำรวจจำนวน 500 ตัวอย่าง ผลงานวิจัยนำเสนอแบบจำลองโลจิตของพฤติกรรมการเลือกใช้รถโดยสารกึ่งสาธารณะ ปัจจัยทางเศรษฐกิจสังคมและลักษณะของรูปแบบการขนส่งที่มีอิทธิพลที่ระดับความเชื่อมั่นร้อยละ 95 ได้แก่ อายุ รายได้ครัวเรือน จำนวนสมาชิก จำนวนรถในครอบครอง ค่าใช้จ่าย และจำนวนผู้โดยสาร และผลการสร้างแบบจำลองการเลือกรถโดยสารประเภทอื่น ผลจากงานวิจัยนี้สามารถนำไปออกแบบการบริการรถโดยสารกึ่งสาธารณะให้มีจำนวนที่นั่งและอัตราค่าโดยสารที่ไม่มากเกินไปจนมีผลต่อกระทบต่อผู้มีรายได้น้อยโดยการวิเคราะห์ความเหมาะสมทางเศรษฐศาสตร์การขนส่ง การจัดบริการรถโดยสารกึ่งสาธารณะที่เหมาะสมควรแบ่งเป็นรถโดยสารกึ่งสาธารณะที่มีสิ่งอำนวยความสะดวกเบื้องต้นและมีอัตราค่าโดยสารไม่สูงสำหรับกลุ่มสูงวัยที่มีอายุ 60 ถึง 70 ปี ที่มีรายได้น้อยหรือปานกลาง และรูปแบบพิเศษที่มีสิ่งอำนวยสะดวกมากสำหรับผู้สูงวัยที่มีอายุ 70 ปีขึ้นไปและกลุ่มผู้มีรายได้สูง&nbsp;</p>', 'มหาวิทยาลัยเกษตรศาสตร์', 'DegreeName: วิศวกรรมศาสตรมหาบัณฑิต\r\nLevel: ปริญญาโท\r\nDescipline: วิศวกรรมโครงสร้างพื้นฐานและการบริหาร\r\nGrantor: มหาวิทยาลัยเกษตรศาสตร์', 'https://tdc.thailis.or.th/tdc/browse.php?option=show&browse_type=title&titleid=726848&query=%BC%D9%E9%CA%D9%A7%C7%D1%C2&s_mode=any&d_field=&d_start=0000-00-00&d_end=2569-10-07&limit_lang=&limited_lang_code=&order=&order_by=&order_type=&result_id=160&maxid', 'มหาวิทยาลัยเกษตรศาสตร์. สำนักหอสมุด'),
('ITM00000000067', 'การพัฒนากิจกรรมเกมที่ใช้ภาพเป็นสื่อกลางเพื่อส่งเสริมสมรรถภาพการมองเห็นของผู้สูงวัย', 'COM00000000003', 'COM00000000004', 'Development of visual-based games to enhance visual acuity in older adults', NULL, 10, '2569', NULL, '<p>การวิจัยนี้มีวัตถุประสงค์เพื่อพัฒนากิจกรรมเกมที่ใช้ภาพเป็นสื่อกลางในการส่งเสริมสมรรถภาพด้านการมองเห็นของผู้สูงวัย ซึ่งเป็นกลุ่มที่เริ่มประสบการเปลี่ยนแปลงและความเสื่อมถอยของการมองเห็นตามวัย เช่น ภาวะสายตายาวตามวัย การรับรู้ความคมชัดและความแตกต่างของสีที่ลดลง อันส่งผลกระทบต่อการทำกิจกรรมในชีวิตประจำวัน งานวิจัยมุ่งเน้นการออกแบบกิจกรรมที่สอดคล้องกับข้อจำกัดด้านการมองเห็นและสมรรถภาพทางกายของผู้สูงวัย โดยใช้ภาพเป็นองค์ประกอบหลักในการกระตุ้นการรับรู้ทางสายตา ควบคู่กับการส่งเสริมการมีส่วนร่วมและปฏิสัมพันธ์ในรูปแบบกิจกรรมในร่ม กระบวนการวิจัยประกอบด้วยการทบทวนแนวคิด ทฤษฎี และงานวิจัยที่เกี่ยวข้อง ได้แก่ ทฤษฎีการมองเห็นและการเสื่อมของสายตาในผู้สูงวัย ทฤษฎีการออกแบบตัวอักษรเพื่อการเข้าถึง (Accessible typography) และแนวคิดการออกแบบเพื่อทุกคน (Universal design) เพื่อนำมาสังเคราะห์เป็นกรอบแนวคิดในการออกแบบกิจกรรม จากนั้นได้พัฒนาแนวคิดกิจกรรมเกมต้นแบบจำนวน 3 รูปแบบ ได้แก่ 1) Color &amp; Shape Bingo 2) Story Boardgame และ 3) Colorful Gamebook ซึ่งล้วนเป็นกิจกรรมที่ใช้ภาพเป็นสื่อกลางในการฝึกการสังเกต การแยกแยะสีและรูปทรง รวมถึงการจดจ่อทางสายตา การประเมินความสนใจและความเหมาะสมของแนวคิดกิจกรรมต้นแบบดำเนินการโดยใช้แบบสอบถามออนไลน์ กลุ่มตัวอย่างประกอบด้วยผู้สูงวัยและผู้ที่เกี่ยวข้องกับการดูแลผู้สูงวัย จำนวนทั้งสิ้น 103 คน ข้อมูลที่ได้ถูกนำมาวิเคราะห์ด้วยสถิติเชิงพรรณนา ได้แก่ ค่าเฉลี่ยและค่าร้อยละ ผลการวิจัยพบว่า แนวคิด Story Boardgame ได้รับระดับความสนใจและความเหมาะสมสูงสุดเมื่อเปรียบเทียบกับแนวคิดอื่น เนื่องจากสามารถส่งเสริมการรับรู้ทางสายตาได้อย่างมีประสิทธิภาพ ควบคู่กับการสร้างความเพลิดเพลินและปฏิสัมพันธ์ทางสังคมภายในครอบครัว ผลการวิจัยนี้สามารถใช้เป็นข้อมูลพื้นฐานในการพัฒนากิจกรรมเกมต้นแบบที่เหมาะสมสำหรับการส่งเสริมสมรรถภาพด้านการมองเห็นของผู้สูงวัยในบริบทการใช้งานจริงต่อไปc</p>', 'มหาวิทยาลัยเทคโนโลยีพระจอมเกล้าพระนครเหนือ. คณะสถาปัตยกรรมและการออกแบบ. ภาควิชาเทคโนโลยีศิลปอุตสาหกรรม. สาขาวิชาศิลปประยุกต์และออกแบบผลิตภัณฑ์', 'มหาวิทยาลัยเทคโนโลยีพระจอมเกล้าพระนครเหนือ. คณะสถาปัตยกรรมและการออกแบบ, มหาวิทยาลัยเกษตรศาสตร์. คณะสถาปัตยกรรมศาสตร์, และมหาวิทยาลัยเทคโนโลยีราชมงคลธัญบุรี. คณะสถาปัตยกรรมศาสตร์. การประชุมวิชาการระดับชาติสถาปัตยกรรมและศิลปะสรรค์สร้าง ครั้งที่ 3 (ACA-03) (IC-61-71). กรุงเทพฯ : มหาวิทยาลัยเทคโนโลยีพระจอมเกล้าพระนครเหนือ', 'https://tdc.thailis.or.th/tdc/browse.php?option=show&browse_type=title&titleid=725751&query=%BC%D9%E9%CA%D9%A7%C7%D1%C2&s_mode=any&d_field=&d_start=0000-00-00&d_end=2569-10-07&limit_lang=&limited_lang_code=&order=&order_by=&order_type=&result_id=159&maxid', 'มหาวิทยาลัยเทคโนโลยีพระจอมเกล้าพระนครเหนือ. สำนักหอสมุดกลาง'),
('ITM00000000068', 'การศึกษาสังคม และพฤติกรรมผู้สูงวัยยุคใหม่ เพื่อการออกแบบสื่อสร้างสรรค์ส่งเสริมการใช้ชีวิตที่มีคุณค่าอย่างยั่งยืน', 'COM00000000003', 'COM00000000002', 'Study of aging behavior and social for new media design promoting sustainable and valuable life', NULL, 10, '2562', NULL, '<p>งานวิจัยนี้มีจุดมุ่งหมายเพื่อค้นหาแนวทางส่งเสริมการใช้ชีวิตที่มีคุณค่าอย่างยั่งยืนด้วยการออกแบบสื่อสร้างสรรค์ เนื่องจากในปีพ.ศ. 2564 ประเทศไทยจะเข้าสู่สังคมผู้สูงวัยอย่างสมบูรณ์ ซึ่งคิดเป็นสัดส่วนถึงร้อยละ 20 ของประชากรทั้งหมด จึงเป็นที่มาของการศึกษาสังคมและพฤติกรรมของผู้สูงวัยยุคใหม่ในปัจจุบัน ซึ่งจากข้อมูลพบว่า ด้วยการเปลี่ยนแปลงในบริบทของสังคมทำให้ผู้สูงวัยยุคใหม่มีแนวคิดในการใช้ชีวิตที่เปลี่ยนไปจากเดิม ไม่ยึดติดกับอายุและมโนทัศน์เก่าของการเกษียณอายุ ที่แม้สภาพร่างกายที่กำลังร่วงโรยแต่ความสำคัญจะอยู่ที่สภาพจิตใจที่มาจากความรู้สึกที่อิสระ หมดภาระการทำงานและหน้าที่การเป็นผู้ปกครอง และพร้อมเริ่มต้นชีวิตใหม่ในแบบที่ตนเองพึงพอใจ ทำให้เกิดนิยามใหม่ Generation Independent หรือ &ldquo;GEN I หรือ คนใจรุ่น&rdquo; ที่แข็งแรงทั้งกายและใจ รู้คุณค่าในตัวเองและพร้อมทำประโยชน์ให้สังคม ซึ่งความต้องการและรูปแบบการใช้ชีวิต สามารถแบ่งได้ 7 แบบ ได้แก่ ใจแอคทีฟ ใจโซเชียล ใจแฟมมิลี่ ใจเนเจอร์ ใจศิลป์ ใจบุญ และใจเที่ยว จากการวิเคราะห์นี้จึงนำมาสู่การออกแบบสื่อสร้างสรรค์ &ldquo;ใจรุ่น Community&rdquo; Platform ภายใต้ แนวคิด Passion Life&rsquo;s: I Design พื้นที่อิสระให้คน GEN. I ใจรุ่นได้ออกแบบชีวิตตามที่ตนเองต้องการ ซึ่งผลจากการทดลองพบว่า ผู้สูงวัยไม่ว่าจะรุ่นหรือยุคใด สามารถใช้ชีวิตที่มีคุณค่าอย่างยั่งยืนได้ ด้วยการรู้คุณค่า มีความภาคภูมิใจในตนเอง (Self-Esteem) และเห็นความหมายในการมีชีวิต กลุ่มเป้าหมายที่เข้าร่วมโครงการ &ldquo;ใจรุ่น Community&rdquo; จะได้รับแนวทางการใช้ชีวิตที่มีพลังจากการให้ความรู้ผ่าน &ldquo;ใจรุ่นซีรีย์&rdquo; และสามารถส่งต่อแนวคิดที่มีคุณค่า รวมถึงสามารถสร้างประโยชน์ต่อสังคมได้ด้วยการแบ่งปันความรู้และประสบการณ์ผ่านการแพร่ภาพสดที่ได้ผลตอบรับอย่างรวดเร็ว เพื่อก่อเกิดความสุขจากการให้และได้รับที่สอดคล้องกับทฤษฎีความพึงพอใจของมาสโลว์ กระบวนการออกแบบในการวิจัยมาจากการสังเคราะห์ประสิทธิผลจากสื่อสร้างสรรค์ และนำไปทดลองใช้งานและวัดผลผ่านช่องทางสังคมออนไลน์ เกิดเป็นการสร้างสังคมที่ประกอบไปด้วยบุคคลต้นแบบ ส่งเสริมให้ผู้สูงวัยได้แนวทางใช้ชีวิตที่มีคุณค่า ตลอดจนสร้างมโนทัศน์ใหม่ให้สังคมผู้สูงวัย นำไปสู่การขยายขอบเขตสังคมย่อยเฉพาะกลุ่มนี้จนเป็นเครือข่ายสังคมผู้สูงวัยยุคใหม่ที่เข้มแข็งและไม่มีที่สิ้นสุด</p>', 'มหาวิทยาลัยศิลปากร', 'DegreeName: ศิลปมหาบัณฑิต\r\nLevel: ปริญญาโท\r\nDescipline: ศิลปะการออกแบบ\r\nGrantor: มหาวิทยาลัยศิลปากร', 'https://tdc.thailis.or.th/tdc/browse.php?option=show&browse_type=title&titleid=722925&query=%BC%D9%E9%CA%D9%A7%C7%D1%C2&s_mode=any&d_field=&d_start=0000-00-00&d_end=2569-10-07&limit_lang=&limited_lang_code=&order=&order_by=&order_type=&result_id=158&maxid', 'มหาวิทยาลัยศิลปากร. สำนักหอสมุดกลาง'),
('ITM00000000069', 'การพัฒนาคุณภาพชีวิตด้านสาธารณสุขของผู้สูงวัยในชุมชนพัฒนาบ่อนไก่ เขตปทุมวัน กรุงเทพมหานคร', 'COM00000000003', 'COM00000000002', 'mproving the quality of life in public health for the elderly in Phattana Bon Kai Community, Pathumwan District, Bangkok', NULL, 10, '2567', NULL, '<p>การพัฒนาคุณภาพชีวิตด้านสาธารณสุขของผู้สูงวัย เป็นสิ่งสำคัญและมีความจำเป็นที่ส่งผลต่อผู้สูงวัยในชุมชนพัฒนาบ่อนไก่ เขตปทุมวัน กรุงเทพมหานคร เป็นอย่างมากดังนั้นผู้วิจัยจึงมีความสนใจในปัญหาและแนวทางในการแก้ไขปัญหาของการพัฒนาคุณภาพชีวิตด้านสาธารณสุขของผู้สูงวัย โดยมีวัตถุประสงค์ในการวิจัย ดังนี้ 1) เพื่อศึกษาสภาพปัญหาคุณภาพชีวิตด้านสาธารณสุขของผู้สูงวัยชุมชนพัฒนาบ่อนไก่ เขตปทุมวัน กรุงเทพมหานคร 2) เพื่อหาแนวทางในการพัฒนาคุณภาพชีวิตด้านสาธารณสุขของผู้สูงวัยชุมชนพัฒนาบ่อนไก่ เขตปทุมวัน กรุงเทพมหานคร การวิจัยนี้เป็นการวิจัยเชิงคุณภาพ ผู้ให้ข้อมูลสำคัญ จำนวน 17 ท่าน โดยเป็นการสัมภาษณ์เชิงลึกเครื่องมือที่ใช้วิจัย ได้แก่ แบบสัมภาษณ์ ผลการวิจัยพบว่า 1. สภาพปัญหาคุณภาพชีวิตด้านสาธารณสุขของ ผู้สูงวัยชุมชนพัฒนาบ่อนไก่ เขตปทุมวันกรุงเทพมหานครพบปัญหาดังนี้ 1.1 สภาพร่างกายมีปัญหาสำคัญคือผู้สูงวัยยังขาดความรู้ความเข้าใจในการดูแลสุขภาพของตนเองและยังให้ความสำคัญกับร่างกายของตนเองน้อยเกินไป และรายได้ไม่เพียงพอต่อการอุปโภคบริโภคส่งผลต่อการได้รับสารอาหารที่ดี 1.2 มีปัญหาสภาพจิตใจที่ไม่สามารถเลือกคุณภาพชีวิตที่ดีได้เนื่องจากสภาพสังคมและความเป็นอยู่ในชุมชนที่ไม่เอื้อยอำนวย และขาดการดูแลเอาใจใส่จากครอบครัวมีการสูญเสียพลัดพรากจากบุคคลใกล้ชิดหรือบุคคลอันเป็นที่รัก 1.3 ผู้สูงวัยอยู่ในชุนชนมีสภาพแวดวล้อมที่แออัดมีพื้นที่จำกัดไม่มีการจัดระเบียบและการดูแลความสะอาดภายในบ้านผู้อาศัยในชุมชนไม่ช่วยกันรักษาความสะอาดขาดการบูรณาการในเชิงรุกจากทางหน่วยงานที่เกี่ยวข้อง 2. แนวทางในการพัฒนาคุณภาพชีวิตด้านสาธารณสุขของผู้สูงวัยชุมชน พัฒนาบ่อนไก่ เขตปทุมวัน กรุงเทพมหานคร คือ 2.1 การพัฒนาสภาพร่างกายควรให้ความรู้ในเรื่องการดูแลสภาพร่างกายของตนเองให้กับผู้สูงวัยและผู้ดูแลที่ใกล้ชิตเพื่อเป็นแนวทางในการปฏิบัติอย่างถูกวิธี 2.2 การพัฒนาสภาพจิตใจควรจัดโครงการส่งเสริมสุขภาพจิตให้กับผู้สูงวัยเพื่อ คัดกรองภาวะสุขภาพจิตและส่งต่อในการรักษากรณีพบความผิดปกติ 2.3 ควรให้ความสำคัญจัดสภาพแวดล้อมภายในบ้านหรือชุมชนให้กับผู้สูงวัยและควรตระหนักถึงการจัดพื้นที่ที่ปลอดภัยให้เหมาะสมกับการใช้ชีวิตประจำวันซึ่งจะครอบคลุมไปถึงบ้านพักอาศัย พื้นที่สาธารณะในชุมชน เช่น พื้นที่ห้องน้ำและพื้นที่บันใด เนื่องจากเป็นพื้นที่ที่มีการเกิดอุบัติเหตุสำหรับผู้สูงวัยมากที่สุดทั้งนี้เพื่อให้ผู้สูงวัยได้รับอันตรายน้อยที่สุด</p>', 'มหาวิทยาลัยราชภัฏสวนสุนันทา', 'DegreeName: รัฐศาสตรมหาบัณฑิต\r\nLevel: ปริญญาโท\r\nDescipline: การเมืองการปกครอง\r\nGrantor: มหาวิทยาลัยราชภัฏสวนสุนันทา', 'https://tdc.thailis.or.th/tdc/browse.php?option=show&browse_type=title&titleid=722341&query=%BC%D9%E9%CA%D9%A7%C7%D1%C2&s_mode=any&d_field=&d_start=0000-00-00&d_end=2569-10-07&limit_lang=&limited_lang_code=&order=&order_by=&order_type=&result_id=157&maxid', 'มหาวิทยาลัยราชภัฏสวนสุนันทา. ศูนย์วิทยบริการ');
INSERT INTO `tb_item` (`item_id`, `item_title`, `community_id`, `collection_id`, `item_alternative`, `item_issued_day`, `item_issued_month`, `item_issued_year`, `item_description`, `item_abstract`, `item_sponsorship`, `item_citation`, `item_uri`, `item_publisher`) VALUES
('ITM00000000070', 'ความคาดหวังที่มีอิทธิพลต่อความพึงพอใจของผู้มาเยือนกลุ่มผู้สูงวัยต่อแหล่งท่องเที่ยวน้ำพุร้อนธรรมชาติเพื่อสุขภาพในอำเภอเมืองเชียงราย จังหวัดเชียงราย', 'COM00000000003', 'COM00000000002', 'The Effect of Expectation Towards Satisfaction of Silver Age Visitors to Wellness Tourism Natural Hot Springs Attractions in Mueang Chiang Rai District, Chiang Rai Province', NULL, 10, '2568', NULL, '<p>การศึกษานี้มีวัตถุประสงค์ 1) เพื่อศึกษาความคาดหวังของผู้มาเยือนกลุ่มผู้สูงวัยต่อแหล่งท่องเที่ยวน้ำพุร้อนธรรมชาติเพื่อสุขภาพในอำเภอเมืองเชียงราย จังหวัดเชียงราย 2) เพื่อศึกษาความพึงพอใจของผู้มาเยือนกลุ่มผู้สูงวัยต่อแหล่งท่องเที่ยวน้ำพุร้อนธรรมชาติเพื่อสุขภาพในอำเภอเมืองเชียงราย จังหวัดเชียงราย และ 3) เพื่อศึกษาความคาดหวังที่มีอิทธิพลต่อความพึงพอใจของผู้มาเยือนกลุ่มผู้สูงวัยต่อแหล่งท่องเที่ยวน้ำพุร้อนธรรมชาติเพื่อสุขภาพในอำเภอเมืองเชียงราย จังหวัดเชียงราย กลุ่มตัวอย่าง คือ ผู้มาเยือนชาวไทยที่มีอายุ 55 ปีขึ้นไปที่เดินทางมาท่องเที่ยวในแหล่งท่องเที่ยวน้ำพุร้อนธรรมชาติเพื่อสุขภาพในอำเภอเมืองเชียงราย จังหวัดเชียงราย จำนวน 384 คน เครื่องมือในการเก็บรวบรวมข้อมูล คือ แบบสอบถามวิเคราะห์ข้อมูลโดยใช้ ความถี่ ค่าร้อยละ ค่าเฉลี่ย ค่าส่วนเบี่ยงเบนมาตรฐาน การทดสอบค่าที Independent Simples T-test การทดสอบ One-way ANOVA (F-Test) ค่าสัมประสิทธิ์สหสัมพันธ์ และการวิเคราะห์การถดถอยพหุคูณ ผลการศึกษาพบว่า 1. ผู้มาเยือนกลุ่มผู้สูงวัยมีความคาดหวังต่อแหล่งท่องเที่ยวน้ำพุร้อนธรรมชาติเพื่อสุขภาพ โดยภาพรวมมีระดับความคาดหวังอยู่ในระดับมากที่สุด เมื่อพิจารณารายด้าน พบว่า ด้านสิ่งที่ดึงดูดใจของแหล่งท่องเที่ยวน้ำพุร้อนธรรมชาติเพื่อสุขภาพ เป็นอันดับแรก รองลงมา คือ ด้านความสะดวกในการเดินทางของแหล่งท่องเที่ยวน้ำพุร้อนธรรมชาติเพื่อสุขภาพ ด้านสิ่งอำนวยความสะดวกของแหล่งท่องเที่ยวน้ำพุร้อนธรรมชาติเพื่อสุขภาพ ด้านกิจกรรมการท่องเที่ยว และด้านการบริการที่พัก ตามลำดับ 2. ผู้มาเยือนกลุ่มผู้สูงวัยมีความพึงพอใจต่อแหล่งท่องเที่ยวน้ำพุร้อนธรรมชาติเพื่อสุขภาพในอำเภอเมืองเชียงราย จังหวัดเชียงราย โดยภาพรวมมีระดับความพึงพอใจอยู่ในระดับมากที่สุดเมื่อพิจารณารายด้าน พบว่า ด้านความเป็นรูปธรรมของการบริการเป็นอันดับแรก รองลงมา คือ ด้านความน่าเชื่อถือ ด้านการเข้าใจและรู้จักลูกค้า ด้านการตอบสนองลูกค้า และด้านการให้ความมั่นใจแก่ลูกค้า ตามลำดับ และ 3. ความคาดหวังของผู้มาเยือนกลุ่มผู้สูงวัยมีความสัมพันธ์กับความพึงพอใจของผู้มาเยือนกลุ่มผู้สูงวัยต่อแหล่งท่องเที่ยวน้ำพุร้อนธรรมชาติเพื่อสุขภาพในอำเภอเมืองเชียงราย จังหวัดเชียงราย และความคาดหวังของผู้มาเยือนกลุ่มผู้สูงวัยมีอิทธิพลต่อความพึงพอใจของผู้มาเยือนกลุ่มผู้สูงวัยต่อแหล่งท่องเที่ยวน้ำพุร้อนธรรมชาติเพื่อสุขภาพในอำเภอเมืองเชียงราย จังหวัดเชียงราย อย่างมีนัยสำคัญทางสถิติที่ระดับ0.05 โดยปัจจัยที่มีอิทธิพลมากที่สุด คือ มีความสวยงามทางธรรมชาติ (X1) รองลงมาคือ ลักษณะของน้ำพุร้อนธรรมชาติมีความน่าสนใจ (X2) ที่พักมีคุณภาพได้รับมาตรฐานและมีความปลอดภัย (X14) มีกิจกรรมที่หลากหลาย (X17) สามารถใช้เป็นสถานที่พักผ่อนหย่อนใจ (X4) และกิจกรรมน่าสนใจ (X18) ตามลำดับ</p>', 'มหาวิทยาลัยพะเยา', 'DegreeName: Master of Arts\r\nLevel: Master\'s Degree\r\nDescipline: Tourism and Hotel Management\r\nGrantor: University of Phayao', 'https://tdc.thailis.or.th/tdc/browse.php?option=show&browse_type=title&titleid=722283&query=%BC%D9%E9%CA%D9%A7%C7%D1%C2&s_mode=any&d_field=&d_start=0000-00-00&d_end=2569-10-07&limit_lang=&limited_lang_code=&order=&order_by=&order_type=&result_id=156&maxid', 'มหาวิทยาลัยพะเยา.ศูนย์บรรณสารและการเรียนรู้'),
('ITM00000000071', 'การวิจัยเรื่องการพัฒนารูปแบบการจัดการเรียนการสอนโดยบูรณาการภูมิปัญญาอาหารไทย สู่การปฏิบัติสำหรับการดูแลสุขภาพของกลุ่มผู้สูงวัย', 'COM00000000003', 'COM00000000001', 'The Development of Instructional Model by Integration Thaifoods Wisdom for the Elderly Healthcare', NULL, 10, '2022', NULL, '<p>การวิจัยครั้งนี้มีวัตถุประสงค์ 1) เพื่อพัฒนารูปแบบการจัดการเรียนการสอนโดยบูรณาการภูมิปัญญาอาหารไทยสู่การปฏิบัติสำหรับการดูแลสุขภาพของกลุ่มผู้สูงวัย 2) เพื่อเปรียบเทียบความสามารถในการดูแลสุขภาพด้านอาหารสำหรับผู้สูงวัยก่อนและหลังการจัดการเรียนรู้ตามรูปแบบที่พัฒนาขึ้น และ 3) เพื่อศึกษาพัฒนาการด้านสุขภาพของกลุ่มผู้สูงวัยหลังการใช้รูปแบบการจัดการเรียนการสอนโดยบูรณาการภูมิปัญญาอาหารไทยสู่การปฏิบัติที่พัฒนาขึ้น กลุ่มตัวอย่าง คือ ผู้สูงวัยหรือผู้ดูแลผู้สูงวัย ตำบลแหลมฟ้าผ่า จำนวน 30 คน ซึ่งได้มาจากการสุ่มอย่างง่าย ด้วยการจับฉลาก เครื่องมือที่ใช้ในการวิจัย คือ แบบวิเคราะห์เอกสาร แบบสัมภาษณ์ แบบตรวจสอบความสอดคล้องเหมาะสมของรูปแบบการเรียนการสอน คู่มือการใช้รูปแบบการเรียนการสอน แบบประเมินความสามารถแบบบันทึก และประเด็นการสนทนากลุ่ม ที่ผ่านการตรวจสอบคุณภาพของเครื่องมือ วิเคราะห์ข้อมูลโดยใช้ ค่าร้อยละ ค่าเฉลี่ย ส่วนเบี่ยงเบนมาตรฐาน การทดสอบค่าที การวิเคราะห์เนื้อหา ผลการวิจัย พบว่า 1. รูปแบบการจัดการเรียนการสอนโดยบูรณาการภูมิปัญญาอาหารไทยสู่การปฏิบัติสำหรับการดูแลสุขภาพของกลุ่มผู้สูงวัย (LIFE3 Model) ที่พัฒนาขึ้นมีองค์ประกอบ 4 ส่วนคือ 1) หลักการ 2) วัตถุประสงค์ 3) ขั้นตอนการจัดการเรียนการสอน ได้แก่ (1) ศึกษารูปแบบการใช้ชีวิตของผู้สูงวัย (2) ให้ปฏิบัติอย่างอิสระและร่วมกันสังเกต (3) ให้ข้อมูลย้อนกลับเพื่อปรับพฤติกรรม (4) ดูแลและโค้ชโดยผู้เชี่ยวชาญ (5) ประเมินผลและสะท้อนคิด และ (6) วิวัฒน์รูปแบบการใช้ชีวิต และ 4) เงื่อนไขความสำเร็จ ค่าความเหมาะสมสอดคล้องอยู่ในระดับมากที่สุด ( X = 4.72, S.D. = .09) 2. ความสามารถในการดูแลสุขภาพด้านอาหารสำหรับผู้สูงวัย หลังเรียนสูงกว่าก่อนเรียน อย่างมีนัยสำคัญทางสถิติที่ระดับ .05 และ 3. หลังการจัดการเรียนการสอนด้วยรูปแบบการเรียนการสอนที่พัฒนาขึ้นผู้สูงวัยมีพัฒนาการทางสุขภาพที่สูงขึ้น</p>', 'ContributorName: Dhonburi Rajabhat University Role: ผู้ให้ทุน', '', 'https://tdc.thailis.or.th/tdc/browse.php?option=show&browse_type=title&titleid=722165&query=%BC%D9%E9%CA%D9%A7%C7%D1%C2&s_mode=any&d_field=&d_start=0000-00-00&d_end=2569-10-07&limit_lang=&limited_lang_code=&order=&order_by=&order_type=&result_id=155&maxid', 'มหาวิทยาลัยราชภัฏธนบุรี. สำนักวิทยบริการและเทคโนโลยีสารสนเทศ'),
('ITM00000000072', 'แนวทางขององค์กรปกครองส่วนท้องถิ่นในการจัดบริการด้านสวัสดิการสังคมและสังคมสงเคราะห์ให้แก่ผู้สูงวัยในพื้นที่ตำบลบางพระ อำเภอนครชัยศรี จังหวัดนครปฐม', 'COM00000000003', 'COM00000000002', 'Role of subdistrict administration organization in providing social welfare and social welfare services for the elderly in the area of Bang Phra Subdistrict, Nakhon Chai Si District, Nakhon Pathom Province', NULL, 10, '2565', NULL, '<p>การวิจัยครั้งนี้ มีวัตถุประสงค์เพื่อ 1) ศึกษาบทบาทและปัญหาในการจัดบริการด้านสวัสดิการสังคมและสังคมสงเคราะห์ให้แก่ผู้สูงวัยขององค์กรปกครองส่วนท้องถิ่น ในตำบลบางพระ อำเภอนครชัยศรี จังหวัดนครปฐม 2) ศึกษาแนวทางการจัดบริการด้านสวัสดิการสังคมและสังคมสงเคราะห์ให้แก่ผู้สูงวัยขององค์กรปกครองส่วนท้องถิ่น ในตำบลบางพระ อำเภอนครชัยศรี จังหวัดนครปฐม และ 3) ศึกษารูปแบบในการจัดบริการด้านสวัสดิการสังคมและสังคมสงเคราะห์ให้แก่ผู้สูงวัยขององค์กรปกครองส่วนท้องถิ่น ในตำบลบางพระ อำเภอนครชัยศรี จังหวัดนครปฐม วิธีการวิจัยใช้เทคนิคการวิจัยเชิงคุณภาพ (qualitative research) การเก็บข้อมูลใช้การสัมภาษณ์เชิงลึก (in-depth interview) จำนวน 3 กลุ่ม ได้แก่ ประชากรที่สังกัดองค์กรปกครองส่วนท้องถิ่นในพื้นที่ ประชากรที่ไม่ได้สังกัดองค์กรปกครองส่วนท้องถิ่นในพื้นที่ และประชากรผู้สูงวัย โดยประชากรทั้งสามกลุ่มตัวอย่าง รวมจำนวนทั้งสิ้น 39 คน ผลการวิจัยเกี่ยวกับบทบาทและปัญหาในการจัดบริการด้านสวัสดิการสังคมและสังคมสงเคราะห์ให้แก่ผู้สูงวัย พบว่า ผู้สูงวัยส่วนใหญ่มีปัญหาสุขภาพเนื่องจากมีโรคประจำตัว ได้แก่ เบาหวาน ความดันโลหิต มะเร็ง ความจำเสื่อม เส้นเลือดในสมองตีบ ซึ่งเป็นโรคที่เกิดจากพฤติกรรมการดำเนินชีวิตและสภาพแวดล้อมรอบตัว ผู้สูงวัยส่วนใหญ่มีความต้องการอยากอยู่ใกล้ชิดกับลูกหลานหรือคนในครอบครัว และต้องการให้คนเหล่านั้นให้การช่วยเหลือดูแลเอาอกเอาใจ ผู้สูงวัยบางส่วนมีปัญหาสภาพจิตใจ มีความรู้สึกเหงา เปล่าเปลี่ยว ท้อแท้ในสภาพร่างกาย อยากอยู่คนเดียวเงียบ ๆ ไม่สนใจสังคมหรือสภาพแวดล้อม ตลอดจนเทคโนโลยีหรือข่าวสารต่าง ๆ ที่มีผลต่อการดำเนินชีวิต เพราะมองว่าอายุเยอะแล้ว ไม่สามารถนำไปใช้ประโยชน์อะไรได้ ผู้สูงวัยส่วนใหญ่มีความพร้อมอยากจะมีส่วนร่วมในกิจกรรมต่าง ๆ หากมีเวลาว่าง ไม่ติดงานหรือธุระ และมีคนชวนถึงจะมาร่วมงาน นอกจากนี้ ผู้สูงวัยมีความต้องการที่จะมีสวัสดิการอื่นเพิ่มเติมหรือหลักประกันทางด้านรายได้ หากว่าตนไม่สามารถทำงานได้ ก็ยังมีสวัสดิการในส่วนนี้เพื่อใช้ในการดำรงชีพ ผลการวิจัยเกี่ยวกับแนวทางการจัดบริการด้านสวัสดิการสังคมและสังคมสงเคราะห์ให้แก่ผู้สูงวัย พบว่า มีการส่งเสริมสนับสนุนการฝึกอบรมและพัฒนาต่อยอดอาชีพให้กับกลุ่มต่าง ๆ เช่น กลุ่มสตรี กลุ่มแม่บ้าน กลุ่ม อสม. ซึ่งมีสมาชิกบางส่วนเป็นผู้สูงวัย โดยไม่ได้มีการมุ่งเน้นอบรมเจาะจงไปที่กลุ่มผู้สูงวัยโดยตรง มีการจัดให้มีอาสาสมัครท้องถิ่นบริบาลเพื่อให้ความช่วยเหลือ และให้คำแนะนำแก่ผู้ที่ดูแลผู้สูงวัยที่มีภาวะพึ่งพิงหรือป่วยติดเตียง มีการประสานไปยังหน่วยงานระดับจังหวัด ตลอดจนมูลนิธิหลวงพ่อสมหวัง วัดกลางบางพระ ในการให้ความช่วยเหลือด้านเครื่องอุปโภคบริโภค สิ่งอำนวยความสะดวกในการดำเนินชีวิต ตลอดจนการจัดหาที่พักหรือซ่อมแซมที่อาศัย ซึ่งเป็นการให้ความช่วยเหลือที่มีการสลับหมุนเวียนแต่ละบ้าน มีการจัดกิจกรรมในวันสำคัญต่าง ๆ เช่น วันสงกรานต์ โดยหากมีการแจกของขวัญก็จะทำให้ผู้สูงวัยมาร่วมงานจำนวนมาก มีการจัดให้มีการทัศนศึกษาดูงาน ซึ่งไม่ได้มีการเจาะจงไปที่กลุ่มผู้สูงวัย หากแต่ประชาชนทั่วไปที่สนใจก็สามารถไปศึกษาดูงานได้ นอกจากนี้มีการประสานไปยังโรงพยาบาลส่งเสริมสุขภาพประจำตำบล อาสาสมัครสาธารณสุขหมู่บ้าน และโรงพยาบาลในการดำเนินกิจกรรมด้านสุขภาพ ได้แก่ การออกกำลังกาย การตรวจสุขภาพประจำเดือน การคัดกรองโรค การให้ความรู้ด้านการดูแลสุขภาพ ผลการวิจัยเกี่ยวกับรูปแบบการจัดบริการสวัสดิการสังคมและสังคมสงเคราะห์ให้แก่ผู้สูงวัย พบว่า ควรมีการส่งเสริมจัดตั้งชมรมผู้สูงวัยเพื่อดำเนินกิจกรรมต่าง ๆ ควรมีการสร้างภาคีเครือข่ายในการดำเนินงาน โดยมีชมรมผู้สูงอายุเป็นศูนย์กลางในการประสานไปยังหน่วยงานราชการต่าง ๆ ที่เกี่ยวข้องเพื่อขอรับการสนับสนุนในด้านต่าง ๆ ควรมีการระดมปัญหาในการจัดบริการสวัสดิการสังคมสำหรับผู้สูงวัยในชุมชน โดยกำหนดความสำคัญและวิธีในการแก้ไขปัญหาที่พบ ควรมีการฝึกอบรมอาชีพและต่อยอดพัฒนาอาชีพเพื่อสร้างรายได้ให้เฉพาะกับกลุ่มผู้สูงวัยที่ว่างงานหรืออยู่บ้านเฉย ๆ ไม่ได้ทำอะไร ควรมีการส่งเสริมสุขภาพในการป้องกันโรค การให้ความรู้ และคำแนะนำการดูแลสุขภาพ รวมถึงการตรวจสุขภาพร่างกายประจำปี โดยมีบริการรถรับส่งกรณีที่ผู้สูงวัยที่เป็นผู้พิการ ป่วยติดเตียง แก่ชรามาก เดินทางไปเองไม่ไหว ควรส่งเสริมมีการจัดตั้งกองทุนสวัสดิการชุมชนตำบลขึ้นมาเพื่อช่วยเหลือผู้สูงวัยในพื้นที่ ตลอดจนประชาชนต่าง ๆ ที่สมัครสมาชิกในกองทุน ควรจัดให้มีการทัศนศึกษาดูงานแก่กลุ่มผู้สูงวัยโดยเฉพาะ ตามที่กลุ่มผู้สูงวัยส่วนใหญ่มีความประสงค์หรือมีความต้องการที่จะไปดู ควรจัดให้มีการเรียนการสอนให้ความรู้กับผู้สูงวัยให้เท่าทันกับยุคสมัยการเปลี่ยนแปลงในปัจจุบัน</p>', 'มหาวิทยาลัยราชภัฏสวนสุนันทา', '', 'https://tdc.thailis.or.th/tdc/browse.php?option=show&browse_type=title&titleid=721981&query=%BC%D9%E9%CA%D9%A7%C7%D1%C2&s_mode=any&d_field=&d_start=0000-00-00&d_end=2569-10-07&limit_lang=&limited_lang_code=&order=&order_by=&order_type=&result_id=154&maxid', 'มหาวิทยาลัยราชภัฏสวนสุนันทา. ศูนย์วิทยบริการ'),
('ITM00000000073', 'แผนธุรกิจร้านขายชุดนอนเพื่อสุขภาพสำหรับผู้สูงวัย', 'COM00000000003', 'COM00000000002', 'A business plan for health-focused sleepwear store for seniors', NULL, 10, '2568', NULL, '<p>ธุรกิจชุดนอนสำหรับผู้สูงอายุในประเทศไทยมีแนวโน้มเติบโตขึ้นอย่างต่อเนื่องในช่วงหลายปีที่ผ่านมา จากการเข้าสู่สังคมผู้สูงวัยโดยสมบูรณ์ แม้จะได้รับผลกระทบจากภาวะเศรษฐกิจและอัตราเงินเฟ้อ แต่สถานการณ์เริ่มผ่อนคลายไปในทิศทางที่ดีขึ้น สำหรับคู่แข่งขันในตลาดสินค้าแฟชั่นผู้สูงอายุส่วนใหญ่ยังขาดการพัฒนาเชิงลึกในด้านการออกแบบเฉพาะกลุ่มและบริการเชิงอารมณ์ ธุรกิจ An-An Sleepwear จึงมองเห็นโอกาสในการวางตำแหน่งแบรนด์ในฐานะสินค้าคุณภาพ พร้อมบริการที่เข้าถึงใจผู้บริโภค ด้วยแนวคิด &ldquo;ของขวัญแทนใจ&rdquo; ที่สร้างความแตกต่างจากผู้เล่นรายอื่นในตลาด ผลการวิจัยทางการตลาดพบว่า กลุ่มผู้สูงอายุหญิงที่ยังมีกำลังซื้อสูง และกลุ่มลูกหลานที่มีรายได้มั่นคง คือกลุ่มเป้าหมายหลักและรองที่มีอิทธิพลต่อพฤติกรรมการซื้อ โดยให้ความสำคัญกับ 3 ปัจจัย ได้แก่ คุณภาพของเนื้อผ้า ดีไซน์ที่สุภาพใส่สบาย และความเป็นของขวัญที่มีความหมาย นอกจากนี้ ยังคำนึงถึงบริการที่รวดเร็วและประทับใจทั้งก่อนและหลังการขาย ส่งผลให้สามารถสกัด Brand DNA ออกมาได้เป็น คุณภาพดี ใส่ใจผู้สูงอายุ และ ของขวัญแทนความรัก ซึ่งจะเป็นแนวทางในการพัฒนาแบรนด์ต่อไป สำหรับแผนการปฏิบัติงาน An-An Sleepwear จะเปิดร้านหลักในเขตเมืองกรุงเทพฯ ซึ่งสามารถเข้าถึงกลุ่มลูกค้าที่มีกำลังซื้อ พร้อมขยายการจำหน่ายผ่านช่องทางออนไลน์และทีวี เพื่อให้ครอบคลุมกลุ่มเป้าหมายที่มีพฤติกรรมการซื้อหลากหลาย นอกจากนี้ยังมีแผนจ้างบุคลากรที่มีความสามารถด้านการให้บริการผู้สูงวัยโดยเฉพาะ และมีระบบผลตอบแทนที่จูงใจเพื่อสร้างคุณภาพการให้บริการ ด้านกลยุทธ์ทางการเงิน ธุรกิจใช้เงินทุนจากเจ้าของกิจการจำนวน 2,000,000 บาท โดยคาดว่าจะสามารถคืนทุนได้ภายใน 2 ปี มีอัตราผลตอบแทนภายใน (IRR) อยู่ที่ 23% ซึ่งสูงกว่าต้นทุนเงินทุนเฉลี่ย (WACC) ที่ 5.77 ซึ่งอยู่ในระดับต่ำ แสดงให้เห็นถึงความเป็นไปได้และความคุ้มค่าของการลงทุน ปัจจัยสำคัญที่จะส่งผลต่อความสำเร็จของธุรกิจ คือ การเข้าถึงกลุ่มเป้าหมายอย่างแม่นยำ การสร้างความเชื่อมั่นผ่านประสบการณ์การใช้งาน และการสื่อสารแบรนด์ในฐานะของขวัญคุณภาพสำหรับผู้สูงวัย เพื่อให้เกิด Brand Loyalty และการกลับมาซื้อซ้ำในระยะยาว</p>', 'มหาวิทยาลัยธรรมศาสตร์', 'DegreeName: บริหารธุรกิจมหาบัณฑิต\r\nLevel: ปริญญาโท\r\nDescipline: บริหารธุรกิจ\r\nGrantor: มหาวิทยาลัยธรรมศาสตร์', 'https://tdc.thailis.or.th/tdc/browse.php?option=show&browse_type=title&titleid=721352&query=%BC%D9%E9%CA%D9%A7%C7%D1%C2&s_mode=any&d_field=&d_start=0000-00-00&d_end=2569-10-07&limit_lang=&limited_lang_code=&order=&order_by=&order_type=&result_id=153&maxid', 'มหาวิทยาลัยธรรมศาสตร์. หอสมุดแห่งมหาวิทยาลัยธรรมศาสตร์'),
('ITM00000000074', 'การศึกษาการแปรรูปโปรตีนไฮโดรไลเซทจากผำด้วยลูกกลิ้งร้อนร่วมกับเอนไซม์โปรติเอสเพื่อพัฒนานวัตกรรมซุปเปอร์ฟู้ดที่ย่อยและดูดซึมง่ายสำหรับผู้สูงวัย', 'COM00000000003', 'COM00000000001', '', NULL, 10, '2568', NULL, '<p>การวิจัยครั้งนี้มีวัตถุประสงค์เพื่อพัฒนากรรมวิธีการผลิตโปรตีนไฮโดรไลเซทจากผำ (Wolffia globosa) ด้วยเทคนิคการทำแห้งแบบลูกกลิ้งร้อน (drum drying) ร่วมกับการใช้เอนไซม์โปรติเอส และเพื่อศึกษาคุณลักษณะของโปรตีนไฮโดรไลเซทที่ได้ในรูปผลิตภัณฑ์ผง การทดลองเริ่มต้นด้วยการทดสอบประสิทธิภาพการย่อยโปรตีนผำด้วยเอนไซม์โปรติเอส 4 ชนิด ได้แก่ โบรมีเลนเกรดวิจัย โบรมีเลนจากผลิตภัณฑ์อาหารเสริม เอนไซม์โปรติเอสจากยาช่วยย่อย และเอนไซม์โปรติเอสการค้าอุตสาหกรรม โดยประเมินค่าระดับการย่อยสลายโปรตีน (%DH) ด้วยวิธี TNBS ผลการทดลองพบว่า โบรมีเลนเกรดวิจัยที่ pH 6.0 ให้ค่าการย่อยสลายสูงสุด (78.78%) แตกต่างจากเอนไซม์ชนิดอื่นอย่างมีนัยสำคัญทางสถิติ (p&le;0.05) ในขณะที่เอนไซม์จากผลิตภัณฑ์อาหารเสริมให้ค่าการย่อยต่ำที่สุด (65.00%) จากนั้นจึงเลือกโบรมีเลนเกรดวิจัยมาทดลองแปรอัตราส่วนเอนไซม์ต่อสารละลายผำใน 5 ระดับ ผลการทดลองพบว่าอัตราส่วน 3:7 ให้ค่าการย่อยสลายสูงสุด (94.56%) แต่การเพิ่มปริมาณเอนไซม์เกินกว่านี้ไม่ช่วยเพิ่มประสิทธิภาพอย่างมีนัยสำคัญ นอกจากนี้ การศึกษาผลของอุณหภูมิการทำแห้งด้วยลูกกลิ้งร้อนที่ 110, 120 และ 130 &deg;C พบว่า เมื่ออุณหภูมิสูงขึ้น ค่า L* และ a* มีแนวโน้มลดลง ขณะที่ค่า b* เพิ่มขึ้นอย่างมีนัยสำคัญ ส่งผลให้ผลิตภัณฑ์โปรตีนไฮโดรไลเซทเปลี่ยนสีจากเขียวเข้มไปสู่เหลืองอมน้ำตาลมากขึ้น</p>', 'มหาวิทยาลัยราชภัฏหมู่บ้านจอมบึง', 'ครองศักดา ภัคธนกนก. (2568). การศึกษาการแปรรูปโปรตีนไฮโดรไลเซทจากผำด้วยลูกกลิ้งร้อนร่วมกับเอนไซม์โปรติเอสเพื่อพัฒนานวัตกรรมซุปเปอร์ฟู้ดที่ย่อยและดูดซึมง่ายสำหรับผู้สูงวัย (รายงานผลการวิจัย). มหาวิทยาลัยราชภัฏหมู่บ้านจอมบึง.\r\nSourceCallNumber: 664.024', 'https://tdc.thailis.or.th/tdc/browse.php?option=show&browse_type=title&titleid=720583&query=%BC%D9%E9%CA%D9%A7%C7%D1%C2&s_mode=any&d_field=&d_start=0000-00-00&d_end=2569-10-07&limit_lang=&limited_lang_code=&order=&order_by=&order_type=&result_id=152&maxid', 'มหาวิทยาลัยราชภัฏหมู่บ้านจอมบึง. สำนักวิทยบริการและเทคโนโลยีสารสนเทศ'),
('ITM00000000075', 'การพัฒนารายวิชาด้านการฟังอย่างลึกซึ้ง (Deep Listening) เพื่อการเรียนรู้แบบเปิดสำหรับผู้สูงวัยในภาคตะวันออก', 'COM00000000003', 'COM00000000001', 'Development of Deep listening course for Open learning for Elderly in the Eastern Region', NULL, 10, '', NULL, '<p>การวิจัยครั้งนี้มีวัตถุประสงค์เพื่อ1)ศึกษาสภาพปัจจุบัน ปัญหาความต้องการจำเป็นรายวิชาเพื่อการเรียนรู้แบบเปิดสำหรับผู้สูงวัยในภาคตะวันออก 2)พัฒนารายวิชาด้านการฟังอย่างลึกซึ้ง(Deep Listening) เพื่อการเรียนรู้แบบเปิดสำหรับผู้สูงวัยในภาคตะวันออก 3)ศึกษาความพึงพอใจของผู้เรียนที่มีต่อรายวิชาการฟังอย่างลึกซึ้งสำหรับผู้สูงวัย โดยมีขั้นตอนการวิจัยคือ ระยะที่1ศึกษาสภาพปัจจุบัน ปัญหาความต้องการจำเป็นรายวิชาเพื่อการเรียนรู้แบบเปิด แหล่งข้อมูลได้แก่กลุ่มผู้สูงวัยในเขตภาคตะวันออกจำนวน 400 คน กลุ่มผู้ทรงคุณวุฒิ ผู้เชี่ยวชาญและผู้มีส่วนได้ส่วนเสีย จำนวน 25 คน เครื่องมือที่ใช้คือ แบบสอบถามสภาพความต้องการ แบบสัมภาษณ์เชิงลึก ระยะที่2 พัฒนารายวิชาด้านการฟังอย่างลึกซึ้ง(Deep Listening)เพื่อการเรียนรู้แบบเปิดสำหรับผู้สูงวัยในภาคตะวันออก แหล่งข้อมูลได้แก่ ผู้ทรงคุณวุฒิ จำนวน 6 คน ผู้เชี่ยวชาญ จำนวน 7 คน เครื่องมือที่ใช้คือ แบบประเมินคุณภาพเนื้อหา แบบประเมินคุณภาพสื่อบทเรียนรายวิชา ระยะที่ 3 การศึกษาความพึงพอใจ แหล่งข้อมูลได้แก่ กลุ่มผู้สูงวัยจำนวน 30 คน เครื่องมือที่ใช้คือ บทเรียนรายวิชาการฟังอย่างลึกซึ้งสำหรับผู้สูงวัย แบบสอบถามความพึงพอใจ วิเคราะห์ข้อมูลโดยใช้สถิติ ค่าร้อยละ ค่าเฉี่ยค่าเฉลี่ย ค่าส่วนเบี่ยงเบนมาตรฐาน การทดสอบค่าที และค่าดัชนีลำดับความสำคัญของความต้องการจำเป็น ผลการวิจัยพบว่า 1. ผู้สูงวัยในภาคตะวันออกมีความต้องการจำเป็นรายวิชาเพื่อการเรียนรู้แบบเปิดทุกกลุ่มเนื้อหา โดยมีค่าดัชนีความสำคัญของความต้องการจำเป็น(PNI modified ) อยู่ระหว่าง 0.42 -1.80 กลุ่มเนื้อหาที่มีความต้องการจำเป็นลำดับที่ 1 คือ กระบวนการฟังอย่างลึกซึ้ง (PNI modified =1.80) ลำดับที่2 คือ กระบวนการสุนทรียสนทนา (PNI modified =1.27) ลำดับที่3 คือ การดูแลระยะสุดท้ายของชีวิต (PNI modified =0.96) ส่วนรายการความต้องการจำเป็นน้อยที่สุดคือ การปฏิบัติพิธีกรรมทางศาสนา(PNI modified =0.42) 2. รายวิชามีส่วนประกอบคือ ประมวลรายวิชา โครงสร้างบทเนื้อหา เอกสารประกอบการสอน แบบทดสอบ และ ประกาศนียบัตร โดยคุณภาพสื่อบทเรียนโดยรวมมีความเหมาะสมอยู่ในระดับมาก (?(\"X\" ) = 4.06, S.D. = .27) ผู้เรียนมีคะแนนเฉลี่ยหลังเรียนสูงกว่าก่อนเรียนอย่างมีนัยสำคัญทางสถิติที่ระดับ .05 และประสิทธิภาพบทเรียนรายวิชาเท่ากับ 86.40/87.11 เป็นไปตามเกณฑ์ที่กำหนด 85/85 3.ผู้เรียนมีความพึงพอใจต่อรายวิชาโดยรวมอยู่ในระดับมาก (?(\"X\" ) = 4.49, S.D. = .44)</p>', 'มหาวิทยาลัยบูรพา. กองทุนส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม', '', 'https://tdc.thailis.or.th/tdc/browse.php?option=show&browse_type=title&titleid=720435&query=%BC%D9%E9%CA%D9%A7%C7%D1%C2&s_mode=any&d_field=&d_start=0000-00-00&d_end=2569-10-07&limit_lang=&limited_lang_code=&order=&order_by=&order_type=&result_id=151&maxid', 'มหาวิทยาลัยบูรพา. สำนักหอสมุด'),
('ITM00000000076', 'การปรับสภาพสิ่งแวดล้อมและเฟอร์นิเจอร์ภายในบ้าน สำหรับผู้สูงวัย', 'COM00000000003', 'COM00000000001', 'Adaptations of environments and furniture to create an agefriendly residence for the elderly', NULL, 10, '2568', NULL, '<p>การวิจัยนี้ มีวัตถุประสงค์เพื่อ 1) ศึกษาสภาพสิ่งแวดล้อมและเฟอร์นิเจอร์ภายในบ้าน สำหรับผู้สูงวัย 2) วิเคราะห์สภาพสิ่งแวดล้อมและเฟอร์นิเจอร์ภายในบ้าน สำหรับผู้สูงวัย 3) ออกแบบร่างต้นแบบของสิ่งแวดล้อมและเฟอร์นิเจอร์ภายในบ้าน สำหรับผู้สูงวัย 4) สร้างต้นแบบสิ่งแวดล้อมและเฟอร์นิเจอร์ภายในบ้าน สำหรับผู้สูงวัยแบบเสมือนจริง ตามต้นแบบภาพร่างที่พัฒนาขึ้นด้วยเทคโนโลยี Augmented reality (AR) และ Animation ผู้ให้ข้อมูลในการวิจัย ประกอบด้วย ผู้สูงวัย หรือผู้ดูแลผู้สูงวัย หรือนักกิจกรรมบำบัด หรือนักกายภาพบำบัด 12 คน ได้มาจากการเลือกตามวัตถุประสงค์ และกลุ่มตัวอย่างที่ใช้ประเมินผลต้นแบบเฟอร์นิเจอร์ 385 คน ได้มาจากการสุ่มอย่างง่าย ผลการวิจัย พบว่า 1) การออกแบบปรับสภาพสิ่งแวดล้อมและเฟอร์นิเจอร์ภายในบ้าน สำหรับผู้สูงวัย จะต้องมีความมั่นคงแข็งแรง มีราวจับ และสร้างความปลอดภัย เข้าถึงง่าย สอดคล้องกับแนวคิดการออกแบบด้านความมั่นคงและปลอดภัยมีขนาดและหน้าที่ใช้งานที่เหมาะสมหลากหลาย 2) ผลการประเมินต้นแบบสิ่งแวดล้อมและเฟอร์นิเจอร์ภายในบ้าน สำหรับผู้สูงวัยแบบเสมือนจริง มีผลการประเมินภาพรวมในระดับมากที่สุด (ค่าเฉลี่ยเท่ากับ 4.729) และผลการประเมินทั้ง 8 ด้าน ได้แก่ (1) มีสัดส่วนการใช้งานในพื้นที่ที่เหมาะสม (2) มีลักษณะเหมาะสมกับการใช้งาน (3) มีคุณค่าทางความงดงามเหมาะสม (4) สามารถนำไปเป็นต้นแบบประยุกต์สร้างในพื้นที่อื่นได้ (5) เป็นผลงานที่คนปกติสามารถใช้พื้นที่ร่วมด้วยได้ (6) เป็นผลงานที่เป็นประโยชน์แก่ผู้สูงวัย(7) เป็นผลงานที่มีรูปแบบไม่ซ้ำกับผลงานผู้อื่น และ (8) มีความชื่นชอบผลงานการปรับปรับสภาพสิ่งแวดล้อมและเฟอร์นิเจอร์ภายในบ้าน สำหรับผู้สูงวัย อยู่ในระดับมากที่สุด โดยมีค่าเฉลี่ยอยู่ระหว่าง 4.704 &ndash; 4.771</p>', 'มหาวิทยาลัยบูรพา. กองทุนส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม', 'มหาวิทยาลัยบูรพา. คณะศึกษาศาสตร์\r\nมหาวิทยาลัยบูรพา. โรงเรียนสาธิตพิบูลบำเพ็ญ\r\nมหาวิทยาลัยเทคโนโลยีพระจอมเกล้าพระนครเหนือ วิทยาเขตปราจีนบุรี. คณะเทคโนโลยีและการจัดการอุตสาหกรรม\r\nมหาวิทยาลัยบูรพา. วิทยาลัยวิทยาการวิจัยและวิทยาการปัญญา', 'https://tdc.thailis.or.th/tdc/browse.php?option=show&browse_type=title&titleid=720434&query=%BC%D9%E9%CA%D9%A7%C7%D1%C2&s_mode=any&d_field=&d_start=0000-00-00&d_end=2569-10-07&limit_lang=&limited_lang_code=&order=&order_by=&order_type=&result_id=150&maxid', 'มหาวิทยาลัยบูรพา. สำนักหอสมุด'),
('ITM00000000077', 'การพัฒนารายวิชาด้านสติ (Mindfulness) เพื่อการเรียนรู้แบบเปิดสำหรับผู้สูงวัยในภาคตะวันออก', 'COM00000000003', 'COM00000000001', 'A Development the Mindfulness Course for Open Learning the Elderly in the Eastern Region', NULL, 10, '2568', NULL, '<p>การวิจัยครั้งนี้ มีจุดมุ่งหมายเพื่อ (1) ศึกษาความต้องการจำเป็นการพัฒนารายวิชาสติ เพื่อการเรียนรู้แบบเปิดสำหรับผู้สูงวัย ในภาคตะวันออก (2) พัฒนารายวิชาสติ เพื่อการเรียนรู้แบบเปิดสำหรับผู้สูงวัย ในภาคตะวันออก และ(3) ทดลองใช้และประเมินผลรายวิชาสติ เพื่อการเรียนรู้แบบเปิดสำหรับผู้สูงวัย ในภาคตะวันออก มีวิธีการดำเนินการวิจัย 3 ขั้นตอน คือ ขั้นตอนที่ 1 ศึกษาความต้องการจำเป็นฯ กลุ่มตัวอย่าง คือ กลุ่มผู้สูงวัย ในภาคตะวันออก จำนวน 400 คน กลุ่มผู้ทรงคุณวุฒิ จำนวน 12 คน เครื่องมือที่ใช้ ได้แก่ แบบสอบถามความต้องการจำเป็น และแบบสัมภาษณ์เชิงลึก ขั้นตอนที่ 2 การพัฒนารายวิชาสติ เพื่อการเรียนรู้แบบเปิดสำหรับผู้สูงวัย ในภาคตะวันออก กลุ่มผู้ทรงคุณวุฒิ จำนวน 5 คน เครื่องมือที่ใช้ ได้แก่ แบบประเมินคุณภาพรายวิชาสติ เพื่อการเรียนรู้แบบเปิดสำหรับผู้สูงวัย ในภาคตะวันออก และขั้นตอนที่ 3 การทดลองใช้รายวิชาสติ เพื่อการเรียนรู้แบบเปิดสำหรับผู้สูงวัย ในภาคตะวันออก กลุ่มผู้เข้าร่วมใช้ฯ จำนวน 30 คน เครื่องมือที่ใช้ ได้แก่ รายวิชาสติ เพื่อการเรียนรู้แบบเปิดสำหรับผู้สูงวัย ในภาคตะวันออก และแบบประเมินความพึงพอใจรายวิชาสติ (Mindfulness) เพื่อการเรียนรู้แบบเปิดสำหรับผู้สูงวัย ในภาคตะวันออก ผลการวิจัยพบว่า 1. ความต้องการจำเป็นในแต่ละด้านเกี่ยวกับการฝึกสติ มีลำดับความสำคัญดังนี้ ด้านที่มีความต้องการจำเป็นสูงสุด คือ ด้านรูปแบบและวิธีการของการฝึกสติ (PNIModified = 0.39) รองลงมา คือ ด้านการนำการฝึกสติไปใช้ในชีวิตประจำวัน (PNIModified = 0.36) ส่วนด้านการฝึกสติขั้นพื้นฐาน (PNIModified = 0.27) มีความต้องการจำเป็นในลำดับถัดมา ขณะที่ด้านความรู้พื้นฐานเกี่ยวกับสติ (PNIModified = 0.19) เป็นด้านที่มีความต้องการจำเป็นน้อยที่สุด 2. ผลการประเมินคุณภาพของบทเรียนรายวิชาสติ (Mindfulness) เพื่อการเรียนรู้แบบเปิดสำหรับผู้สูงวัย ในภาคตะวันออก โดยผู้ทรงคุณวุฒิ พบว่า ค่าเฉลี่ยรวมอยู่ในระดับมาก ( = 4.47, S.D. = 0.50) 3. บทเรียนรายวิชาสติ (Mindfulness) เพื่อการเรียนรู้แบบเปิดสำหรับผู้สูงวัย ในภาคตะวันออก มีประสิทธิภาพเท่ากับ E1/ E2 เท่ากับ 81.86/82.98 และมีผู้เรียนที่ลงทะเบียนเรียนในระบบ ทั้งหมด 50 คนเป็นไปตามเกณฑ์ที่กำหนด 4. คะแนนผลสัมฤทธิ์ทางการเรียน หลังเรียนสูงกว่าก่อนเรียน ( = 7.67) (S.D.=.79) อย่างมีนัยสําคัญทางสถิติที่ระดับ .05 5. ความพึงพอใจของผู้ใช้ระบบการจัดการเรียนรู้แบบเปิด(BUU MOOCs)ฯ โดยรวมอยู่ในระดับมาก. ( = 3.88) (S.D.=.76) สะท้อนให้เห็นว่าการเรียนด้วยบทเรียนออนไลน์ระบบเปิด BUU MOOCs สามารถเป็นส่วนหนึ่งของการจัดการเรียนการสอนออนไลน์ในยุคดิจิทัลได้อย่างมีประสิทธิภาพ</p>', 'มหาวิทยาลัยบูรพา. กองทุนส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม', '', 'https://tdc.thailis.or.th/tdc/browse.php?option=show&browse_type=title&titleid=720433&query=%BC%D9%E9%CA%D9%A7%C7%D1%C2&s_mode=any&d_field=&d_start=0000-00-00&d_end=2569-10-07&limit_lang=&limited_lang_code=&order=&order_by=&order_type=&result_id=149&maxid', 'มหาวิทยาลัยบูรพา. สำนักหอสมุด'),
('ITM00000000078', 'นวัตกรรมเครือข่ายชุมชนแห่งการเรียนรู้ ยล เยี่ยม เยือน เสมือนจริง เพื่อเสริมสร้างคุณค่าภูมิปัญญาผู้สูงวัยในเขตภาคตะวันออก', 'COM00000000003', 'COM00000000001', 'Innovation of Community Learning Networking Virtual tour to Sees and Visit to Enhance the Value Wisdom of Aging in Eastern Region', NULL, 10, '2566', NULL, '<div class=\"row text-left\">\r\n<div class=\"col-sm-10\">การวิจัยนี้มีวัตถุประสงค์เพื่อ: 1) สังเคราะห์องค์ความรู้ภูมิปัญญาท้องถิ่น ปราชญ์ภูมิปัญญา และผลิตภัณฑ์ของผู้สูงวัยในการเพิ่มมูลค่าการท่องเที่ยววิถีชุมชนเพื่อการเรียนรู้ตลอดชีวิตในเขตภาคตะวันออก 2) ศึกษารูปแบบการใช้เทคโนโลยีเพื่อการเชื่อมโยงเครือข่ายชุมชนแห่งการเรียนรู้ &ldquo;ยล เยี่ยม เยือน เสมือนจริง&rdquo; 3) จัดการความรู้ภูมิปัญญาท้องถิ่น ปราชญ์ภูมิปัญญา และผลิตภัณฑ์ของผู้สูงวัยในการเพิ่มมูลค่าการท่องเที่ยววิถีชุมชนเพื่อการเรียนรู้ตลอดชีวิตในเขตภาคตะวันออก 4) สร้างนวัตกรรมเครือข่ายชุมชนแห่งการเรียนรู้ &ldquo;ยล เยี่ยม เยือน เสมือนจริง&rdquo; ภูมิปัญญาผู้สูงวัยในเขตภาคตะวันออกที่มีประสิทธิภาพ และ 5) วิเคราะห์คุณค่าภูมิปัญญาผู้สูงวัยในภาคตะวันออกผ่านนวัตกรรมเครือข่ายฯ กลุ่มตัวอย่าง ประกอบด้วย กลุ่มที่ 1 ผู้เชี่ยวชาญ 5 กลุ่ม จำนวน 8 คน กลุ่มตัวอย่างที่ 2 ประชุมเครือข่ายชุมชนแห่งการเรียนรู้เสน่ห์ภูมิปัญญา จากเครือข่ายด้วยการสะท้อนคิด และอภิปราย (Reflect &amp; Discussion) จากตัวแทนหรือผู้นำชุมชนท่องเที่ยวนวัตวิถีที่ได้รับการคัดสรรให้เป็นต้นแบบจำนวน 7 แห่ง โดยเลือกกลุ่มตัวอย่างแบบเจาะจง (Purposive Sampling) จำนวน 14 คน กลุ่มที่ 3 นักท่องเที่ยวที่เข้าชม&ldquo;ยล เยี่ยม เยือน เสมือนจริง&rdquo; จำนวน 30 คน กลุ่มที่ 4 ผู้นำชุมชนซึ่งเป็นเครือข่ายชุมชน จำนวน 20 คน และกลุ่มที่ 5 ผู้สูงวัยที่เป็นปราชญ์ภูมิปัญญาต้นเรื่องของชุมชนนวัตวิถี จำนวน 20 คน ครอบคลุม 7 จังหวัดในภาคตะวันออก สถิติที่ใช้ในการวิจัย คือ ค่าร้อยละ ค่าเฉลี่ย ค่าเบี่ยงเบนมาตรฐาน ค่า t-test และการวิเคราะห์ความแปรปรวนทางเดียว และวิเคราะห์ค่าสัมประสิทธิ์สหสัมพันธ์ของเพียร์สัน สังเคราะห์เนื้อหา ผลการวิจัยพบว่า 1) องค์ความรู้ภูมิปัญญาท้องถิ่น ปราชญ์ภูมิปัญญา และผลิตภัณฑ์ของผู้สูงวัยในการเพิ่มมูลค่าการท่องเที่ยววิถีชุมชนเพื่อการเรียนรู้ตลอดชีวิตในเขตภาคตะวันออกจากการลงพื้นที่ศึกษานำร่องจำแนกเป็น 5 องค์ความรู้ ได้แก่ (1) ภูมิปัญญาแปรรูปอาหารและเครื่องดื่ม (2) หัตถกรรมของใช้ของตกแต่งของที่ระลึก (3) สมุนไพรพื้นบ้าน (4) ผ้าและเครื่องนุ่งห่ม และ (5) วิถีชีวิตอาชีพวัฒนธรรมและประเพณี 2) รูปแบบการใช้เทคโนโลยีเพื่อการเชื่อมโยงเครือข่ายชุมชนแห่งการเรียนรู้&ldquo;ยล เยี่ยม เยือน เสมือนจริง&rdquo; ได้แก่ โมเดล 7 C: ประกอบด้วย (1) เชื่อมโยงชุมชนด้วยเทคโนโลยีเสมือนจริง (Connection to reality); (2) เรียนรู้ร่วมกันบนฐานการท่องเที่ยว (Collaborative Learning Based on Tourism); (3) เช็คอินเส้นทางแผนที่ท่องเที่ยว (Check in open trip map) ; (4) มุมมองการเปลี่ยนแปลงตามบริบทชุมชน (Climate/Context) ; (5) แสดงผลิตภัณฑ์สินค้าชุมชน (Community Product); (6) สร้างช่องทางการสื่อสารเพื่อการท่องเที่ยว (Communication Channels for Tourism); (7) แสดงผลิตภัณฑ์วัฒนธรรมชุมชน (Community Cultural Product) 3) กระบวนการจัดการความรู้ภูมิปัญญาท้องถิ่น ปราชญ์ภูมิปัญญา และผลิตภัณฑ์ ของผู้สูงวัยในการเพิ่มมูลค่าการท่องเที่ยววิถีชุมชนเพื่อการเรียนรู้ตลอดชีวิตในเขตภาคตะวันออกประกอบด้วย กระบวนการที่ชื่อว่า &ldquo;WE SHARE&rdquo; ได้แก่ W: Wisdom Community analytics การวิเคราะห์ภูมิปัญญาชุมชน, E : Exchanging Knowledge แลกเปลี่ยนองค์ความรู้, S : Storage จัดเก็บความรู้, H : Holistic Identity Community สร้างอัตลักษณ์ชุมชนแบบองค์รวม, A : Acquisition แสวงหาความรู้, R : Refinement กลั่นกรองความรู้, E : Elaboration ขยายความรู้ ซึ่งเป็นการนำความรู้ที่สร้างขึ้นไปเชื่อมโยงกับความรู้เดิม หรือแนวคิดที่ได้ค้นคว้าเพิ่มเติม หรือนำข้อสรุปไปอธิบายสถานการณ์เหตุการณ์ต่าง ๆ ทำให้เกิดความรู้ที่กว้างขึ้น 4) นวัตกรรมเครือข่ายชุมชนแห่งการเรียนรู้ &ldquo;ยล เยี่ยม เยือน เสมือนจริง&rdquo; ภูมิปัญญาผู้สูงวัยในเขตภาคตะวันออกบนลิงก์เว็บแอปพลเคชัน http://weenjoywisdom.com/Travel ประกอบด้วย ไดเร็กทอรี บอร์ด ได้แก่ ยลเรียนรู้ภูมิปัญญาตะวันออก เยี่ยมจุดเช็คอินถิ่นบูรพา เยือน 16 ชุมชน ครอบคลุม 7 จังหวัดในภาคตะวันออก ซึ่งผลการพัฒนา พบว่า นวัตกรรม เครือข่ายชุมชนได้รับการรับรองจากผู้เชี่ยวชาญอยู่ในระดับดีมาก ( =4.52, SD=0.38) และนักท่องเที่ยวที่เข้าร่วมกิจกรรมมีความพึงพอใจในระดับมากที่สุด ( =4.60, SD=0.42) 5) คุณค่าภูมิปัญญาผู้สูงวัยในภาคตะวันออกผ่านนวัตกรรมเครือข่ายชุมชนแห่งการเรียนรู้ &ldquo;ยล เยี่ยม เยือน เสมือนจริง&rdquo; โดยเมื่อทำการเปรียบเทียบคุณค่าภูมิปัญญาผู้สูงวัยก่อนและหลังเข้าร่วมกิจกรรม พบว่านักท่องเที่ยวเห็นคุณค่าภูมิปัญญาผู้สูงวัยมากขึ้น และมีการเปรียบเทียบความรู้สึกภูมิใจของผู้นำชุมชนก่อนและหลังเข้าร่วมกิจกรรมพบว่ามีความภูมิใจในภูมิปัญญาผู้สูงวัยต่อชุมชนสูงขึ้นอย่างมีนัยสำคัญทางสถิติที่ระดับ .05 6) ผลการประเมินการเห็นคุณค่าในตนเองโดยการแสดงความรู้สึกของผู้สูงวัย หลังการเข้าร่วมกิจกรรมส่งเสริมการท่องเที่ยว เสมือนจริงผ่านเทคโนโลยี QTVR 360 องศา &ldquo;ยล เยี่ยมเยือน เสมือนจริง&rdquo; ในประเด็นการเห็นคุณค่าในตนเอง เมื่อมีการเปรียบเทียบการเห็นคุณค่าในตนเอง ของผู้สูงวัยกลุ่มทดลอง ที่เข้าร่วมกิจกรรมโดยเปรียบเทียบก่อนและหลังเข้าร่วมกิจกรรม &ldquo;ยล เยี่ยมเยือน เสมือนจริง&rdquo; โดยใช้สถิติทีคู่ (Paired t-test) พบว่า ผู้สูงวัยมีการแสดงความรู้สึกเห็นคุณค่าในตนเองสูงขึ้นอย่างมีนัยสำคัญทางสถิติที่ระดับ .05</div>\r\n</div>\r\n<div class=\"row text-left\">&nbsp;</div>', 'มหาวิทยาลัยบูรพา. กองทุนส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม', '', 'https://tdc.thailis.or.th/tdc/browse.php?option=show&browse_type=title&titleid=720430&query=%BC%D9%E9%CA%D9%A7%C7%D1%C2&s_mode=any&d_field=&d_start=0000-00-00&d_end=2569-10-07&limit_lang=&limited_lang_code=&order=&order_by=&order_type=&result_id=148&maxid', 'มหาวิทยาลัยบูรพา. สำนักหอสมุด'),
('ITM00000000079', 'การพัฒนารายวิชาการออกกำลังกายเพื่อการเรียนรู้แบบเปิดสำหรับผู้สูงวัยในภาคตะวันออก', 'COM00000000003', 'COM00000000001', 'Development of Massive Open Online Courseware (MOOCs) in Exercise for Elderly in Eastern Economic Corridor', NULL, 10, '2567', NULL, '<p>การวิจัยนี้มีวัตถุประสงค์เพื่อออกแบบเนื้อหาการส่งเสริมการออกกำลังกายที่เหมาะสมกับผู้สูงวัยและศึกษาความพึงพอใจของผู้ใช้งานรายวิชาการออกกำลังกายเพื่อการเรียนรู้แบบเปิด (BUU MOOC) สำหรับผู้สูงอายุในเขตพัฒนาพิเศษภาคตะวันออก ผลการตรวจสอบความเหมาะสมของรายวิชาด้านสื่อและการใช้งานอยู่ที่ระดับ 4.26 จากนั้นนำรายวิชาไปเก็บข้อมูลกับผู้สูงอายุ โดยกลุ่มตัวอย่างเป็นนักเรียนในโรงเรียนผู้สูงอายุมาบไผ่ จังหวัดชลบุรี จำนวน 40 คน รับการถ่ายทอดความรู้รายวิชาการออกกำลังกายเพื่อการเรียนรู้แบบเปิดที่ผู้วิจัยผลิตขึ้น จากนั้นตอบแบบสอบถามความพึงพอใจที่มีต่อรายวิชาการออกกำลังกายเพื่อการเรียนรู้แบบเปิด (BUU MOOC) สำหรับผู้สูงอายุในเขตพัฒนาพิเศษภาคตะวันออก คำถามแบ่งเป็น 3 ด้าน ได้แก่ ด้านการนำเสนอเนื้อหา ด้านองค์ประกอบของบทเรียน และ ด้านการใช้งานบทเรียน ผลการวิจัยพบว่า ความพึงพอใจของผู้สูงอายุที่มีต่อรายวิชาการออกกำลังกายเพื่อการเรียนรู้แบบเปิดในภาพรวม อยู่ในระดับมากที่สุด มีค่าเฉลี่ย 4.60+0.58 และเมื่อวิเคราะห์รายด้านพบว่า ทั้ง 3 ด้านมีค่าเฉลี่ยความพึงพอใจอยู่ในระดับมากที่สุดทั้ง 3 ด้าน โดย ด้านการใช้งานบทเรียน มีค่าเฉลี่ย 4.64+0.10 ด้านการนำเสนอเนื้อหามีค่าเฉลี่ย 4.60+0.13 และ ด้านองค์ประกอบของบทเรียนมีค่าเฉลี่ย 4.56+0.22 และ ตามลำดับ จากข้อมูลที่ปรากฏสามารถสรุปได้ว่าสรุปได้ว่ารายวิชาการออกกำลังกายเพื่อการเรียนรู้แบบเปิด (BUU MOOC) สำหรับผู้สูงอายุในเขตพัฒนาพิเศษภาคตะวันออกสามารถใช้เป็นเครื่องมือในการถ่ายทอดความรู้ด้านการออกกำลังกายที่เหมาะสมสำหรับผู้สูงอายุได้</p>', 'มหาวิทยาลัยบูรพา', '', 'https://tdc.thailis.or.th/tdc/browse.php?option=show&browse_type=title&titleid=716676&query=%BC%D9%E9%CA%D9%A7%C7%D1%C2&s_mode=any&d_field=&d_start=0000-00-00&d_end=2569-10-07&limit_lang=&limited_lang_code=&order=&order_by=&order_type=&result_id=147&maxid', 'มหาวิทยาลัยบูรพา. สำนักหอสมุด'),
('ITM00000000080', 'การพัฒนารูปแบบการจัดการแข่งขันฟุตบอลเพื่อส่งเสริมสุขภาพของผู้สูงวัย', 'COM00000000003', 'COM00000000002', 'The development of a football competition management model to promote the health of the elderly', NULL, 10, '2566', NULL, '<p>การวิจัยและพัฒนา (Reseach and Development) นี้ มีวัตถุประสงค์เพื่อ 1) ศึกษาสภาพและความต้องการการจัดการแข่งขันฟุตบอลเพื่อส่งเสริมสุขภาพของผู้สูงวัยในประเทศไทย 2) พัฒนารูปแบบการจัดการแข่งขันฟุตบอลเพื่อส่งเสริมสุขภาพของผู้สูงวัยในประเทศไทย และ 3) ประเมินรูปแบบการจัดการแข่งขันฟุตบอลเพื่อส่งเสริมสุขภาพของผู้สูงวัยในประเทศไทย กลุ่มตัวอย่างจำนวน 400 คน โดยวิธีการสุ่มอย่างง่าย (Simple Random Sampling) โดยการตอบแบบสอบถาม และผู้ให้ข้อมูลสำคัญ (Key Informants) คือ ผู้ดำเนินการจัดการแข่งขันฟุตบอล ผู้จัดการทีม ผู้ฝึกสอน เจ้าหน้าที่ทีม ผู้ตัดสิน โดยเป็นผู้เชี่ยวชาญทางด้านการจัดการแข่งขันฟุตบอลผู้สูงวัย 28 คน โดยใช้วิธีการเลือกแบบเฉพาะเจาะจง (Purposive Selection) รวมกลุ่มตัวอย่างทั้งสิ้น 428 คน ผลที่ได้จากการวิจัย สรุปได้ดังนี้ 1) สภาพการการแข่งขันฟุตบอลผู้สูงวัยในประเทศไทย พบว่า ด้านกฎกติกาการแข่งขัน ด้านผู้เข้าร่วมการแข่งขัน และด้านการประชาสัมพันธ์ อยู่ในระดับมาก ส่วนด้านการจัดการแข่งขัน ด้านรูปแบบการแข่งขัน ด้านระยะเวลาในการแข่งขัน และด้านสถานที่ในการจัดการแข่งขัน อยู่ในระดับปานกลาง และสภาพความต้องการการจัดการแข่งขันฟุตบอลผู้สูงวัยในประเทศไทย พบว่า อยู่ในระดับมากทุกด้าน 2) รูปแบบการจัดการแข่งขันฟุตบอลผู้สูงวัยเพื่อส่งเสริมสุขภาพผู้สูงวัย คือ SONG GAME Model ประกอบไปด้วย 8 องค์ประกอบ ดังนี้ S: Spirit การมีน้ำใจ O: Organization management การบริหาร การจัดการ N: Network เครือข่ายพันธมิตร G: Good Game กิจกรรมการแข่งขันที่ดี G: Goal เป้าหมาย A: Age อายุ M: Motivation แรงจูงใจ E: Enjoyment ความสนุกสนาน 3) ผลการประเมินรูปแบบการจัดการแข่งขันฟุตบอลเพื่อส่งเสริมสุขภาพของผู้สูงวัยในประเทศไทย SONG GAME Model พบว่า ผู้มีส่วนเกี่ยวข้องกับฟุตบอลผู้สูงวัย มีความพึงพอใจอยู่ในระดับมาก และสามารถนำไปประยุกต์ใช้ในการจัดการแข่งขันฟุตบอลเพื่อส่งเสริมสุขภาพของผู้สูงวัยในประเทศไทยได้อย่างเหมาะสม</p>', '', 'DegreeName: ปรัชญาดุษฎีบัณฑิต\r\nLevel: ปริญญาเอก\r\nDescipline: การจัดการนันทนาการ การท่องเที่ยวและกีฬา\r\nGrantor: มหาวิทยาลัยศิลปากร', 'https://tdc.thailis.or.th/tdc/browse.php?option=show&browse_type=title&titleid=715637&query=%BC%D9%E9%CA%D9%A7%C7%D1%C2&s_mode=any&d_field=&d_start=0000-00-00&d_end=2569-10-07&limit_lang=&limited_lang_code=&order=&order_by=&order_type=&result_id=146&maxid', 'มหาวิทยาลัยศิลปากร. สำนักหอสมุดกลาง'),
('ITM00000000081', 'รูปแบบการจ้างแรงงานผู้สูงวัยของภาคเอกชนเพื่อรองรับเมืองอัจฉริยะ จังหวัดร้อยเอ็ด ประเทศไทย', 'COM00000000003', 'COM00000000001', '', NULL, 10, '2569', NULL, '<p>งานวิจัย เรื่อง รูปแบบการจ้างแรงงานผู้สูงวัยของภาคเอกชนเพื่อรองรับเมืองอัจฉริยะ จังหวัดร้อยเอ็ด ประเทศไทย มีวัตถุประสงค์เพื่อศึกษาความต้องการแรงงานผู้สูงอายุของภาคเอกชนในการทำงาน ศึกษาปัญหาและอุปสรรคการจ้างแรงงานผู้สูงอายุในภาคเอกชน และศึกษารูปแบบการจ้างแรงงานผู้สูงวัยของภาคเอกชนเพื่อรองรับเมืองอัจฉริยะ จังหวัดร้อยเอ็ด ประเทศไทย เป็นการวิจัยเชิงคุณภาพ ผู้ให้ข้อมูลสำคัญในการวิจัยครั้งนี้คัดเลือกแบบเจาะจง จำนวน 23 คน ใช้การสัมภาษณ์เชิงลึก และการสนทนากลุ่มย่อย การวิเคราะห์ข้อมูลใช้วิธีการพรรณนาเชิงวิเคราะห์ ผลการศึกษา พบว่า 1) ความต้องการแรงงานผู้สูงอายุภาคเอกชน ส่วนใหญ่เป็นแรงงานเดิม มีประสบการณ์ และความผูกพัน รวมทั้งความรู้ความสามารถ ทักษะในงานที่ทำ มีการกำหนดนโยบายการจ้างงานสอดคล้องกับลักษณะงานอย่างเหมาะสม มีความจำเป็นเนื่องจากทดแทนแรงงานที่มีไม่เพียงพอ แนวทางการจ้างแบบรายวันและการจ้างเหมา พิจารณาลักษณะงานและศักยภาพของแรงงาน 2) ปัญหาและอุปสรรคการจ้างแรงงานผู้สูงอายุภาคเอกชน พบว่า กฎหมายยังไม่ครอบคลุมแรงงานผู้สูงอายุในแง่ของการจัดสวัสดิการ ลักษณะงานขึ้นอยู่กับประเภทธุรกิจ แต่จะเป็นงานที่ปลอดภัยไม่มีความเสี่ยงหรือความเสี่ยงน้อย การปฏิบัติงานพิจารณาภาระงานอย่างเหมาะสม คำนึงถึงสภาพร่างกายและสภาพจิตใจ และ 3) รูปแบบการจ้างแรงงานผู้สูงวัยของภาคเอกชนเพื่อรองรับเมืองอัจฉริยะ มีประเด็นสำคัญ ดังนี้ (1) ควรมีนโยบาย แผนงาน ประกาศที่ชัดเจนเพื่อสนับสนุนการจ้างงานผู้สูงอายุ (2) ไม่ควรขยายอายุเกษียณ ให้พิจารณาจากลักษณะงานประกอบกับความพร้อมของผู้สูงอายุในด้านสภาพร่างกาย สุขภาพ และด้านอื่น ๆ ที่เกี่ยวข้อง แต่หากคำนึงถึงในอนาคตที่แรงงานขาดแคลนไม่สามารถหาคนมาทำงานได้ การขยายต้องมีมาตรการที่ชัดเจน และควรขยาย ตั้งแต่ 65-70 ปี (3) ความรู้ความสามารถ ทักษะที่ผู้สูงอายุควรได้รับการพัฒนา คือ ทักษะดิจิทัล การใช้เทคโนโลยี เทคโนโลยีสารสนเทศ จำเป็นต่อการปฏิบัติงานในปัจจุบันและแนโน้มในอนาคต การใช้เทคโนโลยีดิจิทัลเพื่อติดต่อ สื่อสาร ทำงานร่วมกันได้ รวมทั้งทักษะแห่งอนาคตอื่น ๆ (4) ภาครัฐโดยหน่วยงานที่เกี่ยวข้องควรสนับสนุนการจ้างแรงงานผู้สูงอายุในลักษณะของนโยบาย หรือผลักดันกฎหมายที่เอื้อต่อการจ้างแรงงานผู้สูงอายุ จากผลการวิจัยดังกล่าว ได้กำหนดองค์ประกอบและประเด็นในการพัฒนารูปแบบการจ้างงานของภาคเอกชนเพื่อรองรับเมือง อัจฉริยะ จังหวัดร้อยเอ็ด ดังนี้ (1) แรงงานผู้สูงวัย องค์ประกอบ ได้แก่ ความสำคัญและจำเป็นของแรงงาน ผู้สูงวัย ลักษณะการจ้างงานผู้สูงวัย ความรู้ความสามารถ ทักษะ และประสบการณ์ ความรู้ความสามารถ คุณสมบัติของแรงงานสูงวัย (2) ภาคเอกชน องค์ประกอบ ได้แก่ นโยบายการจ้างงาน ประเภทธุรกิจ/ลักษณะงาน แนวทางการจ้างงาน (3) ปัจจัยอื่นที่เกี่ยวข้อง ได้แก่ ความร่วมมือของหน่วยงานภาครัฐและเอกชน กฎหมายที่เกี่ยวข้อง สวัสดิการแรงงานผู้สูงวัย และ (4) เมืองอัจฉริยะ จังหวัดร้อยเอ็ด ตามองค์ประกอบที่จังหวัดร้อยเอ็ดกำหนด 2 ประกอบ คือ สิ่งแวดล้อมอัจฉริยะ และเศรษฐกิจอัจฉริยะ รวมทั้งระบบขนส่งและการสื่อสารอัจฉริยะ พลังงานอัจฉริยะ พลเมืองอัจฉริยะ การดำรงชีวิตอัจฉริยะ ระบบบริหารภาครัฐอัจฉริยะ</p>', 'คณะนิติรัฐศาสตร์ มหาวิทยาลัยราชภัฏร้อยเอ็ด', '', 'https://tdc.thailis.or.th/tdc/browse.php?option=show&browse_type=title&titleid=714132&query=%BC%D9%E9%CA%D9%A7%C7%D1%C2&s_mode=any&d_field=&d_start=0000-00-00&d_end=2569-10-07&limit_lang=&limited_lang_code=&order=&order_by=&order_type=&result_id=145&maxid', 'มหาวิทยาลัยราชภัฏร้อยเอ็ด. ศูนย์วิทยบริการ มหาวิทยาลัยราชภัฏร้อยเอ็ด'),
('ITM00000000082', 'การพัฒนารายวิชากระบวนการละครเพื่อการเรียนรู้แบบเปิดสำหรับผู้สูงวัยในภาคตะวันออก', 'COM00000000003', 'COM00000000001', 'Development of Process Drama Course for Massive Open Online Course for Active Aging in the Eastern of Thailand', NULL, 10, '2568', NULL, '<div class=\"row text-left\">\r\n<div class=\"col-sm-10\">การเติบโตอย่างรวดเร็วและความเป็นเมืองของเขตพัฒนาพิเศษภาคตะวันออก (EEC) ของประเทศไทย ได้สร้างความท้าทายที่สำคัญทั้งทางร่างกายและจิตใจให้แก่ผู้สูงวัยในพื้นที่ งานวิจัยนี้มีวัตถุประสงค์สองประการ คือ 1) เพื่อศึกษาองค์ความรู้ที่จำเป็นสำหรับผู้สูงวัยในการปรับตัวและบรรลุสู่การเป็นผู้สูงวัยที่มีพฤฒพลัง (Active Aging) และ 2) เพื่อพัฒนาหลักสูตรออนไลน์แบบเปิด (MOOCs) ที่ใช้กระบวนการละครเป็นฐานในการเสริมสร้างศักยภาพ เพื่อให้ผู้สูงวัยสามารถรับมือกับการเปลี่ยนแปลงและยกระดับคุณภาพชีวิตของตนเองได้ การวิจัยนี้ใช้ระเบียบวิธีวิจัยและพัฒนา (R&amp;D) แบบ 4 ขั้นตอนตามหลักการวิจัยเชิงปฏิบัติการ (Action Research) เก็บรวบรวมข้อมูลจากการสัมภาษณ์เชิงคุณภาพและแบบสอบถามเชิงปริมาณจากกลุ่มตัวอย่างผู้สูงวัยในเขต EEC ที่คัดเลือกแบบเจาะจง ผลการวิจัยตามวัตถุประสงค์ข้อแรกพบว่า ผู้สูงวัยต้องการลดการพึ่งพาผู้อื่นและจำเป็นต้องได้รับการเสริมสร้างศักยภาพใน 5 มิติหลัก ได้แก่ 1) ความรอบรู้ด้านสุขภาพเชิงรุก 2) ความรอบรู้ด้านดิจิทัลโดยเน้นการสร้างภูมิคุ้มกันต่อภัยออนไลน์ 3) การเห็นคุณค่าในตนเองและสุขภาพจิต 4) การมีส่วนร่วมทางสังคม และ 5) ความมั่นคงในชีวิต โดยมีเป้าหมายเพื่อเปลี่ยนบทบาททางสังคมของตนจาก \"ภาระ\" ให้กลายเป็น \"พลัง\" และนำไปสู่วัตถุประสงค์ข้อที่สองการพัฒนาหลักสูตรออนไลน์ (MOOCs) ในชื่อ \"กระบวนการละครเพื่อการเรียนรู้สู่พฤฒพลัง\" ซึ่งบูรณาการแนวคิดพฤฒพลังเข้ากับทฤษฎีการเรียนรู้เพื่อการเปลี่ยนแปลง ผลลัพธ์เชิงรูปธรรมคือหลักสูตร 4 โมดูล ที่นำเสนอผ่านวิดีโอรูปแบบสาระบันเทิง (Edutainment) และกิจกรรมละครที่ออกแบบมาโดยเฉพาะ โดยมีโครงสร้างที่นำพาผู้เรียนตั้งแต่การค้นพบตนเอง การสร้างทักษะ ไปจนถึงการมีส่วนร่วมคืนคุณค่าสู่สังคม ข้อเสนอแนะสำหรับการวิจัยในอนาคตมุ่งเน้น 3 แนวทางหลัก ได้แก่ การวิจัยเชิงคุณภาพเชิงลึกเพื่อการปรับใช้ให้เข้ากับบริบทท้องถิ่น การวิจัยเชิงปฏิบัติการเพื่อทดสอบประสิทธิผลในระดับชุมชน และการวิจัยระยะยาวเพื่อประเมินความยั่งยืนของผลลัพธ์</div>\r\n</div>\r\n<div class=\"row text-left\">&nbsp;</div>', 'มหาวิทยาลัยบูรพา', '', 'https://tdc.thailis.or.th/tdc/browse.php?option=show&browse_type=title&titleid=711202&query=%BC%D9%E9%CA%D9%A7%C7%D1%C2&s_mode=any&d_field=&d_start=0000-00-00&d_end=2569-10-07&limit_lang=&limited_lang_code=&order=&order_by=&order_type=&result_id=143&maxid', 'มหาวิทยาลัยบูรพา. สำนักหอสมุด'),
('ITM00000000083', 'การกระตุ้นการเจริญของเส้นใยด้วยแสงสีน้ำเงินและเปรียบเทียบคุณภาพผลผลิตของเห็ดเศรษฐกิจภายใต้สภาวะควบคุม', 'COM00000000001', 'COM00000000002', 'Stimulation of mycelium growth by blue light spectrum and comparison of yield quality of economic mushrooms under controlled condition', NULL, 10, '2568', NULL, '<p>เห็ด (Mushrooms) เป็นอาหารที่มีคุณค่าทางโภชนาการสูง เนื่องจากมีโปรตีน วิตามินและแร่ธาตุในปริมาณมาก และมีไขมันน้อย อีกทั้งยังมีสารออกฤทธิ์ทางชีวภาพสามารถนำมาใช้ในทางการแพทย์ อย่างไรก็ตาม การผลิตเส้นใยเห็ดเศรษฐกิจบนอาหารเลี้ยงเชื้อ Potato Dextrose Agar (PDA) มักประสบปัญหาการเจริญของเส้นใยไม่ดี ผลผลิตและสารสำคัญบางชนิดในปริมาณน้อย การศึกษานี้มีวัตถุประสงค์เพื่อศึกษาประสิทธิภาพของสเปกตรัมแสงสีน้ำเงินในการตอบสนองด้านการเจริญเติบโตของเส้นใยเห็ดเศรษฐกิจบนอาหารเลี้ยงเชื้อได้แก่ เห็ดขอนขาว เห็ดนางฟ้าภูฐาน เห็ดนางรมเทา เห็ดนางรมสีทอง และเห็ดเป๋าฮื้อ รวมถึงศึกษาเปรียบเทียบการเจริญเติบโต คุณภาพ และการปลดปล่อยก๊าซคาร์บอนไดออกไซด์ของเห็ดเศรษฐกิจในสภาวะควบคุม จากผลการทดลองพบว่า สเปกตรัมแสงสีน้ำเงินมีผลอย่างมีนัยสำคัญต่อการเจริญของเส้นใยและความหนาแน่นเชิงพื้นที่ของเส้นใย โดยเห็ดขอนขาว (สกุล Lentinus) มีการเจริญของเส้นใยดีที่สุด (8.00 เซนติเมตรในวันที่ 9) และเห็ดเป๋าฮื้อ (สกุล Pleurotus) มีความหนาแน่นเชิงพื้นที่เส้นใยสูงที่สุด (90.10 เปอร์เซ็นต์) ในกระบวนการผลิตเห็ดมีการปลดปล่อยก๊าซคาร์บอนไดออกไซด์ออกมาจากกระบวนการหายใจ ซึ่งก๊าซคาร์บอนไดออกไซด์ที่เห็ดปลดปล่อยออกมาส่งผลให้ก๊าซเรือนกระจกเพิ่มมากขึ้น อย่างไรก็ตาม การปลดปล่อยก๊าซคาร์บอนไดออกไซด์ของเห็ดมีปริมาณที่แตกต่างกัน จากการทดลอง พบว่า เห็ดขอนขาว (สกุล Lentinus) มีการเจริญเติบโต ผลผลิตต่ำที่สุด แต่ในทางตรงกันข้ามมีการปลดปล่อยก๊าซคาร์บอนไดออกไซด์ และปริมาณการปลดปล่อยก๊าซคาร์บอนไดออกไซด์ทั้งหมดมากที่สุด (34.30 ถึง 336.13 พีพีเอ็มต่อ 1 กรัมน้ำหนักสด และ 854.00 ถึง 8369.67 พีพีเอ็ม) นอกจากนี้มีคุณค่าทางโภชนาการด้านความชื้นและเส้นใยสูงสุด อีกทั้งมีปริมาณฟีนอลิกทั้งหมดสูงที่สุด ในขณะที่เห็ดสกุล Pleurotus เห็ดนางรมเทาให้ผลผลิตสูงที่สุด (น้ำหนักสด 65.71 กรัมต่อก้อน น้ำหนักแห้ง 11.18 กรัมต่อก้อน และประสิทธิภาพการผลิต 28.22 เปอร์เซ็นต์) และมีคุณค่าทางโภชนาการ ได้แก่ เห็ดนางฟ้าภูฐานมีคาร์โบไฮเดรตและพลังงานสูงที่สุด เห็ดนางรมทองมีโปรตีนและไขมันสูง และเห็ดนางรมทองกับเห็ดเป๋าฮื้อมีปริมาณเถ้าสูงสุด อีกทั้งเห็ดเป๋าฮื้อ มีฤทธิ์ต้านอนุมูลอิสระสูงที่สุด ซึ่งผลวิจัยนี้เป็นข้อมูลพื้นฐานสำหรับการศึกษาการเจริญเติบโต คุณภาพ และการปลดปล่อยก๊าซคาร์บอนไดออกไซด์ของเห็ดเศรษฐกิจในสภาวะควบคุมในบริบทของสิ่งแวดล้อมและเศรษฐกิจหมุนเวียนต่อไป</p>', 'มหาวิทยาลัยธรรมศาสตร์. หอสมุดแห่งมหาวิทยาลัยธรรมศาสตร์', '', 'https://tdc.thailis.or.th/tdc/browse.php?option=show&browse_type=title&titleid=706689&query=Array&s_mode=Array&date_field=date_create&date_start=2568&date_end=2569&limit_lang=&limited_lang_code=tha&order=&order_by=&order_type=&result_id=1&maxid=147', 'มหาวิทยาลัยธรรมศาสตร์. หอสมุดแห่งมหาวิทยาลัยธรรมศาสตร์'),
('ITM00000000084', 'การประเมินคุณสมบัติของคอนกรีตที่มีฟางข้าวผ่านการปรับสภาพเป็นมวลรวมหยาบชนิดเส้นใย', 'COM00000000001', 'COM00000000002', 'Properties evaluation of concrete with treated rice straw as fibrous coarse aggregate', NULL, 10, '2568', NULL, '<p>วิทยานิพนธ์ฉบับนี้มุ่งศึกษาคุณสมบัติของคอนกรีตที่นำฟางข้าวซึ่งผ่านกระบวนการปรับสภาพด้วยวิธีการต่างๆ มาใช้เป็นมวลรวมหยาบชนิดเส้นใย โดยมีแรงจูงใจจากปริมาณฟางข้าวจำนวนมากที่เป็นวัสดุเหลือทิ้งจากการเก็บเกี่ยวในแต่ละปี ซึ่งก่อให้เกิดปัญหามลภาวะทางอากาศและฝุ่นละออง PM 2.5 จากการเผาทำลายในช่วงฤดูเก็บเกี่ยว การนำวัสดุเหลือทิ้งทางการเกษตรเหล่านี้มาใช้เป็นส่วนผสมในคอนกรีตจึงเป็นแนวทางที่น่าสนใจ โดยทั่วไป เส้นใยธรรมชาติมักมีสารเคลือบผิว (Waxes) ที่ไม่เหมาะสมต่อการใช้งานจึงจำเป็นต้องมีการปรับสภาพเส้นใยเบื้องต้น ซึ่งในงานวิจัยนี้ได้ทำการศึกษาการปรับสภาพเส้นใย 3 วิธีหลัก ได้แก่ การแช่ในสารละลายด่าง (โซเดียมไฮดรอกไซด์) ที่ความเข้มข้น 1 M และ 5 M การแช่ในกรดอ่อน (กรดไฮโดรคลอริก) ที่ความเข้มข้น 3.6% และการต้มในน้ำเดือดเป็นเวลา 30 นาที ทั้งนี้ กระบวนการปรับสภาพเส้นใยที่แตกต่างกัน ย่อมส่งผลต่อความแข็งแรงของเส้นใย และคุณสมบัติโดยรวมของคอนกรีตที่ผสมฟางข้าวซึ่งผ่านการปรับสภาพเหล่านั้น จากผลการทดสอบพบว่าการผสมปริมาณฟางข้าวที่ 1 % นั้นส่งผลต่อค่ากำลังต้านทานแรงดัดและกำลังต้านทานแรงอัดที่ลดลงเพียงเล็กน้อย เนื่องจากปริมาณเส้นใยที่ใช้ในการผสมไม่มาก แต่สามารถลดหน่วยน้ำหนักของคอนกรีตและเพิ่มค่าการแอ่นตัวได้ดี โดยจากการทดสอบพบว่าที่ความยาวของฟางข้าว 1 - 2 ซม. สามารถเพิ่มค่าการแอ่นตัวและความเหนียวของคอนกรีตคอมโพสิตเหมาะสมที่สุด โดยวิธีการปรับสภาพเส้นใยด้วยการต้ม NaOH 1 M และ HCl เป็นกลุ่มที่ให้ผลลัพธ์เชิงคุณสมบัติที่ดีพอกัน แต่การใช้ NaOH 1 M จะมีความเหมาะสมในเชิงปฏิบัติและเชิงอุตสาหกรรมมากที่สุด จากข้อมูลการทดสอบคุณสมบัติคอนกรีตที่มีฟางข้าวผ่านการปรับสภาพต่างวิธีการเป็นมวลรวมหยาบชนิดเส้นใย เป็นวิธีการทางเลือกอีกวิธีการนึงที่เป็นมิตรต่อสิ่งแวดล้อม และยังช่วยเพิ่มมูลค่าให้กับวัสดุเหลือทิ้งได้อีกด้วย</p>', 'มหาวิทยาลัยเชียงใหม่', 'DegreeName: วิศวกรรมศาสตรมหาบัณฑิต\r\nLevel: ปริญญาโท\r\nDescipline: วิศวกรรมโยธา', 'https://tdc.thailis.or.th/tdc/browse.php?option=show&browse_type=title&titleid=699177&query=Array&s_mode=Array&date_field=date_create&date_start=2568&date_end=2569&limit_lang=&limited_lang_code=tha&order=&order_by=&order_type=&result_id=2&maxid=147', 'มหาวิทยาลัยเชียงใหม่. สำนักหอสมุด'),
('ITM00000000085', 'การออกแบบและพัฒนาหัวฉีดแบบแอร์บลาสต์เพื่อใช้งานทางด้านการเกษตรกรรม', 'COM00000000001', 'COM00000000002', 'Design and development of air-blast atomizer for agriculture', NULL, 10, '2568', NULL, '<p>งานวิจัยนี้มีวัตถุประสงค์เพื่อออกแบบและพัฒนาหัวฉีดแอร์บลาสต์ต้นแบบเพื่อใช้ทดแทน หัวฉีดเชิงพาณิชย์สำหรับเครื่องพ่นสเปรย์หมอก หัวฉีดต้นแบบถูกออกแบบให้ของเหลวไหลอกมาเป็นแผ่น sheet โดยแผ่นของเหลวจะถูกอากาศไหลมาปะทะในมุมตั้งฉากเพื่อให้ได้แรงเฉือนสูงสุด โดยอากาศไหลเข้าหัวฉีดผ่านใบหมุนวน (Swirler) ก่อนปะทะกับของเหลวทันทีที่ไหลออกจากทางออก งานวิจัยนี้ได้ออกแบบหัวฉีดต้นแบบให้มีใบหมุนวนแตกต่างกัน 3 ค่า คือ 10 15 และ 20 องศา หัวฉีดต้นแบบได้ถูกสร้างด้วยเครื่อง 3D Printer จากนั้นทำการทดลองเพื่อหาคุณลักษณะของสเปรย์ที่ได้จากหัวฉีดต้นแบบและหัวฉีดเชิงพาณิชย์โดยใช้เครื่อง Malvern Spraytec วัดหาขนาดหยดของสเปรย์ และใช้ Pitot tube เพื่อวัดการกระจายตัวของความเร็วอากาศ ในการทดลองได้สร้างชุดทดสอบหัวฉีดที่สามารถควบคุมอัตราการไหลของอากาศและน้ำได้ โดยตลอดการทดลองกำหนดไว้ที่ 0.015 m3/s และ 0.5 LPM ตามลำดับ ผลการทดลองที่ได้พบว่าหัวฉีดต้นแบบที่มีมุมใบหมุนวน 10 องศา (Nozzle A) ให้การกระจายตัวของขนาดหยดที่ดีที่สุดหรือให้สเปรย์ที่มีความละเอียดและมีความสม่ำเสมอมากที่สุด ดีกว่าหัวฉีดเชิงพาณิชย์ (Nozzle D) อย่างชัดเจน โดยมีค่า Drs เท่ากับ 58.23 ไมครอน ต่ำกว่าของ Nozzle D 12 % เมื่อพิจารณาผลกระทบของมุมใบหมุนวนพบว่า เมื่อมุมมีค่าน้อยลงจะส่งผลให้สัดส่วนของหยดขนาดใหญ่น้อยลงอย่างชัดเจน สำหรับการกระจายตัวของความเร็วอากาศพบว่า Nozzle A มีความเร็วสูงสุดของอากาศต่ำกว่า Nozzle D ในทุกระยะ Downstream แม้ว่าสเปรย์ของ Nozzle A จะมีความละเอียดกว่าสเปรย์ของ Nozzle D ซึ่งแสดงให้เห็นถึงสมรรถนะที่ดีในการแตกตัวของหัวฉีด</p>', 'มหาวิทยาลัยเทคโนโลยีพระจอมเกล้าพระนครเหนือ', 'DegreeName: วิศวกรรมศาสตร์มหาบัณฑิต\r\n\r\nLevel: ปริญญาโท\r\nDescipline: วิศวกรรมเครื่องกล\r\nGrantor: มหาวิทยาลัยเทคโนโลยีพระจอมเกล้าพระนครเหนือ', 'https://tdc.thailis.or.th/tdc/browse.php?option=show&browse_type=title&titleid=730557&query=Array&s_mode=Array&date_field=date_create&date_start=2568&date_end=2569&limit_lang=&limited_lang_code=tha&order=&order_by=&order_type=&result_id=3&maxid=147', 'มหาวิทยาลัยเทคโนโลยีพระจอมเกล้าพระนครเหนือ. สำนักหอสมุดกลาง'),
('ITM00000000086', 'ปุ๋ยหมักจากต้นกล้วยหอมทองเสริมซีลีเนียมต่อการเจริญเติบโตของผักกาดหอม', 'COM00000000001', 'COM00000000002', 'Selenium supplemenented Hom Thong banana tree compost on growth of lettuce', NULL, 10, '2568', NULL, '', 'มหาวิทยาลัยราชภัฏวไลยอลงกรณ์ ในพระบรมราชูปถัมภ์. สำนักวิทยบริการและเทคโนโลยีสารสนเทศ', 'DegreeName: วิทยาศาสตรมหาบัณฑิต\r\nLevel: ปริญญาโท\r\nDescipline: สาขาวิชาเทคโนโลยีการจัดการเกษตร', 'https://tdc.thailis.or.th/tdc/browse.php?option=show&browse_type=title&titleid=679349&query=Array&s_mode=Array&date_field=date_create&date_start=2568&date_end=2569&limit_lang=&limited_lang_code=tha&order=&order_by=&order_type=&result_id=4&maxid=147', 'มหาวิทยาลัยราชภัฏวไลยอลงกรณ์ฯ');
INSERT INTO `tb_item` (`item_id`, `item_title`, `community_id`, `collection_id`, `item_alternative`, `item_issued_day`, `item_issued_month`, `item_issued_year`, `item_description`, `item_abstract`, `item_sponsorship`, `item_citation`, `item_uri`, `item_publisher`) VALUES
('ITM00000000087', 'Assessing on the impacts of China border trade and CEMC Project on farmers’ livelihood along Myanmar-China border', 'COM00000000001', 'COM00000000002', 'การประเมินผลกระทบจากการค้าชายแดนจีนเเละโครงการ CEMC ต่อความเป็นอยู่ของชาวนาตามชายแดนจีน-เมียนมา', NULL, 10, '2568', NULL, '<p>As China and Myanmar have historical relation since it shares common borders as neighbors. Likewise, Chinese and Myanmar ethnics especially along the border also create long bonding connection socially, economically and politically. Since 88&rsquo;s crisis in Myanmar, the western countries imposed economic sanction to military junta. To resist and survive from the economic depression, Myanmar change the economic strategy and adopt open-door policy to focus on the land border trade with its neighbor countries rather than maritime trade. Subsequently, the expansion of the cash crop, border-crossing trade had been rapidly increased and the local business along border of the China-Myanmar was substituted according to the market demand. People shift from subsistence to cash cropping and border trade activities. However, the relationship between the two countries has been in intermittent situation and border trade policy changes and border control due to the political situation, border issue and the recent pandemic. Consequently, there are many impacts on corn farmers along the border. Therefore, this study aims to understand how trade policy changes influence agriculture transformation in Northern Shan State, assessing the impacts on local farmers and to propose the implication of policy recommendations to sustainable livelihood and economic development. The study found that uncertain border trade policy, lack of insurance policies for market and political unstable has hindered the local farmer and lead to livelihood instability. To address the Keywords: border trade, farmer, government, policy, market, transport, social, economic As China and Myanmar have historical relation since it shares common borders as neighbors. Likewise, Chinese and Myanmar ethnics especially along the border also create long bonding connection socially, economically and politically. Since 88&rsquo;s crisis in Myanmar, the western countries imposed economic sanction to military junta. To resist and survive from the economic depression, Myanmar change the economic strategy and adopt open-door policy to focus on the land border trade with its neighbor countries rather than maritime trade. Subsequently, the expansion of the cash crop, border-crossing trade had been rapidly increased and the local business along border of the China-Myanmar was substituted according to the market demand. People shift from subsistence to cash cropping and border trade activities. However, the relationship between the two countries has been in intermittent situation and border trade policy changes and border control due to the political situation, border issue and the recent pandemic. Consequently, there are many impacts on corn farmers along the border. Therefore, this study aims to understand how trade policy changes influence agriculture transformation in Northern Shan State, assessing the impacts on local farmers and to propose the implication of policy recommendations to sustainable livelihood and economic development. The study found that uncertain border trade policy, lack of insurance policies for market and political unstable has hindered the local farmer and lead to livelihood instability. To address the issues, it requires a participatory approach, inclusive</p>', 'Chiang Mai University. Library', 'DegreeName: Master of Arts\r\nLevel: Master\'s Degree\r\nDescipline: Public Policy\r\nGrantor: Chiang Mai University', 'https://tdc.thailis.or.th/tdc/browse.php?option=show&browse_type=title&titleid=679709&query=Array&s_mode=Array&date_field=date_create&date_start=2568&date_end=2569&limit_lang=&limited_lang_code=tha&order=&order_by=&order_type=&result_id=5&maxid=147', 'Chiang Mai University'),
('ITM00000000088', 'การวิเคราะห์ลักษณะภัยแล้งและพื้นที่เสี่ยงด้านการเกษตรบริเวณภาคเหนือของประเทศไทยด้วยดัชนีภัยแล้งทางอุตุนิยมวิทยา', 'COM00000000001', 'COM00000000002', 'Analysis of drought characteristics and agricultural risk areas in Northern Thailand by meteorological drought index', NULL, 10, '2568', NULL, '<p>การศึกษาเรื่อง &ldquo;การวิเคราะห์ลักษณะภัยแล้งและพื้นที่เสี่ยงด้านการเกษตรบริเวณภาคเหนือของประเทศไทยด้วยดัชนีภัยแล้งทางอุตุนิยมวิทยา&rdquo; เป็นการวิเคราะห์ลักษณะเชิงพื้นที่และเวลาของภัยแล้งทางอุตุนิยมวิทยาบริเวณภาคเหนือของประเทศไทยตามการแบ่งภาคทางอุตุนิยมวิทยา ตั้งแต่ปีค.ศ.1980 - 2017 รวมทั้งหมด 38 ปี ในช่วงฤดูฝน โดยมีวัตถุประสงค์เพื่อ 1) ศึกษาลักษณะภัยแล้งที่เกิดขึ้นบริเวณภาคเหนือของประเทศไทยในเชิงพื้นที่และเวลา และ 2) วิเคราะห์พื้นที่เสี่ยงภัยแล้งในพื้นที่การใช้ที่ดินด้านการเกษตรบริเวณภาคเหนือของประเทศไทย วิธีการศึกษาสำหรับวัตถุประสงค์ข้อที่ 1 เป็นการวิเคราะห์ลักษณะภัยแล้งเชิงพื้นที่และเวลาบริเวณภาคเหนือของประเทศไทย ตั้งแต่ปี ค.ศ.1980 - 2017 ในช่วงฤดูฝน เริ่มจากการตรวจสอบประสิทธิภาพของข้อมูลปริมาณน้า ฝนตรวจวัดที่จะใช้ในการศึกษา ได้แก่ ข้อมูลปริมาณน้ำ ฝนรูปแบบกริดจาก CRU ความละเอียดเชิงพื้นที่ 0.5&deg; x 0.5&deg; เปรียบเทียบกับข้อมูลปริมาณน้ำ ฝนตรวจวัดจากสถานีอุตุนิยมวิทยาบริเวณภาคเหนือทั้งหมด 31 สถานี โดยการหาค่าความสัมพันธ์ระหว่างข้อมูลปริมาณน้ำฝนทั้ง 2 รูปแบบ โดยผลการศึกษาพบว่าข้อมูลปริมาณน้ำ ฝนทั้ง 2 รูปแบบมีความสัมพันธ์กันในระดับสูง โดยมีค่าความสัมพันธ์ตั้งแต่ 0.826 - 0.983 ที่ระดับนัยสำคัญ 0.01 ดังนั้นข้อมูลปริมาณน้ำ ฝนรูปแบบกริดจาก CRU มีประสิทธิภาพเทียบเท่ากับข้อมูลปริมาณน้ำ ฝนตรวจวัดจากสถานี ในการศึกษานี้จึงใช้ข้อมูลปริมาณน้ำ ฝนรูปแบบกริดจาก CRU แทนข้อมูลปริมาณน้ำ ฝนตรวจวัดจากสถานี ในส่วนของการวิเคราะห์ลักษณะภัยแล้งเชิงพื้นที่และเวลา ทำได้โดยการคำนวณค่าดัชนีปริมาณน้ำ ฝนมาตรฐานหรือดัชนี SPI จากข้อมูลปริมาณน้ำ ฝนรูปแบบกริดจาก CRU ในช่วงเวลา 3 เดือน (SPI3) และ 6 เดือน (SPI6) ในช่วงฤดูฝนตั้งแต่เดือนพฤษภาคม - ตุลาคม ประกอบด้วยการวิเคราะห์ลักษณะเชิงพื้นที่และเวลาของภัยแล้งทางอุตุนิยมวิทยาในช่วงฤดูฝนจากการวิเคราะห์ดัชนี SPI3 ของเดือนกรกฎาคม (ค่าเฉลี่ยของเดือนพฤษภาคม - กรกฎาคม) สิงหาคม (ค่าเฉลี่ยของเดือนมิถุนายน - สิงหาคม) กันยายน (ค่าเฉลี่ยของเดือนกรกฎาคม - กันยายน) ตุลาคม (ค่าเฉลี่ยของเดือนสิงหาคม - ตุลาคม) และช่วงตลอดฤดูฝนจากการวิเคราะห์ค่าดัชนี SPI6 ของเดือนตุลาคม (ค่าเฉลี่ยของเดือนพฤษภาคม - ตุลาคม) การศึกษานี้ให้ความสนใจกับภัยแล้งระดับรุนแรงถึงรุนแรงมาก (&le; -1.50)โดยเฉพาะปี ที่เกิดภัยแล้งระดับรุนแรงถึงรุนแรงมากคิดเป็นพื้นที่มากกว่า 25% ของพื้นที่ภาคเหนือ สำหรับวัตถุประสงค์ข้อที่ 2 เป็นการนำผลการศึกษาจากวัตถุประสงค์ข้อที่ 1 มาวิเคราะห์ร่วมกับข้อมูลการใช้ที่ดินด้านการเกษตร เพื่อวิเคราะห์พื้นที่เสี่ยงภัยแล้งทางอุตุนิยมวิทยาที่เกิดขึ้นในพื้นที่การใช้ที่ดินด้านการเกษตร ผลการศึกษาพบว่า ภัยแล้งจากการวิเคราะห์ค่าดัชนี SPI3 ของเดือนกรกฎาคม มีพื้นที่เกิดภัยแล้งระดับรุนแรงถึงรุนแรงมาก มากกว่า 25% ของพื้นที่ภาคเหนือ ทั้งหมด 2 ปี ได้แก่ ปี ค.ศ. 1987 และ 2015 โดยปี ค.ศ. 2015 มีพื้นที่มากที่สุดคือ 97.10% และมีพื้นที่เสี่ยงภัยแล้งในพื้นที่การใช้ที่ดินด้านการเกษตรระดับรุนแรงมาก 82.456% ระดับรุนแรง 12.943% ของพื้นที่การใช้ที่ดินด้านการเกษตรภัยแล้งจากการวิเคราะห์ค่าดัชนี SPI3 ของเดือนสิงหาคม มีพื้นที่เกิดภัยแล้งระดับรุนแรงถึงรุนแรงมากกว่า 25% ของพื้นที่ภาคเหนือ ทั้งหมด 3 ปี ได้แก่ ปี ค.ศ. 1982 1993 และ 2015 โดยปี ค.ศ. 2015 มีพื้นที่มากที่สุดคือ 77.28% และมีพื้นที่เสี่ยงภัยแล้งในพื้นที่การใช้ที่ดินด้านการเกษตรระดับรุนแรงมาก 46.07% ระดับรุนแรง 22.908% ของพื้นที่การใช้ที่ดินด้านการเกษตร ภัยแล้งจากการวิเคราะห์ค่าดัชนี SPI3 ของเดือนกันยายน มีพื้นที่เกิดภัยแล้งระดับรุนแรงถึงรุนแรงมาก มากกว่า 25% ของพื้นที่ภาคเหนือ ทั้งหมด 3 ปี ได้แก่ ปี ค.ศ. 1986 1989 และ 2015 โดยปี ค.ศ. 2015 มีพื้นที่มากที่สุดคือ 46.44% และมีพื้นที่เสี่ยงภัยแล้งในพื้นที่การใช้ที่ดินด้านการเกษตรระดับรุนแรงมาก 4.232% ระดับรุนแรง 42.932% ของพื้นที่การใช้ที่ดินด้านการเกษตร ภัยแล้งจากการวิเคราะห์ค่าดัชนี SPI3 ของเดือนตุลาคม พบว่ามีพื้นที่เกิดภัยแล้งระดับรุนแรงถึงรุนแรงมาก มากกว่า 25% ของพื้นที่ภาคเหนือ ทั้งหมด 5 ปี ได้แก่ ปี ค.ศ. 1981 1986 1998 2004 และ 2015 โดยปี ค.ศ. 1998 มีพื้นที่มากที่สุดคือ 45.25% และมีพื้นที่เสี่ยงภัยแล้งในพื้นที่การใช้ที่ดินด้านการเกษตรระดับรุนแรงมาก 22.196% ระดับรุนแรง 26.707% ของพื้นที่การใช้ที่ดินด้านการเกษตร และภัยแล้งจากวิเคราะห์ค่าดัชนี SPI6 ของเดือนตุลาคม พบว่ามีพื้นที่เกิดภัยแล้งระดับรุนแรงถึงรุนแรงมาก มากกว่า 25% ของพื้นที่ภาคเหนือ ทั้งหมด 2 ปี ได้แก่ ปี ค.ศ. 1993 และ 2015 โดยปี ค.ศ. 2015 มีพื้นที่มากที่สุดคือ 92.27% และมีพื้นที่เสี่ยงภัยแล้งในพื้นที่การใช้ที่ดินด้านการเกษตรระดับรุนแรงมาก 72.297% ระดับรุนแรง 16.626% ของพื้นที่การใช้ที่ดินด้านการเกษตร</p>', 'มหาวิทยาลัยเชียงใหม่', 'DegreeName: วิทยาศาสตรมหาบัณฑิต\r\nLevel: ปริญญาโท\r\nDescipline: ภูมิศาสตร์และภูมิสารสนเทศศาสตร์\r\nGrantor: มหาวิทยาลัยเชียงใหม่', 'https://tdc.thailis.or.th/tdc/browse.php?option=show&browse_type=title&titleid=681960&query=Array&s_mode=Array&date_field=date_create&date_start=2568&date_end=2569&limit_lang=&limited_lang_code=tha&order=&order_by=&order_type=&result_id=6&maxid=147', 'มหาวิทยาลัยเชียงใหม่. สำนักหอสมุด'),
('ITM00000000089', 'กลยุทธ์การปรับตัวเพื่อการดำรงชีพของกลุ่มแรงงานใน \"สวนกล้วยจีน\" บริเวณชายแดนไทย-ลาว', 'COM00000000001', 'COM00000000002', 'Adaptation strategies for livelihood of labor groups in “Chinese banana plantation” along Thai-Lao border', NULL, 10, '2568', NULL, '<p>การศึกษานี้ให้ความสนใจประเด็นการปรับตัวของกลุ่มแรงงานภายใต้กระบวนการผลิตที่เข้มข้นของสวนกล้วยจีนบริเวณพื้นที่อำเภอพญาเม็งราย จังหวัดเชียงราย โดยศึกษารูปแบบกลยุทธ์การปรับตัวในการดารงชีพ (Adaptation Strategies for Livelihood) ของแรงงานกลุ่มต่าง ๆ ที่ยึดโยงกับเงื่อนไข (condition) ทางสังคมวัฒนธรรมในบริบทที่อิทธิพลจีนรุกคืบเข้าสู่ภาคเกษตร (agroindustry)ชายแดนไทย งานศึกษานี้มีวัตถุประสงค์เพื่อ 1) ศึกษากลยุทธ์การปรับตัวในการดำรงชีพของแรงงานกลุ่มต่าง ๆ ในสวนกล้วยจีนบริเวณชายแดนไทย-ลาวในบริบทการพัฒนาเศรษฐกิจการเกษตรชายแดนภายใต้อิทธิพลจีน และ 2) เพื่ออธิบายระบบความสัมพันธ์ในมิติทางสังคมวัฒนธรรมของแรงงานกลุ่มต่างๆ ที่ใช้เป็นกลยุทธ์การปรับตัวในการดำรงชีพ งานวิจัยใช้วิธีการศึกษาเชิงคุณภาพ เก็บข้อมูลภาคสนามในพื้นที่สวนกล้วยจีน สังเกตการณ์และสัมภาษณ์กลุ่มแรงงาน กลุ่มผู้ให้ข้อมูลหลักตลอดจนกลุ่มผู้ให้ข้อมูลที่เกี่ยวข้องกับประเด็นศึกษาผลการศึกษา พบว่า รูปแบบการใช้กลยุทธ์การปรับตัวในการดารงชีพของแรงงานสวนกล้วยมี สามรูปแบบ คือ หนึ่ง การสร้างความหลากหลายของการดารงชีพ เป็นการใช้ทางเลือกหรือชุดกิจกรรมที่หลากหลายผสมผสานเพื่อให้บรรลุเป้าหมาย สอง การปรับเปลี่ยนทุนในการดารงชีพเป็นกลยุทธ์การจัดการทรัพยากรและทุนให้สามารถหนุนเสริมแทนกันได้ และ สาม การปรับใช้เครื่องมือทางสังคม เป็นกลยุทธ์ที่แรงงานใช้เพื่อเป็น &ldquo;กันชน&rdquo; (Buffer) รองรับชีวิตในยามเผชิญกับความเปราะบาง โดยเงื่อนไขในการเลือกใช้กลยุทธ์ของแรงงานเหล่านี้ คือ ทุน (capital) ประเภทต่าง ๆ ที่แต่ละกลุ่มมีหรือสามารถเข้าถึงได้ นอกจากนี้ งานศึกษายังพบว่า ชุดความสัมพันธ์ทางสังคมคือเครื่องมือสาคัญที่ช่วยสนับสนุนการปรับตัวของแรงงานในยามเผชิญหน้ากับความเสี่ยง (risk)ในการดำรงชีพ จะพบว่า กลุ่มแรงงานที่มีเครือข่ายความสัมพันธ์ทางสังคม (social network) กว้างขวาง ไม่ว่า กลุ่มเครือญาติ เพื่อน หัวหน้างาน มักปรับตัวได้อย่างยืดหยนุ่ และลดความเสี่ยงในการดำรงชีพได้งานศึกษานี้ยังพบผลลัพธ์ที่เกิดจากการปรับตัวในการดำรงชีพของแรงงาน ที่สามารถแบ่งได้สามกลุ่ม คือ หนึ่ง กลุ่มแรงงานประสบความสาเร็จในการดำรงชีพ โดยฉวยใช้ทักษะความรู้และฝีมือความชำนาญผนวกกับเครือข่ายความสัมพันธ์ที่เกิดขึ้นใหม่จากการทำงานในสวนกล้วย พัฒนาตัวเองไปสู่การเป็นแรงงานอาชีพ (professional worker) สอง กลุ่มแรงงานสามารถปรับตัวได้ โดยใช้กลยุทธ์และทุนที่มีความหลากหลายในการดารงชีพ สาม กลุ่มแรงงานที่ไม่สามารถปรับตัวได้ และต้องเผชิญความยากลาบากในการทางานในสวนกล้วย เพราะไม่สามารถเข้าถึงปัจจัยการผลิต และมีเครือข่ายทางสังคมน้อยกว่า ทาให้แรงงานกลุ่มนี้มีทางเลือกน้อย ซึ่งส่วนใหญ่มักเป็ นกลุ่มแรงงานต่างถิ่นและแรงงานข้ามชาติ</p>', '', 'DegreeName: ศิลปศาสตรมหาบัณฑิต\r\nLevel: ปริญญาโท\r\nDescipline: สังคมวิทยาและมานุษยวิทยา\r\nGrantor: มหาวิทยาลัยเชียงใหม่', 'https://tdc.thailis.or.th/tdc/browse.php?option=show&browse_type=title&titleid=681975&query=Array&s_mode=Array&date_field=date_create&date_start=2568&date_end=2569&limit_lang=&limited_lang_code=tha&order=&order_by=&order_type=&result_id=7&maxid=147', 'มหาวิทยาลัยเชียงใหม่. สำนักหอสมุด'),
('ITM00000000090', 'การใช้ประโยชน์ที่ดินกับปัญหาอุทกภัยในตำบลวังหมัน อำเภอสามเงา จังหวัดตาก', 'COM00000000001', 'COM00000000002', 'Land use and flood problem in Wangman Sub-distric, Samngao Distric, Tak Province', NULL, 10, '2568', NULL, '<p>การศึกษาวิจัยครั้งนี้มีวัตถุประสงค์เพื่อศึกษาและวิเคราะห์ลักษณะทางกายภาพของลุ่มน้ำ ลักษณะทางกายภาพของพื้นที่ ลักษณะภูมิอากาศด้านฝนและพายุ และการใช้ประโยชน์ที่ดินในตำบล วังหมัน อำเภอสามเงา จังหวัดตาก เป็นสาเหตุสำคัญของภาวะอุทกภัยเมื่อมีมวลน้ำปี 2554 และและเพื่อ ศึกษาและวิเคราะห์การบริหารมวลน้ำด้วยระบบของชลประทาน และการจัดการของหน่วยงานและ ชุมชน เพื่อการบรรเทาภาวะอุทกภัยในตำบลวังหมัน อำเภอสามเงา จังหวัดตาก ด้านการเป็นสาเหตุ ของภาวะอุทกภัยเมื่อมีมวลน้ำปี 2554 ในพื้นพื้นที่ โดยการใช้ข้อมูลจากการสัมภาษณ์ผู้มีส่วนเกี่ยวข้อง ประกอบกับข้อมูลจากการค้นคว้าวิจัยแหล่งข้อมูลต่าง ๆ ซึ่งผลการวิจัยพบว่า ปัจจัยอันเป็นเหตุให้ อุทกภัยปี พ.ศ.2554 มาจากลักษณะกายภาพของพื้นที่ ลักษณะภูมิอากาศ และการเปลี่ยนแปลงการใช้ ที่ดินเพื่อการอยู่อาศัยและการเกษตร รวมทั้งโครงสร้างสาธารณูปโภคในพื้นที่ และเป็นผลจากการ ประสบอุทกภัยทำให้เกิดการเปลี่ยนแปลงการใช้ที่ดินโดยเฉพาะด้านที่อยู่อาศัยและการเกษตรนั้นเป็น สาเหตุให้อุทกภภัยในปี 2554 เกิดขึ้นอย่างรุนแรงในพื้นที่ ร่วมกับการบริหารจัดการมวลน้ำในพื้นพื้นที่ ณ ขณะเกิดภัยทั้งโดยชลประทานและการจัดการของหน่วยงานและชุมชนนั้นยังไม่เต็มประสิทธิภาพ ความไม่พร้อมด้านข้อมูลประกอบกับการขาดการประสานงานกันแบบทันทีทันด่วน ล้วนเป็น ประเด็นที่ส่งผลให้ภาวะอุทกภัยในพื้นที่ไม่บรรเทาเบาบางลง ทั้งนี้วิกฤตน้ำท่วมที่เกิดขึ้นในปี 2554 จะเป็นข้อมูลสำคัญในการนำไปสู่แนวทางในการบริหารจัดการเพื่อพัฒนาอย่างยั่งยื่นในพื้นที่ต่อไป</p>', 'มหาวิทยาลัยเชียงใหม่', 'DegreeName: วิทยาศาสตรมหาบัณฑิต\r\nLevel: ปริญญาโท\r\nDescipline: การใช้ที่ดินและการจัดการทรัพยากรธรรมชาติอย่างยั่งยืน\r\nGrantor: มหาวิทยาลัยเชียงใหม่', 'https://tdc.thailis.or.th/tdc/browse.php?option=show&browse_type=title&titleid=682162&query=Array&s_mode=Array&date_field=date_create&date_start=2568&date_end=2569&limit_lang=&limited_lang_code=tha&order=&order_by=&order_type=&result_id=8&maxid=147', 'มหาวิทยาลัยเชียงใหม่. สำนักหอสมุด'),
('ITM00000000091', 'การปะทะประสานของภูมิทัศน์การเกษตรกับภูมิทัศน์การท่องเที่ยวในกระบวนการกลายเป็นสินค้าของสังคมชนบทในชุมชน เมืองแกนพัฒนา อำเภอแม่แตง จังหวัดเชียงใหม่', 'COM00000000001', 'COM00000000002', 'Articulation of agricultural landscape and touristscape in the commoditization of rural society in Mueang Kaen Pattana Community, Mae Taeng District, Chiang Mai Province', NULL, 10, '2568', NULL, '<p>การวิจัยนี้ศึกษาการปะทะประสานของวิถีการดำรงชีพด้านการเกษตรกับธุรกิจบริการ ด้านการท่องเที่ยวในชุมชนเมืองแกนพัฒนา รวมถึงพินิจและวิเคราะห์การเปลี่ยนผ่านวิถีชีวิตของ สังคมชนบทท่ามกลางการอุบัติขึ้นมาของอุดสาหกรรมการท่องเที่ยวในฐานะที่เป็นกรอบ แนวความคิดในการวิจัย โดยมองผ่านการต่อรองระหว่างภูมิทัศน์การเกษตรและภูมิทัศน์การท่องเที่ยว ตลอดจนผลประโยชน์และผลกระทบที่เกิดขึ้นจากผู้กระทำการที่มีส่วนเกี่ยวข้องในบริบทที่ หลากหลาย กระบวนการวิจัขดำเนินภายได้กรอบแนวคิดที่อธิบายถึงการเปลี่ยนแปลงผ่านมุมมอง ด้านภูมิทัศน์ด้วยการวิจัยเชิงคุณภาพ โดยมีการนำเอาวิธีการวิจัยหลายแบบนำมาใช้ในการเก็บข้อมูล ดังเช่นในเชิงคุณภาพมีการสัมภาษณ์แบบบเขาะลึกจากบุคคลสำคัญในชุมชน ผู้นำชุมชุมชน และนักธุรกิจที่ เข้ามาลงทุนในชุมชน รวมทั้งหมด 9 คน ประกอบกับการสังเกตการณ์ในสนาม ทั้งนี้ยังมีเชิงปริมาณ โดยการเก็บข้อมูลเชิงสถิติจากกลุ่มตัวอย่างเกษตรกร 160 คน ข้อมูลเหล่านี้ได้นำมาวิเคราะห์และ ให้ความหมายข้อมูลโดยอาศัยเครื่องมือทางความคิดที่เกี่ยวข้องกับบริบท พร้อมกับนำเสนอ ผลการศึกษาผ่านการอธิบายเชิงพรรณนาประกอบกับการอภิปรายร่วมกับทฤษฎี และการสนทนา แลกเปลี่ยนกับวรรณกรรมที่เกี่ยวข้อง ผลการวิจัยชี้ให้เห็นว่าปฏิบัติการของวาทกรรม \"\"การพัฒนา\"\" ส่งผลให้โฉมหน้าของชุมชน เมืองแกนพัฒนาเปลี่ยนผ่านเข้าสู่ภาวะความเป็นสมัยใหม่ที่มีความเหลื่อมซ้อนของอัดลักษณ์สังคม ชาวนาดั้งเดิมในบางประการ การเปลี่ยนแปลงดังกล่าวปรากฏผ่านภูมิทัศน์การเกษตรและ ภูมิทัศน์การท่องเที่ยว เช่น การที่ชาวบ้านมีการประกอบอาชีพที่หลากหลาขนอกเหนือจากการเกษตร แม้ว่าภาพลักษณ์ของชุมชนคล้ายกับสังคมเมืองมากขึ้นทุกขณะ แต่ในทางกลับกันยังพบกระบวนการ หวนคืนสู่ภาคการเกษตรในชุมชน คือ การทำการเกษตรเพื่อการค้าในรูปแบบใหม่ ซึ่งมีเงื่อนไข เชิงบริบททางการเมืองและเทคโนโลยีเป็นพลังผลักต้นให้เกิดการเปลี่ยนแปลง ทั้งนี้สังคมเกษตรกรรม ของชุมชนเมืองแกนพัฒนายังขาดพลังอำนาจในการต่อรองราคารับซื้อผลผลิตกับนายทุนหรือ หน่วยงานรัฐในแง่ของโครงการพัฒนาด้านต่างๆ นายกเทศมนตรีฯ ณ ขณะนั้นจึงมีการแก้ไขปัญหา ด้วยการผลิตสร้าง \"\"ภูมิทัศน์การท่องเที่ยว\"\" เพื่อเพิ่มมูลค่าให้แก่สินค้าทางการเกษตรและต้องการ หลุดพ้นจากอำนาจการครอบงำของนายทุนได้ ชุมชนเมืองแกนพัฒนาในปัจจุบันจึงอยู่ในสภาวะของการปะทะประสานระหว่างภูมิทัศน์ ทางการเกษตรและภูมิทัศน์การท่องเที่ยว ผู้นำชุมชนได้บอกเล่าลักษณะธรรมชาติและวัฒนธรรมผ่าน การผลิตสร้างเทศกาล \"\"หนาวนี้ทีเมืองแกน\"\" ในปี พ ศ 2553 ภายใต้กระบวบการกลายเป็นสินค้า อย่างไรก็ตามกระบวนการดังกล่าวกลับกลายเป็นต้นธารสู่ความไม่เสมอภาคในหมู่ชาวบ้าน เนื่องจากการเปิดพื้นที่เศรษฐกิจใหม่นี้กระตุ้นให้เกิดการสะสะสมทุนของนายทุนอย่างแยบผล ผ่านการกว้านซื้อที่ดินของชาวบ้าน เพื่อประกอบธุรกิจการท่องเที่ยวสนองต่อผู้คนที่ถวิลหาความเป็น ชนบท อย่างไรก็ดึการกระจายผลประโยชน์ดังกล่าวยังไม่มีความสอดคล้องกับสถานะทางเศรษฐกิจ ของชาวบ้านเท่าที่ควร เพราะปัจจัยการผลิตหรือที่ดินประกอบกับต้นทุนการเงินยังคงเป็นส่วนสำคัญ ต่อการเปลี่ยนแปลงภูมิทัศน์ ดังนั้น พลังอำนาจของการท่องเที่ยวจึงยังไม่ถึงกับมีบทบาทใน การเปลี่ยนแปลงวิถีชีวิตของชาวบ้านอย่างมีนัยสำคัญ เป็นที่น่าสังเกตว่าการเปลี่ยนแปลงพื้นที่ในครั้ง นี้ได้มีการแทรกแซงจากหลายกลุ่มผู้กระทำการ ซึ่งการเปลี่ยนแปลงดังกล่าวไม่ได้เกิดขึ้นอย่างตายตัว เพราะมีการสลับไปมาระหว่างภูมิทัศน์ทางการเกษตรและภูมิทัศน์การท่องเที่ยว โดยในบางครั้งนั้นมี การซ้อนทับในช่วงเวลาเดียวกัน ผลที่ได้จากการศึกษาครั้งนี้เป็นการเน้นช้ำถึงความไม่สมดุลระหว่าง นโขบายการพัฒนาและวิถีการดำรงชีพของคนในท้องถิ่น ที่เป็นบทเรียนสำหรับการวางแผนส่งเสริม การพัฒนาการท่องเที่ยวโดยมีชุมชนเป็นฐานในการศึกษาอื่น ๆ ที่เกี่ยวข้องต่อไป</p>', 'มหาวิทยาลัยเชียงใหม่', 'DegreeName: วิทยาศาสตรมหาบัณฑิต\r\nLevel: ปริญญาโท\r\nDescipline: ภูมิศาสตร์และภูมิสารสนเทศศาสตร์\r\nGrantor: มหาวิทยาลัยเชียงใหม่', 'https://tdc.thailis.or.th/tdc/browse.php?option=show&browse_type=title&titleid=682802&query=Array&s_mode=Array&date_field=date_create&date_start=2568&date_end=2569&limit_lang=&limited_lang_code=tha&order=&order_by=&order_type=&result_id=9&maxid=147', 'มหาวิทยาลัยเชียงใหม่. สำนักหอสมุด'),
('ITM00000000092', 'การพัฒนาเครื่องหยอดเมล็ดธัญพืชสำหรับรถไถ', 'COM00000000001', 'COM00000000002', 'Development of sowing machine for tractor', NULL, 10, '2568', NULL, '', 'มหาวิทยาลัยราชภัฏวไลยอลงกรณ์ ในพระบรมราชูปถัมภ์', 'DegreeName: วิทยาศาสตรมหาบัณฑิต\r\nLevel: ปริญญาโท\r\nDescipline: สาขาวิชาการจัดการเทคโนโลยี\r\nGrantor: มหาวิทยาลัยราชภัฏวไลยอลงกรณ์ฯ', 'https://tdc.thailis.or.th/tdc/browse.php?option=show&browse_type=title&titleid=683186&query=Array&s_mode=Array&date_field=date_create&date_start=2568&date_end=2569&limit_lang=&limited_lang_code=tha&order=&order_by=&order_type=&result_id=10&maxid=147', 'มหาวิทยาลัยราชภัฏวไลยอลงกรณ์ ในพระบรมราชูปถัมภ์. สำนักวิทยบริการและเทคโนโลยีสารสนเทศ'),
('ITM00000000093', 'รูปแบบการจัดการน้ำเพื่อการเกษตรด้วยระบบสารสนเทศภูมิศาสตร์ในพื้นที่ ตำบลนาทราย อำเภอลี้ จังหวัดลำพูน', 'COM00000000001', 'COM00000000002', 'Water management model for agriculture with geographic information system in Na Sai Subdistrict, Li District, Lamphun Province', NULL, 10, '2568', NULL, '', 'มหาวิทยาลัยราชภัฏเชียงใหม่', 'Grantor: มหาวิทยาลัยราชภัฏเชียงใหม่\r\nDegreeName: วิทยาศาสตรมหาบัณฑิต\r\nLevel: ปริญญาโท\r\nDescipline: พลังงานชุมชนและสิ่งแวดล้อม', 'https://tdc.thailis.or.th/tdc/browse.php?option=show&browse_type=title&titleid=685152&query=Array&s_mode=Array&date_field=date_create&date_start=2568&date_end=2569&limit_lang=&limited_lang_code=tha&order=&order_by=&order_type=&result_id=11&maxid=147', 'มหาวิทยาลัยราชภัฏเชียงใหม่. สำนักหอสมุด'),
('ITM00000000094', 'การเสริมกากปาล์มเนื้อในผสมมันเส้นบทหมักยีสต์ร่วมกับอาหารข้นต่อผลิตองค์ประกอบน้ำนม และผลตอบแทนทางเศรษฐกิจในโครีดนม', 'COM00000000001', 'COM00000000002', 'Supplementation of mixed palm meal and cassava chip meal fermented yeast with concentrate on milk yield, milk compositions and economic benefit in lactating dairy cows', NULL, 10, '2568', NULL, '<p>การศึกษานี้มีวัตถุประสงค์เพื่อศึกษาการเสริมกากปาล์มเนื้อในผสมมันเส้นบดหมักยีสต์ร่วมกับอาหาร ขั้นต่อผลผลิต คุณภาพน้ํานม และผลตอบแทนทางเศรษฐกิจในโครีดนม โดยใช้โคนมสายพันธุ์ไทยฟรี เขียน จํานวน 10 ตัว โคมีน้ําหนักตัว 395 &plusmn; 50 กิโลกรัม และมีผลผลิตน้ํานมเฉลี่ย 10.2 &plusmn; 1.2 กิโลกรัม/ตัว/วัน โดยแบ่งการทดลองออกเป็น 2 ทรีทเมนต์ คือ ทรีทเมนต์ที่ 1 อาหารควบคุม โคได้รับ อาหารข้นโปรตีนร้อยละ 16 และทรีทเมนต์ที่ 2 อาหารทดลอง โคได้รับอาหารข้นโปรตีนร้อยละ 16 เสริมด้วยกากปาล์มเนื้อในผสมมันเส้นบดหมักยีสต์ 1 กิโลกรัม/ตัว/วัน ผลการศึกษาพบว่า ปริมาณ การกินได้ อัตราการแลกน้ํานม องค์ประกอบน้ํานม และต้นทุนค่าอาหาร ไม่มีความแตกต่างทางสถิติ (P&gt;0.05) แต่ในส่วนของอัตราการให้ผลผลิตน้ํานม พบว่าโคที่ได้รับอาหารข้นโปรตีนร้อยละ 16 เสริม ด้วยกากปาล์มเนื้อในผสมมันเส้นบดหมักยีสต์ มีผลผลิตน้ํานมสูงกว่ากลุ่มควบคุมที่ได้รับอาหารข้น โปรตีนร้อยละ 16 เพียงอย่างเดียว (P&lt;0.05) ดังนั้น การเสริมกากปาล์มเนื้อในผสมมันเส้นบดหมัก ยีสต์ร่วมในสูตรอาหารข้นสามารถช่วยเพิ่มผลผลิตน้ํานมในการเลี้ยงโคนมของเกษตรกรได้</p>', 'มหาวิทยาลัยราชภัฏมหาสารคาม', 'DegreeName: วิทยาศาสตรมหาบัณฑิต\r\nLevel: ปริญญาโท\r\nDescipline: เทคโนโลยีการเกษตร', 'https://tdc.thailis.or.th/tdc/browse.php?option=show&browse_type=title&titleid=688586&query=Array&s_mode=Array&date_field=date_create&date_start=2568&date_end=2569&limit_lang=&limited_lang_code=tha&order=&order_by=&order_type=&result_id=12&maxid=147', 'มหาวิทยาลัยราชภัฏมหาสารคาม. สำนักวิทยบริการและเทคโนโลยีสารสนเทศ');
INSERT INTO `tb_page` (`page_id`, `page_banner`, `page_title`) VALUES
(1, 'banner.png', '<p style=\"text-align: center;\"><span style=\"font-size: 18pt; color: #236fa1;\"><strong>คลังสารสนเทศ 12 จุดเน้น ม.อ.<br></strong></span><span style=\"font-size: 18pt; color: #236fa1;\"><strong>12 Focus Area of Prince of Songkla University Repository</strong></span></p>\n<p style=\"text-align: center;\"><span style=\"font-size: 14pt; color: #000000;\">แหล่งรวมข้อมูลผลงานด้านวิชาการ ได้แก่ บทความวิชาการ ผลงานวิจัย วิทยานิพนธ์ สารนิพนธ์ หนังสือ ตำรา สื่อการสอน และเอกสารอื่น ๆ <br>ของนักศึกษา อาจารย์ และบุคลากรมหาวิทยาลัยสงขลานครินทร์ ที่เข้าถึงได้อย่างเสรี (Free Open Access) โดยมีขอบเขตเนื้อหา<br>ตามยุทธศาสตร์การพัฒนามหาวิทยาลัย พ.ศ. 2566-2570<br></span></p>\n<p>&nbsp;</p>');
